///////////////////////////////////////////////////////////////////////////////
//	Copyright : Maxim Kornienko / Open Enterprise Solutions
//	Name      : mcpToolPatterns.cpp
//	Purpose   : `pattern_read` — how to read a request and which shape it asks for.
//
//	⭐⭐ WHY THIS IS A TOOL AND NOT MORE `instructions`.
//
//	The connection's `instructions` are read in full by every client, every time, and they had
//	grown past seven kilobytes. Everything put there is paid for on every connection whether it is
//	needed or not — and this material is exactly the kind that keeps growing: every conversation
//	with someone who knows the domain adds another "and when they say THIS, it means THAT".
//
//	The dividing line is not size, it is whether a model can know to ask:
//	  · a DISCIPLINE — write notes on the object, name things in English, link by id — is something
//	    nobody asks for, because not knowing it feels like nothing. It stays in `instructions`.
//	  · a PATTERN is consulted at a moment the model can recognise: it is about to choose a
//	    metatype, and it knows it is choosing. Told that these exist, it will come and read one.
//
//	And these are RECOMMENDATIONS, deliberately: "where it is better to look", not obligations.
//	A rule that cannot be followed sensibly in some case gets ignored wholesale; advice that says
//	what it is FOR survives being disagreed with.
//
//	⭐⭐ WHAT THIS CORPUS IS, so that what gets added to it stays the same kind of thing.
//
//	A KNOWLEDGE BASE, not advice addressed to an assistant. It is written for whoever is reading —
//	a model connected over MCP today, a person learning the platform tomorrow — and this tool is
//	one door onto it rather than its purpose. Nothing in the entries should assume its reader.
//
//	What it holds is a TRANSLATOR — from the words of the people who ask for the work into the
//	shapes this platform has. An accountant does not say "accumulation register with RegisterType
//	= turnovers"; they say "I want to see the sales by month", and that sentence names the shape
//	precisely. The entries record which sentence means which shape, and why.
//
//	So it is NOT documentation of the platform: what a register IS belongs to the docs and to the
//	help corpus, and repeating it here would only give the two a chance to disagree. What lives
//	here is the step BEFORE that — hearing the request correctly — which is nowhere else, because
//	it is not a property of the platform at all. It is experience, one person's, written down
//	deliberately as such: it will be extended as more of it is put into words, and an entry may be
//	argued with, which is why each says what it is FOR rather than only what to do.
///////////////////////////////////////////////////////////////////////////////

#include "backend/mcp/mcpTool.h"

#include <algorithm>   // the addresses are ranked, and the bar is the best score there was

#include <vector>

namespace {

using ibArg = ibMcpTool::ibMcpArgument;
const ibArg& ArgName() { static const ibArg a(wxT("name"), ibArg::Kind::Text, ibMcpText("Which pattern to read. Alone it answers the summary and the list of topics inside; with `topic` it answers that part in full. Omit it to list what there is.")); return a; }

const ibArg& ArgTopic()
{
	static const ibArg a(wxT("topic"), ibArg::Kind::Text,
		ibMcpText("Which part of that pattern, by any words of its heading as the listing shows them. "
		  "Omit for the table of contents; pass `all` for the whole entry."));
	return a;
}

// ⭐⭐ THE WAY IN WHEN THE PATTERN'S NAME IS NOT KNOWN - and it usually is not. A caller has the
// WORDS OF A PROBLEM ("stock will not write off", "spread the overheads", "the shops serve each
// other") and no idea which of thirty entries holds the answer, or whether one does at all.
//
// Searching the corpus answers with ADDRESSES: which pattern, which topic inside it, and the line
// that matched. Then one more call reads that topic. Nothing else is fetched, and an entry that
// does not match is never opened - which is the whole point at a hundred kilobytes.
const ibArg& ArgQuery()
{
	static const ibArg a(wxT("query"), ibArg::Kind::Text,
		ibMcpText("Words of the problem - 'will not write off', 'close the month', 'column per "
		  "warehouse'. THE CORPUS IS WRITTEN IN ENGLISH, so ask in English: if the person put it in "
		  "another language, say it here in the words the trade uses in English rather than passing "
		  "theirs through. Answers WHERE the corpus speaks about it: the pattern, the topic inside "
		  "it, and the matching line. Ranked, not filtered: what matched every word if anything "
		  "did, otherwise the best there was, marked '3 of your 5 words' - so a word too many "
		  "narrows the answer instead of erasing it. A REGULAR EXPRESSION works too and is read as "
		  "one whenever it carries | \\ [ ] ^ $ .* - 'lot|batch|fifo', 'advance.*offset'."));
	return a;
}

// ONE ENTRY. `name` is the address, `summary` is what the listing shows, `text` is the whole of it.
struct ibMcpPattern {
	const wxChar* m_name;
	wxString      m_summary;
	wxString      m_text;
};

// ⚠ HELD AS A FUNCTION, not a file-scope table: a static built before the locale is set would
// freeze whatever the strings were at that moment for the life of the process.
//
// 🛑⭐ AND THE ENTRIES ARE `wxT`, NOT `_()`, WHICH IS NOT A STYLE CHOICE. The translation macro
// resolves to `wxASCII_STR` here, so every character outside ASCII in a translatable literal comes
// back as a question mark - and this corpus is written with ⭐ / 🛑 / ⚠ opening its headings. The
// result was `??? FIXED OVERHEADS…`: the marks were gone from the text, from the table of contents
// built out of those headings, and from every search hit quoting them.
//
// ⚠ Seen only by READING AN ANSWER, never by anything failing: the tool worked, the topics split
// correctly, and the noise was three characters wide (2026-09-02, on the first live check of the
// layered reading). The entries are English by rule and are not translated, so `wxT` costs nothing
// and keeps the marks - but any NEW string here that a person is meant to read in their own
// language has to stay `_()` and stay ASCII.
//
// 🛑⭐ CHECKING THIS TABLE AFTER AN EDIT: COUNT QUOTES PER LINE, NOT BRACES. An entry ends
// `"…text.") },` and the mistake that is actually made is `"…text.\") },` - the closing quote
// escaped, so the literal never closes and the next entry is swallowed. Counting openers against
// `") },` reports a healthy balance either way, because the broken form CONTAINS the good one as a
// substring; 18 such lines passed that check on 2026-09-03 and only the compiler would have
// noticed. What finds them is parity, per line, with escaped quotes removed first:
//     awk '/^\t+"/ { l=$0; gsub(/\\"/,"",l); if (gsub(/"/,"",l)%2) print NR": "$0 }' <file>
//
// ⚠ AND WHEN PASTING INTO AN ENTRY, ANCHOR ON A WHOLE LINE AND INSERT AFTER IT. The text is broken
// across source lines, so a sentence quoted from a rendered answer usually spans two of them and
// matches nothing; and inserting BEFORE an anchor splits the paragraph it belongs to, mid-sentence,
// which reads as correct in the diff and as nonsense in the answer.
const std::vector<ibMcpPattern>& Patterns()
{
	static const std::vector<ibMcpPattern> s_patterns = {

	{ wxT("shapes"),
	  ibMcpText("Which metatype a described need asks for - and the words that give it away."),
	  ibMcpText("READING A REQUEST FOR ITS SHAPE.\n"
		"\n"
		"What someone describes tells you which metatype it is. Listen for the QUESTION behind the\n"
		"words, not for the nouns - the same noun lands in different shapes depending on what is\n"
		"being asked of it.\n"
		"\n"
		"\"It changes over time and I need it as of a date\" - a price, a rate, who is responsible\n"
		"for something - is an InformationRegister with `Periodicity` set. The period is part of\n"
		"the key: you are keeping a value that was true for a stretch of time, not one that was\n"
		"overwritten. And the granularity is dictated too - \"once a month\", \"I want to see it\n"
		"monthly\" means `Periodicity` = Month, not a date field someone rounds by hand.\n"
		"\n"
		"\"I just need somewhere to keep this, nothing produces it\" is an InformationRegister with\n"
		"`WriteMode` = Independent. Nothing posts it, it is written directly. Reach for this before\n"
		"inventing a document whose only purpose is to carry data.\n"
		"\n"
		"SETTINGS LIVE THERE TOO, and this is the case most often missed. Anything kept PER\n"
		"something - per user, per user and warehouse, per user and report - is an independent\n"
		"InformationRegister keyed by exactly that. The key is the whole design: \"whose setting is\n"
		"this\" answered as dimensions. A setting that is the same for everybody is not this - see\n"
		"`constants`.\n"
		"\n"
		"\"How much happened over a period\" - sales, where a return is a reversing movement against\n"
		"the same register rather than a second register - is an AccumulationRegister with\n"
		"`RegisterType` = turnovers. It answers totals for an interval and nothing else, which is\n"
		"the point: a narrow question, answered cheaply.\n"
		"\n"
		"\"What is left\" - stock on hand, how much is reserved, lot accounting, opening and closing\n"
		"figures - is an AccumulationRegister with `RegisterType` = balances. Read it through\n"
		"`<Register>.Balance` and `<Register>.Turnovers`; never compute a balance by summing\n"
		"movements yourself.\n"
		"\n"
		"The moment the words are an accountant's - an account, a correspondence, debit against\n"
		"credit - it is an AccountingRegister over a ChartOfAccounts with `Correspondence` on.\n"
		"Nothing else carries double entry, and imitating it with a pair of accumulation registers\n"
		"loses the one property that makes it accounting.\n"
		"\n"
		"KEY: THE WORDS THEY USE ALREADY CONTAIN A DESIGN - AND IT IS NOT THEIR DECISION TO HAVE MADE.\n"
		"An accountant saying \"lots of goods in warehouses\", \"write off by FIFO\", \"the receipt\n"
		"document of the batch\" is not describing a requirement: they are repeating the shape of a\n"
		"system they have used, and they will keep repeating it because it is the only one they have\n"
		"seen. Take it as a strong signal about their HABITS and a weak one about their NEEDS.\n"
		"\n"
		"STOP: SO DO NOT SILENTLY DECIDE EITHER WAY. Two mistakes, and the second is the common one:\n"
		" building what their words imply, because they said it - and inheriting a mechanism they\n"
		" never needed;\n"
		" building the cheaper design because it is better - and being wrong at the audit, when\n"
		" the policy really did say FIFO.\n"
		"\n"
		"* PUT THE FORK TO THEM, IN THEIR LANGUAGE, WITH THE CONSEQUENCE OF EACH. Not \"lots or\n"
		"average cost?\" - that asks them to know what you know - but \"do you ever need to say which\n"
		"delivery a particular item came from? if not, cost can be an average and the whole system\n"
		"is simpler; if yes, we keep the deliveries apart and it costs this much more\". People\n"
		"answer that immediately and correctly, because it is a question about their work rather\n"
		"than about the software.\n"
		"NOTE: AND SAY WHICH ONE YOU RECOMMEND. A fork offered without a recommendation is work handed\n"
		"back to somebody who came for an answer.\n"
		"\n"
		"KEY: AND A PROPERTY THAT CHANGES OVER TIME DOES NOT BELONG ON THE CATALOGUE ITEM AT ALL. This\n"
		"is the same rule as the first one above, applied where people least expect it: a fixed\n"
		"asset does not carry its cost, its useful life, its depreciation method, its state and its\n"
		"\"charge depreciation or not\" as attributes. Every one of those changes - modernisation\n"
		"raises the cost, a decision changes the method, the asset is put into service and later\n"
		"withdrawn - and every one of them is needed AS IT WAS at the moment being computed.\n"
		"\n"
		"So they live in information registers with periodicity, one per family of facts, and any\n"
		"calculation reads the LATEST ENTRY AS OF ITS OWN DATE. The item itself keeps only what\n"
		"never changes: what it is, its inventory number, what it is called.\n"
		"NOTE: THE TEST: \"if I recompute last year, must this value be last year's?\" If yes, it is a\n"
		"register entry, not an attribute - and putting it on the item means last year can never be\n"
		"recomputed, only remembered.\n"
		"* The same reasoning covers a person's position and salary, an item's tax rate, a\n"
		"warehouse's responsible person, an agreement's settlement rules. A catalogue is what a\n"
		"thing IS; a periodic register is what was TRUE about it at a time.\n"
		"\n"
		"AND WHEN THE REQUEST IS A VERB RATHER THAN A THING - \"load the statement\", \"upload to the\n"
		"portal\", \"recalculate the cost\", \"find and replace\", \"close the month\" - it is a DATA\n"
		"PROCESSOR. Told apart from its two neighbours by what it leaves behind:\n"
		" A DOCUMENT records that something HAPPENED and stays in the base as evidence of it,\n"
		" with movements behind it. If the event has a date, a number and consequences, it is a\n"
		" document however much work the entry takes.\n"
		" A REPORT only READS. It answers and changes nothing.\n"
		" A PROCESSOR ACTS and keeps nothing of its own: it creates documents, rewrites values,\n"
		" sends a file. Afterwards there is no trace of the processor itself, only of what it\n"
		" did - which is why what it did has to be visible before it does it (see\n"
		" `external-data` for the shape of a loading screen, and note the rule that nothing is\n"
		" written before the command).\n"
		"NOTE: THE MISTAKE IN BOTH DIRECTIONS: a \"month-end closing\" built as a processor leaves nobody\n"
		"able to say when the month was closed or to undo it - that is a document. And a document\n"
		"invented to carry the parameters of an import, posted for no reason and never looked at\n"
		"again, is a processor that was afraid to be one.\n"
		"* AND A TINY ONE NEEDS NO METAOBJECT AT ALL: \"recalculate this document's lines\", \"fill\n"
		"the table from the order\" is a COMMAND on the object it acts upon, living in its module.\n"
		"A processor earns its own existence when it works across many objects, or has parameters\n"
		"and a screen of its own.\n"
		"\n"
		"A CLOSED SET THE CODE ITSELF BRANCHES ON IS AN ENUMERATION - VAT rate, direction of a\n"
		"movement, state of an order. The test is not how many values there are but WHO MAY ADD\n"
		"ONE: nobody, because the code names them (`Enums.VatRates.Vat20`) and a value added by a\n"
		"user would be a value nothing knows what to do with. The moment somebody says \"and we will\n"
		"add our own kinds later\", it is a catalogue instead, and the code stops branching on\n"
		"identity - it reads an attribute of the row.\n"
		"NOTE: AND THE ENUMERATION HOLDS THE NAME, NOT THE NUMBER. The member is `Vat20`; that this\n"
		"currently means twenty percent is a fact of law, and it belongs in a function that maps the\n"
		"member to a figure - or, once the figure has to be right for OLD documents too, in an\n"
		"information register with periodicity (see `shapes` above and `printing`). Writing the\n"
		"number into the member's name is why systems end up with `Vat20` meaning eighteen.\n"
		"NOTE: AND ANYTHING THAT MUST BE STORED NEEDS AN ENUMERATION OF YOUR OWN, even where the\n"
		"platform already has a type for it. A platform's own kind-of-message, kind-of-severity or\n"
		"kind-of-status is usually not storable and cannot be compared across a connection; yours can\n"
		"sit in a register, in a saved report and in a filter.\n"
		"* So the two coexist and are CONVERTED AT THE DOOR, in one place per direction, and the old\n"
		"one is kept accepted for callers written before the split. That is the honest arrangement;\n"
		"what fails is storing the platform's value somewhere and discovering it later in a table\n"
		"nobody can query.\n"
		"\n"
		"STOP: AND DO NOT PROJECT A CLASSIFICATION INTO A STRING AND THEN COMPARE STRINGS. Whoever\n"
		"worked out what kind of thing this is should HAND BACK THE KIND, not a word for it. The\n"
		"shape of the mistake is unmistakable once seen: a long cascade deciding the class and\n"
		"returning text, then a second family of predicates comparing that text against literals -\n"
		"and, in the system measured, the same fact re-derived by four separate cascades over four\n"
		"different inputs, which disagreed about coverage and about whether they raised at all.\n"
		"* THE TEST: if a caller has to ask \"does this string end with…\" or \"is this string equal\n"
		"to…\", the answer it was given was the wrong shape.\n"
		"\n"
		"STOP: AND THE DEFAULT OF A HAND-WRITTEN CLASSIFICATION IS SILENCE, WHICH IS WHY ITS DEFECTS\n"
		"ARE NEVER REPORTED. A cascade of conditions that maps one set onto another - the account to\n"
		"its tax group, this designation against that one - answers \"nothing\" when no branch fires,\n"
		"and nothing is a legal value everywhere downstream: the row simply drops out of the\n"
		"calculation, or the pair is quietly judged admissible. Both were found live in one system,\n"
		"one of them caused by a single mistyped account in one branch.\n"
		"* SO A CORRESPONDENCE BETWEEN TWO SETS OF VALUES IS DATA - a table keyed by both sides, or an\n"
		"attribute on one of them - and where it must stay code, the final branch RAISES with the\n"
		"unmatched value named. A classification that cannot say \"I do not know this one\" cannot be\n"
		"tested at all.\n"
		"\n"
		"NOTE: AND A DATA PROCESSOR IS FOUR DIFFERENT GENERA, NOT \"A VERB\" - which is why \"it is a\n"
		"processor\" is not yet a design. Counted in a full system, they divide into: a WORKPLACE\n"
		"somebody lives in for hours (an order schedule, a purchasing calendar, a staffing board, a\n"
		"report console); a GATE OUTWARD (loading a statement, rates, a shop's orders); a BULK ACTION\n"
		"over a selection; a CONSTRUCTOR, where a person assembles data of a shape no object form can\n"
		"take; and only then the plain ACTION.\n"
		"* THE ONE WORTH RECOGNISING IN A REQUEST IS THE FIRST. \"I need a screen where I see it all at\n"
		"once and can click things\" is a WORKPLACE - not a report, which answers a question and\n"
		"changes nothing, and not a list form, which shows one kind of thing. Building it as a report\n"
		"is the commonest way that request is refused without anybody saying no.\n"
		"* AND A WORKPLACE HAS NO STORAGE OF ITS OWN: what it shows is read, what it does is done to\n"
		"real objects. If it starts wanting to remember something between sessions, that is a register\n"
		"and a setting per person (`user-settings`).\n"
		"\n"
		"NOTE: AND THE GENERAL FORM OF ALL OF THESE: \"I want to see it by month\", \"per warehouse\",\n"
		"\"as of a date\" is a request for a REGISTER of some kind. A catalogue or a document that\n"
		"someone reports over is the shape that has to be unpicked later, once the data is real.\n"
		"\n"
		"KEY: \"THE USER SHOULD BE ABLE TO ADD THEIR OWN KINDS, AND EACH KIND HOLDS A DIFFERENT SORT\n"
		"OF VALUE\" IS ITS OWN METATYPE. Colour is a word, expiry is a date, supplier is a reference -\n"
		"and the person, not the developer, decides which kinds exist. That is a chart of\n"
		"characteristic types, and it always comes as a PAIR: the KINDS live there, the VALUES live\n"
		"in an information register keyed by (object, kind). Counted in a working system, only three\n"
		"of ten such charts were accounting analytics - the rest were properties of objects,\n"
		"EXTRA PERMISSIONS beyond the roles, personal defaults, questionnaire questions, barcode\n"
		"types. One mechanism, and it is not about bookkeeping.\n"
		"\n"
		"KEY: A SETTING CAN BE A DOCUMENT, AND SOMETIMES SHOULD BE. Where a setting must have an\n"
		"effective DATE, an author and a history - which accounts this class of goods posts to, what\n"
		"the accounting parameters are from the first of the year - it is entered as a DOCUMENT and\n"
		"read as \"the one in force on this date\". A register keyed by period answers the same\n"
		"question; the document additionally gives a thing that can be printed, approved, entered on\n"
		"the basis of another and found in a journal. Decide by whether the CHANGE itself is an event\n"
		"somebody is accountable for.\n"
		"\n"
		"KEY: A STATE AND AN EVENT ARE TWO DIFFERENT SHAPES, AND THE DIFFERENCE IS WHO MAY ADD ONE. A\n"
		"STATE is a closed set the code branches on - taken on, in service, disposed of - so it is an\n"
		"ENUMERATION, and nobody adds to it without a release. AN EVENT is whatever the customer\n"
		"wants to record - an overhaul, an inspection, a repaint - so it is a CATALOGUE, and the\n"
		"thing the engine reacts to is not the item but its KIND attribute. Then a person may invent\n"
		"a fifteenth event and the code, which knows only the kinds, keeps working.\n"
		"* AND WHERE THE TWO MUST MEET - which event puts the object into which state - that is a\n"
		"small table, and it is the ONE hand-maintained seam between them. Keep it small and in one\n"
		"place; it is the part that rots.\n"
		"* A STATE OFTEN NEEDS ITS OWN DATE, separate from when the record was written: the order was\n"
		"signed on the 3rd and typed in on the 14th. Two dates, and the reports mean different things\n"
		"by them.\n"
		"\n"
		"KEY: BEFORE CREATING A NEW DOCUMENT, ASK WHETHER IT IS A KIND OF OPERATION OF AN EXISTING\n"
		"ONE. Most \"we also need a document for...\" requests are a variation of something already\n"
		"built: the same lines, the same checks, the same printing, differing in which registers are\n"
		"touched or which accounts are used. That is an OPERATION KIND - one enumeration attribute -\n"
		"and it buys the whole existing apparatus for nothing: the forms, the blanks, the rights, the\n"
		"reports, the entering-from, the exchange.\n"
		"* AND THE SAME MOVE WORKS SIDEWAYS, WHICH IS THE UNDERUSED ONE: a mechanism that already\n"
		"works in one area can often be CARRIED ACROSS to another and the new case distinguished by\n"
		"an operation kind. Goods handed to an agent and materials handed to a contractor for\n"
		"processing are the same movement of things that stay ours (`not-mine`); a job card and a\n"
		"production order are the same object with a different consumer. Look for the analogue\n"
		"before designing (`look-first`).\n"
		"* WHEN IT IS GENUINELY A NEW DOCUMENT: when the LINES are different in kind, when the life\n"
		"cycle differs (one is approved and the other is not), when different people must be allowed\n"
		"to see them, or when the two would appear in different journals for different jobs. Those\n"
		"are the four tests, and none of them is \"it feels different\".\n"
		"* THE COST OF OVERUSING IT is a document whose form is half hidden at any moment and whose\n"
		"posting is a tree of conditions on the kind. When the branches of the posting share almost\n"
		"nothing, the kinds have become separate documents wearing one name.\n"
		"\n"
		"NOTE: \"WHAT IS IT NOW\" AND \"HOW LONG WAS IT SO\" ARE TWO SHAPES OF THE SAME FACT. The state\n"
		"of an employee or an asset as of a date is a periodic register; how many days it stood in\n"
		"each state is a register of INTERVALS. A system that answers both usually keeps both\n"
		"(`query-craft`, `derived-registers`), and picking only one because they \"say the same thing\"\n"
		"is how a monthly calculation ends up recomputing intervals on every line.") },

	{ wxT("combining"),
	  ibMcpText("The handful of primitives every entry here is made of - and how a real request is assembled from several."),
	  ibMcpText("THE SAME DOZEN MOVES, UNDER DIFFERENT NAMES.\n"
		"\n"
		"Nearly every entry in this corpus is one of a small set of primitives applied to a\n"
		"different subject. Recognising WHICH primitive a request needs is faster than looking for\n"
		"an entry about that subject - and it is the only way to answer something no entry covers.\n"
		"\n"
		"A BOUNDARY - A MONOTONE MARK SAYING \"UP TO HERE EVERYTHING IS SETTLED\".\n"
		"It appears as the validity boundary of a calculation (`sequences`), as the date of the first\n"
		"document not yet fully posted (`deferred-posting`), as the freeze date of a plan\n"
		"(`planning`), as the closed shift (`production`), as the processed-up-to mark of a scheduled\n"
		"routine (`scheduled-documents`), and as the acknowledged message number between bases\n"
		"(`data-exchange`). Same object every time: cheap to advance, meaningful to move back, and\n"
		"THE THING TO SHOW A PERSON when they ask whether the figures are current.\n"
		"* WHENEVER A REQUEST INVOLVES \"RECALCULATE\", ASK WHERE ITS BOUNDARY IS. If there is none,\n"
		"the recalculation has no way to know what still needs doing.\n"
		"\n"
		"PRIORITY AS DATA, NOT AS BRANCHES.\n"
		"A user-chosen strategy never forks the algorithm - it supplies an ORDER. Matching debts\n"
		"oldest-first (`settlements`), choosing which specification applies (`bill-of-materials`),\n"
		"covering from stock before supplier orders (`planning`), falling back from a specific\n"
		"variant to any variant (`pricing`), personal before group before everyone\n"
		"(`user-settings`). Written as branches, each new case rewrites the resolver; written as a\n"
		"priority constant per branch of one union, a new case is one more branch.\n"
		"* AND THE SAME NUMBER OFTEN SERVES TWICE - AS THE ORDER AND AS THE CEILING. Where the modes\n"
		"nest - this deal only, this deal first then the free ones, anything at all - turn the mode\n"
		"into one integer, stand it in the ORDER BY and in the WHERE, and let a single loop run from\n"
		"the first rank up to that ceiling. Admissibility and preference are then one setting rather\n"
		"than a list plus a sort, and a new mode is a new rank in the same CASE.\n"
		"* IT HOLDS ONLY WHILE THE MODES NEST. Two modes admitting different sets, neither\n"
		"containing the other, need two columns; forcing them into one number gives an order nobody\n"
		"can read back.\n"
		"\n"
		"SUBTRACT YOURSELF.\n"
		"Anything that reads a total it also contributes to must remove its own contribution:\n"
		"re-filling an offset from balances the document already sits in (`settlements`), asking how\n"
		"much money is free while holding a reservation (`cash-flow`), asking whether a state was\n"
		"already recorded when you are the one recording it (`fixed-assets`), showing free stock in a\n"
		"selection list for the document being typed (`stock-control`). The symptom is always the\n"
		"same shape: \"it refuses because of itself\", or a figure that doubles on re-posting.\n"
		"\n"
		"DECLARE IT, DO NOT WRITE IT.\n"
		"A description held as data plus ONE mechanism that executes it: the fields a posting needs\n"
		"and which of them are mandatory (`posting`), the rule filling each cell of a statutory form\n"
		"(`regulated-forms`), the fields a report panel offers (`report-common-settings`), the recipe\n"
		"of an allocation base (`allocation`), what carries across when entering one document from\n"
		"another (`entered-from`), the condition of an offer (`promotions`). The test that it was\n"
		"done right: a new case is a new ROW, and several subsystems can each ADD to the same\n"
		"declaration without touching one another.\n"
		"\n"
		"KEEP THE DELTA BESIDE THE COMPUTED VALUE.\n"
		"Never overwrite what was computed with what a person corrected: hold both, and the\n"
		"recomputation survives by construction (`regulated-forms`). The same shape answers \"what\n"
		"changed\" as a difference of two stored states (`vat`), and \"what did it look like then\" as a\n"
		"snapshot compared at reading time (`object-history`).\n"
		"\n"
		"MATERIALISE WHAT IS ASKED FOR CONSTANTLY - WITH A SWITCH.\n"
		"A stored answer that adds no new fact: free balance (`derived-registers`), the allocation\n"
		"base (`allocation`), intervals beside a periodic register (`query-craft`), the index that\n"
		"makes documents restrictable (`row-level-access`), the placement of orders against supply\n"
		"(`planning`). Always the same four parts - a switch, a date it is trusted from, a routine to\n"
		"build it, a routine to remove it - and always a second truth to keep in step.\n"
		"\n"
		"CHECK THE OLD STATE AND THE NEW ONE.\n"
		"Anything guarding a transition must look at both sides: a document moving out of a closed\n"
		"period as well as into one (`closing-a-period`), out of a closed shift as well as into one\n"
		"(`production`), registered for the branch it is leaving as well as the one it is joining\n"
		"(`data-exchange`). Guarding only the new state misses exactly half the cases, and the half\n"
		"it misses is the one people do deliberately.\n"
		"\n"
		"AN EMPTY VALUE IS A MEANING, NOT AN ABSENCE.\n"
		"Empty dimension = accounting is not kept by it (`posting`); empty \"whose\" = everybody's\n"
		"(`user-settings`); empty company = travels to every base (`data-exchange`); no time-of-day\n"
		"row = always in force (`promotions`); the payment as its own settlement key = not yet\n"
		"allocated (`settlements`); empty value on a line = as in the header (`posting`).\n"
		"STOP: AND THE TRAP THAT COMES WITH IT - a composite-typed field has AS MANY EMPTIES AS IT\n"
		"HAS TYPES, and they are different values. Normalise before comparing (`settlements`).\n"
		"* SO \"IS IT FILLED IN\" IS A SET MEMBERSHIP, NOT A COMPARISON: build the set of empties from\n"
		"the field's DECLARED types - one per member, plus nothing-at-all - and test against it. A\n"
		"single function that yields the empty value of a simple type and an ARRAY for a composite\n"
		"one is worth having in the shared layer; every place that improvises this gets it right for\n"
		"the types it thought of.\n"
		"\n"
		"WHERE A VALUE CAME FROM IS DATA, NOT DECORATION.\n"
		"Colour it however you like - but do not STORE the answer there. Found twice in one system,\n"
		"which is what makes it a rule rather than an anecdote: the fill mode of a statutory cell is\n"
		"decided by comparing its background against literal colours, and a price that is a\n"
		"substitute rather than a real one is marked by painting it blue and nothing else. Both work\n"
		"until somebody changes a palette, adds a theme, or reads the data anywhere but on that\n"
		"screen.\n"
		"* THE TEST: could a report answer this question without the screen? If not, the fact is\n"
		"living in the paint. Keep the flag beside the value and let the colour RENDER it.\n"
		"STOP: AND THE SAME RULE FOR TEXT, WHICH IS THE COMMONER VERSION - A PRESENTATION IS NOT A\n"
		"KEY. Found three times in one system: a row's editability decided by searching for a word\n"
		"inside the document's displayed name, a resolution decided by comparing a cell against the\n"
		"translated words \"not found\", and a filter group identified by the caption shown to the\n"
		"person. All three work in one language, on one naming convention, until an item is renamed,\n"
		"the interface is translated, or a counterparty's name happens to contain the word. Branch on\n"
		"the TYPE, on a flag beside the value, on the identity - and in every one of those three cases\n"
		"the correct test already existed a few lines away.\n"
		"NOTE: AND WHERE A SHARED ROUTINE CALLS AN UNDER-SPECIFIED SERVICE, IT VALIDATES THE SHAPE OF\n"
		"THE ANSWER, NOT ONLY ITS SUCCESS. Found live and worth copying: a presentation service is\n"
		"asked for one value, and the caller checks that what came back is a collection, that it holds\n"
		"exactly one entry, that the entry is of the expected kind, and that its text is non-empty -\n"
		"and on any doubt returns the ordinary conversion of the value instead. Four cheap tests at\n"
		"one call site. The rule underneath: a routine everybody depends on may not propagate somebody\n"
		"else's surprise.\n"
		"\n"
		"A REFUSAL IS A FLAG PLUS A MESSAGE, NOT AN EXCEPTION.\n"
		"Collect every problem, name the line and the values, then refuse once (`posting`,\n"
		"`stock-control`, `lot-accounting`). And the message must name what the reader has to DO -\n"
		"which register to fill in (`fixed-assets`), how much is short and under which key\n"
		"(`stock-control`).\n"
		"KEY: AND THE WORDING ITSELF IS A SMALL TABLE, NOT FREE TEXT AT EACH SITE. Two words decide it\n"
		"- WHERE the problem is (a field, a column of a table, a whole list) and WHAT is wrong with it\n"
		"(not filled, not admissible) - and the pair picks one of six sentence templates, into which\n"
		"the field name, the row number and the caller's own explanation are substituted. A column's\n"
		"template mentions the row and the table; a list's mentions neither.\n"
		"* WHY IT IS WORTH THE TABLE: the wording is translated once instead of four hundred times,\n"
		"and a person reading a screenful of complaints sees six shapes rather than a different voice\n"
		"per author. Name the substitution slots - positional parameters where the second one means\n"
		"\"row number\" only by convention is how a list message ends up passing two empty strings and\n"
		"nobody noticing.\n"
		"STOP: AND SUBSTITUTE INTO A TEMPLATE BY SCANNING IT ONCE, NEVER BY REPLACING ONE PLACEHOLDER\n"
		"AFTER ANOTHER. A loop of replace-all passes has two failures nobody predicts: a value that is\n"
		"empty leaves its placeholder standing in the finished sentence, and a value that itself\n"
		"contains a placeholder is substituted again by a later pass. Both were live in the routine\n"
		"under every message in the system measured - the careful hand-written scanner was correct,\n"
		"the convenience form added later was not. And keep the substitution outside the translation\n"
		"call, not inside it, or the messages that use it drop out of whatever collects translatable\n"
		"text.\n"
		"\n"
		"A MESSAGE CARRIES AN ADDRESS.\n"
		"Not \"the quantity is wrong\" but a data key, a field, and a path down to the cell of a line -\n"
		"so the person is put ON the thing that is wrong. And the refusal flag only ever goes UP:\n"
		"nothing that has decided to refuse may un-refuse (`posting`, `stock-control`).\n"
		"* THE ADDRESS IS ONE DOTTED PATH, AND IT IS THE SAME VOCABULARY IN THREE PLACES - the address\n"
		"a message lands on, the path a filling rule writes through, and the key a saved setting is\n"
		"filed under. \"Object.Company\", \"Goods[7].Quantity\". One walker splits it and indexes down,\n"
		"and because all three mechanisms speak it, a message can land on exactly the cell a filling\n"
		"rule failed to fill.\n"
		"* THE ROW INDEX IS THE ROW NUMBER MINUS ONE, AND IT IS FORMATTED WITH GROUPING SUPPRESSED -\n"
		"row 1234 written as \"1 234\" addresses nothing, and the failure is silent. And the writer\n"
		"takes a \"do not overwrite\" switch, so filling defaults cannot step on what a person typed.\n"
		"* AND THE SAME CALL HAS THREE DESTINATIONS DEPENDING ON WHO IS LISTENING - the collector, a\n"
		"person's screen, or a RAISE when there is nobody at all. Accumulating messages where nobody\n"
		"will read the accumulator is a silent failure, and the check for it belongs in the reporting\n"
		"call rather than at every site (`closing-a-period`).\n"
		"* AND WHERE THERE IS A PANEL, THE MESSAGES ARE A TREE: a heading is a row of its own, each\n"
		"complaint hangs under it, and the posting call RETURNS the row it created so the caller can\n"
		"hang detail under that. Twenty complaints from four documents are then four collapsed rows\n"
		"instead of a scroll. A message also carries something to open - the object, or a short list\n"
		"of named targets - because the reader's next act is always to go there.\n"
		"STOP: AND WATCH WHAT THE FALLBACK DOES. Where the tree is not available the same call drops\n"
		"through to a flat window, and in the system measured that path kept only the errors and\n"
		"silently discarded everything informational. A message that exists in one client and not in\n"
		"another is worse than one that never existed: the person who reported it will not be\n"
		"believed.\n"
		"\n"
		"GUARD THE RELEASE EXACTLY AS YOU GUARDED THE ACQUIRE.\n"
		"Optional infrastructure is acquired behind a condition and released unconditionally, and the\n"
		"release then fails for the caller who declined it - found twice in one system: a temporary\n"
		"table manager created only when a flag was set and closed always, and an exclusive mode\n"
		"raised inside a guarded block whose error path lowered the OTHER state it had raised and left\n"
		"that one standing until the session ended.\n"
		"* THE TEST IS MECHANICAL: for every state raised, name the paths that leave the routine - the\n"
		"ordinary one, the refusal, the exception - and check each releases exactly what that path\n"
		"took. And where two states are raised in sequence, they are released in the other order, both\n"
		"of them. The cost of getting this wrong is not an error message; it is a base nobody can log\n"
		"into.\n"
		"\n"
		"FRESHNESS IS CHOSEN BY THE CALLER, NOT BY THE MECHANISM.\n"
		"The same answer is wanted fresh in one place and cached for the session in another, and only\n"
		"the caller knows which. Where that choice is made at the call site, staleness stops being a\n"
		"property of the mechanism and becomes a decision with a name on it.\n"
		"STOP: AND WHATEVER IS CACHED FOR A SESSION MUST BE TRUE FOR A SESSION. A reading of the\n"
		"database keyed by a reference does not qualify, however rarely it changes - it is the one\n"
		"found sitting in a session cache in a working system, beside four facts that genuinely\n"
		"cannot change.\n"
		"* THE MECHANISM FOR CHOOSING AT THE CALL SITE IS A CACHE PASSED AS AN ARGUMENT, NOT HELD IN A\n"
		"MODULE. The caller that loops passes one and keeps it for the loop; the caller that asks once\n"
		"passes none and the routine reads. Lifetime is then written at the call site, in a name the\n"
		"reader can see.\n"
		"STOP: AND A CACHE THAT IS ONLY EVER READ IS NOT A CACHE. Found live: a lookup that consulted\n"
		"the structure it was handed, ran the query on a miss, returned the row and never inserted it\n"
		"- so every key that missed missed again on every pass. Whoever reads the cache must write it,\n"
		"in the same routine; a fill left to callers is a fill that happens in one of them.\n"
		"STOP: AND WHATEVER IS CACHED MUST BE HANDED OUT FROZEN. A cached routine that returns a\n"
		"structure, a map or a table hands EVERY caller the same object, so the first caller that\n"
		"edits it - sorts it, adds a key, clears a column - has changed what every later reader sees,\n"
		"in a place none of them can find. The defect presents as a value that is right the first time\n"
		"it is read and wrong afterwards. Freezing must be DEEP to be a defence at all: a frozen outer\n"
		"structure holding a live inner one protects nothing; and what may go inside is a decided list\n"
		"of value kinds - the primitives, identities, references - with anything else refused by name\n"
		"at the moment of freezing rather than discovered later.\n"
		"\n"
		"KINDS THE USER MAY ADD, EACH WITH A VALUE.\n"
		"Kinds in one place, values in a register keyed by (subject, kind): properties of items,\n"
		"extra permissions (`roles`), personal defaults, analytics of a ledger (`shapes`).\n"
		"\n"
		"---\n"
		"\n"
		"KEY: AND A REAL REQUEST IS ALWAYS SEVERAL OF THESE AT ONCE. Two worked examples of the\n"
		"assembly, because that is the skill this corpus is for.\n"
		"\n"
		"\"I WANT TO SEE HOW MUCH IS FREE, AND NOT LET THEM SELL BELOW IT.\"\n"
		" the shape: a balance register, read through its balance (`shapes`)\n"
		" the free figure: on hand minus reserved minus due out (`stock-control`)\n"
		" if that check is slow: a derived register with its four-part switch (`derived-registers`)\n"
		" the selection list must subtract the document being typed (`combining`: subtract yourself)\n"
		" the refusal: a flag and a message naming every dimension of the key (`stock-control`)\n"
		" who may exceed it: a permission with a value, asked INSIDE the check (`roles`)\n"
		" and the check runs privileged, so the rights it bypasses must be checked by hand\n"
		" (`row-level-access`).\n"
		"\n"
		"\"CLOSE THE MONTH AND GIVE ME THE FIGURES.\"\n"
		" the order of the close is part of the design, and it is computed, not declared\n"
		" (`production`)\n"
		" every cost spread by a base that must be SHOWABLE, so materialise it (`allocation`)\n"
		" the policy is read as of the month's end, from a register, per company (`constants`)\n"
		" anything entered backdated has invalidated part of it - which part is the boundary\n"
		" (`sequences`), and the heavy postings may be queued (`deferred-posting`)\n"
		" the month is then frozen, and the freeze must cover direct writes to registers too\n"
		" (`closing-a-period`, `cross-cutting-hooks`)\n"
		" the reports over the result are one family with a shared shape (`ledger-reports`), every\n"
		" cell leads to the next report (`report-shapes`), and the reader's own period and company\n"
		" live in a panel above them (`report-common-settings`).\n"
		"\n"
		"STOP: A SHARED ROUTINE THAT CHANGES WHAT IT WAS GIVEN MUST SAY SO IN ITS NAME, OR NOT DO IT.\n"
		"This is the commonest defect in a mature shared layer, and it is always found by somebody\n"
		"debugging something else. Counted in one such layer: a set operation that collapsed BOTH\n"
		"input tables in place, a rounding helper that rewrote its caller's number, a de-duplicator\n"
		"that also replaced unfilled values with nothing and returned the same collection it mutated,\n"
		"an optional argument replaced with a fresh empty one when the caller passed none, and a\n"
		"reporting helper that BLANKED the caller's heading so the next tier would not reprint it.\n"
		"* THE LINE IS NOT \"NEVER MUTATE\" - the last shape in that list is the disciplined one: a\n"
		"collector handed to a flush routine is CLEARED by it, and that clearing is the contract,\n"
		"stated in the note, which is what makes the collector safe to reuse. Mutation as a documented\n"
		"contract is fine. Mutation as a side effect of a routine named after something else is a\n"
		"defect with no symptom.\n"
		"\n"
		"NOTE: WHEN A REQUEST MATCHES NO ENTRY, IT USUALLY MATCHES A PRIMITIVE. Ask which of the ten\n"
		"above it is - a boundary, a priority, a declaration, a delta, a materialisation - and build\n"
		"THAT, in the subject the person is talking about. The entries here are those primitives\n"
		"already applied; the list above is what they are made of.\n"
		"\n"
		"STOP: AND ASK WHAT CONSTRAINT PRODUCED A SHAPE BEFORE INHERITING IT. Most of what is written\n"
		"here was learned in systems built under limits that were real at the time and may not be\n"
		"real now - no window functions, expensive joins, a column budget per table, a base that had\n"
		"to be walked in document order because nothing could solve. A shape that exists to get\n"
		"around a limit is not the same kind of knowledge as a shape that exists because the trade\n"
		"works that way, and the two read identically once the reason has been forgotten.\n"
		"* THE TEST IS ONE QUESTION: WOULD ANYBODY CHOOSE THIS IF THEY WERE STARTING TODAY? Folding\n"
		"eight dimensions into one interned key buys width that a modern engine may not be short of.\n"
		"Sequences and boundaries of validity exist because cost is WALKED in document order - solve\n"
		"it as simultaneous equations instead and the whole machinery has nothing to do\n"
		"(`sequences`, `derived-registers`). A running total maintained by hand is a window function\n"
		"somewhere else. Each of those is correct advice for the world it came from.\n"
		"* SO INHERIT THE DECISION, NOT THE ERA. What survives every era is the FORK and its PRICE -\n"
		"which is why every entry here states both, and why an entry that only described a mechanism\n"
		"would be worthless the moment the mechanism aged.\n"
		"* AND SAY IT WHEN YOU NOTICE IT: \"this is how it was done, here is what it was working\n"
		"around, and that constraint is gone\" is a better answer than either copying the old shape or\n"
		"quietly ignoring it. It is also how a genuine improvement gets found - almost every one\n"
		"begins as somebody asking why a step is there.") },

	{ wxT("intake"),
	  ibMcpText("Taking a request: which questions to ask, in what order, and how to offer the options back."),
	  ibMcpText("TAKING A REQUEST FROM SOMEBODY WHO KNOWS THE TRADE AND NOT THE SYSTEM.\n"
		"\n"
		"They will not describe a design. They will describe a day at work, name a document they\n"
		"have seen elsewhere, or ask for a field. The job is to get from that to a shape - and to do\n"
		"it in ONE conversation, not by delivering something and being corrected.\n"
		"\n"
		"KEY: THE FIRST PASS IS FOUR QUESTIONS AND NONE OF THEM IS TECHNICAL.\n"
		" WHAT IS COUNTED, AND WHAT IS ASKED ABOUT IT - how much is left, or how much happened over\n"
		" a period? (`shapes`)\n"
		" WHAT CHANGES OVER TIME AND MUST STILL BE TRUE FOR AN OLD MONTH? (`shapes`: periodic\n"
		" register, never an attribute)\n"
		" WHOSE OBLIGATION IS OPEN, AND WHAT CLOSES IT? (`orders`, `document-chains`)\n"
		" WHO MAY DO IT, AND WHO MAY SEE IT? (`roles`, `row-level-access`)\n"
		"Four answers name most of the metatypes. Ask them in the person's own words, about their\n"
		"own work, and never ask which metatype they want.\n"
		"\n"
		"KEY: THEN SEARCH YOUR OWN STOCK BEFORE DESIGNING ANYTHING. In order:\n"
		" IS IT A KIND OF OPERATION OF SOMETHING THAT EXISTS? (`shapes`) The cheapest answer by far.\n"
		" IS IT THE MIRROR OF SOMETHING THAT EXISTS - the other direction of a cycle? (`orders`)\n"
		" IS IT A LINK OF A CHAIN ALREADY BUILT - an intention, a fact, a reversal?\n"
		" (`document-chains`)\n"
		" IS IT A KNOWN SHAPE IN UNFAMILIAR WORDS? (`unfamiliar-domain`)\n"
		" IS IT ONE OF THE PRIMITIVES - a boundary, a priority, a declaration, a delta, a\n"
		" materialisation? (`combining`)\n"
		"Only when all five come back empty is something genuinely new being asked for, and that is\n"
		"rare enough to be worth saying out loud when it happens.\n"
		"\n"
		"KEY: PUT THE FORK BACK TO THEM IN THEIR LANGUAGE, WITH THE PRICE OF EACH SIDE. Not \"lots or\n"
		"average\" but \"do you need to know which delivery a particular item came from - and are you\n"
		"willing to enter it every time?\" Two options, what each costs them in daily work, and WHICH\n"
		"ONE YOU RECOMMEND. A fork offered without a recommendation is work handed back.\n"
		"* AND OFFER AT MOST TWO OR THREE. A list of five options is a refusal to decide, and they\n"
		"will pick the one that sounds most complete.\n"
		"\n"
		"KEY: THE QUESTIONS WORTH ASKING ARE THE ONES WHOSE ANSWERS CHANGE THE DESIGN. In practice\n"
		"they are always these:\n"
		" \"Does this ever differ per company, or change from a date?\" - constant or register\n"
		" (`constants`).\n"
		" \"If I recompute last year, must this come out as it was then?\" - periodic or not.\n"
		" \"Can two people be doing this at the same time?\" - locking and free-balance checks\n"
		" (`posting`).\n"
		" \"Will anyone enter this backdated?\" - a boundary, and everything that follows\n"
		" (`sequences`).\n"
		" \"Does the same rule apply on a transfer, or a return?\" - document rule or mechanism rule\n"
		" (`where-behaviour-lives`).\n"
		" \"What happens when it is not enough / not approved / already closed?\" - the refusal is\n"
		" part of the design, not an afterthought.\n"
		"\n"
		"STOP: AND THREE THINGS NOT TO DO IN THIS CONVERSATION.\n"
		" DO NOT ANSWER OUT OF ANOTHER SYSTEM'S FLUENCY. Concepts from elsewhere have familiar\n"
		" names here and different edges, and an imported design reads as competence right up until\n"
		" it is built.\n"
		" DO NOT DESIGN THE WHOLE THING FROM ONE SENTENCE. Take the area they are actually in,\n"
		" prove it (`building-an-erp`: each step has a DONE WHEN), and let the next area be asked\n"
		" for.\n"
		" DO NOT SILENTLY DECIDE A FORK BECAUSE ONE SIDE IS EASIER TO BUILD. That is the decision\n"
		" they will discover last and mind most.\n"
		"\n"
		"NOTE: AND WHEN THE ANSWER IS \"THIS ALREADY EXISTS HERE\", SAY SO AND SHOW IT rather than\n"
		"building a second one (`look-first`). Half of what is asked for is a mechanism the system\n"
		"already has under a name nobody in the room recognised.\n"
		"\n"
		"KEY: AND SAY WHICH OF THE TWO KINDS OF KNOWLEDGE AN ANSWER CAME FROM. Whoever reads this has\n"
		"a whole trade in their own head as well - lead times, safety stock, finite capacity, other\n"
		"schools of accounting - and that knowledge is broader than this corpus by a wide margin. Use\n"
		"it. But the two are not the same kind of thing: general knowledge is SHAPES WITHOUT SCARS.\n"
		"It knows the ten ways something can be done; it does not know which one is taken four\n"
		"hundred times against sixty, what the wrong one costs on a Tuesday in March, or that the\n"
		"guard everybody writes has a hole in it exactly where a revaluation happened.\n"
		"* SO THEY COMPOSE, IN ONE DIRECTION: the wider knowledge supplies what EXISTS in the world,\n"
		"this corpus supplies what it COSTS and how it FAILS. Reaching outside for a shape nobody\n"
		"here has written down is right, and so is bringing it back through the questions this corpus\n"
		"asks of everything - what does it need from a platform, what is the sign it was applied in\n"
		"the wrong place, what is the price nobody mentions.\n"
		"STOP: AND THE DANGER IS FLUENCY, NOT IGNORANCE. An answer assembled from general knowledge\n"
		"reads exactly as confident as one measured against a system that runs, and the person asking\n"
		"cannot tell them apart - which makes a confident answer in an area this corpus is silent on\n"
		"worse than an admitted gap, because a gap is visible and a fluent guess is not. Mark it in\n"
		"one clause: \"this part is checked against a working system; this part is ordinary practice\n"
		"and is not\". It costs a sentence and it is the whole difference between advice and\n"
		"performance.\n"
		"\n"
		"KEY: AND WHEN THE ANSWER IS \"THIS CANNOT BE BUILT HERE YET\", SAY THAT OUT LOUD, IN THE SAME\n"
		"BREATH AS THE DESIGN. A pattern here states WHAT IT NEEDS FROM A PLATFORM - a declared\n"
		"subscription, a job in the metadata, an interned key, a register that computes over a period\n"
		"of action. It does not know what any particular engine has, and it must not: the day the\n"
		"engine gains the feature, a pattern that reported its absence has become wrong.\n"
		"* SO THE COMPARISON IS YOURS TO MAKE, EVERY TIME, AND IT IS THREE SENTENCES: what the shape\n"
		"needs; whether anything here provides it - go and look, do not assume; and if not, whether\n"
		"it can be worked around and at what price. \"It can be done, by hand, and here is the cost\"\n"
		"and \"it cannot be done until the engine has X\" are different answers and both are useful.\n"
		"* NAME THE MISSING PIECE AS A PIECE OF WORK, not as a complaint: which mechanism, what it\n"
		"would have to do, and what is impossible without it. That sentence is a request for work\n"
		"someone can act on - which is the only form in which a gap is worth mentioning at all.\n"
		"STOP: AND DO NOT QUIETLY BUILD A WEAK IMITATION INSTEAD. Answering \"we have no calculation\n"
		"engine\" with a document that computes pay once and stores the number is not a smaller\n"
		"version of the feature - it is a system that cannot recompute a corrected month, and nobody\n"
		"is told until the first correction. Say the limit, offer the honest smaller thing, and let\n"
		"somebody decide.") },

	{ wxT("where-behaviour-lives"),
	  ibMcpText("\"Make it do X in the sales document\" - and X lives in a mechanism shared by twenty documents."),
	  ibMcpText("THEY NAME THE DOCUMENT THEY SEE; THE BEHAVIOUR IS SOMEWHERE ELSE.\n"
		"\n"
		"\"In the sales document I want it to...\" - and the thing they want is not in that document\n"
		"and never was. A document is a SHELL: it collects what a person typed, and hands it to\n"
		"mechanisms that are shared by every other document (`posting`: the document does not know\n"
		"how, it hands its tables to whoever owns each register). Half of what a person attributes to\n"
		"\"the sales document\" is executed by stock costing, by settlements, by tax, by the month-end\n"
		"close - and some of it does not run at posting time at all.\n"
		"\n"
		"KEY: SO THE FIRST QUESTION IS NOT \"WHERE IN THIS DOCUMENT\" BUT \"WHOSE RULE IS THIS\". Three\n"
		"answers, three different places, and picking wrong is the whole problem:\n"
		" A RULE OF THIS DOCUMENT ONLY - \"equipment may not be sold on this kind of contract\". Lives\n"
		" in the document, and nowhere else needs it.\n"
		" A RULE OF A MECHANISM - how a cost is written off, how a debt is matched, how tax is\n"
		" designated, how stock is checked. Lives in the mechanism, and changing it changes EVERY\n"
		" document that uses it. That is usually what the person actually wants, and they do not\n"
		" know they are asking for it.\n"
		" A RULE OF THE OBJECT BEING TRADED - shelf life, units, whether it is tracked by series.\n"
		" Lives on the item or its settings, and every document inherits it.\n"
		"* THE QUESTION THAT SEPARATES THEM, IN THEIR LANGUAGE: \"and if the same thing happens on a\n"
		"transfer, or on a return - should it behave the same way?\" A yes means it is not a rule of\n"
		"this document.\n"
		"\n"
		"STOP: PUTTING A MECHANISM'S RULE INTO ONE DOCUMENT IS THE MOST EXPENSIVE MISTAKE IN THIS\n"
		"WHOLE CORPUS, AND IT LOOKS LIKE THE CHEAPEST FIX. It works, it ships, and then the same rule\n"
		"is copied into the next document a month later, and the two copies disagree within a year.\n"
		"The reverse error is louder but cheaper: changing a shared mechanism for one document's sake\n"
		"breaks nineteen others, and you find out immediately.\n"
		"\n"
		"KEY: AND SOME OF WHAT THEY ASK FOR CANNOT HAPPEN AT POSTING TIME AT ALL. \"Show me the profit\n"
		"on this sale\" - the cost of what was sold is not known when the sale is posted; it is\n"
		"resolved over the whole chain at the close (`lot-accounting`, `production`). \"Why is the\n"
		"figure zero in my document\" is then not a defect of the document: the answer belongs to the\n"
		"month-end, and the honest reply names WHEN the figure appears and what makes it appear.\n"
		"* THE SAME FOR TAX ADJUSTMENTS THAT DEPEND ON HOW SOMETHING WAS EVENTUALLY USED (`vat`), FOR\n"
		"COST ADJUSTED BY A CYCLE OF MUTUAL TRANSFERS (`production`), AND FOR ANYTHING BEHIND A\n"
		"DEFERRED POSTING (`deferred-posting`). A request that assumes an immediate answer to a\n"
		"question that is only answerable in a batch is a request to redesign the accounting, not to\n"
		"edit a document.\n"
		"\n"
		"KEY: A ROUGH MAP OF WHERE THINGS ACTUALLY LIVE, for reading a request:\n"
		" what the lines cost -> costing and lots, resolved at the close\n"
		" who owes what -> settlements, keyed by the contract's own settings\n"
		" is there enough -> stock control, run privileged, before the write\n"
		" which accounts -> a settings document read as of the date, not typed in\n"
		" tax treatment -> a designation travelling with the line\n"
		" what the person may do -> roles and permissions, asked inside the check\n"
		" what it prints -> a command on the object, with its own blanks\n"
		" what may be edited -> the prohibition date, on the write, for every kind of register\n"
		" what the numbers look like -> prefixes and series\n"
		"None of these is \"in the sales document\", and all of them are reached FROM it.\n"
		"\n"
		"KEY: A MECHANISM SERVING DOZENS OF DOCUMENTS ASKS THE METADATA WHAT EACH ONE HAS, rather\n"
		"than keeping a list of which document carries which field. \"Has this document a price\n"
		"column here? a discount? a planned cost?\" - probe, and recalculate whatever is present. It\n"
		"is what lets one routine serve documents whose columns overlap without being equal, and it\n"
		"is why adding a column to a document sometimes changes behaviour with no code written at\n"
		"all (`shapes`: a hand-kept list of participants is a defect).\n"
		"* THE COST IS THAT THE CONTRACT IS INVISIBLE - nothing declares which fields the mechanism\n"
		"will use if it finds them. Write that list down beside the mechanism; it is the only place\n"
		"it exists.\n"
		"\n"
		"NOTE: AND THE WORDS FOR THE SHELL VARY WHILE THE SHELL DOES NOT. Sale, shipment, issue,\n"
		"invoice, dispatch note, act, hand-over - one link of one chain (`document-chains`). Do not\n"
		"spend the conversation agreeing on the noun; ask what it must MOVE, and what must be true\n"
		"before it may.\n"
		"\n"
		"NOTE: SO THE USEFUL REPLY TO \"ADD X TO THE SALES DOCUMENT\" HAS THREE PARTS: where the rule\n"
		"actually belongs, who else it will affect if put there, and - when the answer is the close\n"
		"rather than the document - when the figure they want becomes knowable at all.") },

	{ wxT("document-chains"),
	  ibMcpText("Intention, fact, reversal - the one chain behind every \"order, delivery, return\", whatever it is called."),
	  ibMcpText("EVERY AREA IS THE SAME CHAIN OF THREE LINKS.\n"
		"\n"
		"An order to a supplier, then a receipt, then a return. An order from a customer, then a\n"
		"shipment, then a return. A spending request, then a payment. A production order, then\n"
		"output, then scrap. Different words, one chain: AN INTENTION, THE FACT THAT FULFILS IT, AND\n"
		"A REVERSAL THAT UNDOES PART OF THE FACT. Recognising which link is being described is worth\n"
		"more than knowing the trade, because each link has fixed properties.\n"
		"\n"
		"KEY: THE INTENTION MOVES NOTHING THAT IS OWNED. It books a promise: demand to be met, stock\n"
		"held back, money committed, capacity taken. It is read as a BALANCE - what of it is still\n"
		"outstanding (`orders`) - and it must be closable both by fulfilment and by abandonment\n"
		"(`orders`: closing is a mirror movement, not a status).\n"
		"* PEOPLE CALL IT: order, request, application, booking, reservation, pre-order, quotation,\n"
		"claim, requisition, plan, commitment, allocation. All the same link. If the thing being\n"
		"described creates an expectation and does not change what anyone owns, it is this one.\n"
		"\n"
		"KEY: THE FACT MOVES OWNERSHIP AND MONEY, AND IT DISCHARGES THE INTENTION BY READING ITS\n"
		"BALANCE. Filling a delivery from an order reads what is STILL OUTSTANDING, never the order's\n"
		"lines (`entered-from`) - which is why partial fulfilment needs no counter and no \"partly\n"
		"done\" status anywhere.\n"
		"* PEOPLE CALL IT: receipt, delivery, shipment, issue, sale, invoice, act, hand-over,\n"
		"payment, output, write-off.\n"
		"* AND THE FACT MAY ARRIVE WITHOUT AN INTENTION - somebody just delivers. The chain must work\n"
		"with the first link missing, or every walk-in sale needs a fake order.\n"
		"\n"
		"KEY: THE REVERSAL IS ITS OWN LINK, NOT A NEGATIVE FACT. A return has its own operation kind,\n"
		"its own document and often its own rules - which lot it goes back into (`lot-accounting`),\n"
		"which debt it moves (`settlements`), whether it re-opens the intention it came from. Written\n"
		"as a fact with a minus sign, it understates both sides of every turnover report and is\n"
		"invisible to \"how much did we actually ship\".\n"
		"* PEOPLE CALL IT: return, refund, credit note, reversal, correction, scrap, write-back,\n"
		"cancellation.\n"
		"\n"
		"KEY: SO WHEN SOMEBODY DESCRIBES ONE LINK, ASK ABOUT THE OTHER TWO. \"How does a supplier\n"
		"order work\" is answered in full only with: what does it reserve or expect, what discharges\n"
		"it and by how much, what happens when goods come back, and what closes it when the deal\n"
		"falls through. Four questions, and they are the same four in every area.\n"
		"* AND ASK WHETHER A LINK IS DELIBERATELY ABSENT. Some businesses have no intention link at\n"
		"all (over-the-counter), some have two (a quotation and then an order), some have a reversal\n"
		"that is legally a different document. Absence is a design decision worth confirming, not an\n"
		"omission to be filled in silently.\n"
		"\n"
		"KEY: THE LINKS ARE JOINED BY BALANCES, NOT BY POINTERS. Each link writes to a register that\n"
		"the next one reads; the reference from one document to another is for people and for\n"
		"navigation. A chain built on references alone cannot answer \"how much is still outstanding\"\n"
		"without walking every document, and it breaks the moment two documents partly fulfil one\n"
		"intention.\n"
		"* AND WHOEVER SPEAKS FIRST OWNS THE MOVEMENT. Where the intention already records the\n"
		"obligation, the fact must not record it again (`cash-flow`). Decide once, per register,\n"
		"which link owns it.\n"
		"\n"
		"NOTE: THE CHAIN ALSO TELLS YOU WHERE THE CONTROLS GO. Availability and credit are checked\n"
		"when the INTENTION is made and again when the FACT is written, because the world moved in\n"
		"between (`stock-control`). Approval sits on the intention (`orders`). The prohibition date\n"
		"and the sequence boundary belong to the fact, because that is what the books are made of\n"
		"(`closing-a-period`, `sequences`). Putting a control on the wrong link is the commonest\n"
		"reason a rule \"does not work\": it fires where nobody is, or too late to matter.\n"
		"\n"
		"NOTE: AND THE SAME CHAIN APPEARS OUTSIDE TRADE, WHICH IS THE POINT. Hiring: a vacancy, an\n"
		"engagement, a dismissal. Maintenance: a job request, the work done, a re-do under warranty.\n"
		"Lending: a facility, a drawdown, a repayment. Whenever three documents in a row are\n"
		"described, check whether they are these three - they usually are.") },

	{ wxT("unfamiliar-domain"),
	  ibMcpText("A trade nobody here knows - logging, catering, haulage - is almost always a known pattern plus small differences."),
	  ibMcpText("A TRADE YOU HAVE NEVER SEEN IS USUALLY ONE YOU HAVE.\n"
		"\n"
		"Somebody asks for a system for logging, or a bakery, or a car workshop, and none of the\n"
		"words in the request appear anywhere in this corpus. That is almost never a new problem. It\n"
		"is one of the shapes here, wearing the vocabulary of that trade, PLUS TWO OR THREE GENUINE\n"
		"DIFFERENCES - and the whole skill is telling those apart.\n"
		"\n"
		"KEY: ASK THE FOUR QUESTIONS THAT STRIP THE VOCABULARY AWAY.\n"
		" 1. WHAT COMES IN, WHAT GOES OUT, AND DOES ONE BECOME THE OTHER? If yes, it is\n"
		" `production` - whatever it is called locally.\n"
		" 2. WHAT IS COUNTED, AND WHAT MUST BE ANSWERED ABOUT IT - how much is left, or how much\n"
		" happened over a period? That names the register (`shapes`).\n"
		" 3. WHAT CHANGES OVER TIME AND MUST BE REPRODUCIBLE FOR AN OLD MONTH? Periodic register,\n"
		" never an attribute.\n"
		" 4. WHOSE OBLIGATION IS OPEN, AND WHAT CLOSES IT? That is `orders` and `settlements`.\n"
		"Four answers usually name every metatype the system needs, before anybody has learned what\n"
		"the trade's words mean.\n"
		"\n"
		"WORKED EXAMPLE - LOGGING, because it looks nothing like a factory and is one.\n"
		" A felling site is an ORDER: work is booked against it, costs collect on it, and it closes\n"
		" (`orders`).\n"
		" Cutting a stem into logs is a SPECIFICATION RUN BACKWARDS: one input, several outputs of\n"
		" different grades. The corpus already has that - it is by-products (`bill-of-materials`),\n"
		" and the cost of the stem is spread over the outputs exactly like a kit being broken up\n"
		" (`promotions`: distribute every numeric column proportionally, remainder to the last row).\n"
		" Tops and sawdust are RETURNABLE WASTE, carrying an amount, not products.\n"
		" Grade is a VARIANT of the item, and volume-versus-weight is a UNIT with a coefficient and\n"
		" its own rounding policy (`pricing`).\n"
		" Standing timber that has not been felled is stock in a place you do not own yet; timber\n"
		" felled and not hauled is GOODS IN TRANSIT (`stock-control`), and it is the case everyone\n"
		" forgets.\n"
		" Machines are `fixed-assets`, and their depreciation is by OUTPUT, not by month - the\n"
		" corpus lists that method already, with the note that it has no annual figure.\n"
		" Season is not a special case: it is the month's share of an annual sum (`fixed-assets`).\n"
		"THE GENUINE DIFFERENCES, and there are only about three: the yield of grades is known only\n"
		"AFTER cutting, so the specification is a norm and the actual output is a fact - which means\n"
		"a variance, and the variance is where the trade's money is; measurement is by convention\n"
		"(a table converting dimensions to volume), so THE CONVERSION RULE IS DATA, not arithmetic;\n"
		"and the felling licence is a quota - a balance register that must not go negative, which is\n"
		"`stock-control` with a different noun.\n"
		"\n"
		"OTHER TRANSLATIONS, IN ONE LINE EACH - the point being how few shapes there are.\n"
		" A KITCHEN: a recipe is a specification, a dish is output, portioning is units with\n"
		" coefficients, waste and trimming are returnable waste, shelf life is a series with a date.\n"
		" A WORKSHOP: a job card is an order; labour and parts are the two kinds of line on it; a\n"
		" warranty job is the same job with a different payer.\n"
		" HAULAGE: a trip is an order, fuel norms are a specification against distance, the vehicle\n"
		" is an asset depreciated by output, the driver's hours are a periodic state (`shapes`).\n"
		" CONSTRUCTION: a site is a long-running order, work in progress is the whole subject\n"
		" (`production`), stages are route stages, and retention is a debt that falls due later\n"
		" (`settlements`).\n"
		" RENTING THINGS OUT: the object is an asset; the charge is a scheduled document\n"
		" (`scheduled-documents`); the rate is a periodic register; the deposit is an advance\n"
		" (`settlements`).\n"
		" FARMING: a field is an order, a harvest is output with by-products, the yield is known\n"
		" after the fact - the same variance as logging.\n"
		"\n"
		"STOP: THE MISTAKE IS TO BUILD A NEW METATYPE FOR THE TRADE'S OWN WORD. \"We need a Felling\n"
		"Site object\", \"we need Recipes\", \"we need a Trip document\" - all of those are catalogues,\n"
		"documents and registers you already know, and calling the metatype after the trade buys\n"
		"nothing while losing every mechanism that already works on the general shape: reporting,\n"
		"rights, exchange, closing a period. NAME THE OBJECT in the customer's language\n"
		"(`naming`: the synonym is their words); keep the SHAPE the one it actually is.\n"
		"\n"
		"KEY: AND THE DIFFERENCES THAT ARE REAL FALL INTO THREE KINDS, WHICH IS WHY THEY ARE EASY TO\n"
		"MISS AND EASY TO HANDLE ONCE NAMED.\n"
		" A CONVERSION RULE THAT IS DATA - board-feet from dimensions, litres per hundred\n"
		" kilometres, grams to portions. It looks like arithmetic and it is a table, dated, because\n"
		" it changes by regulation or by agreement.\n"
		" A NORM AGAINST WHICH THE ACTUAL IS COMPARED - yield, consumption, hours. Wherever the\n"
		" outcome is known only afterwards, the trade lives on the VARIANCE, and the system must\n"
		" carry both figures and report the difference. This is the single most common thing that\n"
		" is missing from a first design.\n"
		" A LEGAL OR PHYSICAL LIMIT - a quota, a licence, a capacity, a shelf life. Every one of\n"
		" them is a balance that must not go negative, or a date that must not be passed, and both\n"
		" are already here (`stock-control`, `closing-a-period`).\n"
		"\n"
		"NOTE: SO THE ANSWER TO \"DO YOU KNOW THIS INDUSTRY\" IS HONEST AND USEFUL AT ONCE: the shapes\n"
		"are the same, the words are yours, and what I need from you is the three or four places\n"
		"where your trade genuinely differs - the conversions, the norms, the limits. Asking for THAT\n"
		"rather than for a description of the business gets a usable design in one conversation.") },

	{ wxT("predefined"),
	  ibMcpText("A particular item named in conversation has to exist as a predefined one."),
	  ibMcpText("A NAMED INSTANCE IS A PREDEFINED ITEM.\n"
		"\n"
		"When someone says \"for the Central warehouse\", \"the VAT rate\", \"the main cash desk\" -\n"
		"naming a PARTICULAR item rather than a kind of item - that item has to exist as predefined.\n"
		"\n"
		"The reason is identity. Code has no other stable handle on a single row: without a\n"
		"predefined name it has to go and find the row by name or by code, and then a rename, a\n"
		"typo, or a second row that happens to share the name turns the lookup into a silent wrong\n"
		"answer rather than an error. A predefined item is named in the metadata and reached by that\n"
		"name, and the name is checked when the configuration is applied.\n"
		"\n"
		"The signal is grammatical: a definite article, a proper name, \"the\" rather than \"a\". If\n"
		"the sentence would still be true of any row of that catalogue, it is not this pattern.\n"
		"\n"
		"KEY: A PREDEFINED ITEM LIVES IN TWO PLACES AT ONCE, and everything awkward about it follows\n"
		"from that. It is declared in the CONFIGURATION and it exists as a ROW IN THE DATA, and the\n"
		"two are tied by a NAME the row carries in a standard attribute of its own. There is a\n"
		"second standard attribute beside it - a flag saying the row is predefined at all.\n"
		"\n"
		"WHAT THAT BUYS: code names it directly, with no search - and a query filters on that same\n"
		"name attribute rather than on code or description, which is the whole point (a query\n"
		"matching on a description is the silent wrong answer this pattern exists to prevent).\n"
		"\n"
		"STOP: AND WHAT IT COSTS, in the order people meet it:\n"
		" THE ROW CAN BE MARKED FOR DELETION BY A PERSON, unless the right to do so is withheld.\n"
		" The declaration stays; the row goes to the bin. Decide who may, rather than assuming\n"
		" nobody will.\n"
		" REMOVING THE DECLARATION DOES NOT REMOVE THE ROW. The row survives as an ordinary item\n"
		" with its tie broken - and every reference in every document still points at it. That is\n"
		" the correct behaviour (references must not evaporate) and it surprises everybody once.\n"
		" REFERENCING A PREDEFINED ITEM THAT IS NOT THERE RAISES. Code that names one assumes it\n"
		" exists, and in a base restored from before it was added, it does not. Where that is\n"
		" possible, ask through something that answers \"nothing\" instead of throwing.\n"
		" THE TIE IS THE NAME, AND THE NAME CAN BE MOVED. Writing the name onto another row hands\n"
		" the identity over - which is how a predefined item is re-pointed at a row a person\n"
		" already created, instead of ending up with two.\n"
		"\n"
		"NOTE: WHERE IT DOES NOT BELONG: a catalogue whose items belong to an OWNER (which item of which\n"
		"owner would the name mean?), and any set that changes with the business - a predefined item\n"
		"is a thing the CODE knows, so adding one is a configuration change, and a set that grows\n"
		"monthly does not want to be one. Also not needed where a lookup by a stable attribute\n"
		"already answers: this pattern buys identity, not convenience.\n"
		"\n"
		"NOTE: AND IN A BASE THAT IS SPLIT - copies exchanging data, or one base serving several tenants\n"
		"- the rows are per copy and per tenant, so the same predefined name is a DIFFERENT\n"
		"reference in each. Anything comparing references across the boundary has to compare the\n"
		"names instead.\n"
		"* WHICH IS EXACTLY WHY A TRANSFER LOOKS UP A PREDEFINED ITEM BY ITS NAME BEFORE TRYING ITS\n"
		"IDENTITY (`data-exchange`). Same name, different identity, in every base - so the name is\n"
		"the more reliable key of the two, and this is the one case where that is true.\n"
		"* AND GROUPS AND PREDEFINED ITEMS TEND TO BE SENT EVERYWHERE UNCONDITIONALLY, because they\n"
		"are the skeleton other data hangs on. Worth knowing when a filter is being designed: the\n"
		"exemption is deliberate, and it is also how items reach a branch that was never supposed to\n"
		"see them.") },

	{ wxT("recipes"),
	  ibMcpText("Building a whole area from nothing: what to create, in what order, for each classic subsystem."),
	  ibMcpText("RECIPES FOR THE AREAS THAT ARE SOLD ELSEWHERE AS SEPARATE PRODUCTS.\n"
		"\n"
		"STOP: FIRST, A CORRECTION OF LANGUAGE, because it changes the answer. Large systems sell\n"
		"currency accounting, settlements, treasury, asset accounting and controlling as MODULES,\n"
		"and it is easy to repeat that framing and say a platform \"does not have currency\n"
		"accounting\". It is the wrong sentence. None of these is a feature a platform either has or\n"
		"lacks: each is an APPLICATION built out of registers, documents and reports - a fortnight\n"
		"or two of work apiece, on primitives this platform already has.\n"
		"\n"
		"So the honest answer to \"do you support multi-currency?\" is not \"no\" and not \"yes\" - it is\n"
		"THIS RECIPE: here is what gets created, in what order, and how you know it works. The\n"
		"things genuinely absent are few and named where they arise (`payroll` is the clear one -\n"
		"no calculation register, so its machinery is yours to build).\n"
		"\n"
		"WHAT THE BIG SYSTEMS SELL AS MODULES, AND WHERE IT IS HERE - so the answer to \"where is\n"
		"your module for this\" is an address rather than an apology:\n"
		" materials, warehousing, procurement the STOCK and PURCHASING recipes below,\n"
		" `lot-accounting`, `stock-control`\n"
		" sales and distribution the SALES recipe, `pricing`\n"
		" financial accounting, the general ledger the FINANCIAL RESULT recipe,\n"
		" `ledger-reports`, `parallel-accounting`\n"
		" controlling - cost centres, cost objects, allocation `production`, `allocation`\n"
		" treasury and cash management the MONEY recipe, `cash-flow`\n"
		" asset accounting the FIXED ASSETS recipe\n"
		" production planning and execution `production`, and the graph it is built on\n"
		" taxation `vat`\n"
		" consolidation and multiple entities the SEVERAL LEGAL ENTITIES recipe\n"
		" human resources and payroll `payroll`, WITH the missing pieces named there\n"
		"Every one of those is an application written on registers, documents and reports. What is\n"
		"bought elsewhere as a module is here a fortnight of building - which is a different\n"
		"proposition, not a smaller one, and worth stating in exactly those terms.\n"
		"\n"
		"Each recipe has a settled order. Do them in the order given: every step is needed by the\n"
		"one after it, and building them the other way round means rebuilding.\n"
		"\n"
		" CURRENCY (read `currency`) \n"
		" 1. Catalogue of currencies. 2. Rates: an information register, periodicity by day,\n"
		" currency as the dimension, TWO resources - rate and multiplicity.\n"
		" 3. Give every document that can be in currency its own currency, rate and multiplicity\n"
		" ATTRIBUTES - copied at posting, never re-read afterwards.\n"
		" 4. Registers that hold money in currency get a currency dimension AND a second resource\n"
		" for the currency amount beside the base-currency one.\n"
		" 5. Revaluation at period end, per kind of currency holding.\n"
		" DONE WHEN: re-opening last quarter's document shows the rate it was posted with, and\n"
		" the revaluation reproduces the same difference twice.\n"
		"\n"
		" SETTLEMENTS (read `settlements`) \n"
		" 1. Counterparties, then AGREEMENTS under them - the agreement carries the currency of\n"
		" settlement and the level of detail (as a whole / per order / per invoice / per\n"
		" settlement document).\n"
		" 2. The settlement register: dimensions counterparty, agreement, and the detail key;\n"
		" resources the amount and, from day one, the currency amount.\n"
		" 3. Posting on both sides - what creates debt (sale, receipt) and what settles it\n"
		" (payment) - through ONE offsetting routine, never per document.\n"
		" 4. The offset itself: split each payment into what closes debt and what becomes an\n"
		" advance; advances on their own account.\n"
		" 5. The reconciliation act, and a screen to pick documents by hand.\n"
		" DONE WHEN: a prepayment followed by a partial delivery leaves the right advance and the\n"
		" right debt, and the balance by agreement equals the balance by documents.\n"
		"\n"
		" STOCK (read `shapes`, `lot-accounting`, `stock-control`) \n"
		" 1. Items, warehouses, units - and the DECISION about lots before anything is built.\n"
		" 2. The balance register: warehouse, item, whatever else is genuinely kept (series,\n"
		" characteristic) - and QUANTITY ALONE as its resource. Money does not belong here.\n"
		" Measured in a working system the stock balance register has five dimensions and ONE\n"
		" resource; value lives in the lot register (nine dimensions, and one such register per\n"
		" set of books) and the free balance in a third. Putting the amount beside the quantity\n"
		" looks economical and forecloses ever having two valuations of one quantity - which is\n"
		" exactly what a second set of books is (`parallel-accounting`).\n"
		" 3. Receipt and issue documents writing into it, through one write-off routine.\n"
		" 4. Control of free balance at posting, with the override as a property of the warehouse.\n"
		" 5. Reserves, if orders exist: a second register, and the control reads both.\n"
		" 6. Stocktake, transfer, write-off - and only then reports.\n"
		" DONE WHEN: an issue of more than is free is refused with the line named, and the\n"
		" balance report agrees with the sum of movements for any period.\n"
		"\n"
		" MONEY (read `cash-flow`) \n"
		" 1. Bank accounts and tills; the register of actual funds.\n"
		" 2. Incoming and outgoing documents, each recording what it settles (link to\n"
		" `settlements`).\n"
		" 3. The cash-flow classification - the item of the movement - on every document, because\n"
		" retrofitting it means revisiting history.\n"
		" 4. Requests to spend, with approval and CLOSING; the reserved-money register.\n"
		" 5. Expected receipts and payments, for the payment calendar.\n"
		" DONE WHEN: the calendar for next week is produced without anybody typing a figure\n"
		" twice, and an approved request reduces what may still be committed.\n"
		"\n"
		" FINANCIAL RESULT (read `ledger-reports`, `parallel-accounting`) \n"
		" 1. Chart of accounts, then the accounting register over it with correspondence on.\n"
		" 2. Decide HOW entries arise: written by each document, or DERIVED later from the\n"
		" operational registers - that choice shapes everything after it.\n"
		" 3. Rules of reflection as data (which account for which operation), never as branches\n"
		" inside documents.\n"
		" 4. The standard ledger reports, all of them - they are what an accountant judges the\n"
		" system by.\n"
		" 5. Closing the period: what may still be posted into it, and by whom.\n"
		" DONE WHEN: the trial balance balances, and every figure in it drills down to the\n"
		" documents that made it.\n"
		"\n"
		" PURCHASING AND SALES - THE TWO CYCLES (read `settlements`, `stock-control`, `pricing`) \n"
		" Both are the same chain in opposite directions: an INTENT, a FACT, and MONEY. But do not\n"
		" plan them as mirrors - measured by how many registers each document writes, the two\n"
		" sides are nowhere symmetric, and the reason is structural: WHAT LEAVES HAS TO BE VALUED\n"
		" (lots, cost of sales, revenue, discounts) while WHAT ARRIVES HAS TO BE CLASSIFIED - one\n"
		" receipt document is the entrance to stock, to assets under construction, to work in\n"
		" progress, to expenses and to items in use, which is why it is the largest ordinary\n"
		" document in the system. Budgeting the second cycle as \"the first one mirrored\" is how\n"
		" the estimate is missed.\n"
		" And the full chain is longer than the three steps below - in a working system: a\n"
		" quotation (which posts NOTHING and exists to be a basis), the order, reservation and\n"
		" placement, a WAREHOUSE ORDER, the sale itself, the return, the closing, plus separate\n"
		" documents for correcting and for amending. The three steps here are links two, five and\n"
		" seven; the rest appear as soon as the warehouse acts separately from the accounts.\n"
		" 1. The order - what was agreed. It is a promise with a date and lines, AND IT USUALLY\n"
		" MOVES MORE THAN ITS OWN REGISTER: in a working system a customer order writes to\n"
		" eight, including the reservation, the free balance and the placement against supply.\n"
		" \"An order reserves nothing\" is only true of a system that has decided not to reserve;\n"
		" ask which one you are building, because the answer decides half the stock design.\n"
		" 2. A register of orders. \"What is still outstanding\" is its POINT but not its content:\n"
		" measured in a working system it carries twelve dimensions - the agreement, the order,\n"
		" the item and its variant, THE AGREED PRICE, the discount and the condition that gave\n"
		" it, the unit, the tax rate - against three resources. Because the commercial terms of\n"
		" the promise have to survive to the delivery: \"the price we agreed on the order\" is the\n"
		" commonest reason a delivery is disputed, and the order line is where that price lives.\n"
		" Reduce the register to quantity and you have to re-derive the terms from the document\n"
		" every time, which fails the moment the order is amended.\n"
		" 3. The delivery or receipt, ENTERED FROM the order so nothing is retyped, closing the\n"
		" outstanding quantity and moving stock.\n"
		" 4. Payment against it, settling the debt (`settlements`), with the order as the detail\n"
		" key if the agreement says so.\n"
		" 5. CLOSING an order that will never be completed - a deliberate document, never a status\n"
		" somebody edits, because \"why is this still open\" must have an answer.\n"
		" DONE WHEN: partial delivery leaves the right remainder, over-delivery is refused or\n"
		" permitted by right, and \"what is owed to us and by when\" is one report.\n"
		"\n"
		" FIXED ASSETS (read `shapes` on time-varying properties, `parallel-accounting`) \n"
		" 1. The asset catalogue holds only what never changes - what it is, its inventory number.\n"
		" 2. EVERYTHING ELSE IS A PERIODIC REGISTER, one per family of facts: initial value and\n"
		" useful life, depreciation method and parameters, current state (in service,\n"
		" withdrawn), where it is and whose cost centre it belongs to, whether depreciation is\n"
		" charged at all - each of them separately for each set of books.\n"
		" 3. Documents are EVENTS that write those registers: accepted, put into service,\n"
		" modernised, moved, state changed, written off.\n"
		" 4. Monthly depreciation reads the registers AS OF ITS OWN MONTH and writes the charge to\n"
		" the cost account the reflection register names.\n"
		" 5. Revaluation, and the companion entry it drags into the other books.\n"
		" DONE WHEN: recomputing an old month reproduces the old figure exactly, after a\n"
		" modernisation and a method change have both happened since.\n"
		"\n"
		" SEVERAL LEGAL ENTITIES IN ONE BASE \n"
		" 1. The organisation is a DIMENSION of every register that holds VALUE OR AN OBLIGATION,\n"
		" from the first day - retrofitting it means re-posting everything. NOT of every\n"
		" register: measured in a working system, 85 of 148 carry it, and the 63 that do not are\n"
		" exactly the operational layer - stock, reserves, every kind of order, costs, work in\n"
		" progress, plans. Those hold quantity or intent, and quantity has no owner until it is\n"
		" valued. Adding the company there costs a dimension on the busiest registers and buys\n"
		" nothing.\n"
		" 2. Documents carry it, and posting refuses when the agreement, the warehouse or the\n"
		" account belongs to another one.\n"
		" 3. Transfers BETWEEN organisations are sales and purchases, not movements: one entity's\n"
		" stock leaves and another's arrives, with a debt between them.\n"
		" 4. Access by organisation is row-level (`roles`), and the exemption \"sees every\n"
		" organisation\" is a role.\n"
		" 5. Reports take it as a parameter and default to one, because a total across legal\n"
		" entities is meaningless in most questions and is a consolidation in the rest.\n"
		" DONE WHEN: a document naming another entity's warehouse is refused, and every balance\n"
		" report is right for one organisation and for all of them.\n"
		"\n"
		"* AND THE ORDER BETWEEN THE AREAS is the one in `where-to-start`: goods move first, money\n"
		"and who owes it second, production third, payroll last. Currency runs alongside whichever\n"
		"of them meets a foreign currency first.\n"
		"NOTE: Each recipe ends with a CHECK rather than a list of objects, on purpose: an area is not\n"
		"finished when its metaobjects exist, it is finished when a question it was built for gets\n"
		"the right answer twice.") },

	{ wxT("where-to-start"),
	  ibMcpText("The order configurations actually grow in - useful for knowing what comes next."),
	  ibMcpText("WHAT APPEARS, AND ROUGHLY IN WHAT ORDER.\n"
		"\n"
		"Almost every configuration grows the same way, and knowing the sequence is worth more\n"
		"than it sounds: it tells you what is coming, so that what you build today does not have\n"
		"to be unpicked to make room for it.\n"
		"\n"
		" 0. THE VOCABULARY, AND IT IS A STAGE, not a preliminary. Items, parties, places,\n"
		" companies, units, and the enumerations for every kind the code will branch on. In a\n"
		" full system one section holds a hundred catalogues, no documents and no registers at\n"
		" all - reference data is an area of its own, with its own maintenance, its own rights\n"
		" and its own loading from outside (`external-data`). Treating it as \"we'll add the\n"
		" directories as we go\" is why the third month is spent merging duplicates.\n"
		" 1. GOODS MOVING. Receipt, transfer between warehouses, write-off, sale. This is the\n"
		" spine, and almost everything later hangs off it. Get the stock registers right here\n"
		" - see `shapes` for balances against turnovers - because everything downstream reads\n"
		" them.\n"
		" 2. MONEY AND WHO OWES IT. Settlements with counterparties, contracts, currency (see\n"
		" `settlements`, `currency`). Arrives as soon as the goods do, and often the same\n"
		" week.\n"
		" 3. PRODUCTION, if there is any. The shift production report, transport documents,\n"
		" material consumption - and with it costs, lots and the month-end close (see\n"
		" `production`, `lot-accounting`).\n"
		" 4. PAYROLL, if there is any. Work orders and piece records, accrual, deductions. It is\n"
		" its own world with its own periodicity and its own rules, and it touches the cost\n"
		" side at the close.\n"
		"\n"
		"* THE USE OF KNOWING THIS is not to build it all. It is to ask the one question that\n"
		"stops a design being cornered: is there production here? is there payroll? A stock model\n"
		"laid out without knowing that costs will have to be allocated over it is the model that\n"
		"gets rebuilt in month four - and the answer costs one question at the start.\n"
		"STOP: AND THE THIRD QUESTION IS THE ONE THAT REORGANISES EVERYTHING: WILL THIS BASE KEEP TWO\n"
		"CIRCUITS - what the business runs on, and what its papers say? Because that seam does not sit\n"
		"at a stage. It runs the whole length: the stock lots, the costs, the work in progress and the\n"
		"output each exist twice; the accounting policy is two registers; the close computes cost\n"
		"twice, in parallel; even an agreement carries the settlement detail twice, once per circuit.\n"
		"* SO THE STAGE LIST IS THE ORDER OF WORK, NOT THE AXIS OF THE SYSTEM. A base built stage by\n"
		"stage on the assumption of one circuit does not gain the second by adding a stage - it gains\n"
		"it by revisiting every stage at once, which is the most expensive shape of rework there is.\n"
		"* THE ANSWER IS AUDIBLE IN THE FIRST CONVERSATION: two stock reports that disagree, a \"real\"\n"
		"figure beside an \"official\" one. Ask then, not later (`parallel-accounting`).\n"
		"\n"
		"STOP: AND THE ORDER IS NOT THE WEIGHT. Counted by objects claimed in a finished system, the\n"
		"areas rank: the ledger ~400 · production ~360 · the shared mechanism layer ~360 · personnel\n"
		"~330 · the standard infrastructure ~300 · payroll ~290 · tax ~290 · sales ~250 · stock ~190 ·\n"
		"purchasing ~185. PERSONNEL AND PAYROLL TOGETHER ARE THE LARGEST AREA IN THE SYSTEM - larger\n"
		"than the ledger, two and a half times sales, three and a half times purchasing - and they\n"
		"come LAST in the build order. \"Last\" means \"depends on the others\", never \"small\".\n"
		"* AND STOCK, WHICH IS BUILT FIRST AND FEELS CENTRAL, IS AMONG THE SMALLEST. It is the spine\n"
		"because everything hangs off it, not because it is where the work is. Anyone reading a build\n"
		"order as an estimate gets both ends wrong.") },

	{ wxT("building-an-erp"),
	  ibMcpText("The whole route: what is decided once at the start, what is built in what order, and what proves each step."),
	  ibMcpText("HOW A WHOLE SYSTEM IS ASSEMBLED OUT OF THESE PATTERNS.\n"
		"\n"
		"`where-to-start` says what appears first. `recipes` says how each area is built. This is the\n"
		"route through both, and the part nobody writes down: what must be decided BEFORE the first\n"
		"object, because it cannot be retrofitted.\n"
		"\n"
		"STOP: DECIDED ONCE, AT THE START. Each of these costs almost nothing on day one and is a\n"
		"rewrite once fifty documents exist. Ask all of them before writing anything:\n"
		" HOW MANY SETS OF BOOKS, and are they independent computations or projections of one\n"
		" another (`parallel-accounting`)? This decides whether every movement carries flags saying\n"
		" which books it is reflected in - and `deferred-posting` later depends on those flags\n"
		" existing.\n"
		" IS THERE MORE THAN ONE LEGAL ENTITY, and does the management structure differ from the\n"
		" legal one (`org-structure`)?\n"
		" WILL THERE BE SEVERAL BASES that must agree (`data-exchange`)? If yes, prefixes and\n"
		" identity of predefined items are decided now (`numbering`, `predefined`).\n"
		" WHICH CROSS-CUTTING MECHANISMS EXIST AT ALL - prohibition date, history of changes,\n"
		" number prefixes, registration for transfer, record-level access, deferred posting, cache\n"
		" invalidation (`cross-cutting-hooks`). Not built now; their HOOK POINTS reserved now.\n"
		" WHAT THE UNIT OF ACCOUNTING IS for the things being traded - by item, by variant, by\n"
		" series, by lot, per warehouse (`lot-accounting`, `stock-control`). This is the single\n"
		" most expensive thing to change later, because it is the KEY of every stock balance.\n"
		"\n"
		"KEY: THEN BUILD IN THIS ORDER, AND DO NOT INVERT IT.\n"
		"\n"
		"1. THE VOCABULARY. Items, counterparties, warehouses, companies, currencies, units - and\n"
		"the ENUMERATIONS for every kind the code will branch on (`proportions`: there are more of\n"
		"those than of anything else). Predefined entries for everything code names directly.\n"
		" DONE WHEN: a person can enter their own reference data and nothing in it is a free-text\n"
		" field that the code later has to parse.\n"
		"\n"
		"2. GOODS MOVING, WITH ONE BALANCE REGISTER. Receipt, transfer, write-off, sale. The chain\n"
		"of `document-chains` in its simplest form, posting through `posting`, checked through\n"
		"`stock-control`.\n"
		" DONE WHEN: a shipment of more than there is, is refused with the line and the key named;\n"
		" and re-posting a document twice leaves the balance unchanged.\n"
		"\n"
		"3. WHO OWES WHAT. Contracts, settlement by the key the contract dictates, advances offset,\n"
		"currency if there is any (`settlements`, `currency`).\n"
		" DONE WHEN: a prepayment followed by a partial delivery leaves the right advance and the\n"
		" right debt, and the same in a second currency produces an exchange difference that closes\n"
		" to the last cent.\n"
		"\n"
		"4. WHAT THINGS COST. Lots or average, the write-off routine as ONE module, the boundary of\n"
		"validity (`lot-accounting`, `sequences`).\n"
		" DONE WHEN: a document entered backdated moves the boundary, the restore recomputes, and\n"
		" the recomputed figures for an old month reproduce exactly.\n"
		"\n"
		"5. ORDERS, BOTH DIRECTIONS, AND WHAT THEY RESERVE (`orders`, `planning`).\n"
		" DONE WHEN: partial fulfilment leaves the right remainder; closing an order leaves nothing\n"
		" behind in any register.\n"
		"\n"
		"6. THE LEDGER, ON TOP OF ALL THAT. Chart of accounts, the accounting register, entries\n"
		"derived from the movements that already exist (`parallel-accounting`, `ledger-reports`).\n"
		"NOT FIRST - the ledger is where results are assembled, not where work happens\n"
		"(`proportions`: four accounting registers against four hundred and fifty).\n"
		" DONE WHEN: the trial balance balances, and every figure in it drills down to documents.\n"
		"\n"
		"7. COSTS AND THE CLOSE, if anything is manufactured (`production`, `allocation`).\n"
		" DONE WHEN: closing the month twice gives the same answer, and the allocation base can be\n"
		" SHOWN to the person disputing it.\n"
		"\n"
		"8. THE SHELLS, in this order because each depends on the last: sections and forms\n"
		"(`sections`, `form-layout`), printing (`printing`, `batch-printing`), reports and variants\n"
		"(`report-shapes`, `report-variants`), roles and record-level access (`roles`,\n"
		"`row-level-access`), then exchange (`data-exchange`).\n"
		" DONE WHEN: a person who has never seen the system can do one day's work in it without\n"
		" being shown where anything is.\n"
		"\n"
		"STOP: THE THREE INVERSIONS THAT COST THE MOST.\n"
		" STARTING FROM THE CHART OF ACCOUNTS. It produces a system that can report and cannot\n"
		" work, and every operational question then has to be reverse-engineered out of entries.\n"
		" BUILDING RIGHTS BEFORE THERE IS DATA. Record-level access designed against imagined data\n"
		" restricts the wrong things and is rebuilt when the real keys appear (`row-level-access`).\n"
		" WRITING REPORTS PER QUESTION. Reports outnumber documents (`proportions`); built one per\n"
		" question they become hundreds. Build the FAMILY and the variants (`report-variants`).\n"
		"\n"
		"KEY: AND THE SIZE OF THE WHOLE THING IS KNOWN, so nobody has to guess. A full manufacturing\n"
		"ERP measures roughly: 440 enumerations, 380 reports, 300 registers of settings, 300\n"
		"documents, 230 catalogues, 145 balance registers, 66 roles, 20 sections, 4 ledgers\n"
		"(`proportions`). What that says about effort: the core mechanisms are a small part of it,\n"
		"and the bulk is breadth - which is exactly the part that can be built incrementally, by\n"
		"area, with each area proved by its own DONE WHEN before the next begins.") },

	{ wxT("proportions"),
	  ibMcpText("How much of what a full ERP actually contains - counted, not guessed."),
	  ibMcpText("THE SHAPE OF A FINISHED SYSTEM, BY THE NUMBERS.\n"
		"\n"
		"Counted off one deployed manufacturing ERP. Not an estimate - a count of what is in it:\n"
		"\n"
		" enumerations       443    reports              382\n"
		" information regs   347    documents            306\n"
		" catalogues         230    shared modules       219\n"
		" tools/processors   166    accumulation regs    148\n"
		" constants          123    shared templates      93\n"
		" shared forms        88    roles                 66\n"
		" event hooks         50    sections              37\n"
		" document journals   35    scheduled jobs        18\n"
		" filter criteria     14    functional options    11\n"
		" characteristic kinds 10   sequences              9\n"
		" calculation regs     7    exchange plans         6\n"
		" ACCOUNTING REGISTERS 4    charts of accounts     4\n"
		" business processes   1    (registers, all kinds: 506)\n"
		"\n"
		"KEY: CLOSED SETS OUTNUMBER EVERYTHING. There are more enumerations than catalogues, and more\n"
		"than documents. Every place the code branches on \"what kind of thing is this\" has been given\n"
		"a name and a type rather than a string or a flag. If a design has three enumerations and\n"
		"forty documents, the kinds are hiding in strings.\n"
		"\n"
		"KEY: SETTINGS AND \"AS OF A DATE\" OUTWEIGH \"HOW MUCH\". Information registers outnumber\n"
		"accumulation registers two to one. The bulk of a system is not counting things - it is\n"
		"remembering what was true, for whom, on which date (`shapes`).\n"
		"\n"
		"STOP: DOUBLE ENTRY IS A SMALL PART OF THE WHOLE. Four accounting registers against 506\n"
		"registers in total - well under one per cent. The ledger is where the results are ASSEMBLED,\n"
		"not where the work happens, which is why building the ledger first and the operational\n"
		"registers afterwards gets the order backwards (`where-to-start`).\n"
		"\n"
		"NOTE: THERE ARE MORE REPORTS THAN DOCUMENTS. Whatever is entered will be asked about from\n"
		"more angles than there were ways to enter it. A plan that budgets for documents and treats\n"
		"reports as the easy tail has the ratio inverted.\n"
		"\n"
		"NOTE: ONE BUSINESS PROCESS IN THE ENTIRE CONFIGURATION. Approval routes, task assignment and\n"
		"the rest are built out of documents, registers and states - not out of a workflow metatype.\n"
		"Useful when somebody asks for \"a workflow engine\": in a real system of this size, exactly\n"
		"one thing needed it.\n"
		"\n"
		"NOTE: SETTINGS SPLIT THREE WAYS, AND THE PROPORTION IS THE LESSON. 123 constants, 11\n"
		"functional options, and 347 information registers. Anything with a company or a date behind\n"
		"it became a register - that is the bulk. A constant is what has neither. And a functional\n"
		"option is the third thing: a switch that whole PARTS OF THE INTERFACE AND THE DATA hang off,\n"
		"declared as such rather than read as an ordinary flag - eleven of them, against a hundred\n"
		"and twenty-three plain constants, which says how rarely a switch really deserves that\n"
		"weight (`constants`).\n"
		"\n"
		"NOTE: 66 ROLES AND 37 SECTIONS - rights about a fifth of the document set, navigation about\n"
		"an eighth. Neither is a footnote to be added at the end (`roles`, `sections`). And 219\n"
		"shared modules against 306 documents: nearly as much code lives BESIDE the objects as inside\n"
		"them, which is what `where-behaviour-lives` is about.\n"
		"\n"
		"⚠ HOW THESE WERE COUNTED, because it is easy to get wrong and I did: count the DECLARATIONS,\n"
		"one file per metaobject. Counting the folders instead counts only the objects that happen to\n"
		"own a module or a form, and silently loses every simple one - which understated the\n"
		"constants here by a factor of five and reported the functional options as zero.") },

	{ wxT("planning"),
	  ibMcpText("Plans against facts, what is still needed, and covering a requirement from somewhere."),
	  ibMcpText("PLANNING, AND THE THREE THINGS PEOPLE MEAN BY IT.\n"
		"\n"
		"KEY: A PLAN IS A COORDINATE, NOT A DOCUMENT. \"The pessimistic plan for workshop two for the\n"
		"quarter\" is addressed by four things at once - the KIND of planning, the SCENARIO, the\n"
		"department, the project - and every reading asks for \"my value OR the empty one\", so a\n"
		"general rule and a specific one live in the same register and compete. The scenario is a\n"
		"catalogue item and carries the periodicity.\n"
		"* AND THE PLAN ITSELF SITS IN A REGISTER OF THE SAME SHAPE AS THE FACT - plans of sales\n"
		"beside sales, plans of purchases beside purchases. Not a field on the fact, not a separate\n"
		"subsystem: the same kind of register, so \"plan against fact\" is a join of two readings and\n"
		"nothing has to be invented for the report.\n"
		"\n"
		"KEY: ROLLING PLANNING IS A FREEZE DATE, NOT A STATUS ON THE PLAN. \"The first month is agreed\n"
		"and must not be touched, the rest may be edited\" is one date per coordinate, held in a\n"
		"register. THE PERIOD IS FROZEN, NOT THE OBJECT - one plan document may lie partly in the\n"
		"closed zone and partly in the open one. Rolling the plan forward is then moving ONE date,\n"
		"with no statuses, no re-approval and no rebuilding of documents.\n"
		"\n"
		"NOTE: PERIODICITY STAYS A WORD. The engine already knows how to truncate a date to a week, a\n"
		"month, a quarter - so the periodicity is the NAME of the period, passed into the call, not a\n"
		"five-branch condition rebuilt in each place. And a date the person types is quietly ALIGNED\n"
		"to the period boundary and they are told so, rather than being refused: a plan date that is\n"
		"not on a boundary has no meaning.\n"
		"\n"
		"KEY: A REQUIREMENT IS A BALANCE REGISTER THAT SOMEBODY MUST DISCHARGE. \"How much is still to\n"
		"be issued for this order\" is never computed as a formula - the order BOOKS the requirement,\n"
		"the issuing documents CONSUME it, and what is left is the balance. Read it through the\n"
		"balance, exactly as `shapes` says.\n"
		"* AND THE REQUIREMENT REMEMBERS WHAT IT AROSE FOR - not just the material, but the product it\n"
		"is for and under which specification. Without that, a partial output cannot say which part\n"
		"of the materials has been worked off.\n"
		"\n"
		"KEY: DISCHARGING HAS TWO MODES AND BOTH ARE NEEDED. Normally take the OVERLAP - the lesser of\n"
		"what the document does and what is outstanding - and where the document exceeds the\n"
		"requirement, SAY SO with the detail and post anyway. The second mode is \"the order is closed\n"
		"/ everything has been produced\": then the whole remaining requirement is written off\n"
		"regardless of the document. Without the second, every under-issue leaves rubbish outstanding\n"
		"for ever; without the first, a document would silently close somebody else's requirement.\n"
		"\n"
		"KEY: COVERING A REQUIREMENT IS ONE UNION ORDERED BY THE STRATEGY. The document's lines, the\n"
		"free stock and the outstanding supplier orders go into a SINGLE query with an ORDER column,\n"
		"totalled by item, and the walk hands out quantity greedily from the top. \"Reserve from stock\n"
		"first, then place against orders\" versus the reverse IS TWO NUMBERS in the parameters - the\n"
		"priority is expressed as DATA, and a fourth source of supply is a fourth branch with a\n"
		"constant, not a rewrite. The same move as choosing a specification (`bill-of-materials`) and\n"
		"matching debts (`settlements`).\n"
		"\n"
		"NOTE: SUBSTITUTES ARE THE SAME QUESTION AS SUB-ASSEMBLIES - \"what else can close this line\".\n"
		"They carry a priority and a kind, and the quantity is converted through the unit\n"
		"coefficients IN THE QUERY, guarding against a zero or missing coefficient. Worth noticing\n"
		"that one mechanism answers both, rather than two mechanisms answering half each.\n"
		"\n"
		"KEY: A BUDGET IS A LEDGER, NOT A TABLE OF NUMBERS - AND THE SCENARIO IS A BALANCE-BEARING\n"
		"DIMENSION. Plan lines go into an accounting register of their own with the scenario as a\n"
		"dimension that carries balances, so \"the optimistic plan\" and \"the approved plan\" coexist,\n"
		"are compared by subtraction, and a version is copied rather than overwritten. The\n"
		"organisation, by contrast, is usually NOT a dimension there: budgets are set for the group\n"
		"and cut by centre and project, and forcing a legal entity onto every line asks a question the\n"
		"planner cannot answer.\n"
		"* AND THE PLANNER WRITES ONE-SIDED LINES; THE DOUBLE ENTRY COMES FROM A TEMPLATE ON THE\n"
		"ARTICLE. Nobody budgets in debits and credits - they type an amount against an article - so\n"
		"each article carries the correspondence it implies and the register receives a balanced pair.\n"
		"That is what lets a budget be added up like a ledger while being entered like a spreadsheet.\n"
		"* THE SCENARIO ALSO CARRIES ITS OWN RATE CURVE, and one switch says whether to use it or the\n"
		"real rates - so a plan can be re-read \"at last year's rates\" without a second copy of\n"
		"anything. And a plan entry touching three currencies is REFUSED unless all three have a rate\n"
		"that day: a missing rate silently valuing a line at nothing is the commonest way a budget\n"
		"stops adding up.\n"
		"\n"
		"KEY: THE ACTUAL IS NOT MAPPED FROM ACCOUNTS - EACH ARTICLE NAMES ITS OWN QUERY. What counts\n"
		"as \"actual marketing spend\" is a question about the business, not about the chart, and the\n"
		"sources differ per article: a ledger turnover for one, an accumulation register for another,\n"
		"a document's own lines for a third. So the article holds the name of the reading, and the\n"
		"comparison joins whatever comes back.\n"
		"* WHICH MAKES THE UNION OVER HETEROGENEOUS SOURCES THE REAL WORK: fix ONE vocabulary of\n"
		"columns every source must produce, and where a source has no value for one of them, select a\n"
		"TYPED EMPTY rather than omitting the column (`query-craft`). A source added later then needs\n"
		"no change anywhere above it.\n"
		"* AND THE PLAN AND THE ACTUAL OBEY DIFFERENT STORAGE RULES - one is stored by period, the\n"
		"other by moment; one is dense, the other sparse - so they are reconciled AT READ TIME, in the\n"
		"report, and never by writing one into the other's shape.\n"
		"STOP: AND ALIGNING THE PLAN TO THE ACTUAL DESTROYS THE VARIANCE, WHICH IS THE WHOLE POINT OF\n"
		"THE PLAN. It is a legitimate request - re-plan the rest of the year from where we actually\n"
		"are - and it must say what it is about to do, write a NEW version rather than editing the\n"
		"approved one, and leave the original readable. A plan silently corrected to match reality is\n"
		"a report that always shows zero variance.\n"
		"\n"
		"NOTE: TWO SMALLER SHAPES THAT PAY FOR THEMSELVES. Closing a period in the plan ledger is a\n"
		"MOVING BOUNDARY per scenario, centre and project rather than one date for the base - the\n"
		"sales budget is agreed in October and the capital one in December (`closing-a-period`: it is\n"
		"a table, not a date). And a line computed from another line - \"transport is six per cent of\n"
		"purchases\" - is a REGISTER of dependencies, not code: the dependent lines are then\n"
		"recomputed, shown, and switched off by the person who disagrees.\n"
		"* AND ONE PRIMITIVE COVERS BOTH SPREADING AND SCALING: a PROFILE - a curve of weights over\n"
		"the periods - either spreads an annual figure across the year or scales last year's actual\n"
		"into next year's plan, and which of the two it is doing is a setting rather than a second\n"
		"mechanism.") },

	{ wxT("bill-of-materials"),
	  ibMcpText("What a product is made of: exploding it into requirements, and the traps in doing so."),
	  ibMcpText("DESCRIBING WHAT A PRODUCT IS MADE OF, AND EXPLODING IT.\n"
		"\n"
		"KEY: A SPECIFICATION IS NOT A COMPOSITION - IT IS FOUR TABLES UNDER ONE HEADING. What comes\n"
		"OUT (and there may be several outputs), what is CONSUMED, what RETURNS to store as usable\n"
		"waste - carrying an amount, since it is a negative cost rather than a product - and what is\n"
		"produced ALONGSIDE. A caller asks for the ones it needs and the others are not computed at\n"
		"all, because nine callers in ten want only the materials and walking the tree again for\n"
		"waste is a second full pass.\n"
		"* THE COST IS THAT THE SHAPE OF THE ANSWER BECOMES PART OF THE CONTRACT, and it has to be\n"
		"documented at the entry point rather than discovered.\n"
		"KEY: WHEN TWO THINGS COME OUT OF ONE RUN, ASK WHO PAYS - THE ANSWER PICKS WHICH TABLE THEY\n"
		"GO IN. Usable waste TAKES AWAY an amount: it carries a value of its own, priced at a PLANNED\n"
		"rate held in the specification and scaled by actual over standard, plus the cost item it\n"
		"credits - never a warehouse price, or the cost of a run moves with what the store paid last\n"
		"week. A by-product DIVIDES an amount: it carries a share and takes part in splitting what the\n"
		"run cost between the outputs. One physical situation, two rows of different shape; choosing\n"
		"wrongly shows up as a product whose cost changes when nothing about it did.\n"
		"* AND ON THE LEDGER SIDE WASTE IS LESS OUTPUT, NOT MORE STOCK - negate amount and quantity\n"
		"and swap the two sides of the entry, so the class comes out net in one pass. It reads\n"
		"backwards on a single row, which is exactly why the reason belongs written beside it.\n"
		"\n"
		"KEY: A LINE OF A SPECIFICATION IS POLYMORPHIC, AND A KIND FIELD SAYS WHICH KIND IT IS.\n"
		"Four kinds, and the last two are what stop the specifications multiplying:\n"
		" A MATERIAL - the ordinary case.\n"
		" A SUB-ASSEMBLY - a named bundle, expanded in place.\n"
		" AN ITEM DERIVED FROM THE PRODUCT'S OWN PROPERTY - \"colour = red\" resolves to \"red paint\".\n"
		" A FIXED ITEM WHOSE VARIANT IS INHERITED from the product being made.\n"
		"Without the last two, a product in six colours and four sizes needs twenty-four\n"
		"specifications. This is `shapes` one floor down: the kind is a type, not a flag.\n"
		"\n"
		"KEY: A SUB-ASSEMBLY AND A SPECIFICATION ARE TWO DIFFERENT KINDS OF NESTING. A sub-assembly\n"
		"expands into the CURRENT level - it is an expansion of text, nothing is manufactured. A\n"
		"reference to another specification creates the NEXT level - something is manufactured there.\n"
		"Two nestings, two independent paths, and each needs its own loop check.\n"
		"* AND THE TWO ANSWER \"IS THERE A LOOP\" DIFFERENTLY. In specifications, only a repeat WITHIN\n"
		"THE SAME BRANCH is forbidden - the same part legitimately appears in several branches. Where\n"
		"the graph is of work centres feeding each other, ANY repeat is a loop. One question, two\n"
		"correct answers; deciding which you are asking is the design.\n"
		"\n"
		"KEY: EXPLODE IN WAVES BY LEVEL, NOT DEPTH-FIRST. Take every line not yet expanded at level\n"
		"N, mark them, raise the level, append what they contain. Two things fall out for free: the\n"
		"depth limit becomes a comparison rather than a parameter threaded through recursion, and the\n"
		"result arrives already ordered by level, which is what the \"structure of the product\" report\n"
		"wants. Fix the convention for the limit and state it: do not explode at all, explode fully,\n"
		"or explode exactly N levels.\n"
		"\n"
		"KEY: THE LOOP CHECK IS A PATH CARRIED IN EACH ROW, NOT A GLOBAL SET OF VISITED NODES. Every\n"
		"row holds the chain from the root down to itself; a child copies the parent's chain and adds\n"
		"itself, and if it is already there, this branch stops. A global set would refuse the second\n"
		"legitimate occurrence in a different branch. And when it fires, REPORT THE PATH, not the name\n"
		"- \"a loop was found\" without the chain is unactionable. Paid for in memory: one copied path\n"
		"per row, against wrong answers.\n"
		"\n"
		"KEY: \"WHICH SPECIFICATION APPLIES\" IS A LADDER OF WEAKENINGS RESOLVED IN ONE QUERY. Item\n"
		"plus variant plus department, then the same with no department, then ignoring department,\n"
		"then item with no variant, then item alone - each branch carrying a PRIORITY CONSTANT, all\n"
		"unioned, ordered by priority, take one. Five separate lookups would be five round trips per\n"
		"exploded line.\n"
		"* AND THIS IS THE SAME MOVE THAT APPEARS IN PRICING, IN DEBT MATCHING AND IN SUPPLY: A\n"
		"USER-CHOSEN \"STRATEGY\" NEVER BRANCHES THE ALGORITHM - IT SUPPLIES AN ORDER. Adding a new\n"
		"source of the answer is adding a branch with a number, not rewriting the resolver.\n"
		"STOP: AND THE RUNGS MUST CARRY EXPLICIT PRIORITIES - \"more specific\" is never derived from\n"
		"the DATA. A ladder that ranks candidates by the LENGTH OF A HIERARCHICAL CODE is correct only\n"
		"while every level of the coding scheme is the same width, and it is wrong from the day\n"
		"somebody adds a level or a four-character code beside a two-character one. The same for\n"
		"tie-breaks: ordering by a REFERENCE gives an order the storage happens to have, so which of\n"
		"two equally specific rules wins is undefined and changes between bases.\n"
		"* SO EVERY BRANCH NAMES ITS OWN NUMBER, AND THE LAST TIE IS BROKEN BY SOMETHING A PERSON\n"
		"CHOSE - a priority column, a date, anything they can be shown. A resolver whose answer cannot\n"
		"be explained in one sentence will be argued with, and there will be nothing to point at.\n"
		"* AND IT IS READ AS OF A DATE, with the cache keyed to the DAY. Precision finer than a day\n"
		"was judged unnecessary here - a decision worth copying, and worth stating.\n"
		"\n"
		"NOTE: THE NUMBER OF UNITS PRODUCED IS A FRACTION, NOT A NUMBER - carried down as numerator\n"
		"and denominator, with the division left until last. Four levels of nesting and a norm of\n"
		"\"three per hundred\" is where rounding at each level starts inventing material. That a\n"
		"working system carries a small rational-arithmetic helper for this is the evidence that it\n"
		"matters.\n"
		"\n"
		"NOTE: A BY-PRODUCT IS NETTED OFF THE REQUIREMENT BEFORE THE REQUIREMENT IS EXPLODED, and a\n"
		"filter over the result is applied AFTER exploding, consistently across all four tables -\n"
		"filtering before would cut a branch and lose everything under it.\n"
		"\n"
		"KEY: A NORM IS NOT ALWAYS PER UNIT PRODUCED - IT MAY BE PER QUANTITY OF THE PRINCIPAL RAW\n"
		"MATERIAL. \"Paint is two per cent of the weight of the metal\" is a different base from \"two\n"
		"litres per item\", and the line says which one it uses. The coefficient is worked out AS THE\n"
		"WALK PROCEEDS - when the line marked as the principal material is met, it becomes actual\n"
		"over standard - and it also governs the returnable waste (swarf comes from the metal, not\n"
		"from the product).\n"
		"* WHICH MAKES THE ORDER OF LINES SIGNIFICANT: the principal material must be computed before\n"
		"its dependants. That is a real constraint on the data, and it belongs in the description of\n"
		"the object, or someone reorders the lines and the norms change.\n"
		"\n"
		"NOTE: THE EXACT QUANTITY AND THE ROUNDED ONE ARE BOTH NEEDED - the norm as it is, and what\n"
		"will actually be issued once minimum batch and multiplicity are applied. Carry them as TWO\n"
		"columns. (The system examined instead RENAMES the columns around a routine that only knows\n"
		"one name - a working prop, and the sign that the layer below has no way to say which of the\n"
		"two it wants. Give it one.)\n"
		"\n"
		"NOTE: A NORM MAY BE A FORMULA rather than a number, with substitutions from the parameters\n"
		"of the output, from the properties of the product's variant, and from the row being built.\n"
		"It exists to avoid a specification per size. The costs are exactly two and both must be\n"
		"planned for: an interpreter runs inside the explosion loop, and A FORMULA THAT FAILS MUST\n"
		"YIELD ZERO PLUS A NAMED ERROR - the line of the specification, not a silent nothing.\n"
		"\n"
		"KEY: THE EXPLOSION STOPS AT \"WE BUY THIS\", AND THE GATE LIVES ON THE ITEM. Before looking for\n"
		"a specification at all, ask the item how it is OBTAINED - made, subcontracted, or bought. A\n"
		"bought item returns nothing INSTANTLY, with no query, and that branch of the wave ends. Take\n"
		"the gate away and the tree walks into the entire materials catalogue. Default to \"bought\"\n"
		"where the attribute was never filled in: the cheap answer is also the safe one here.\n"
		"\n"
		"NOTE: \"MAKE THIS THE MAIN SPECIFICATION\" IS WRITTEN BACKWARDS - from the specification to\n"
		"every product it outputs, one dated row per (item, variant). \"Main\" is a property of the\n"
		"PAIR (product, date), not of the specification, so one button produces N rows and the\n"
		"operation is not undoable - it is an entry in a periodic register, and the way back is\n"
		"another entry.\n"
		"\n"
		"NOTE: THE ROUTE STAGE IS ATTRIBUTES OF THE COMPONENT ROW, NOT AN OBJECT OF ITS OWN -\n"
		"operation number, route point, department, work centre, carried on every row of the\n"
		"explosion including outputs and waste. And it feeds back: the department taken from the\n"
		"route point participates in choosing WHICH specification applies, so the route decides whose\n"
		"composition is used.") },

	{ wxT("production"),
	  ibMcpText("Costs, month-end close and work in progress - and why the close is several documents."),
	  ibMcpText("PRODUCTION, COSTS AND CLOSING THE MONTH.\n"
		"\n"
		"OVERHEADS ARE KEPT APART. General production costs do not belong to any one item, so they\n"
		"are collected in a COST register of their own and distributed afterwards. Which register\n"
		"depends on the strategy (see `parallel-accounting`): for management figures an\n"
		"AccumulationRegister; where the statutory books lead, turnovers and the accounting\n"
		"register itself, accumulating against the particular account.\n"
		"\n"
		"One large register holding costs AND lots together is also a real design - everything in\n"
		"one place, one pass to resolve it - and so is keeping them separate. The trade is the\n"
		"usual one: one register means one mechanism and one order of resolution; separate ones\n"
		"are simpler each but must then be reconciled with each other.\n"
		"\n"
		"KEY: AND THAT IS THE SECOND FORK, WORTH SEEING WHOLE. The traditional shape gives every\n"
		"accounting subject its own register - lots, costs, work in progress, scrap in production,\n"
		"output, and each of them again for the second set of books. It is how large configurations\n"
		"are built, and it is why they have fifty accumulation registers: each is simple, each has\n"
		"exactly the dimensions its subject needs, and the virtual balance and turnover tables\n"
		"answer its questions directly.\n"
		"\n"
		"The other shape is ONE register of movements, with the subject as a dimension. Everything\n"
		"lands in one place and one resolution pass walks it all. What it saves is the multiplication\n"
		"- one mechanism instead of ten, one order to get right, one place where a new kind of\n"
		"movement is added.\n"
		"NOTE: What it costs is that the dimensions become a UNION: a column that only work in progress\n"
		"needs is empty on every stock row, and the queries grow conditions that the specialised\n"
		"registers did not need. It works while the subjects share most of their key - item,\n"
		"warehouse, department, order - and stops working when one of them is keyed by something\n"
		"nothing else has.\n"
		"\n"
		"NOTE: THE HONEST TEST is not elegance but the QUESTIONS: if each subject is asked about\n"
		"separately, in its own words, by different people, separate registers keep those questions\n"
		"cheap. If everything is really one question - \"what is the value sitting in production\n"
		"right now\" - one register is the shape, and ten registers are ten reconciliations.\n"
		"\n"
		"CLOSING THE MONTH IS NOT ONE OPERATION. It is a pile of regulated ones - distributing\n"
		"overheads, valuing output, adjusting actual cost, writing off what was consumed - and\n"
		"they run in an order that matters. Two ways to carry it:\n"
		" ONE document that performs all of them. Simple, and the whole month closes or does\n"
		" not.\n"
		" A DOCUMENT PER AREA, each closing its own section. More pieces, and much better in\n"
		" practice: rights can be granted per area, so the person who closes payroll is not the\n"
		" person who closes stock; a failure is localised to its own step; and a step can be\n"
		" re-run without redoing the rest. Prefer this once there is more than one person\n"
		" involved - the roles are the reason, not the tidiness.\n"
		"\n"
		"WORK IN PROGRESS IS THE PENNIES AGAIN. What is left unfinished at the close has to take\n"
		"its share of the costs, and that share is a distribution - the same arithmetic, the same\n"
		"remainder, the same decision about where the odd penny lands (see `allocation`). It is\n"
		"the part people find hardest, and the reason is not conceptual: it is that the same\n"
		"rounding problem is met for the third time, now with the numbers mattering to a tax\n"
		"authority.\n"
		"\n"
		"NOTE: THE ORDER OF THE CLOSE IS PART OF THE DESIGN, not an implementation detail. Write it\n"
		"down - in the notes of whatever performs it - because it is invisible in the code and the\n"
		"next person will reorder it while making something else work.\n"
		"KEY: SO LET THE PERSON CHOOSE WHICH STEPS OF THE CLOSE TO RUN, NEVER IN WHICH ORDER. A list\n"
		"of actions on the closing document reads like a program and must not be one: map the chosen\n"
		"actions onto the phases and run the phases in the order the design fixed, whatever order they\n"
		"were listed in. The dependencies between them are not the person's business, and a close run\n"
		"in the order somebody typed produces figures that balance and are wrong.\n"
		"STOP: AND WHERE A PHASE MUST RUN AGAIN BECAUSE THE FIRST PASS CHANGED WHAT IT DEPENDS ON,\n"
		"THAT IS AN ITERATION, NOT A SECOND RUN. Repeat until it stops changing, with a cap, and\n"
		"report which of the two ended it - a fixed point iterated exactly once is a guess that\n"
		"usually holds.\n"
		"\n"
		"KEY: WHAT PEOPLE SAY, AND WHAT THEY ARE ASKING FOR - because nobody dictates this in steps.\n"
		" \"CLOSE THE MONTH\" - the whole list below, in order. Ask which parts they actually run:\n"
		" a trading company skips the processing stages entirely.\n"
		" \"SPREAD THE OVERHEADS\" - compute a BASE first, then distribute in proportion to it.\n"
		" Two steps, and the base is the one they will argue about.\n"
		" \"WORK OUT THE COST\" - the graph adjustment, then the cost of what was produced. Not a\n"
		" formula, and not something a document can do at posting time.\n"
		" \"WORK IN PROGRESS DOES NOT ADD UP\" - the reconciliation step between loading costs onto\n"
		" the account and carrying them off was skipped, or ran before something it depends on.\n"
		" \"WRITE OFF THE DEFERRED EXPENSES\" - this month's slice, by days when the period is\n"
		" partial.\n"
		" \"REVALUE THE CURRENCY\" - exchange differences on what is held in foreign currency.\n"
		" \"THE SHOPS SERVE EACH OTHER\" - the mutual-output cycle below. This sentence is the\n"
		" warning that no closing order exists yet.\n"
		"\n"
		"KEY: AND A REAL CLOSE HAS A REPAIR PROLOGUE BEFORE ANY OF THE ARITHMETIC. Measured as a\n"
		"route of nineteen activities and thirty-four edges - the one genuine workflow in a whole\n"
		"ERP - it begins with five STRICTLY SERIAL steps that fix the state the month was left in:\n"
		"finish the deferred postings, restore the two settlement sequences, post by lots, correct\n"
		"the cost of what was written off. Only then do six independent steps run in parallel, then\n"
		"the managerial and the statutory costing IN PARALLEL WITH EACH OTHER, then tax, and the\n"
		"financial result last.\n"
		"* TWO THINGS FOLLOW. The close is a GRAPH with parallel branches, not a list - and it is\n"
		"the one place a workflow object earns itself (`proportions`: exactly one existed). And\n"
		"COSTING RUNS TWICE, once per set of books, which a five-step checklist has no room for.\n"
		"* AND THE PROLOGUE IS WHY \"CLOSE THE MONTH\" IS SLOW IN A WAY NOBODY EXPECTS: most of the\n"
		"time goes on repairing what was posted badly during the month, not on computing anything.\n"
		"\n"
		"WHAT A FULL CLOSE ACTUALLY CONTAINS, in the order it runs - useful as a checklist, because\n"
		"a close missing a step produces figures that balance and are wrong:\n"
		" 1. DEPRECIATION of fixed and intangible assets.\n"
		" 2. REVALUATION of currency holdings - the exchange differences for the month.\n"
		" 3. DEFERRED EXPENSES written off for their share of the month (a start date, an end date\n"
		" and a method: the month's slice of a yearly insurance, computed by days rather than\n"
		" by twelfths when the period does not start on the first).\n"
		" 4. INDIRECT COSTS DISTRIBUTED - which needs a BASE first: the coefficients each\n"
		" receiver's share is computed from, calculated as its own step over its own list of\n"
		" cost items.\n"
		" 5. SCRAP AND REWORK distributed the same way, on its own base.\n"
		"\n"
		"KEY: HOW INDIRECT COSTS ARE ACTUALLY SPREAD, in three facts:\n"
		" THE BASE IS CHOSEN PER COST ITEM, and the choices are few and standard: by materials,\n"
		" by wages, by output volume, by planned cost, by all direct costs, or by a NAMED LIST of\n"
		" cost items. So the base is computed once, for every one of those measures at the same\n"
		" time, keyed by cost account, department, product group - and each item then picks the\n"
		" column it distributes by. One query, six answers, no re-reading per item.\n"
		" BUT THE COST ITEM DOES NOT HOLD THE BASE - IT HOLDS A REFERENCE TO A NAMED METHOD, and\n"
		" that method carries the whole recipe: which kind of base, which measure of it, which\n"
		" receivers to restrict to, per-receiver coefficients, a percentage, the rounding, and a\n"
		" stored filter. Otherwise \"distribute by wages, but only across these three departments,\n"
		" two of them at half weight\" has nowhere to live, and it is asked for immediately.\n"
		" AND WHERE THE BASE IS \"WHICHEVER FIGURE WE ACTUALLY HAVE\", CHOOSE IT BY WHETHER THE COLUMN\n"
		" TOTALS TO ANYTHING - share of value if that sums above zero, else weight, else quantity -\n"
		" and choose ONCE for the whole run, not per row. Per row it silently mixes bases and the\n"
		" shares stop adding to one.\n"
		" AND THE BASE IS MATERIALISED BEFORE IT IS USED - written out to a register by its own\n"
		" pass, and only then read by the distribution. Two things are bought with that: the base\n"
		" becomes SHOWABLE, which is the first question asked when a cost figure is disputed; and\n"
		" rows summing to zero are dropped in that pass, so division by zero cannot arise later\n"
		" (`derived-registers`). EXCLUSIONS AND WEIGHTS BELONG INSIDE THAT QUERY AS MULTIPLIERS,\n"
		" not as conditions around it: join the exclusion list, the \"did this receiver produce\n"
		" anything\" table and the method's per-row coefficients, and multiply the row by each - a\n"
		" missing join yields one, a match on the exclusion list yields zero, because that\n"
		" register stores the CONSTANT zero rather than a flag - and the whole result is cut by\n"
		" one total-greater-than-zero test. A new kind of exclusion is then a new register and\n"
		" one more factor, never a new branch; rows worth nothing never reach the base register\n"
		" at all; and \"there was nothing to spread this over\" becomes an absent row in a table\n"
		" the person can open, which is the first thing asked when a cost figure is disputed.\n"
		" A SHARE IS THE ORDINARY PROPORTION - this receiver's base over the total base - and the\n"
		" pennies problem is the one in `allocation`. A total base of ZERO is the case to decide\n"
		" deliberately: there is a cost and nothing to spread it over, and silently dropping it\n"
		" is how costs disappear.\n"
		" AND EVERY FIGURE EXISTS IN PARALLEL - accounting, tax, and the tax-designation split -\n"
		" so the base carries a column per measure PER SET OF BOOKS. That is why the table looks\n"
		" wide: it is six measures times the books being kept.\n"
		"\n"
		"STOP: FIXED OVERHEADS ARE NOT SPREAD LIKE THE REST - THEY GO BY NORMAL CAPACITY. Variable\n"
		"overheads follow the actual base. Fixed ones are spread against the NORMAL level of\n"
		"activity the department was planned for, and when the month produced less than that, the\n"
		"unabsorbed remainder is NOT loaded onto the goods: it goes straight to cost of sales as a\n"
		"cost of the period. Loading it onto a small output would inflate the value of stock with\n"
		"the cost of idleness, which is exactly what the rule exists to prevent.\n"
		"NOTE: So the design needs, per department: the normal capacity figure, the split of overheads\n"
		"into fixed and variable, and somewhere for the unabsorbed part to land. Missing any of the\n"
		"three produces figures that look right and overstate inventory in every bad month.\n"
		"\n"
		"SCRAP IS COST THAT NEVER BECOMES PRODUCT. It is collected on its own, and then either\n"
		"charged to whoever is responsible, or spread over the good output of the same product group\n"
		"- by the same base machinery as the overheads, on its own base. What must not happen is\n"
		"scrap quietly sitting in work in progress: it is not unfinished, it is lost, and leaving it\n"
		"there overstates what the department still holds.\n"
		"\n"
		"AND WORK IN PROGRESS IS WHAT IS LEFT AFTER ALL OF THAT - not a figure computed, but the\n"
		"residue: everything loaded onto the department minus what was carried onto finished output\n"
		"and minus scrap. Which is why the reconciliation step above matters so much: an error\n"
		"anywhere upstream lands in work in progress, where it looks like an ordinary balance.\n"
		" 6. DIRECT COSTS, stage by stage through processing.\n"
		" 7. ACTUAL COST ADJUSTED (the graph above), then the cost of finished output computed.\n"
		"\n"
		"KEY: AND THE ORDER OF THE STAGES IS COMPUTED, NOT DECLARED. Which department closes before\n"
		"which, and which processing stage before which, follows from what was actually produced\n"
		"this month - department A's output fed department B, so A closes first. So the close begins\n"
		"by ANALYSING the month's production and deriving that order, and then CHECKS it before\n"
		"using it. A hand-written order is right until somebody adds a department.\n"
		"\n"
		"* HOW THE ORDER IS DERIVED, and it is short: take the month's production as pairs of what\n"
		"WENT IN against what CAME OUT. Anything consumed that nobody produced is bought from\n"
		"outside - those lines are stage ONE. Then repeat: a line whose input is produced only by\n"
		"stages already numbered becomes the next stage. Sweep after sweep, until nothing new gets\n"
		"a number.\n"
		"STOP: AND THE STOPPING CONDITION IS THE DIAGNOSIS. If a sweep numbers NOTHING while unnumbered\n"
		"lines remain, there is no order - the remaining lines feed each other. That is the mutual\n"
		"output below, detected exactly here, and it must be reported as that rather than as a\n"
		"failure to close: the person needs to know which two departments are in the knot.\n"
		"\n"
		"STOP: AND THE CHECK EXISTS BECAUSE OF MUTUAL OUTPUT: two departments serve each other in the\n"
		"same month - the boiler house heats the workshop, the workshop repairs the boiler house -\n"
		"and no order exists at all. It is the cycle from the cost graph wearing different clothes,\n"
		"and it is resolved the same way: detect it, break it deliberately (net the mutual volumes,\n"
		"or price one side at a planned rate), and say in the result that it was broken. A close\n"
		"that loops or silently drops one side of the exchange is the classic production defect.\n"
		"\n"
		"KEY: ADJUSTING ACTUAL COST IS A GRAPH PROBLEM, and knowing that in advance is the difference\n"
		"between a week and a quarter. It is not a loop over documents in date order.\n"
		" A STATE is one place value can sit: the combination of warehouse, department, account\n"
		" and analytics that identifies it. Number them - the algorithm works on integers, not\n"
		" on structures, or every comparison costs a dictionary lookup.\n"
		" A MOVEMENT between two states is an EDGE. One query builds the whole table of them for\n"
		" the period; nothing is read document by document.\n"
		" THE COST OF A STATE is opening balance + arrivals from OUTSIDE + everything arriving\n"
		" along its incoming edges. Which means a state can be computed only when EVERY incoming\n"
		" edge already is - a topological order, and the whole calculation is that order.\n"
		" STOP: AND THE ORDER DOES NOT ALWAYS EXIST. Goods move A to B and B back to A within the\n"
		" month, and the graph has a CYCLE: neither state can be computed first, and a naive\n"
		" pass either loops forever or silently leaves cost behind.\n"
		"\n"
		" * BREAKING ONE IS A SMALL, EXACT ALGORITHM, and it is worth knowing rather than\n"
		" re-deriving: walk the graph depth-first, CARRYING THE PATH - the vertices visited and,\n"
		" for each, the edge that got there. When the next vertex is already ON the path, the\n"
		" cycle is the stretch of path from its first appearance plus the edge that closes it.\n"
		" Find the SMALLEST quantity among that cycle's edges, and subtract it from EVERY edge of\n"
		" the cycle. At least one edge becomes zero - so the cycle is gone - and the arithmetic\n"
		" is untouched, because going round the loop the same amount was removed from what came\n"
		" in and from what went out. Then mark the vertex as already explored so the same cycle\n"
		" is not taken apart twice, and carry on.\n"
		" NOTE: Two details that are easy to lose: the path has to be COPIED at each branch (a shared\n"
		" one leaks vertices between sibling branches), and the closing edge must be included in\n"
		" the minimum - it is often the small one.\n"
		"\n"
		" Nothing in the accounting says this is needed; it emerges from the data, and it is the\n"
		" single hardest part of the whole close.\n"
		"\n"
		"KEY: AND THERE IS A COMPLETELY DIFFERENT WAY TO SOLVE THE SAME GRAPH - WORTH KNOWING BEFORE\n"
		"CHOOSING THE ONE ABOVE. Instead of walking it in order, write it as SIMULTANEOUS EQUATIONS\n"
		"and solve them all at once:\n"
		" A COST CENTRE is the key cost is computed for - organisation, warehouse, kind of stock,\n"
		" item, characteristic, accounting section. Each centre's unit cost is one UNKNOWN.\n"
		" EACH CENTRE GETS A BALANCE EQUATION: opening value + everything that arrived (from\n"
		" outside, and from other centres at THEIR unknown costs) = what left (quantity times\n"
		" THIS centre's unknown cost) + closing value.\n"
		" Arcs that cannot exist are struck out - televisions moved within a warehouse do not\n"
		" become coffee makers - and what remains is a sparse system with one equation per\n"
		" centre.\n"
		" SOLVE IT. Every cost comes out together.\n"
		"\n"
		"STOP: AND THIS IS WHY IT MATTERS: A CYCLE IS NO LONGER A PROBLEM. Mutual transfers, departments\n"
		"serving each other, goods going back and forth - all of it is just coefficients in the\n"
		"matrix. No topological order, no cycle detection, no breaking. The hardest part of the\n"
		"traversal approach simply does not arise.\n"
		"\n"
		"THE METHOD IS CHOSEN BY THE LEFT-HAND SIDE, which is a neat property: value the CLOSING\n"
		"stock as quantity times the unknown, and the system yields the monthly weighted average;\n"
		"value it by FIFO from the actual receipts - a known number - and the same system yields\n"
		"FIFO. One mechanism, two accounting policies, differing in one term.\n"
		"\n"
		"NOTE: THE COSTS: it needs a solver and it is a MONTHLY, batch answer - there is no meaningful\n"
		"cost for a single document mid-month, only a provisional one. And a badly formed system\n"
		"(a centre with no incoming value, a quantity that went out where nothing came in) has to be\n"
		"diagnosed as a system, which is harder to explain to an accountant than \"lot 17 ran out\".\n"
		"NOTE: AND KEEP LAST MONTH'S LOTS APART. Rolling the opening balance into one averaged lot makes\n"
		"FIFO impossible from that point on and quietly changes the figures - the older editions of\n"
		"one well-known system did exactly this and it was treated as a defect.\n"
		" TWO SETS OF BOOKS SHARE THE ALGORITHM AND NOT THE QUERIES: management and statutory\n"
		" figures are read by their own queries and then walked by the same graph code. Writing\n"
		" the traversal twice is how the two quietly start disagreeing.\n"
		"\n"
		"AND IT IS A DOCUMENT, NOT A PROCESSOR (see `shapes`): it produces movements that somebody\n"
		"has to be able to see, reverse and re-run for a period, and \"when was the cost adjusted\"\n"
		"is a question with an answer.\n"
		"\n"
		"KEY: A CALCULATION THAT EMITS A ROW PER INTERMEDIATE STEP MUST COLLAPSE ITS OWN MOVEMENTS. An\n"
		"allocation and a cost solver write once per step, and the steps are not accounting facts. So\n"
		"the last phase reads the document's OWN movements back, groups them by the complete natural\n"
		"key - every dimension, the correspondence, the kind of movement, the operation and the period\n"
		"- writes an empty set to clear them, and writes the grouped result.\n"
		"STOP: THE GROUPING KEY MUST BE COMPLETE OR THE COLLAPSE LOSES FACTS. Leave the period out and\n"
		"a document whose movements span days merges them into one; leave one dimension out and rows\n"
		"that genuinely differ merge silently. And the register briefly holds a superset of the truth,\n"
		"so nothing may read it between the two writes.\n"
		"\n"
		"KEY: AND THIS MACHINE IS NOT ABOUT COST. What it actually does is carry a VALUE ALONG A PATH\n"
		"through states, splitting and merging it as the path branches - and that shape turns up all\n"
		"over an accounting system:\n"
		" overheads pushed down through a hierarchy of departments, each passing on what it\n"
		" received plus its own;\n"
		" services re-invoiced along a chain of parties, where the cost has to arrive at whoever\n"
		" finally consumed it;\n"
		" a mark-up applied stage after stage through processing, so the last stage knows what\n"
		" the first one contributed;\n"
		" any \"distribute this in proportion, then distribute the result again\".\n"
		"Recognise it by the sentence \"the amount has to travel\" - the moment a distribution feeds\n"
		"ANOTHER distribution, it is this algorithm and not a formula. Build it once, keep the\n"
		"traversal separate from the queries that fill the graph, and the second use costs a query\n"
		"instead of a rewrite. Production is simply where it is met first and where it is\n"
		"unavoidable.\n"
		"\n"
		"KEY: A MOVEMENT ROW NAMES BOTH ENDS, BECAUSE PRODUCTION IS A TRANSFER AND NOT A CREATION.\n"
		"Every analytical coordinate of the normalised table exists twice - the source value and the\n"
		"receiver value - so one row describes a whole move, and the generators read one half writing\n"
		"the expense and the other writing the receipt. Carry it into the register too: each row holds\n"
		"its own key AND the opposite key as correspondence, which turns a balance-with-history into a\n"
		"ledger that answers \"against what\" without matching amounts across rows of the same document.\n"
		"Where value moves between keys of ONE register, that correspondence is what makes it\n"
		"self-balancing with no chart of accounts.\n"
		"NOTE: The costs are doubled width and mirrored argument lists - a transposition between the\n"
		"two halves is invisible and lands as a misfiled amount, never as a crash. Resolve the\n"
		"opposite side BEFORE the row is formed, and say so where it is formed, because nothing\n"
		"enforces the order.\n"
		"\n"
		"HOW WORK IN PROGRESS ACTUALLY MOVES, because \"it takes its share\" hides the mechanism.\n"
		"Costs are loaded onto the work-in-progress account as they are incurred - debited to it,\n"
		"again and again, from stock and from everywhere else. At the close the account is\n"
		"credited off: the accumulated amount is carried onto the cost accounts it belongs to.\n"
		"Then the close has to LOOK at what it has done - the loading and the carrying off do not\n"
		"land equal, deltas appear between the accounts - and level them. Only after that does the\n"
		"per-item distribution of actual cost run, position by position.\n"
		"\n"
		"So the sequence is: accumulate, carry off, RECONCILE, then distribute. The reconciliation\n"
		"step is the one that gets left out, because nothing demands it until the balance does not\n"
		"balance - by which time the distribution has already run on figures that were not final.\n"
		"\n"
		"NOTE: NAME ACCOUNTS BY WHAT THEY ARE, NEVER BY THEIR NUMBER. A chart of accounts is\n"
		"legislation: the numbering differs by country and changes with the law, while the ROLES\n"
		"are the same everywhere - the account work in progress accumulates on, the account stock\n"
		"is held on, the accounts production costs are gathered into. Think and write in those\n"
		"terms, and take the actual accounts from the chart the configuration has (a predefined\n"
		"account is exactly how code holds onto one - see `predefined`). A mechanism with numbers\n"
		"written into it is wrong the first time it meets another chart, and wrong silently: the\n"
		"posting still goes somewhere.\n"
		"\n"
		"* AND THE CHAIN ENDS AT THE FINANCIAL RESULT. The last document of the period closes the\n"
		"settlements and determines what was earned - everything above exists to make that figure\n"
		"correct. It is called different things in different jurisdictions and the concept is\n"
		"everywhere; if a design has no such terminal step, the question to ask is not \"do you\n"
		"need one\" but \"where do you close the period today\".\n"
		"\n"
		"KEY: WORK IN PROGRESS IS A BALANCE, NOT A COMPUTATION. One register where a PARTIAL report of\n"
		"output is a receipt of progress and a FINISHED one is an expense of it, the two told apart\n"
		"by a kind on the row. Then \"what is unfinished\" is a balance reading like any other, instead\n"
		"of a figure derived at the close by subtracting things (`shapes`).\n"
		"* AND WORK IN PROGRESS NEEDS COORDINATES OF ITS OWN, DECLARED BESIDE THE DOCUMENT'S. The\n"
		"balance sits for months and is read by somebody other than the person who consumed the\n"
		"material, so the department, the product group and the order it hangs under are not always\n"
		"the ones the consumption was booked in. Carry a second, OPTIONAL set on the document plus one\n"
		"flag saying whether it is in use, and resolve each coordinate once - in the query that builds\n"
		"the movement table - so nothing downstream ever asks the flag. The cost is one conditional\n"
		"expression per coordinate per document text, repetitive enough to be worth generating;\n"
		"forcing the balance onto the consumption coordinates costs more, because the report the\n"
		"accountant actually opens cannot then be grouped the way the work is organised.\n"
		"* AND A ROW THAT WOULD CANCEL ITSELF IS GUARDED AWAY rather than written as two movements -\n"
		"a receipt and an expense of the same amount in the same instant say nothing and cost two\n"
		"rows for ever.\n"
		"* ONE REPORTED OUTPUT MAY SPLIT INTO TWO EVENTS with the cost apportioned between them; take\n"
		"the second part by SUBTRACTION so the halves add back exactly (`allocation`).\n"
		"\n"
		"KEY: WHOSE IT IS REPLACES WHERE IT WAS MADE. In subcontract work the marker lives on the\n"
		"COST ITEM, not on the document: where it holds, the counterparty becomes a dimension and the\n"
		"usual triple - department, product group, cost item - is not filled at all, because the cost\n"
		"belongs to somebody else's job. And the mirror case - OUR materials in THEIR shop - gets registers\n"
		"of its own, two of them: what is out there, and a lot register carrying its cost with BOTH\n"
		"the original receipt and the transfer as dimensions, because the cost has to survive the\n"
		"journey and come back attached (`not-mine`).\n"
		"* AND A RULE OF THIS KIND SHOWS UP AS A FINAL WASH OVER THE FINISHED ROW, appearing verbatim\n"
		"in every builder. Repetition in three places is evidence that it is a RULE and belongs in\n"
		"one, not that somebody copied it.\n"
		"\n"
		"NOTE: HOW A POSTING MODULE OF A MEGABYTE IS ORGANISED, since one exists and it has a shape\n"
		"worth knowing: about fifteen routines whose entire body is a query TEXT, one per pair of\n"
		"(document, tabular section), every one of them ending in the SAME fixed column list writing\n"
		"into the SAME temporary table. The variety of documents is absorbed at the query level, and\n"
		"the thousand lines of movement logic below know nothing about which document they serve.\n"
		"* THE COST IS THAT THE CONTRACT IS THE COLUMN LIST, and it is checked by nothing. Write it\n"
		"down beside the temporary table; it is the interface of the whole module.\n"
		"\n"
		"KEY: A SHIFT IS A BOUNDARY, NOT A DOCUMENT. Reduce the pair (date, shift) to ONE value - the\n"
		"moment the shift began - and let everything downstream use only that. A shift crossing\n"
		"midnight then needs no special case anywhere except in that one reduction: the hours before\n"
		"it starts belong to the previous day, and \"which day does the night shift belong to\" is\n"
		"answered once.\n"
		"* AND CLOSING A SHIFT IS A PROHIBITION LIKE ANY OTHER (`closing-a-period`): a small register\n"
		"of closed shifts per department, checked BOTH against the document as it stands in the base\n"
		"AND against its new values - somebody will move a document out of an open shift into a\n"
		"closed one, or the reverse.\n"
		"\n"
		"KEY: ASSIGNING A MATERIAL TO THE PRODUCTS IT WENT INTO IS A LADDER OF WEAKENINGS, and it is\n"
		"worth writing down because the alternative is material left hanging. Match the consumption\n"
		"against the requirements on the full key first - material, variant, specification, product\n"
		"group, order, cost account, cost item, tax designation. Empty result: drop the cost item.\n"
		"Still empty: distribute across the products of this specification regardless of\n"
		"requirements, by value or weight or quantity. Still empty: drop the specification and spread\n"
		"over all output. Still empty: leave it, and SAY SO. Each rung is a decision about what the\n"
		"figure means, so the ladder belongs in the documentation of the close, not in a comment.\n"
		"\n"
		"STOP: ONE QUERY TEXT SERVING FOUR SETS OF BOOKS BY COMMENTING BRANCHES IN AND OUT IS A TRAP\n"
		"WORTH NAMING. It is real, it exists, and it does keep one source of truth for four\n"
		"variants - but the text stops being checkable: a typo inside a marker is caught by nothing,\n"
		"and the query nobody can run as written is the query nobody can debug. If the variants\n"
		"differ only by fields and table names, DECLARE the differences and assemble the text\n"
		"(`posting`) rather than hiding them in comments.") },

	{ wxT("user-formulas"),
	  ibMcpText("Letting people write the rule: indicators as data, expression evaluated at run time."),
	  ibMcpText("WHEN THE RULE BELONGS TO THE PERSON, NOT TO THE PROGRAMMER.\n"
		"\n"
		"THE SIGNAL: \"the bonus is worked out differently for each scheme\", \"the discount depends\n"
		"on the manager's own conditions\", \"we change how this is calculated a few times a year\".\n"
		"Written as code, every change is a developer, a release and a wait - and the rule is not\n"
		"actually the developer's to know.\n"
		"\n"
		"THE SHAPE IS THREE PARTS, and it is the same in payroll, in pricing, in bonuses, in\n"
		"scoring and in cost allocation:\n"
		" INDICATORS - a catalogue of the things a formula may refer to, each with a name and a\n"
		" type: hours worked, revenue of the department, plan fulfilment, tariff, coefficient.\n"
		" They are DATA, so a new one is added without touching anything.\n"
		" VALUES OF INDICATORS - a register keyed by indicator plus whoever it is about plus the\n"
		" period it holds for. This is where the numbers come from when a formula runs.\n"
		" THE FORMULA ITSELF - a text stored beside the scheme, written in the platform's own\n"
		" script and EVALUATED at run time with the indicators bound as variables. The engine\n"
		" that runs modules is the same engine; there is no second expression language, and no\n"
		" parser to write.\n"
		"\n"
		"* WHAT THIS BUYS is that the rule stops being a release. A scheme is a row, its formula is\n"
		"a string, and the person who owns the rule edits it.\n"
		"\n"
		"NOTE: AND WHAT IT COSTS, said before it is built: a formula written by a person can be WRONG -\n"
		"a name that does not exist, a division by zero, a reference to an indicator nobody filled\n"
		"in. So it needs the same three things any code needs, exposed to a non-programmer: a CHECK\n"
		"when it is saved (compile it, do not wait for the payroll run), a clear error naming the\n"
		"scheme and the indicator rather than a stack, and a TEST - let them run it against one\n"
		"person for one month and see the number.\n"
		"NOTE: Do not let a formula reach the database or change anything. It computes a value from the\n"
		"indicators it was given, and nothing else - which is also what makes it safe to run\n"
		"thousands of times in a loop.\n"
		"\n"
		"NOTE: AND KEEP THE INDICATORS COARSE. The temptation is to expose everything so any formula is\n"
		"possible; the result is a language nobody can use and every formula reads the whole\n"
		"database. Publish the dozen quantities people actually name when they describe the rule out\n"
		"loud - that list is short, and it is the real specification.\n"
		"\n"
		"KEY: A FAILING FORMULA YIELDS ZERO AND A NAMED MESSAGE, NEVER AN ABORT. It is written by a\n"
		"person, so it WILL be wrong - a missing indicator, a division by zero, a typo. The run must\n"
		"continue and report which scheme, which line and which formula failed. A payroll that stops\n"
		"on the first bad formula is a payroll that cannot be run at all on the day it matters.\n"
		"\n"
		"KEY: THE FORMULA IS STORED AS SLOTS, AND THE READABLE FORM IS A RENDERING. What is kept is\n"
		"the expression with the indicators as positional references; what a person sees is produced\n"
		"by substituting their names back in. Storing the names themselves means a rename breaks\n"
		"every formula ever written.\n"
		"STOP: AND THE SUBSTITUTION MUST BE A PROPER SCAN, NOT A TEXT REPLACE. Replacing slot 1 by\n"
		"name inside a formula that also uses slot 10 corrupts it - the shortest name matches first.\n"
		"This is exactly the defect found in the system examined, and it only shows up on schemes\n"
		"with ten or more indicators.\n"
		"\n"
		"NOTE: WHERE THE ENGINE COMPUTES SOME INDICATORS ITSELF, THEIR RESOLUTION BELONGS IN ONE\n"
		"PLACE, generated from the declared list rather than written out - and the conversion of\n"
		"kinds (a percentage divided by a hundred, a reference passed through untouched) belongs in\n"
		"that same place. Otherwise every formula author has to know which indicators are already\n"
		"scaled.\n"
		"\n"
		"NOTE: AND THE TRACE IS PART OF THE FEATURE, NOT A DEBUGGING AID. \"Why did this person get\n"
		"this amount\" is asked about every formula-driven figure, so the run must be able to hand\n"
		"back what it read, in order, with the values it used. Where the trace is built only for a\n"
		"person at a screen, a run on the server produces nothing to show - which is where it is most\n"
		"needed (`long-operations`). And the trace is a TREE with navigable evidence - each figure\n"
		"carrying what it was read from, openable - because a flat list of numbers answers \"what\" and\n"
		"never \"why\".\n"
		"\n"
		"KEY: AN INDICATOR IS A CATALOGUE ENTRY, AND SOME OF THEM ARE COMPUTED RATHER THAN ENTERED.\n"
		"The customer adds their own; a couple of dozen are the product's, resolved by the engine from\n"
		"registers or from the run itself. Both look the same in a formula, which is the point - and\n"
		"the resolution of the computed ones is ONE place, generated from the list, never a lookup\n"
		"table somebody maintains beside it.\n"
		"* AND THEIR VALUES COME FROM MORE THAN ONE PLACE, so say which wins: a register of values\n"
		"entered per subject and a register of values entered for the whole company, where an EMPTY\n"
		"subject means \"everybody\" (`combining`: an empty value is a meaning). A report that computes\n"
		"figures can be a feeder too - its own query writing indicator values - which is cheap and\n"
		"must be deliberate, since a report then has a side effect.\n"
		"* A SCALE - a ladder of from-to bands with a result - IS AN INFORMATION REGISTER AND A\n"
		"FUNCTION IN THE FORMULA LANGUAGE AT ONCE. That pairing is what keeps \"pay 3 per cent up to\n"
		"this much and 5 above it\" out of code, and it is the single most-asked-for shape after plain\n"
		"arithmetic.") },

	{ wxT("payroll"),
	  ibMcpText("What payroll needs from a platform - and what it costs when those two metatypes are absent."),
	  ibMcpText("PAYROLL IS ITS OWN WORLD, and the first honest thing to say is what it needs.\n"
		"\n"
		"STOP: IT ASKS FOR TWO METATYPES OF ITS OWN - A CALCULATION REGISTER AND A CHART OF\n"
		"CALCULATION TYPES. In systems built for payroll those two carry the whole machinery below -\n"
		"period of validity, displacement, base, recalculation - and it is done FOR you. GO AND CHECK\n"
		"WHETHER THIS BASE HAS THEM (`metadata_accepts` on the configuration answers it) rather than\n"
		"assuming either way, and say the answer out loud before a date is agreed: with them, payroll\n"
		"is application code; without them, every mechanism named below is yours to build out of\n"
		"registers and documents, and that is a different project.\n"
		"\n"
		"KEY: AND THE ENGINE'S HALF OF IT IS SMALL - FOUR READINGS, measured against a system that has\n"
		"the metatype. Worth knowing, because it turns \"we cannot do payroll\" into a bounded piece of\n"
		"work, and because building the wrong three of the four is the usual way this is got wrong:\n"
		" THE ACTUAL PERIOD OF ACTION - the interval a record declares, MINUS the intervals of the\n"
		" records that displace it. Computed WHEN READ and never stored: a record written today\n"
		" changes the actual period of records written last month, so a stored answer is wrong the\n"
		" moment anything is added. This is the one piece that cannot be faked by a table.\n"
		" THE BASE - given a set of records and the kinds they are computed from, the amounts.\n"
		" ⚠ AND THIS IS THE ONE THAT IS ROUTINELY REJECTED IN PRACTICE: its period rule is fixed,\n"
		" while the domain wants the rule to depend on the KIND of accrual, and there is no\n"
		" parameter for that. In the system measured, withholdings and statutory contributions\n"
		" write the join by hand instead, saying so in a comment - four near-identical sixty-line\n"
		" queries kept in step by discipline. If this reading is ever built, its period rule has\n"
		" to be an argument.\n"
		" THE RECALCULATION TABLE - a store that fills ITSELF from declared dependencies, recording\n"
		" what must be recomputed because something behind it moved. Its rows are (the document to\n"
		" redo) by (the values it was about), and each of its dimensions is BOUND to a dimension of\n"
		" the source: write a record there and the engine writes the row here. Nobody writes those\n"
		" rows in the ordinary path - which is the whole point, because the propagation has to\n"
		" happen on EVERY write, including ones nobody remembered.\n"
		" THREE DECLARATIONS ON THE KIND - what it is based on, what it displaces, what it leads.\n"
		"* EVERYTHING ELSE IS APPLICATION CODE - and in the system measured it was eighteen thousand\n"
		"lines of it against fifty lines of declaration. Do not expect the metatype to carry the\n"
		"payroll; expect it to carry those four readings.\n"
		"KEY: AND IT IS NOT ONE PAIR - IT IS ONE PAIR PER FAMILY OF CALCULATION. Measured in a system\n"
		"that has the metatype: seven registers and seven charts of kinds, paired exactly, and the\n"
		"pairing is the design - accruals and deductions for each circuit, statutory contributions,\n"
		"average earnings, and the reflection of pay in the ledger.\n"
		"* ACCRUALS AND DEDUCTIONS ARE NEVER ONE REGISTER WITH A SIGN. They have different bases,\n"
		"different dependence on the period and different displacement rules; average earnings is a\n"
		"third again, because it READS the history of accruals and is itself a base for others.\n"
		"* AND ONLY THE FAMILIES THAT CROWD EACH OTHER NEED A PERIOD OF ACTION - two of the seven. The\n"
		"rest merely compute over a base. That is worth knowing before building: displacement is the\n"
		"expensive half of the machinery, and most of what is asked for does not need it.\n"
		"\n"
		"KEY: THE ORDER OF PASSES IS DATA, AND THE RESULT IS WRITTEN BETWEEN THEM. Kinds are grouped\n"
		"into passes - what is computed first, what depends on it, what depends on that - and the\n"
		"pass number is simply the position of the value in the enumeration. The set of records is\n"
		"WRITTEN TO THE DATABASE between passes, because the next pass reads its own base back with a\n"
		"query. Holding everything in memory across passes looks faster and cannot work: the base\n"
		"reading is a query, and a query cannot see what has not been written.\n"
		"\n"
		"KEY: REPRODUCIBILITY IS STORED, NOT RECOMPUTED. Average earnings is itself a register with a\n"
		"row per contributing month, editable by a person - and an edited row is read back exactly as\n"
		"edited, because the reason it was edited is not in the system. The per-unit rate is FROZEN\n"
		"onto the record so a later reversal uses the rate that was actually paid. And which version\n"
		"of a rule applies is chosen by THE DATE OF THE EVENT against a list of dates the rules\n"
		"changed on - never by today's date (`fixed-assets`: a norm is dated more strongly than a\n"
		"parameter).\n"
		"\n"
		"WHAT THE MACHINERY ACTUALLY IS, in case it is being built or judged:\n"
		" A KIND OF ACCRUAL is a thing in its own right - salary, bonus, sick leave, holiday,\n"
		" each with its own formula. They are data, not code branches: somebody adds one.\n"
		" TWO PERIODS, ALWAYS. The period the money is FOR (a holiday covering the last week of\n"
		" March) and the period it is REGISTERED in (the March payroll run). Every figure needs\n"
		" both, and reports ask for one or the other depending on the question - taxes by\n"
		" registration, averages by validity.\n"
		" DISPLACEMENT: some accruals push others out for the days they cover. Holiday displaces\n"
		" salary for those days - the salary is not reduced by hand, it is CROWDED OUT by a\n"
		" period that overlaps it. Without this, a month with any absence is wrong by\n"
		" construction.\n"
		" BASE: some accruals are computed FROM others. A contribution is a percentage of a set\n"
		" of accruals; average earnings are computed over a window of previous ones. So a kind\n"
		" of accrual declares WHICH kinds form its base, and the order of calculation follows\n"
		" from that - the same dependency ordering as the cost graph in `production`.\n"
		" REVERSAL: backdated changes do not edit old records, they STORNO them - a negative\n"
		" entry in the new period cancelling the old figure, and a fresh entry replacing it. The\n"
		" filed reports stay filed and the correction is visible as a correction.\n"
		"\n"
		"* AND WHAT IS DECIDED BY LAW IS DECIDED BY DATE, more than anywhere else in accounting.\n"
		"Contribution rates, tax thresholds, indexation rules, minimum wage - each changed on a\n"
		"named day, and last year's payroll must still recompute as it was filed. Two habits from\n"
		"systems that survive this: every legislative boundary is a NAMED constant (a function or a\n"
		"register entry called \"the day rule N came in\"), never a date literal inside a formula;\n"
		"and where the law itself was ambiguous, the CHOICE of interpretation is stored as a\n"
		"setting, so an organisation that read it differently is not a fork of the code.\n"
		"\n"
		"NOTE: AND THE SCHEDULE IS A SEPARATE MECHANISM AGAIN: working-time norms per calendar per\n"
		"month, before any of the above can compute a day. It is the first thing to build and the\n"
		"one most often left until last.\n"
		"\n"
		"KEY: WHO IS IN THIS RUN IS A READING, NOT A LIST. The population is the people in force as\n"
		"at a moment, MINUS those already covered by another posted document of the same period -\n"
		"an anti-join, not a flag on a person. Then two runs cannot pay somebody twice, and a\n"
		"document entered late falls into the next run by itself.\n"
		"\n"
		"KEY: A CEILING IS CUMULATIVE, AND A GROSSED-UP AMOUNT IS SOLVED THEN CORRECTED. A cap on\n"
		"contributions applies to the year to date, so the base already used must be subtracted\n"
		"before the rate is applied - a cap tested against the month alone is wrong from the second\n"
		"month on.\n"
		"* AND \"PAY THEM THIS MUCH NET\" IS SOLVED IN CLOSED FORM PER BAND AND THEN ADJUSTED BY A\n"
		"DELTA, because rounding to two decimals breaks the algebra: the closed form gives the right\n"
		"answer to the exact arithmetic and the wrong one to the rounded arithmetic. Iterating\n"
		"instead is slower and no more correct; the delta is the honest fix and belongs beside the\n"
		"formula with a note saying why.\n"
		"\n"
		"KEY: WHAT \"BASE\" MEANS IS DECLARED ONCE FOR THE WHOLE FAMILY, NOT PER KIND. One setting on\n"
		"the chart of kinds says whether a base is gathered BY PERIOD OF ACTION or BY PERIOD OF\n"
		"REGISTRATION, and everything else follows from it. Getting it wrong is not a defect that\n"
		"shows: the figures are plausible and consistently a month out.\n"
		"* AND WHICH PERIOD A PARTICULAR ACCRUAL TAKES ITS BASE BY IS A PROPERTY OF THE KIND, NOT OF\n"
		"THE RULE. Average earnings looks back over whole closed months; a percentage of this month's\n"
		"pay looks at this month. Write it on the kind and let the reader ask the kind.\n"
		"* THE BASE ITSELF IS BEST SHAPED AS A FUNCTION OF A DIMENSION MAP - give it the person, or\n"
		"the person and the job, or the department, and it answers for exactly that key. The same\n"
		"question is genuinely asked twice at different widths (once per person for a ceiling, once\n"
		"per job for an allocation), and one parameterised reader beats two.\n"
		"* AND WHERE THE ENGINE'S OWN BASE TABLE IS TOO COARSE, REPLACING IT WITH A HAND-WRITTEN JOIN\n"
		"IS LEGITIMATE - it is what the engine would have written - but say so where it is written,\n"
		"because the two then have to be kept in step by discipline.\n"
		"\n"
		"KEY: THE THREE DECLARATIONS ON A KIND HAVE ARITHMETIC BETWEEN THEM, AND IT IS WORTH\n"
		"ENFORCING. A kind's LEVEL is exactly one above the highest level of what it is based on, so\n"
		"the pass number is derived rather than typed; and the list of kinds it LEADS must contain the\n"
		"list it is BASED ON, because anything that feeds you must be able to wake you. Check both\n"
		"when the kind is saved - a cycle or a gap found at the save is a message, found at the run it\n"
		"is a payroll that silently misses a recalculation.\n"
		"* AND A RECALCULATION ROW IS CONSUMED, NOT MERELY READ. The register records who must be\n"
		"recomputed; the run reads those rows, recomputes, and DELETES exactly the rows it honoured.\n"
		"Left in place they are recomputed for ever; deleted wholesale, the ones that arrived during\n"
		"the run are lost. Delete by key, not by clearing the table.\n"
		"* THE SWEEP THAT FILLS IT HAS THREE TERMS AND ALL THREE ARE NEEDED: records whose period\n"
		"OVERLAPS what changed, records registered EARLIER than the change, and kinds that are LED BY\n"
		"or DISPLACED BY what changed. Drop any one and a class of dependants stops being recomputed -\n"
		"quietly, and only for the people who had that combination.\n"
		"\n"
		"KEY: A REVERSAL IS A NEGATIVE RECORD THAT REMEMBERS BOTH ITS PERIODS AND ITS ORIGINAL. Not a\n"
		"deletion and not an edit: a row carrying the period it is FOR, the period it is registered\n"
		"in, and a link to the record it cancels - so the old month still reproduces and the new month\n"
		"shows the correction as its own fact. And once a document has been corrected or reversed it\n"
		"is FROZEN: further edits go into a new correction, or the chain of who cancels whom stops\n"
		"being readable.\n"
		"* AND AN ACCRUAL THAT SPANS MONTHS IS SPLIT INTO MONTHLY RECORDS BEFORE IT REACHES THE\n"
		"REGISTER. Splitting later means every reader splits, and they will not all split the same\n"
		"way. The same move upstream: occupancy or state periods are derived from EVENTS once, as\n"
		"intervals, rather than re-derived by each report that needs \"how long was this so\".\n"
		"\n"
		"KEY: A CALCULATION METHOD IS AN ENUMERATION AND A SWITCH, NOT A SCRIPT - and each method\n"
		"DECLARES WHAT DATA IT NEEDS as a structure of flags. The engine then gathers only what some\n"
		"method in this run asked for, one temporary table per concern (time, the base, the\n"
		"indicators, the scales), and hands each method its own slice. A method added tomorrow\n"
		"declares its appetite and gathers nothing itself.\n"
		"* WHICH IS THE LINE BETWEEN THIS AND `user-formulas`: the METHOD is a closed set the product\n"
		"owns; the FORMULA is an open set the customer owns. Letting a customer write a method is how\n"
		"a payroll becomes unsupportable; letting them write a formula is the feature.\n"
		"\n"
		"NOTE: AND \"HOW MUCH TIME\" HAS MORE THAN ONE ANSWER, SO THE RECORD CARRIES SEVERAL. Days and\n"
		"hours, worked and scheduled, within the period of action and within the period of\n"
		"registration - six resources on one row, because every one of them is asked for by some rule\n"
		"and deriving one from another needs the schedule again. Time is not an input to the\n"
		"calculation; it is a SCHEDULE the register is bound to.\n"
		"NOTE: AND WHERE A STATUTORY RULE IS GENUINELY AMBIGUOUS, THE VARIANT IS A SETTING, NOT A\n"
		"DATE. Which reading of a rule this company follows is a decision they made and can defend,\n"
		"and it does not change on a date; the ALGORITHM VERSION, by contrast, is chosen by the date\n"
		"of the EVENT being computed, never by today. Two different mechanisms that look alike and\n"
		"must not be merged.\n"
		"NOTE: AND TWO SMALL THINGS THAT COST MORE THAN THEY LOOK. A hand-written rounding needs its\n"
		"WINDOW written down beside it - what is being rounded to how many places, and at which step -\n"
		"or the same routine is reused one step too early and the difference reappears somewhere else.\n"
		"And a run that complains per record will complain a thousand times about one cause: keep a\n"
		"small table of what has already been said and say each thing once, naming how many records it\n"
		"affected.") },

	{ wxT("vat"),
	  ibMcpText("Indirect tax: the designation that follows every line, and the earlier of two events."),
	  ibMcpText("VAT IS TWO MECHANISMS, AND BOTH ARE EASY TO MISS UNTIL AN AUDIT.\n"
		"\n"
		"KEY: FIRST, A TAX DESIGNATION TRAVELS WITH EVERY LINE. Not the rate - the PURPOSE: is this\n"
		"purchase for taxable activity, for exempt activity, for something outside the tax\n"
		"altogether, for non-business use. It decides whether the input tax may be recovered at all,\n"
		"and it has to be carried on the movement, through stock, through cost, through the\n"
		"write-off - because goods bought for one purpose get used for another, and the correction\n"
		"is computed from what they were bought AS.\n"
		"NOTE: Bolting it on later means every register gains a dimension and every historic row has an\n"
		"empty one. This is the dimension worth having from the first day in any base that will\n"
		"ever see indirect tax.\n"
		"\n"
		"KEY: SECOND, THE LIABILITY ARISES ON THE EARLIER OF TWO EVENTS - the shipment or the money -\n"
		"and which came first is knowable only by looking at both. So the shape is: each side\n"
		"records what it caused as EXPECTED, and a later step decides which event was first and\n"
		"CONFIRMS one of them. Hence the pairs of registers - expected against confirmed, for sales\n"
		"and for purchases - and the reconciliation between them, which is where the tax invoices\n"
		"are matched up.\n"
		"NOTE: Computing tax at the moment of the sale alone is right in the simple case and silently\n"
		"wrong the first time somebody prepays.\n"
		"\n"
		"THE RATE IS A KIND, NOT A NUMBER (`shapes`): an enumeration member whose current percentage\n"
		"comes from a function or a dated register, so old documents keep old figures. And the tax's\n"
		"own parameters - registration status, special regimes, thresholds - are read AS OF THE\n"
		"DOCUMENT'S DATE for the same reason.\n"
		"\n"
		"NOTE: AND THE ARITHMETIC HAS TWO DIRECTIONS: tax INCLUDED in the price is extracted from it,\n"
		"tax ON TOP is added to it, and the two produce different totals from the same numbers\n"
		"(`printing`). Which one applies is a property of the agreement or the price type - never a\n"
		"constant in the calculation.\n"
		"\n"
		"NOTE: THE PRINTED TAX DOCUMENT IS ITS OWN OBJECT, with its own number, its own state (issued,\n"
		"registered, rejected) and its own reporting. It is created FROM the sale, and it is not the\n"
		"sale - which matters the moment one invoice covers several deliveries, or one delivery is\n"
		"invoiced in parts.\n"
		"\n"
		"STOP: TWO DIFFERENT RATES CAN BOTH BE ZERO AND MEAN OPPOSITE THINGS. \"Not taxable\" and\n"
		"\"taxable at nought\" produce the same number and different legal consequences - one has no\n"
		"object of taxation, the other is taxed at zero WITH the right to reclaim. Any code that\n"
		"reduces the rate to its NUMBER has lost the distinction, and the loss surfaces in the return\n"
		"rather than in the document. THE RATE IS A KIND; the percentage is only one of its\n"
		"projections, and behaviour in the return is another.\n"
		"* AND THE RATE IS LOOKED FOR ON THE LINE FIRST AND ON THE ITEM AFTER - the line may override,\n"
		"the item is the default.\n"
		"\n"
		"KEY: THE PURPOSE A THING WAS BOUGHT FOR AND WHAT IT WAS ACTUALLY USED FOR ARE TWO SEPARATE\n"
		"FACTS, BOTH STORED. A lot carries the designation it was acquired under, and the movement\n"
		"that consumes it carries the designation it was really used under. Where they differ, tax\n"
		"has to be given back or may be reclaimed - and THAT IS COMPUTED AS THE DIFFERENCE BETWEEN\n"
		"THE TWO, not by recomputing the tax from scratch. Recomputation cannot tell an adjustment\n"
		"from a correction of an error; a difference can.\n"
		"* AND THE ANSWER IS A NAMED CLASSIFICATION - loss of entitlement, restoration of\n"
		"entitlement, no change - rather than a pair of booleans. The accountant asks for it by that\n"
		"name, and the register that records it is read by that name (`shapes`).\n"
		"\n"
		"NOTE: THE DESIGNATION ITSELF IS USUALLY TWO AXES CROSSED - the kind of activity and the tax\n"
		"treatment - and a working system OBJECTIFIES the crossing as a catalogue of allowed\n"
		"combinations rather than carrying two fields. That buys one field on every line and\n"
		"document, a list a person can be shown, and one place to add a combination when the law\n"
		"changes. It costs a check that says which combinations may face which on the two sides of\n"
		"an entry - and in the system examined that check is a hand-written matrix, which is what\n"
		"such a rule looks like when nobody has found a way to derive it.\n"
		"\n"
		"NOTE: AND WHAT A FIELD WILL ACCEPT CAN DEPEND ON THE DOCUMENT'S DATE, because a treatment\n"
		"introduced this year must not be selectable on last year's document. Retired values are\n"
		"moved out of the way rather than deleted - old documents still point at them.\n"
		"\n"
		"NOTE: AND THAT MAKES THE CHOICE LIST A FUNCTION OF THE DATE, WHICH THE FORM HAS TO OBEY. The\n"
		"type of the field stops being a fact of the metadata: what may be selected is computed from\n"
		"the document's date, so the list must be RE-READ whenever the date changes, and a value\n"
		"already typed has to be re-tested and cleared with a message if it has become inadmissible\n"
		"(`entered-from`).\n"
		"* THE FAILURE WITHOUT IT IS SILENT AND ONE-SIDED: the posting check refuses a value the form\n"
		"was still offering, and the person reads it as the system contradicting itself.") },

	{ wxT("cash-flow"),
	  ibMcpText("Money: what is planned, what is promised and what actually moved."),
	  ibMcpText("PLANNED MONEY AND REAL MONEY ARE DIFFERENT REGISTERS.\n"
		"\n"
		"Everybody starts with one balance of cash and finds out within a month that the questions\n"
		"are three, not one:\n"
		" WHAT WE HAVE - the actual balance of each account and till. Moved only by payments that\n"
		" happened.\n"
		" WHAT IS COMING AND GOING - expected receipts and expected payments, each with a DATE\n"
		" somebody promised. This is the cash-flow forecast, and it is what a director asks for\n"
		" when they say \"will we cover the salaries on Friday\".\n"
		" WHAT IS SPOKEN FOR - money reserved against approved requests to spend, which is not\n"
		" the same as spent. A request approved today reduces what may be committed tomorrow\n"
		" while the balance is untouched.\n"
		"Three questions, three registers - and a fourth for the CASH-FLOW STATEMENT, which\n"
		"classifies real movements by activity and item, because \"where did the money go\" is asked\n"
		"of history rather than of balances.\n"
		"* IN PRACTICE THERE IS A FIFTH, AND IT IS THE ONE PEOPLE FORGET: MONEY IN TRANSIT. Cash\n"
		"handed to a collector, a transfer between own accounts, a card payment not yet settled by\n"
		"the bank - it has left one place and not arrived at another, and it belongs to neither\n"
		"balance. Without it, every transfer makes the company briefly poorer and somebody\n"
		"reconciles it by hand. Counted off a working system: what we have, in transit, reserved,\n"
		"due in, due out, plus the statement.\n"
		"* AND \"HOW MUCH MAY I COMMIT\" IS AN ARITHMETIC OVER THEM, NOT A REGISTER: what we have,\n"
		"less what is reserved, less what is due out, plus what is due in - and A REQUEST BEING\n"
		"CHECKED MUST SUBTRACT ITSELF from the encumbrances, or it competes with its own reservation\n"
		"and refuses.\n"
		"* GENERALISE THAT: ANY \"HOW MUCH IS FREE\" CALCULATION MUST BE TOLD WHO IS ASKING and take\n"
		"the asker's own claims out of the encumbrances. It applies to reserved stock, to placed\n"
		"orders and to committed money alike, and its absence always presents the same way - \"the\n"
		"system will not let me spend against my own request\".\n"
		"\n"
		"KEY: A PAYMENT'S MOVEMENT IS STAMPED WITH THE DATE IT IS PLANNED FOR, NOT THE DATE IT WAS\n"
		"TYPED. The document sits in today's journal and its movement stands in the register on\n"
		"Friday. THE PAYMENT CALENDAR THEN COSTS NOTHING - it is just balances read at future dates.\n"
		"* AND SAY THE CONSEQUENCE OUT LOUD, because it breaks an assumption everyone holds: the\n"
		"balance \"as of now\" is NOT the sum of the documents entered so far, and unposting something\n"
		"today changes the future.\n"
		"\n"
		"KEY: ONE DOCUMENT MAY WRITE BOTH THE INTENTION AND THE FACT, AND THE INTENTION MUST NOT BE\n"
		"STAMPED LATER THAN ITS REMOVAL. A payment that is already made writes the money out AND\n"
		"writes the commitment in and out in one go - it raises the intention against itself and\n"
		"clears it. Take the EARLIER of (the planned date, the document date) for the raising. With a\n"
		"planned date in the past, the clearing would otherwise precede the raising and the committed\n"
		"balance dips negative over that stretch.\n"
		"\n"
		"KEY: A REQUEST IS DISCHARGED BY THE PLANNED AMOUNT WHILE THE MONEY MOVES BY THE ACTUAL ONE.\n"
		"The line carries both, and the request's own register is reduced by what was PLANNED -\n"
		"otherwise an exchange difference leaves a few cents outstanding for ever and the request\n"
		"never closes.\n"
		"* AND WHERE THE PAYMENT IS IN ANOTHER CURRENCY, THE RATE IS RECOVERED FROM THE TWO AMOUNTS\n"
		"RATHER THAN LOOKED UP: the request fixed the rate of the deal, and the payment obeys THAT,\n"
		"not the rate of the day.\n"
		"\n"
		"NOTE: WHOEVER MENTIONED THE OBLIGATION FIRST OWNS THE MOVEMENT FOR IT. Where a request can\n"
		"already appear in the calendar, the payment made against it must NOT record the obligation a\n"
		"second time - and where the request stayed out of the calendar, the payment records it\n"
		"itself. Ownership of a movement follows the FIRST document in the chain, not the kind of\n"
		"document. The cost is real and worth stating: changing that flag on a posted request\n"
		"requires re-posting the whole chain, or the obligation is doubled or lost.\n"
		"\n"
		"* THE REQUEST TO SPEND IS A DOCUMENT, and its life is the mechanism: raised, approved,\n"
		"paid, and CLOSED - closed being the state that releases what was reserved and is never\n"
		"automatic. Requests that are neither paid nor closed accumulate and quietly eat the\n"
		"available balance, so the closing document (or the closing job) is part of the design, not\n"
		"an afterthought.\n"
		"\n"
		"NOTE: AND EXPECTED MONEY HAS TWO DATES: when it was promised and when it is expected. Reports\n"
		"are built on the second, disputes on the first, and a register carrying only one of them\n"
		"answers half the questions asked of it.\n"
		"\n"
		"NOTE: THE SIGNAL THAT ANY OF THIS IS WANTED: \"payment calendar\", \"cash gap\", \"who approves the\n"
		"payment\", \"we must not pay more than we planned\". None of them is answered by a balance of\n"
		"cash, and all of them are cheap while the money registers are being designed.") },

	{ wxT("roles"),
	  ibMcpText("Cutting roles: a job is not a role, and rights combine rather than nest."),
	  ibMcpText("HOW RIGHTS ARE ACTUALLY CUT UP.\n"
		"\n"
		"STOP: THE BEGINNER'S SHAPE IS ONE ROLE PER PERSON - \"Ivanov's rights\" - and it collapses the\n"
		"first time two people do overlapping jobs. The working shape is TWO KINDS OF ROLE, handed\n"
		"out together:\n"
		" A JOB ROLE, named after the work: storekeeper, cashier, buyer, salesperson, accountant,\n"
		" payroll clerk, treasurer. It carries what that job needs all day and nothing else. This\n"
		" is the same cut as a section (`sections`) - and that is not a coincidence: what a\n"
		" person may do and where they work are the same question asked twice.\n"
		" A PERMISSION ROLE, named after ONE capability: may edit items, may edit counterparties,\n"
		" may edit the organisation, may change a document's status, may run external processing,\n"
		" may see everything. Small, additive, granted on top.\n"
		"A person then holds a job plus the handful of permissions they were trusted with, and the\n"
		"question \"who may edit a counterparty\" has an answer that is a list rather than an audit.\n"
		"\n"
		"* AND ONE BASE ROLE EVERYBODY HAS - the right to start the application at all, to read the\n"
		"common classifiers, to open their own settings. Without it every job role repeats the same\n"
		"twenty entries, and the twenty-first is forgotten in one of them.\n"
		"\n"
		"NOTE: EDITING REFERENCE DATA IS ITS OWN PERMISSION, separately from using it. Everybody selects\n"
		"items and counterparties; almost nobody should create them, because a duplicate\n"
		"counterparty splits a balance that then has to be merged by hand. This single split -\n"
		"choose freely, create by permission - prevents more mess than any other rule here.\n"
		"* AND THE SPLIT GOES FINER THAN READ AND WRITE. \"See the customer in a list\", \"see the\n"
		"customer's own data\", \"see the deals done with them\" are three permissions over one object,\n"
		"and the request \"let him see the client but not the prices we shipped at\" needs all three\n"
		"to exist. Without them, the only remaining lever is hiding the client entirely\n"
		"(`row-level-access`).\n"
		"\n"
		"NOTE: A PERMISSION THAT IS NOT IN ANY ROLE IS STILL A PERMISSION - \"may give a discount over\n"
		"ten per cent\", \"may post into a closed period\", \"may ship beyond the order\". These are\n"
		"VALUES held per person, not roles, because they carry a number or a limit and change without\n"
		"a release (`shapes`: kinds the user may add, with a value each).\n"
		"* AND SUCH A PERMISSION IS ASKED INSIDE THE CHECK IT SWITCHES OFF, not around the operation:\n"
		"the balance check begins by asking \"is this person allowed to exceed\", and returns early.\n"
		"Asking it at the caller means every caller must remember to.\n"
		"* WHERE SEVERAL VALUES APPLY - one per group the person belongs to - THE MOST PERMISSIVE\n"
		"WINS, and that is the opposite of how a prohibition date resolves (`closing-a-period`).\n"
		"A grant widens, a restraint narrows; say which one you are building.\n"
		"* AND THEY ARE READ ONCE PER SESSION. A new permission takes effect when the person next\n"
		"signs in, which has to be said, or it is reported as \"the setting does not work\".\n"
		"STOP: ONE PERMISSION, THREE ROADS TO ITS VALUE, IS A DEFECT WAITING. In the system examined:\n"
		"full rights answer from a hard-coded function without reading the register at all; a person\n"
		"with a POLICY PROFILE is answered from the profile only, groups ignored entirely; everyone\n"
		"else from person plus groups. Two people with identical groups then behave differently and\n"
		"nothing on screen explains it - and a fix on one road leaves the other two.\n"
		"* AND SOME PERMISSIONS ARE STORED INVERTED (\"control the excess\" rather than \"allow it\"),\n"
		"so a default of false means opposite things across the set. Keep one polarity.\n"
		"STOP: AND FOR A PERMISSION THAT CARRIES A LIMIT RATHER THAN A YES, AN UNSET VALUE IS THE\n"
		"WIDEST VALUE OF ALL. \"Do not sell below this price type\", \"do not discount past this\n"
		"figure\": where one of the person's groups has no value recorded, the check finds nothing to\n"
		"compare against and allows everything. So a limit is defeated not by a permissive row but\n"
		"by an EMPTY one, which is what a newly created group looks like. Decide that case\n"
		"explicitly and say which way it falls - a missing limit means unrestricted, or it means the\n"
		"strictest of the others. Either is defensible; only silence is not.\n"
		"\n"
		"KEY: AND SOME PERMISSIONS CHANGE THE ARITHMETIC, NOT WHAT IS VISIBLE - which is why they\n"
		"cannot be expressed as record-level access at all. May-exceed-the-balance does not filter\n"
		"any row: without it the quantity available is the LESSER of the free balance and the\n"
		"company's own balance, with it the free balance plainly. The same permission elsewhere\n"
		"turns a refusal into an informational line and drops the rows that have no approved request\n"
		"from the check entirely.\n"
		"* SO ONE PERMISSION CAN SIT IN THREE DIFFERENT MECHANISMS, and naming which one is the\n"
		"design decision: which ROWS may be read (`row-level-access`), whether a control REFUSES or\n"
		"merely says, and which FORMULA is evaluated. Reaching for row-level access to express the\n"
		"third is how a grant ends up hiding data nobody asked to hide, and it is paid for on every\n"
		"query.\n"
		"\n"
		"* THE PLACE TO SAY \"AFTER THE NEXT SIGN-IN\" IS THE MOMENT OF GRANTING, NOT THE\n"
		"DOCUMENTATION. On writing a set of rights, walk the open connections, find the affected\n"
		"people and print \"these will take effect when each of them next signs in\", naming them.\n"
		"The cache is not a defect - the right is asked on every line of every posting and cannot be\n"
		"a query - but a latency of one session that nobody is told about is reported as \"the\n"
		"setting does not work\", and it is reported by the administrator, not the user. The same\n"
		"holds for everything else folded into a session at start-up: the prohibition dates, the\n"
		"per-kind restriction switches (`row-level-access`). One notice can cover them all.\n"
		"\n"
		"* AN ATOMIC ROLE POINTS EITHER WAY, and both are ordinary:\n"
		" GRANTING - \"may edit items\", \"may change a status\", \"may run external processing\".\n"
		" EXEMPTING - \"do not apply the automatic filter\", \"see every organisation\", \"post into\n"
		" a closed period\". The restriction is the normal state and the role lifts it. Better\n"
		" than a flag on the user record, because it reads correctly and can be listed: who is\n"
		" exempt is a query, not an inspection.\n"
		"\n"
		"STOP: AND DO NOT SHRED ACCESS BEFORE SOMEBODY ASKS. Atomic roles are for a division that\n"
		"actually exists in the conversation - \"the sales people must not create counterparties\",\n"
		"\"only the chief accountant closes a period\". When nothing in what the person describes\n"
		"suggests they want to split a right, the job roles alone are correct and complete. Every\n"
		"speculative atomic role is another tick box on every user, which somebody will forget to\n"
		"set - and the symptom is not a refusal, it is a person quietly unable to do their job.\n"
		"Listen for the division; build it then.\n"
		"\n"
		"NOTE: AND ADMINISTRATION IS NOT A JOB. \"Full rights\" exists for one or two people and is not\n"
		"how a head of department is described - they are a job role plus permissions, or the system\n"
		"has no answer to what anybody may actually do.\n"
		"* AND \"MAKE HIM AN ADMINISTRATOR\" IS AT LEAST FOUR DIFFERENT QUESTIONS, none of which\n"
		"reduces to the others: does THIS SESSION have full rights; does THAT PERSON have them; may\n"
		"someone create and edit users (which need not include access to the data); and may someone\n"
		"do technical administration. Answer them with separate predicates from the start - a system\n"
		"that has only \"is admin\" will grow the other three as exceptions.\n"
		"* AND A BASE WITH NO USERS AT ALL MUST ANSWER \"FULL RIGHTS\", or nobody can ever log in to\n"
		"create the first one. It is the one degenerate case worth writing down.\n"
		"\n"
		"KEY: THE BASE ROLE IS AN INVARIANT, NOT A CHOICE. It is added on saving whenever the person\n"
		"has neither it nor full rights, and it is HIDDEN from the list of roles to pick - it cannot\n"
		"be removed and need not be seen.\n"
		"* AND IT CARRIES THE MOST RESTRICTIONS OF ANY ROLE, by a wide margin. That is the shape:\n"
		"the base role opens everything shared and immediately cuts it down by record\n"
		"(`row-level-access`), and job roles ADD on top. A design where each job role separately\n"
		"grants access to the common data repeats the restrictions in every one of them.\n"
		"\n"
		"NOTE: ROLES NEED A CLASSIFICATION THE INTERFACE CAN SHOW - a group per role and a mark for\n"
		"the ones that CANNOT BE GRANTED ALONE (a role that only makes sense beside another). Sixty\n"
		"roles in a flat alphabetical list is how people end up granting full rights instead.\n"
		"STOP: BUT IF THAT CLASSIFICATION IS A SEPARATE TABLE, IT WILL DRIFT FROM THE ROLES\n"
		"THEMSELVES. The real list is the metadata; a hand-kept table beside it is a second list, and\n"
		"a role added and not entered there simply vanishes from the interface, silently. If the\n"
		"grouping cannot be derived from the roles themselves, at least make the divergence LOUD -\n"
		"report what is in one list and not the other (`shapes`).\n"
		"\n"
		"KEY: A PERSON HAS TWO IDENTITIES AND DIFFERENT MECHANISMS DEPEND ON DIFFERENT ONES. The\n"
		"authentication subject carries the ROLES; the data subject - an ordinary catalogue item -\n"
		"carries groups, extra permissions, prohibition dates and record-level settings. They are\n"
		"tied by a stored identifier, and the session must be able to REPAIR that tie: not found by\n"
		"identifier, look up by name, and write the identifier back.\n"
		"* WHICH MEANS RENAMING SOMEONE IN ONE PLACE AND NOT THE OTHER IS A REAL FAILURE MODE, and it\n"
		"deserves a check that reports the divergence rather than a session that silently gets the\n"
		"wrong person's rights.") },

	{ wxT("row-level-access"),
	  ibMcpText("\"Only their own customers\": restricting which ROWS a person sees, and what it costs."),
	  ibMcpText("SEEING ONLY YOUR OWN.\n"
		"\n"
		"`roles` decides who may open WHAT. This decides who may see WHICH ROWS of it, and it is a\n"
		"different mechanism with a different price.\n"
		"\n"
		"KEY: THE REQUEST UNFOLDS INTO FOUR SWITCHES, AND ALL FOUR MUST BE UP.\n"
		" 1. THE WHOLE MECHANISM, on or off for the base.\n"
		" 2. WHICH KINDS of thing restrict anything here at all - counterparties, warehouses,\n"
		" companies, people, projects. A base that restricts by warehouse pays nothing for the\n"
		" others.\n"
		" 3. WHICH KIND RESTRICTS WHICH GROUP of users.\n"
		" 4. AND ONLY THEN the actual permissions: this group may see these warehouses.\n"
		"* THE COST OF NOT HAVING STEPS 1-3 IS THAT THE MECHANISM CANNOT BE SWITCHED OFF, and it is\n"
		"paid for on EVERY query by everyone. The cost of having them is that \"give him access\" is\n"
		"four different places, and an administrator who fills in only the fourth sees no effect at\n"
		"all - which is the single most common support call about this feature.\n"
		"\n"
		"KEY: THE RESTRICTION MUST BE ABLE TO VANISH FROM THE QUERY TEXT ENTIRELY. Each kind of\n"
		"restricting object gets a boolean session parameter, and the restriction template is wrapped\n"
		"in a conditional on it: if this user is not restricted by that kind, the condition IS NOT\n"
		"COMPILED - no join, no subquery, nothing in the plan. Row-level security is expensive by\n"
		"construction, and the only way not to charge everyone for it is textual absence, not a\n"
		"cheap condition.\n"
		"* THE PARAMETERS ARE COMPUTED ONCE WHEN THE SESSION STARTS, which means changing who is\n"
		"restricted does not affect sessions already open. Say so, or it is reported as a bug.\n"
		"\n"
		"KEY: ACCESS IS GRANTED TO A GROUP, AND WHERE TWO GROUPS DISAGREE THE PERMISSIVE ONE WINS. A\n"
		"row passes if AT LEAST ONE of the person's groups lets it through.\n"
		"STOP: WHICH MEANS SOMEBODY IN NO GROUP AT ALL SEES NOTHING. Forgetting to put a new employee\n"
		"in a group is indistinguishable from forbidding them everything, and it presents as \"all my\n"
		"lists are empty\". Worth a check at the moment a user is created.\n"
		"* AND RIGHTS CANNOT BE GIVEN TO ONE PERSON AROUND THE GROUPS. Adding groups always widens,\n"
		"never narrows.\n"
		"\n"
		"KEY: \"SEE THE CUSTOMER\" AND \"SEE THE DEALS WITH THAT CUSTOMER\" ARE DIFFERENT PERMISSIONS ON\n"
		"THE SAME OBJECT. The permission row carries an AREA - the list, the data, the extra\n"
		"information - and a catalogue list asks about one area while a document asks about another.\n"
		"Without this, letting someone see a customer at all would show them every price and every\n"
		"shipment, and the only remaining option would be hiding the customer entirely.\n"
		"STOP: AND A FORM'S ELEMENTS ARE A FUNCTION OF WHO IS LOOKING. Where a person has no right to\n"
		"an object, an attribute or a command, the control bound to it is NOT THERE when the form is\n"
		"built - so any code addressing an element by name fails for exactly the accounts with the\n"
		"narrowest rights, and never for the developer.\n"
		"* The cure is a pair of tolerant helpers - set a property of an element if it exists, read\n"
		"one if it exists - given the obvious names so they are what gets typed. Code that must react\n"
		"to absence asks first; code that merely arranges the screen carries on. This is the ordinary\n"
		"shape of \"it throws for the warehouse clerks and works for everyone else\", and it is\n"
		"invisible in any test run under full rights.\n"
		"\n"
		"KEY: A DOCUMENT IS RESTRICTED THROUGH AN INDEX, NOT THROUGH ITS OWN FIELDS. What the\n"
		"restriction is about often sits in a TABULAR SECTION - the warehouse per line, the person\n"
		"per line - and a row-level condition can only look at the row it filters. So a hook lays\n"
		"every document out into an index (document -> kind -> object) on writing, and the template\n"
		"joins THAT.\n"
		"* THE PRICE IS THREE THINGS AND ALL THREE SHOW UP: a second write for every document, a\n"
		"re-indexing pass after any change to what counts as an access object, and - in the system\n"
		"examined - a HAND-WRITTEN ladder of some 250 documents saying which of their fields matter.\n"
		"A hand-kept list of participants is exactly what `shapes` warns about; here it is load-\n"
		"bearing, and a document that falls through it raises on write.\n"
		"\n"
		"KEY: INHERITANCE DOWN A HIERARCHY IS MATERIALISED, AND THAT IS WHAT \"THE LONG RECALCULATION\"\n"
		"IS. \"Give access to the whole group of warehouses\" is not resolved by climbing the tree at\n"
		"query time - too expensive inside a restriction - it is EXPANDED INTO ROWS for every child\n"
		"when the permission is saved. Consequences, all of them real: moving an item to another\n"
		"parent rewrites permissions along the old branch and the new one; a new item must be given\n"
		"its parent's rights before it is first written; and each row remembers WHO it was inherited\n"
		"from, so it can be removed again.\n"
		"\n"
		"STOP: A DECLARED-BUT-UNREAD PERMISSION IS THE WORST DEFECT OF THIS AREA, AND IT WAS FOUND\n"
		"LIVE. The settings register offers both READ and WRITE; the write templates check the write\n"
		"flag, and the read templates check nothing - the mere EXISTENCE of a row is enough. Across\n"
		"all 66 roles the read flag is never once consulted. The field is shown, edited and stored,\n"
		"and it silently permits. When a rule is written down, find the reader (`look-first`).\n"
		"\n"
		"NOTE: AND THE CODE THAT CHECKS BALANCES RUNS PRIVILEGED (`stock-control`), which means the\n"
		"restriction does not apply there and every check it should have made has to be made by hand.\n"
		"Privilege is granted to whole modules, so it spreads: in the system examined, 24 modules of\n"
		"219 - and all of them legitimately, because they sum across the whole base and the answer\n"
		"must not depend on who is asking. Cost must be the same figure for everyone.\n"
		"STOP: BUT PRIVILEGE IS GRANTED TO A FILE, NOT TO AN OPERATION, AND THAT IS WHAT ROTS. The\n"
		"rule for which modules deserve it is simple and holds - anything that FOLDS DATA ACROSS THE\n"
		"WHOLE BASE must see all of it - but nothing keeps a module to that rule afterwards. In the\n"
		"system examined one module named after the administrator role had grown to two and a half\n"
		"thousand lines, its own role never checked inside it, holding everything that ever needed to\n"
		"bypass a restriction: filling a document header, creating a scheduled job.\n"
		"* SO NAME THE MODULE AFTER THE CALCULATION, NEVER AFTER THE RIGHT. A module called for a role\n"
		"is an invitation, and the boundary of what is privileged is then invisible both to the reader\n"
		"and to whoever adds the next function to it.\n"
		"STOP: AND A HAND-WRITTEN CHECK INSIDE PRIVILEGED CODE MUST CARRY ITS REFUSAL BACK TO THE\n"
		"CALLER. The privilege removed the platform's automatic refusal; if the manual one prints a\n"
		"message and returns without setting the refusal, the caller sees success, reports success,\n"
		"and re-reads the data it believes it wrote. Found live: writing somebody's access rights,\n"
		"where the check is correct, the message is correct, and nothing fails.\n"
		"* THE SHAPE OF THE DEFECT IS \"I PRESSED SAVE, THERE WAS NO ERROR, AND NOTHING CHANGED\" - and\n"
		"it is indistinguishable from a caching problem, which is where people look first. The same\n"
		"applies to any exception swallowed into a bare \"return false\" here: a rights routine that\n"
		"cannot say WHY it did not write is a rights routine nobody can audit (`posting`: a problem is\n"
		"a refusal plus a message).\n"
		"\n"
		"KEY: AND THE GROUPING RIGHTS ARE GRANTED OVER NEED NOT BE THE OBJECT'S OWN HIERARCHY. Beside\n"
		"the tree people file things in, a working system keeps separate CLASSIFIER catalogues -\n"
		"groups of parties, of individuals, of warehouses - existing only to be the thing access is\n"
		"granted to. A person is given a group; objects are assigned to groups; neither the object nor\n"
		"its tree is touched.\n"
		"* WHAT IT BUYS: regrouping for rights stops being a reorganisation of the master data.\n"
		"Without it, the first request to give somebody \"these twelve customers\" is answered by moving\n"
		"customers in the tree everybody else navigates, and the tree slowly becomes a rights\n"
		"structure nobody can read.\n"
		"* WHAT IT COSTS: a second membership to maintain, and an object in no group at all is\n"
		"invisible to everyone - the same failure as a person in no group, and it needs the same\n"
		"check.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. Two things, and they are what the shape above asks\n"
		"for rather than a statement about any particular engine. A RESTRICTION THAT LIVES IN THE\n"
		"QUERY LANGUAGE, so it can vanish from the text entirely when nobody is restricted; and a\n"
		"VALUE THE SESSION OWNS - set once when the session starts, writable nowhere else - because a\n"
		"filter is only safe if the thing it filters by cannot be assigned by the code being\n"
		"filtered.\n"
		"* WITHOUT THE FIRST, every reader assembles its own condition and one forgotten reader is a\n"
		"hole nobody sees. Without the second, the restriction is decoration. The DATA side - access\n"
		"groups, membership, inheritance down a hierarchy - is yours to build either way.") },

	{ wxT("closing-a-period"),
	  ibMcpText("Freezing what has been reported: who may still edit, and what the guard must cover."),
	  ibMcpText("CLOSING A PERIOD SO IT STOPS MOVING.\n"
		"\n"
		"\"After the 20th nobody touches the closed month - except the chief accountant.\" The figure\n"
		"has been reported to someone outside; from now on a change to it is a different act.\n"
		"\n"
		"KEY: IT IS A TABLE, NOT A DATE - (company, who) -> date. The \"who\" is composite: a person, a\n"
		"group of people, or NOTHING, which means everybody. Where two rows apply, THE MORE SPECIFIC\n"
		"ADDRESS WINS - personal beats group beats everybody.\n"
		"* WORTH NOTICING BESIDE IT: this is the OPPOSITE resolution to the one used for permissions,\n"
		"where the most permissive value wins. Two mechanisms sitting next to each other with\n"
		"deliberately inverted rules, because one is a grant and the other is a restraint. Neither\n"
		"is \"the\" convention - say which you are building.\n"
		"* THE WHOLE TABLE IS FOLDED ONCE AT THE START OF A SESSION into a small map. If the person\n"
		"has no prohibitions at all the map is simply absent, and every check exits on its first\n"
		"line - the full-rights case costs nothing and needs no separate branch.\n"
		"\n"
		"KEY: CHECK THE OLD VERSION AND THE NEW ONE. Read the document as it stands in the base and\n"
		"test the prohibition against BOTH dates. Otherwise the two interesting cases both slip\n"
		"through: carrying a document OUT of a closed period, and carrying one INTO it.\n"
		"* THE SAME FOR REGISTERS: test the records that already exist under this recorder, not only\n"
		"the ones about to be written. Replacing a record set DELETES the old movements, and if those\n"
		"were in a closed period the period has just changed.\n"
		"* AND THE EFFECTIVE DATE IS NOT ALWAYS THE DOCUMENT DATE. Where a document carries a\n"
		"separate registration period, take the EARLIER of the two.\n"
		"\n"
		"KEY: THE GUARD LIVES ON WRITING; THE FORM ONLY REPEATS IT. Five hooks - the document and\n"
		"each of the four kinds of register (`cross-cutting-hooks`). The form additionally asks the\n"
		"SAME predicate to open read-only, which is politeness, not enforcement. In that order: a\n"
		"guard without the form means \"saved, then lost\"; a form without the guard is not a\n"
		"prohibition at all.\n"
		"\n"
		"STOP: AND INCOMING DATA IS DELIBERATELY EXEMPT FROM THIS ONE. A transfer from another base\n"
		"passes straight through the write guard - otherwise a closed period would stop the exchange\n"
		"dead. The right to refuse foreign data is a SEPARATE mechanism with its own date\n"
		"(`data-exchange`), checked in the exchange rather than at the write. Two prohibitions that\n"
		"look like one and must not be merged: one protects my reported figures from MY OWN people,\n"
		"the other decides what I accept from OUTSIDE.\n"
		"\n"
		"NOTE: THE MESSAGE MUST NOT BE PRINTED WHERE THERE IS NOBODY TO READ IT. The same guard runs\n"
		"under a background job and an external connection; there it refuses silently and logs. A\n"
		"refusal announced to an empty room is a refusal nobody can act on.") },

	{ wxT("pricing"),
	  ibMcpText("Prices, discounts and the four things a price is measured in."),
	  ibMcpText("A PRICE IS NEVER JUST A NUMBER.\n"
		"\n"
		"It is a number PLUS four facts, and every one of them can differ from the document it is\n"
		"about to land in: the PRICE TYPE it belongs to (wholesale, retail, planned cost), the\n"
		"CURRENCY, the UNIT it is quoted per, and whether it INCLUDES TAX. Store all four beside the\n"
		"figure - a price register keyed by item and price type, kept with periodicity so yesterday's\n"
		"price is still answerable (`shapes`).\n"
		"\n"
		"KEY: AND EVERY ONE OF THE FOUR MEANS A RECALCULATION, not a relabelling. Change the document\n"
		"to another currency and the price converts by rate AND multiplicity; change the unit and it\n"
		"scales by the packing coefficient; switch \"price includes tax\" and it is extracted or added\n"
		"(`printing` has the arithmetic, and the two directions do not produce the same number).\n"
		"Leaving the figure and changing the label is how a base ends up selling at a tenth of its\n"
		"price.\n"
		"\n"
		"* ROUNDING IS TO A STEP, NOT TO PENNIES. Retail prices are wanted at 0.05, at 0.10, at the\n"
		"whole unit, at fifty - so rounding takes an ORDER: divide by the step, take whole steps,\n"
		"multiply back. And it takes a direction: ALWAYS UP is a separate switch, because a shop\n"
		"that rounds its sale prices down loses the difference on every line. The step and the\n"
		"direction belong to the price type, not to the code.\n"
		"\n"
		"DISCOUNTS COME FROM SEVERAL PLACES AT ONCE, and that is the whole difficulty: the\n"
		"counterparty's agreement, a discount card, a promotion running on a date, a volume\n"
		"threshold on this line, a sales condition attached to the item. Build the list of\n"
		"POSSIBLE GRANTERS for the document first, then ask each what it offers, then decide -\n"
		"largest wins, or they add up, or one excludes the others. That rule is a decision to be\n"
		"asked about, and it is the first thing that will be changed after go-live.\n"
		"* AND \"LARGEST\" MEANS THE LARGEST AMOUNT OF MONEY, NOT THE LARGEST PERCENTAGE. They are\n"
		"different answers whenever the discounts apply to different bases - a percentage off one\n"
		"line against a fixed sum off the document - and the person meant the money.\n"
		"* AND THE WINNER IS RECORDED IN THE LINE, not merely applied to it. Which promotion gave\n"
		"this discount is asked about constantly afterwards, and it cannot be recomputed later:\n"
		"the promotion may have ended, the card may have changed hands, the threshold may have moved.\n"
		"* WHERE TWO DISCOUNTS DO COMBINE, THEY ADD RATHER THAN COMPOUND - ten and five is fifteen,\n"
		"not fourteen and a half. Compounding is defensible arithmetic and nobody in the trade means\n"
		"it; if it is genuinely wanted, it has to be said out loud.\n"
		"\n"
		"NOTE: A PROMOTION IS DATED AND A CARD IS NOT. \"Special offer\" means \"on this date, for this\n"
		"item, for this buyer\", so it is read as of the document's date like a rate is - never as\n"
		"of today, or last month's invoices reprice themselves when the promotion ends.\n"
		"\n"
		"NOTE: AND SELLING BELOW COST IS A QUESTION SOMEBODY WILL ASK. Keeping a planned cost per item\n"
		"lets the document compare its total against it and warn - or refuse, by a right rather\n"
		"than by a constant. Cheap to add while the price mechanism is being built, awkward to\n"
		"retrofit into every sales document afterwards.\n"
		"* AND \"NOT BELOW X\" IS USUALLY NOT A NUMBER BUT A PRICE TYPE the person is entitled to sell\n"
		"down to - so the limit moves with the price list instead of being edited. And when a\n"
		"discount would breach it, TRIM THE DISCOUNT to the limit rather than refusing the line:\n"
		"the salesperson gets the best allowed price and a message, not a dead end.\n"
		"* AND TRIM ONLY WHAT THE MACHINE GAVE. The floor applies to the AUTOMATIC discount and never\n"
		"to one a person typed: automation may not put a seller in breach of a rule, while a person\n"
		"may, on their own responsibility and under their own name. Two consequences to build rather\n"
		"than discover: where the list price is ALREADY below the floor there is nothing to trim and\n"
		"nothing to say, and where the person's own rights name no price type at all there is no\n"
		"floor - the permissive reading wins, as wherever several grants meet (`roles`). The floor\n"
		"is therefore a MINIMUM over the price types the person is entitled to, computed once per\n"
		"run and cached by item, variant and unit.\n"
		"\n"
		"KEY: THE UNIT COEFFICIENT IS A SNAPSHOT IN THE LINE, NOT A LOOKUP. Copy it into the row when\n"
		"the unit is chosen. Two reasons, and both are the kind that only appear later: correcting\n"
		"the coefficient in the reference must NOT silently restate documents already posted; and\n"
		"when the unit is changed, the recalculation needs the OLD coefficient, which by then exists\n"
		"nowhere else.\n"
		"* AND A COEFFICIENT OF ZERO IS A REAL CASE - a unit somebody created and never filled in.\n"
		"Refuse by name (which item, which unit) instead of dividing by it.\n"
		"\n"
		"STOP: DO NOT LET ONE FIELD MEAN TWO THINGS DEPENDING ON WHICH OTHER COLUMNS EXIST. In the\n"
		"system examined, \"price\" means price per chosen unit in most documents, and price per base\n"
		"unit wherever a packages column is present - so changing the unit recalculates the price in\n"
		"one document and the quantity in another. The distinction lives in a comment and in a\n"
		"metadata probe at run time, in neither the name nor the type. If two meanings are genuinely\n"
		"needed, they are two fields.\n"
		"\n"
		"NOTE: A COMPUTED PRICE TYPE HAS A SECOND FORM BESIDES A PERCENTAGE - A BAND. \"Everything\n"
		"under a hundred sells at ninety-nine\": the base price is converted to the base type's\n"
		"currency, the first band whose ceiling is above it is found, and THAT band's price is taken.\n"
		"The result does not vary inside a band, which is the point - retail price points are a\n"
		"table, not a function. Read the bands as ONE generation, like any scale.\n"
		"\n"
		"KEY: FILLING A PRICE IS A PIPELINE OF EIGHT STEPS, AND ROUNDING IS NOT LAST.\n"
		" 1. FIND the price row for (item, variant), falling back to the variant-less one.\n"
		" 2. TAKE the base price.\n"
		" 3. IF THE PRICE TYPE IS COMPUTED - apply its percentage over the base type, or read the\n"
		" band it falls into.\n"
		" 4. APPLY the mark-up of the sales condition (prepayment, deferral).\n"
		" 5. CONVERT into the unit of the LINE.\n"
		" 6. ROUND, by the step belonging to the PRICE TYPE.\n"
		" 7. CONVERT into the currency of the document.\n"
		" 8. RE-STATE it for the tax flags of this document.\n"
		"* STEP EIGHT IS NOT SYMMETRIC BETWEEN BUYING AND SELLING, and the asymmetry is deliberate.\n"
		"SELLING: if this document does not account for tax, take the listed price AS IT IS - do not\n"
		"extract tax from it. The company sells at the same price whatever its tax regime; extracting\n"
		"would quietly cut the price by the rate. BUYING: the restatement runs normally, because what\n"
		"is being reconstructed there is what the supplier actually charges. Same function, one\n"
		"branch, and it is a commercial decision rather than arithmetic - write it down beside the\n"
		"code or somebody will \"fix\" it into symmetry.\n"
		"* ROUNDING SITS AT SIX BECAUSE THE STEP IS A PROPERTY OF THE PRICE TYPE AND IS EXPRESSED IN\n"
		"THE PRICE TYPE'S OWN CURRENCY. Round after converting and \"round to five cents\" becomes\n"
		"round to something meaningless. The consequence is honest and worth stating to the customer:\n"
		"the price is tidy in the price list, and may be untidy in a document in another currency.\n"
		"THAT ORDER IS A DECISION, not an accident.\n"
		"\n"
		"KEY: A SPECIAL PRICE COMES IN THREE DIFFERENT SIZES, AND THEY MUST NOT BE ONE TABLE.\n"
		" AN INDIVIDUAL PRICE for this customer and this item - overrides THE PRICE.\n"
		" A DIFFERENT PRICE LIST for this customer and this group of items - overrides THE PRICE\n"
		" TYPE, and the calculation then continues under the new type.\n"
		" A DIFFERENT PERCENTAGE on this item within a computed type - overrides THE MARK-UP.\n"
		"Each is checked in that order and each replaces a different thing. Collapsing them into one\n"
		"\"price exceptions\" table is the usual mistake: the second and third then have to be\n"
		"expanded into thousands of rows of the first, and they stop following the price list when it\n"
		"changes.\n"
		"STOP: ZERO IS A VALUE, AND NOT-FOUND IS NOT ZERO. Two halves of one mistake, both found live.\n"
		"On the writing side: a lookup that finds no price must LEAVE THE FIELD AS IT IS - writing\n"
		"nought destroys a figure the person typed and reads afterwards as a genuine price of nothing.\n"
		"On the reading side: a row carrying nought per cent in an override table is meaningful - it is\n"
		"the explicit no-discount-here that beats a more general rule - so a condition that filters\n"
		"nought away loses exactly the overrides it was meant to honour.\n"
		"* WHERE NO-ANSWER MUST BE TELLABLE FROM NOUGHT, it is an absent row or a flag beside the\n"
		"figure, never the number itself. This is the same distinction `showing-a-value` makes about a\n"
		"blank cell, one floor down in the data.\n"
		"\n"
		"NOTE: FALLING BACK TO \"ANY VARIANT\" CAN BE DONE BY SORTING RATHER THAN BY BRANCHING - ask\n"
		"for both the specific and the empty variant in one query and let the specific one sort\n"
		"first. It saves a round trip, and its limit should be known: the priority rests on the\n"
		"ORDER OF REFERENCES, which is not expressible in the language of the trade and does not\n"
		"extend to a third level such as an item group. At three levels, use an explicit priority\n"
		"constant per branch (`bill-of-materials`).\n"
		"\n"
		"KEY: ROUNDING ERROR IS BANKED, NOT DROPPED. Tax rounded per line to two decimals does not\n"
		"add up to the tax on the total. Do not fix the total and do not force the last line - carry\n"
		"an ACCUMULATOR of fractions through all the lines, KEYED BY THE TAX RATE, so each rate has\n"
		"its own bank and the crumbs are handed to whichever line comes next. The same accumulator\n"
		"serves currency conversion: one mechanism, two sources of fractions.\n"
		"* AND WHEN THE TOTAL HAS MOVED, SAY SO - \"the tax was X, it is now Y\". A figure that changes\n"
		"by a cent without a word is the one people stop trusting the system over.\n"
		"\n"
		"NOTE: ROUNDING THE DOCUMENT TOTAL IS A DIFFERENT OPERATION FROM ROUNDING A PRICE. The total\n"
		"is cut DOWN to the step and the difference is taken off ONE line - the largest, so it cannot\n"
		"go negative - and if the step exceeds even that line, refuse. If the amounts are net of tax,\n"
		"the difference has to be split between the net and the tax parts. And ASK before applying\n"
		"it: this is a discount, and a discount is not given silently.\n"
		"STOP: AND DO NOT HAND-ADJUST A FIGURE THAT A RECALCULATION OWNS. Where the tax, the discount\n"
		"or the line total is recomputed automatically from the lines, a difference poked into that\n"
		"same figure survives until the next recalculation and not one moment longer. So the\n"
		"rounding above REFUSES while automatic tax calculation is switched on, and says why, rather\n"
		"than writing a correction that will vanish. The general form is worth applying before any\n"
		"manual write: ask who else writes this field - if a mechanism does, either switch that\n"
		"mechanism off for this document or refuse the manual act. The failure it prevents is the\n"
		"worst-tempered kind there is: correct on the screen, wrong after the next edit, with\n"
		"nothing in between to look at.\n"
		"\n"
		"NOTE: A UNIT CARRIES ITS OWN ROUNDING POLICY, because the rule is physical, not documentary.\n"
		"\"How many pallets is this\" is rarely a whole number, and the unit itself says whether to\n"
		"warn about a part-full one and what THRESHOLD in base units rounds it up - \"a half-empty box\n"
		"counts as a box if it holds at least N\". The document must not decide this.\n"
		"\n"
		"STOP: IN RETAIL THE PRICE IS A DIMENSION OF THE STOCK BALANCE, NOT AN ATTRIBUTE OF THE LINE.\n"
		"Goods sit on the shelf AT A PRICE, so changing the price is not editing a field - it is a\n"
		"revaluation document moving the balance from one price to another. Any routine that refills\n"
		"prices \"by price type\" has to refuse for such a warehouse and say why. This is the largest\n"
		"fork in the whole area, and it is decided by the kind of warehouse, not by the document.\n"
		"\n"
		"STOP: A SHARED MUTABLE CONTEXT INSIDE A LOOP OVER LINES IS THE QUIET DEFECT OF THIS AREA. One\n"
		"structure is built for the document and reused per line; a line whose item carries its own\n"
		"price type writes that type INTO it - and the next line starts from the previous line's\n"
		"type, currency and rounding. The intent is right (an item may override), the carrier is\n"
		"wrong: override into a COPY for that line, never into the document's own context.\n"
		"\n"
		"NOTE: ROWS OF DIFFERENT TABULAR SECTIONS ARE TIED BY A ROW KEY, NEVER BY THE ROW NUMBER -\n"
		"the composition of a kit, the serial numbers of a line. The number shifts when anything is\n"
		"inserted or deleted. A small integer issued on insertion is enough; the identity never\n"
		"leaves the document.") },

	{ wxT("promotions"),
	  ibMcpText("Offers, gifts and kits: conditions, \"two plus one\", and splitting a set into its parts."),
	  ibMcpText("OFFERS, GIFTS AND SETS - WHERE A DISCOUNT STOPS BEING A PERCENTAGE.\n"
		"\n"
		"`pricing` covers what a thing costs. This is the machinery behind \"two pizzas and a drink\n"
		"free\", \"ten per cent from ten pieces\", \"happy hours from two to four\" - and it is not a\n"
		"bigger discount table.\n"
		"\n"
		"KEY: A CONDITION IS A PAIR - THE KIND OF CONDITION, AND ITS VALUE OF A COMPOSITE TYPE. From\n"
		"a quantity, from a document total, when paying by card, on this kind of loyalty card: one\n"
		"kind field and one value that may be a number, a payment method or a reference. Anything\n"
		"else means a column per kind and a table nobody can extend.\n"
		"* AND A THRESHOLD IN MONEY IS STORED IN A CURRENCY, so comparing it means converting the\n"
		"document first - a threshold is not a bare number.\n"
		"STOP: AND \"FROM TEN PIECES\" IS NOT A CONDITION OF THE LINE - IT IS THE WHOLE DOCUMENT. The\n"
		"quantity has to be totalled across the document IN BASE UNITS before the condition can be\n"
		"tested, which means a separate reading that only exists when such a condition is actually\n"
		"in play. Treating it per line silently gives the discount to nobody.\n"
		"KEY: A DISCOUNT EARNED BY PAST TURNOVER IS A SECOND MECHANISM, NOT ANOTHER CONDITION. It reads\n"
		"accumulated sales for that buyer from a register of its own, matches them against a scale of\n"
		"thresholds, and REPLACES the percentage on whichever offers that buyer's card carries. Two\n"
		"things belong to the accounting policy rather than to the offer: the LENGTH of the\n"
		"accumulation window, and whether it means from the start of the current window until today,\n"
		"or the whole previous CLOSED window. Those are different promises to the customer, both are\n"
		"asked for, and neither can be recovered from the other - so make it a setting and say which\n"
		"is in force.\n"
		"* AND READ THE THRESHOLDS AS ONE GENERATION, like any scale: a latest-per-key reading\n"
		"assembles a ladder from two different dates that nobody ever approved.\n"
		"\n"
		"KEY: THE PERIOD OF AN OFFER IS TWO DIFFERENT THINGS. A start and an end DATE belong to the\n"
		"offer itself. A window WITHIN THE DAY - the weekday, from this hour to that one - is a\n"
		"separate table joined optionally, where NO ROW MEANS ALWAYS. Cramming both into one record\n"
		"forces a row per weekday for every offer that has no such restriction.\n"
		"* AND A TIME OF DAY IS A TYPE OF ITS OWN, even when the platform has no separate type for\n"
		"it. Pick one representation and use it in the storage AND in the comparison; comparing a\n"
		"time of day against a full timestamp is how an offer runs for exactly one second.\n"
		"\n"
		"KEY: A GIFT IS DESCRIBED AS A KIT, NOT AS A DISCOUNT. The offer is a set whose components\n"
		"are partly REQUIRED and partly MARKED AS THE GIFT. How many sets a document has earned is\n"
		"the MINIMUM over the required components of \"how many whole sets does this line cover\".\n"
		"* APPLYING IT SUBTRACTS the components from the lines - deleting any line that reaches zero -\n"
		"and ADDS the gift as a line of its own.\n"
		"* WHICH CHANGES THE DOCUMENT, SO THE WHOLE SEARCH RUNS AGAIN. This is computed TO A FIXED\n"
		"POINT, not in one pass: applying one offer can qualify the document for another, and\n"
		"stopping after a single sweep gives an answer that depends on the order the offers happened\n"
		"to be read in.\n"
		"* AND SHOW WHAT WAS NOT EARNED. A set the customer is one item short of is worth more than\n"
		"the sets they already have: display it greyed, with how many they hold, so the seller can\n"
		"say \"add one and the third is free\". The interface for this mechanism is half its value.\n"
		"* CONVERT THE LINE TO BASE UNITS BEFORE SUBTRACTING. Sets are counted in pieces and lines\n"
		"are typed in boxes.\n"
		"\n"
		"KEY: SPLITTING A SET INTO ITS PARTS IS A GENERIC DISTRIBUTION OVER EVERY NUMERIC COLUMN. A\n"
		"kit line is replaced by its components; the base of the distribution is the sum of price\n"
		"times quantity across them; and then EVERY numeric column of the row - amount, discount,\n"
		"tax, weight - is spread by the same running formula: what is left of the value, times this\n"
		"component's share of what is left of the base. Round each to THAT COLUMN'S OWN declared\n"
		"precision, accumulate, and put the final difference into the last row.\n"
		"* REFERENCE COLUMNS ARE NOT DISTRIBUTED - they follow a different rule: take the\n"
		"component's own value, and where it is empty, INHERIT FROM THE KIT (warehouse, series,\n"
		"quality, write-off method). Two kinds of column, two rules, one pass.\n"
		"* WRITING IT PER FIELD INSTEAD - amount here, discount there - is how a kit ends up with\n"
		"components whose amounts do not add back to the set.\n"
		"\n"
		"KEY: A PERCENTAGE TAKEN FROM A BASE IS RECOVERED BY DIVISION, NOT BY MULTIPLICATION. \"How\n"
		"much did we discount\" from an amount that is ALREADY discounted is amount / (100 - percent)\n"
		"* percent - the same arithmetic as extracting tax included in a price (`vat`). It is not\n"
		"about tax or about discounts: it is about knowing WHAT THE PERCENTAGE WAS TAKEN FROM. And\n"
		"one hundred per cent needs its own branch, or it divides by zero.\n"
		"\n"
		"NOTE: COMPUTE ALL OF THIS ON A COPY OF THE LINES, AND WRITE THE RESULT BACK COLUMN BY\n"
		"COLUMN. Three reasons at once, and they apply to any bulk recalculation: a detached table\n"
		"raises no form events, so the recalculation cannot loop (`form-layout`); a detached table\n"
		"can be indexed, searched and collapsed, which the document's own lines cannot; and it can be\n"
		"given the extra working columns a document does not have, so ONE routine serves documents\n"
		"with different attributes.") },

	{ wxT("stock-control"),
	  ibMcpText("Refusing to go negative: free balance, reserves, and who may override it."),
	  ibMcpText("CHECKING THERE IS ENOUGH BEFORE WRITING THE MOVEMENT.\n"
		"\n"
		"KEY: THE FIGURE TO CHECK IS THE FREE BALANCE, NOT THE BALANCE. What is on the shelf minus\n"
		"what is already promised: reserved for orders, allocated to production, being shipped.\n"
		"Checking the raw balance lets a document consume goods that another document has already\n"
		"spoken for, and the shortage surfaces later - at the far end, where nobody can tell which\n"
		"of the two took it.\n"
		"\n"
		"STOP: THE CHECK RUNS PRIVILEGED, and this catches everyone once. The person posting may be\n"
		"allowed to see only their own warehouse, or only their own department's rows - so a check\n"
		"run with their rights reads a SMALLER balance than exists and refuses a perfectly good\n"
		"document. Worse, in the other direction: a filter that hides other people's reserves lets\n"
		"the same goods be promised twice. The control must see everything; the person must not.\n"
		"\n"
		"* WHETHER IT REFUSES IS A PROPERTY OF THE PLACE, NOT OF THE CODE. Some warehouses may not\n"
		"go negative; some may, deliberately - a shop counting stock once a week, a production line\n"
		"where the paperwork lags the physical movement. So the switch lives on the WAREHOUSE (or on\n"
		"the organisation), and where it is off the shortage is still SAID and no longer refuses.\n"
		"Reporting and refusing are two decisions, and only one of them is configurable.\n"
		"KEY: AND WHERE A LIMIT WILL BE BROKEN LEGITIMATELY, RECORD THE EXCESS INSTEAD OF BLOCKING IT.\n"
		"Give the register a resource of its own for the quantity issued OVER the limit and let the\n"
		"person state it on the line. Returns then net against what was issued while the irregular\n"
		"part SURVIVES the netting, so \"how much did this department draw beyond its card\" is a\n"
		"reading rather than an investigation. On a shop floor the alternative to a recorded\n"
		"over-issue is an unrecorded one.\n"
		"* AND THE MECHANISM ITSELF HAS A SWITCH - per item and place, plus one setting turning it off\n"
		"altogether. Asking for a limit while it is off must answer out loud, not return nothing.\n"
		"\n"
		"AND THE MESSAGE HAS TO BE ACTIONABLE - what was asked for, what is available, HOW MUCH IS\n"
		"MISSING, and the item named with its characteristic and unit. \"Insufficient stock\" tells a\n"
		"person to go and find out; \"needed 10 pcs, free 6 pcs, short 4 pcs of <item>\" tells them\n"
		"what to do. Every shortage in the document is reported, not the first one.\n"
		"\n"
		"NOTE: SERIES AND CHARACTERISTICS MAKE IT TWO CHECKS. Enough of the item overall does not mean\n"
		"enough of THAT series, and a reserve made without naming a series cannot be matched against\n"
		"an issue that names one. Decide which of the two the base actually keeps - and check at\n"
		"exactly that level, no finer (`posting`: a dimension filled where it should be empty splits\n"
		"the balance).\n"
		"* AND BOTH LEVELS COME FROM ONE READING, NOT TWO. Ask the query for TOTALS by the coarser\n"
		"key: the detail rows answer \"with the series\", the total rows answer \"without it\", and one\n"
		"walk over the result checks both. Two queries for two levels of the same question is the\n"
		"reflex to resist.\n"
		"* THEN SUPPRESS THE SECOND MESSAGE. Once a person has been told \"not enough of this item at\n"
		"this warehouse\", telling them again per series is noise - keep the pairs already reported\n"
		"and skip them. Say WHICH level the message is about, because \"there is stock but it will not\n"
		"write off\" is almost always the finer one.\n"
		"\n"
		"NOTE: AND WHAT IS BEING ISSUED OUT OF GOODS ALREADY SHIPPED IS NOT CHECKED AT ALL. It has\n"
		"left the free balance once already; checking it again refuses correct documents. Every\n"
		"control of this kind has one or two such exemptions, and they belong in the same place as\n"
		"the check, stated - not discovered later as \"why does this document refuse\".\n"
		"\n"
		"KEY: THE MESSAGE MUST CARRY EVERY DIMENSION THE BALANCE WAS COMPUTED BY - how much was\n"
		"asked, how much is free, what is reserved, what is due out, what is due in, the warehouse,\n"
		"the item, the variant, the series, the quality, the unit. A refusal that names fewer\n"
		"dimensions than the key cannot be acted on: the person sees stock on the screen and a\n"
		"refusal on the document, and the difference is exactly the dimension that was not mentioned.\n"
		"* AND THE REFUSAL IS ONE MESSAGE PLUS SEVERAL INFORMATIONAL LINES - the failure, then\n"
		"\"reserved: 5\", \"due out: 3\". One thing went wrong; the rest is why.\n"
		"* THE WORDING FOLLOWS THE FACTS: say \"free balance\" only when something is actually\n"
		"reserved or due out. Where nothing is, the word \"free\" invites a hunt for a reservation\n"
		"that does not exist.\n"
		"\n"
		"NOTE: AND THE SAME MECHANISM ANSWERS \"MAY I PROMISE THIS\": an order reserving goods is checked\n"
		"against the free balance, and an order exceeding what was ordered upstream is checked\n"
		"against the order. Control of quantity is one idea applied at several moments, not a\n"
		"feature of the shipping document.\n"
		"\n"
		"KEY: AND A COUNT ESTABLISHES QUANTITY AND HAS NO OPINION ABOUT VALUE. Price the difference\n"
		"PRO RATA from the book value of the position counted - every amount on the row scaled by one\n"
		"ratio - never from a price list or from today's cost. One routine serves both directions with\n"
		"a flag choosing which way the subtraction runs, so \"the books hold more than the floor\" and\n"
		"its opposite cannot drift apart.\n"
		"STOP: SCALE THE AMOUNTS AND THE QUANTITY IN THE RIGHT ORDER. Deriving a unit price from an\n"
		"already-scaled amount against the not-yet-overwritten quantity scales it twice. The movements\n"
		"stay correct and only the printed price is wrong - which is precisely why a defect of this\n"
		"shape survives for years.") },

	{ wxT("derived-registers"),
	  ibMcpText("A register kept only to make a question fast - and what owning one costs."),
	  ibMcpText("A REGISTER THAT HOLDS NO NEW FACT, ONLY A FASTER ANSWER.\n"
		"\n"
		"\"Posting has become slow\", \"the check for free stock takes seconds on a full warehouse\".\n"
		"The figure being asked for is a DIFFERENCE between registers - what is on hand minus what is\n"
		"reserved minus what is due out - and computing it means joining two or three balance\n"
		"readings on every line of every document.\n"
		"\n"
		"THE ANSWER IS A REGISTER THAT KEEPS THE DIFFERENCE ITSELF. It invents nothing: every row is\n"
		"derived from rows that already exist elsewhere. That is what makes it safe, and it is also\n"
		"what makes it a liability - two places now say the same thing.\n"
		"\n"
		"KEY: SUCH A REGISTER MUST BE SWITCHABLE, AND THE SWITCH HAS FOUR PARTS, not one:\n"
		" A FLAG saying whether it is in use at all.\n"
		" A DATE from which it is trusted - below it, the slow path is still correct, so turning the\n"
		" mechanism on does not require rebuilding all of history before anyone can work.\n"
		" A FILLING ROUTINE that populates it from the source registers as of that date.\n"
		" A CLEARING ROUTINE that deletes its movements when the flag goes off - otherwise a\n"
		" half-populated shadow survives, and the day somebody switches it back on it lies.\n"
		"* AND THE REBUILD TAKES THE BASE EXCLUSIVELY. There is no way to derive a consistent copy\n"
		"while the sources are moving, and pretending otherwise is where the mismatch is born.\n"
		"\n"
		"STOP: THE READER MUST ASK THE SWITCH, NOT THE REGISTER. Every place that consults the fast\n"
		"register needs the slow path beside it, chosen by the flag and the date. A system where the\n"
		"fast path is the only path cannot be turned off when it turns out to be wrong.\n"
		"\n"
		"KEY: WHAT DOES NOT REACH IT MUST BE KNOWN AND WRITTEN DOWN. In a real system the derived\n"
		"register deliberately omits one of the sources - goods due IN are not reflected in it - so\n"
		"the checking code adds that term back by hand. An omission like this is a design decision\n"
		"with a reason, and it becomes a defect the moment it stops being stated.\n"
		"\n"
		"NOTE: THE HONEST ALTERNATIVE IS TO ASK WHETHER THE QUESTION IS ASKED OFTEN ENOUGH. This is\n"
		"one register, one switch, two routines, a rebuild and a permanent second truth - paid so\n"
		"that one check during posting is cheap. Worth it for a check that runs on every line of\n"
		"every shipment; not worth it for a report run twice a month.\n"
		"\n"
		"KEY: AND THE LARGEST VERSION OF THIS IS REPLACING A WHOLE ACCOUNTING MODEL, WHICH IS DONE THE\n"
		"SAME WAY - a dated switch, both models in the tree at once, and the old one left able to\n"
		"answer for its own periods for ever. Read off a system carrying two costing models side by\n"
		"side:\n"
		" THE SWITCH IS A DATE COMPARED WITH THE DOCUMENT'S OWN DATE, so a document dated before it\n"
		" is posted by the old model FOREVER - including when re-posted today. That is the property\n"
		" that makes the past reproducible, and it is the reason not to switch \"from now on\".\n"
		" THE SWITCH LIVES IN THE OLD CODE, as an early return at each of its entry points, rather\n"
		" than in a dispatcher above both. Nothing new has to be threaded through the old paths.\n"
		" THE MIGRATION CARRIES BALANCES, NOT HISTORY, and carries them as ORDINARY DOCUMENTS of\n"
		" adjustment - which is what makes the whole move undoable by deleting them.\n"
		" AND THE SWITCH DATE IS A PERIOD BOUNDARY, WITH THE ROUNDING IN THE STORED VALUE RATHER\n"
		" than in the dialogue. A date inside a month leaves that month half posted by each model\n"
		" and reconcilable by nobody: take the balances at the end of the day before the start of\n"
		" the month and store THAT. Where the rounding lives only in the form offering the switch,\n"
		" first-run initialisation writes an unrounded date and the guarantee is gone with\n"
		" nothing said. And the base must record WHICH GENERATION of the migration moved it -\n"
		" both routines have to be kept, since a base that moved under the old one still has to\n"
		" be explicable - so stamp the generation onto the documents the migration writes.\n"
		" Otherwise \"how did this base get here\" has two answers and nothing in the data chooses\n"
		" between them.\n"
		" AND WHAT THE NEW MODEL CANNOT DO IS REFUSED OUT LOUD. Where the third set of books is not\n"
		" supported, the honest answer was \"do not switch\" rather than a half-working mode.\n"
		"* AND WHERE THE NEW MODEL FOLDS SEVERAL DIMENSIONS INTO ONE INTERNED KEY, READING COSTS A\n"
		"LOOKUP PER KEY PER ROW: \"group the report by division\" means UNFOLDING every row - the\n"
		"engine's own word for it. Folding is cheap to write and dear to report on, so budget the\n"
		"reporting side before choosing it.\n"
		"KEY: WHICH ANALYTICS A FOLDED KEY CARRIES IS DATA, NOT METADATA - AND THAT IS THE POINT. Keep\n"
		"one row per dimension in a settings table, with a flag per set of books and a default value;\n"
		"build the key from a QUERY over that table, and where a dimension is switched off write its\n"
		"default instead of the document's value. Turning one off then changes no schema - it\n"
		"collapses that dimension to a single value and the interning merges keys that used to differ,\n"
		"which is how the composition of the analytics becomes a customer's decision without a fork of\n"
		"the configuration.\n"
		"NOTE: THE PRICE IS THAT \"WHICH DIMENSIONS ARE IN FORCE\" BECOMES A DATABASE QUESTION - no\n"
		"query over the key registers can be written without asking it first - and the same document\n"
		"produces a coarser key for one set of books than for the other, so the two compare in totals\n"
		"and never row for row. Blank BEFORE interning, and let the policy for the document's own date\n"
		"decide what is blanked (`posting`).\n"
		"KEY: AND FOLDING ALSO BUYS HOUSEKEEPING, WHICH IS THREE ROUTINES RATHER THAN ONE. Two tables\n"
		"holding one fact diverge: keys no movement references any more, register rows whose element\n"
		"is gone, elements with no row, and the human-readable name of a key - a snapshot of\n"
		"presentations - wrong the moment anything it names is renamed. Budget a sweep of unused keys,\n"
		"a rebuild of names and an integrity check between the halves, each with a DRY RUN that prints\n"
		"what it would do. A plain set of dimensions has none of those failure modes.\n"
		"STOP: AND A FOLDED KEY CANNOT APPEAR IN A MESSAGE - its presentation is a list of values\n"
		"joined by semicolons and means nothing to the reader. Name the accounting section instead and\n"
		"attach a ROUTE, the report that shows the problem opened on the right rows; keep the keys for\n"
		"a debugging mode.\n"
		"* AND A ROW THAT CANCELS ITSELF IS DROPPED - EXCEPT WHEN IT IS THE ONLY WITNESS. A movement\n"
		"whose source and target keys are equal carries no information and is swept away; but where\n"
		"the two sides differ in something THE KEY DOES NOT CONTAIN - a warehouse, when costing is\n"
		"not kept per warehouse - that row is the only remaining evidence the move happened. Any\n"
		"sweep of \"empty\" rows needs this exception beside it, or a transfer between warehouses\n"
		"silently produces nothing.\n"
		"STOP: BUT MOST OF ITS REFUSALS ARE ADVISORY, AND THAT IS THE TRAP. An operation with no rule\n"
		"prints \"not supported, will not be included in the cost calculation\" and returns WITHOUT\n"
		"setting the refusal flag: the document posts and its cost silently vanishes. A message is\n"
		"not a refusal (`posting`).\n"
		"* AND AN ALL-EMPTY KEY MUST NOT BE INTERNED - return the empty reference instead. Otherwise\n"
		"the store fills with keys that stand for nothing, and every reader has to know that this\n"
		"particular key means the same as no key at all (`combining`: an empty value is a meaning).\n"
		"* WHERE TWO FAMILIES OF KEY SHARE ONE COLUMN, the discrimination is BY TYPE and it must be\n"
		"made at both ends: the writer returns without writing when the value is of the other family,\n"
		"the reader looks the other family up elsewhere and merges. A typed reference makes that free -\n"
		"and it is the reason the column can be shared at all.\n"
		"\n"
		"STOP: AND A ROUTINE THAT ADDS ONE ROW MUST NOT SECRETLY WRITE THE SET. Flushing the\n"
		"accumulated movements from inside the per-row routine when it reaches a size read from a\n"
		"constant does solve the memory problem of a document producing tens of thousands of rows -\n"
		"and it gives that routine a side effect its name denies, makes a half-written set visible to\n"
		"anything reading mid-transaction, and forces any caller who wants the whole set to pass a\n"
		"flag suppressing it. If batching is needed, let the CALLER drive it.\n"
		"\n"
		"* AND A BOUNDARY DATE MUST NOT BE USED AS A SUBSTITUTE FACT. Where migrated stock has no\n"
		"supplying document, one report shows the SWITCH DATE as the date the goods arrived. A\n"
		"technical date presented as a business fact is worse than an empty one.\n"
		"\n"
		"NOTE: THE SAME SHAPE APPEARS ELSEWHERE UNDER OTHER NAMES - materialised allocation bases\n"
		"(`allocation`), stored intervals beside a periodic register (`query-craft`), stored\n"
		"placement of orders against supply. Recognising it as one shape means the four parts of the\n"
		"switch are not reinvented each time.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. Everything above is buildable out of registers and a\n"
		"scheduled job except one thing: an INTERNED KEY - folding several dimensions into one stored\n"
		"element, so a register carries one reference instead of eight. That is the one part worth\n"
		"asking for rather than writing, because writing it brings the three housekeeping routines\n"
		"above with it, and they never stop being maintained.\n"
		"* SO THE DECISION RULE STANDS ON ITS OWN: prefer the plain set of dimensions and pay the\n"
		"width; reach for folding only when a measurement says the width is the problem, and only\n"
		"when something else owns the interning.") },

	{ wxT("not-mine"),
	  ibMcpText("Goods that are not yours, and yours that are not with you - commission and safekeeping."),
	  ibMcpText("SOMEBODY ELSE'S GOODS IN YOUR WAREHOUSE, AND YOURS IN THEIRS.\n"
		"\n"
		"THE SIGNAL: \"we take it on commission\", \"we hand it over for sale\", \"it is stored with us\n"
		"but it is not ours\", \"we sent materials out for processing\". Four situations, one\n"
		"question: WHOSE is it, and WHERE is it. Those are two different facts and both have to be\n"
		"kept.\n"
		"\n"
		"STOP: THE MISTAKE IS TO MIX IT WITH YOUR OWN STOCK. Goods that are not yours must not enter\n"
		"your balances, your cost calculation or your valuation - they are not an asset of yours,\n"
		"and averaging them into your cost quietly corrupts every figure downstream. In the books\n"
		"they belong off-balance; in the operational registers they are told apart by a STATUS on\n"
		"the lot - bought, taken on commission, held for safekeeping - or by a register of their\n"
		"own.\n"
		"STOP: DO NOT ENCODE \"OURS\" AS THE ABSENCE OF AN ANSWER. Where the marker is an enumeration of\n"
		"one value and own goods are the empty reference, every row that LOSES the attribute - a copy,\n"
		"a fill from a basis, a table assembled by hand - silently becomes yours, and never the other\n"
		"way. The asymmetry runs the wrong way by construction: the state that must never be entered\n"
		"by accident is the one every accident produces, and it is the state that puts somebody else's\n"
		"goods into your cost.\n"
		"* MAKE THE STATE THAT COSTS MONEY EXPLICIT and let the empty value mean \"not answered\", so it\n"
		"can be refused. Where the axis is already built the other way, at least keep the column\n"
		"VISIBLE - in the system examined it was hidden unless a second mechanism was switched on, so\n"
		"the fact lived in the data and appeared on no form.\n"
		"\n"
		"AND THE TWO AXES ARE INDEPENDENT, which is what decides the design:\n"
		" YOURS, WITH YOU - ordinary stock.\n"
		" YOURS, ELSEWHERE - handed to an agent to sell, sent out for processing, in transit.\n"
		" Still your asset, still in your cost, but not available to sell from the shelf. A\n"
		" register of TRANSFERRED lots, separate from the warehouse one - or, better, a HOLDER\n"
		" dimension on the ownership register rather than a register of its own: empty while it\n"
		" is with you, the party once it is out, so handing goods over is ONE balanced pair\n"
		" inside that register, an expense with the holder empty and a receipt with the holder\n"
		" filled. The physical register is then simply relieved and answers \"what is on the\n"
		" shelf\" and nothing more. Which is also why the count of registers cannot be cut\n"
		" further: physical presence, legal ownership, what you owe for somebody else's goods\n"
		" and what they owe for yours are four independent questions; only the middle two\n"
		" collapse into one table with a dimension, and folding the outer two in produces a\n"
		" register that answers none of them.\n"
		" NOT YOURS, WITH YOU - taken on commission, accepted for safekeeping. In your building,\n"
		" absent from your assets.\n"
		" NOT YOURS, ELSEWHERE - not your problem, and worth saying so when somebody asks for it.\n"
		"\n"
		"KEY: GOODS THAT ARE NOT WITH YOU HAVE NO WAREHOUSE - THE PARTY IS THE PLACE. Key the\n"
		"transferred and the held-for-others registers by party, contract, deal and a STATUS saying\n"
		"why it is there, with quantity and a settlement amount as resources, and give them no\n"
		"warehouse dimension at all: which of the agent's sites holds it is not a fact you have.\n"
		"* SO \"WHERE IS IT\" HAS TWO ANSWERS AND ONE READING SERVES BOTH BY SUBSTITUTION - given a\n"
		"party, swap the physical register for the transferred one, force the warehouse parameter\n"
		"empty, select a literal empty warehouse in its place, and the rest of the query stands\n"
		"unchanged. A second query written for the same question is where the two answers begin to\n"
		"disagree.\n"
		"\n"
		"* SELLING SOMEBODY ELSE'S GOODS CREATES AN OBLIGATION, not a profit. The movement that\n"
		"matters is not \"stock went down\" but \"we now owe the owner for what was sold\" - a separate\n"
		"record, written at the moment of sale, from which the report to the owner and the\n"
		"settlement are later built. And it has to be written for goods sold BOTH from your\n"
		"warehouse and from wherever else they were sitting, which is the case that gets forgotten.\n"
		"KEY: AND THE MARGIN ON SOMEBODY ELSE'S GOODS IS ZERO BY CONSTRUCTION - THE FEE IS THE WHOLE\n"
		"INCOME. Write ONE line into the sales register for the commission - the service, no quantity,\n"
		"the fee as its value - and never the goods. In the cost engine, the write-off of a consigned\n"
		"lot takes THE ROW'S OWN REVENUE as its cost rather than a stored one, so revenue equals cost\n"
		"on those rows and the entire spread stays a payable to the owner.\n"
		"KEY: AND WHETHER THE INTERMEDIARY KEEPS THE FEE IS ONE FLAG, NOT A SECOND DOCUMENT. Set, the\n"
		"debt is booked NET of the fee and its tax with no counter-movement; clear, it is booked GROSS\n"
		"and an opposite movement for the fee goes into every settlement register. The netted road\n"
		"costs the fee its existence as a turnover - right for the settlement, useless for any\n"
		"analysis of what was earned.\n"
		"\n"
		"NOTE: THE OWNER'S REPORT IS ITS OWN DOCUMENT, in both directions: the one you send for what you\n"
		"sold of theirs, and the one you receive telling you what an agent sold of yours. The second\n"
		"is what finally turns your transferred lot into a sale - until it arrives, the goods are\n"
		"still yours and still unsold, however long ago they physically left.\n"
		"KEY: AND THE HOLDER'S REPORT SETTLES AT TWO PRICES AT ONCE, BOTH ON THE ROW. What the goods\n"
		"were handed over at closes the transferred balance; what they were sold for raises the debt -\n"
		"each with its own tax amount. Then goods out with an agent are always valued at what you gave\n"
		"them for, the debt is always what they sold for, and the difference is exactly the margin\n"
		"plus the fee, with nothing left to reconcile.\n"
		"NOTE: Such a row therefore carries several amount columns which must all be filled and none\n"
		"of which may be negative - check them as a SET, naming the column, before anything is\n"
		"written. Where one routine below expects a single amount and the columns are renamed around\n"
		"the call, that is the sign the layer below cannot say which amount it wants\n"
		"(`bill-of-materials`).\n"
		"\n"
		"NOTE: AND THE RETURN PATHS ARE REAL: goods come back from an agent unsold, and goods you took\n"
		"on commission go back to their owner. Neither is a sale in reverse - both are movements\n"
		"between the states above, and each needs its own operation kind so the write-off knows\n"
		"which register it is taking from (`lot-accounting`).\n"
		"KEY: AND WHAT KIND OF MOVEMENT THIS IS COMES FROM THE RELATIONSHIP, NOT FROM THE PERSON. A\n"
		"shipment under a contract held with an agent IS a hand-over: the ordinary sale document\n"
		"suppresses the settlement leg and the revenue, writes the transferred register with the\n"
		"consignment status and moves ownership onto the holder - no second document type is needed.\n"
		"And a return entered from a hand-over derives its own direction from the document it came out\n"
		"of, so nobody is asked a question whose answer is already recorded.\n"
		"STOP: ANSWER IT ONCE. Where the pair (operation kind, contract kind) is re-tested at each of\n"
		"twenty sites, a contract disagreeing with the chosen operation quietly produces an ordinary\n"
		"sale - with a debt raised against a party who owes nothing, and no message anywhere.\n"
		"\n"
		"KEY: THE FOUR STATES ARE FOUR ACCOUNT SLOTS ON ONE SETTINGS ROW, and posting only moves the\n"
		"value between them: on our books here, off our books here, on our books elsewhere, off our\n"
		"books elsewhere - plus a marker saying whose it is. Held per (party, item, place), so the\n"
		"answer is a lookup rather than a chain of conditions in every document. If the four are\n"
		"scattered across four mechanisms, every new document has to learn all four.\n"
		"KEY: THERE IS A THIRD RELATIONSHIP OF THIS KIND - RETURNABLE PACKAGING - AND IT IS THE ONLY\n"
		"ONE WITH A CEILING. It travels on the same two registers under its own status, and a settings\n"
		"register holds a limit per party and item. The test is not \"does this document exceed the\n"
		"limit\" but \"does what they already hold PLUS this document exceed it\": group the document's\n"
		"rows, join the current balance and the limit in force, and put the comparison in the\n"
		"aggregate test.\n"
		"STOP: AND LOCK THE BALANCE FOR THE TEST, or two shipments checked in the same instant both\n"
		"pass. Name all three numbers in the refusal - the limit, what is already out, what is being\n"
		"added - since otherwise the person cannot tell whether to cut the order or chase a return.\n"
		"\n"
		"KEY: THE SALE DOES NOT CREATE WHAT YOU OWE THE OWNER - THE WRITE-OFF DOES. And it addresses\n"
		"the owner by THE ORIGIN OF THE LOT, not by the sale: the contract comes from the document the\n"
		"lot arrived on. Only then is the right owner credited when a shipment draws on lots from two\n"
		"of them.\n"
		"* WHICH MEANS ANY write-off owes the owner, not only a sale - goods written off to costs, or\n"
		"found short at a count, are just as much theirs.\n"
		"* AND THE LOOP HAS TO RUN TWICE, because goods taken on commission can be handed on again:\n"
		"the origin of the lot may itself be a consignment.\n"
		"\n"
		"KEY: OWN AND CONSIGNED STOCK ARE ONE POOL, AND WHICH GOES FIRST IS THE DIRECTION OF ONE SORT\n"
		"COLUMN. Rank the candidate lots by ownership, and the policy \"sell ours first\" or \"sell\n"
		"theirs first\" only decides whether that column is ascending or descending. The same device\n"
		"as every other strategy here (`combining`: priority as data, not as branches) - and it means\n"
		"the pool is never split into two searches that can disagree.\n"
		"\n"
		"KEY: WHEN THE HOLDER'S COUNT DISAGREES WITH YOURS, THE COUNT IS A DOCUMENT THAT DOES NOT\n"
		"POST. The difference becomes a sale only when the owner's report is filled FROM it, and the\n"
		"value is prorated from the register's own amount balance. A count that posts by itself would\n"
		"decide, on its own authority, that goods were sold.\n"
		"* AND ROWS WHERE THE HOLDER HAS MORE THAN YOU THINK ARE SKIPPED - which is defensible and\n"
		"must be SAID, because silence here reads as agreement.\n"
		"\n"
		"STOP: AND THE GUARD AGAINST REPORTING OR RETURNING MORE THAN WAS GIVEN IS THE ONE THAT GETS\n"
		"SWITCHED OFF. In the system examined both balance checks return immediately unless the\n"
		"posting is happening in real time - so anything entered backdated, and every re-posting,\n"
		"drives the balance negative in silence. A check that only runs in the easy case is not a\n"
		"check (`stock-control`: decide the strictness deliberately, and say which mode has which).\n"
		"KEY: AND WHERE SHIPPING IS TWO-STEP, EVERY AXIS NEEDS ITS OWN COMMITMENT REGISTER. Goods\n"
		"leaving on a warehouse order relieve neither stock nor ownership - they write a due-out\n"
		"record, and there are TWO: one keyed by warehouse carrying the reserving document, one keyed\n"
		"by the owning entity carrying the transfer document. The relief happens later, on the order\n"
		"itself.\n"
		"NOTE: AVAILABILITY IS THEN COMPUTED, NOT STORED - the ownership balance less the entity-side\n"
		"due-out, joined on the full key and floored at zero. It is the reservation pattern applied to\n"
		"the ownership axis rather than to the shelf, and a design that builds only the warehouse side\n"
		"promises the same goods twice: once to a buyer, once to the agent they are already assigned\n"
		"to.\n"
		"\n"
		"NOTE: AND THE OWNER'S REPORT IN THE TWO DIRECTIONS IS TWO DOCUMENTS OF THE SAME SHAPE, not\n"
		"one document with a sign - in the system examined, some three thousand lines each, largely\n"
		"parallel. That is the honest cost of the symmetry, and it is worth knowing before promising\n"
		"the second direction as \"the same thing mirrored\".") },

	{ wxT("posting"),
	  ibMcpText("Writing a document's movements: sets, partial replacement, locks and refusals."),
	  ibMcpText("HOW MOVEMENTS ARE ACTUALLY WRITTEN.\n"
		"\n"
		"A RECORD SET IS THE UNIT, NOT A RECORD. Movements are collected into a table while the\n"
		"posting works, and written ONCE per register at the end. Writing them one at a time turns\n"
		"a document of two hundred lines into two hundred round trips, and leaves the register half\n"
		"filled if something fails in the middle.\n"
		"\n"
		"KEY: AND THE HANDLER FILLS THE SET - THE PLATFORM WRITES IT. `Posting` adds the rows and\n"
		"returns; the document's own write then stores every set that CHANGED. So a handler that\n"
		"calls Write() itself is doing the platform's half a second early, and the two halves are\n"
		"not idempotent: the write empties the set, and the final pass would REPLACE the rows just\n"
		"stored with nothing. (An engine that skips unmodified sets survives this; one that does not\n"
		"posts the document and loses its movements, with nothing raised - seen live, 2026-09-03.)\n"
		"* WRITE FROM THE HANDLER ONLY WHEN A LATER STEP MUST READ THE ROWS BACK from the database\n"
		"(the flush described further down), and then know that the set is empty afterwards.\n"
		"STOP: WHICH IS ALSO WHY A CONTROL CANNOT READ ITS OWN MOVEMENTS DURING `Posting`. They are\n"
		"not in the database yet. A free-balance check compares the balance AS IT STANDS against\n"
		"what this document is about to take - from the lines or from the set in memory - and never\n"
		"by querying the register for rows it has not written.\n"
		"\n"
		"AND WRITING A SET REPLACES EVERYTHING THAT RECORDER HAD. That is what makes re-posting\n"
		"safe - and it is also the trap:\n"
		"\n"
		"STOP: TWO MECHANISMS WRITING TO ONE REGISTER FROM ONE DOCUMENT WILL ERASE EACH OTHER. The\n"
		"document posts its own movements; later the cost adjustment writes its own into the same\n"
		"register under the same recorder - and replaces the lot. Nothing raises; the first set is\n"
		"simply gone.\n"
		"* THE CURE IS A MARK ON THE RECORD: an attribute saying which mechanism made it. Then a\n"
		"mechanism re-posting itself READS the set, removes only the rows carrying ITS mark, adds\n"
		"its new rows with the mark set, and writes. Each half owns its own records, and the two\n"
		"stop overwriting each other. Worth deciding the day a second writer appears - the symptom\n"
		"otherwise is movements that vanish depending on the order things were run in.\n"
		"\n"
		"LOCK BEFORE YOU READ WHAT YOU ARE ABOUT TO CHANGE. Balances read for a decision - are there\n"
		"enough lots, what is the remaining amount - can change between the reading and the write,\n"
		"and the document then posts on figures that were true a second ago. Take the lock over the\n"
		"table and the values being touched, then read. This is invisible in testing, where nobody\n"
		"else is working, and shows up as impossible balances on a busy day.\n"
		"* AND LOCK THE VALUES, NOT THE TABLE. Put the DISTINCT combinations this document is about\n"
		"to touch into a temporary table and lock by that set - some dimensions pinned to fixed\n"
		"values, the rest taken from the table's columns. Then two payments under different contracts\n"
		"do not wait for each other. Locking the register whole is what turns a busy afternoon into a\n"
		"queue.\n"
		"* AND THE LOCK IS BEST WRITTEN AS A LINE OF THE QUERY THAT READS, naming the exact table\n"
		"being locked, with the reason in a comment beside it. Then the concurrency decision sits next\n"
		"to the read it protects instead of in a separate call somewhere above, and a reader of the\n"
		"text can see whether the lock and the read are about the same rows. Where the register is\n"
		"chosen by the caller, the name in that clause is assembled from the same parameters that\n"
		"chose the table, so one generic check locks whichever register it was asked about.\n"
		"* AND ORDER THE MOVEMENTS DETERMINISTICALLY - by the full set of dimensions - before writing\n"
		"them. Two documents touching the same rows in opposite orders deadlock; touching them in the\n"
		"same order cannot. It costs one sort and removes a class of failure that is nearly\n"
		"impossible to reproduce.\n"
		"* AND TAKE A SHARED LOCK WHERE YOU ONLY READ, an exclusive one where you intend to move\n"
		"something - the boundary in `sequences` is the standing example: readers of it are frequent,\n"
		"movers are rare.\n"
		"\n"
		"KEY: WITHIN ONE POSTING, THE OUTGOING MOVEMENTS GO BEFORE THE INCOMING ONES. A document that\n"
		"moves something and then consumes it writes both in the same period, and if the consumption\n"
		"is ordered first the balance dips negative and the check refuses a correct document. Sort\n"
		"the set before writing - direction first, then line number - and the case disappears\n"
		"instead of being special-cased.\n"
		"\n"
		"KEY: DECIDE THE RULE ONCE AT THE BOUNDARY, AND DO NOT RE-ASK IT INSIDE. Read the policy, the\n"
		"regime, the dated law ONCE for this document, and put the ANSWERS - already decided, as\n"
		"plain yes-or-no - into the context everything downstream reads. Then the generation of\n"
		"movements asks \"is this taxed under the old rules\" rather than comparing the date again in\n"
		"forty places. That single move is what makes recomputation of an old period reproducible:\n"
		"there is one place where \"when\" turns into \"what\", and it is at the entrance.\n"
		"\n"
		"NOTE: SOMETIMES A STEP MUST SEE THE PREVIOUS STEP'S MOVEMENTS, and then the set is FLUSHED TO\n"
		"THE DATABASE mid-posting on purpose - a later step asks the register whether the order it\n"
		"just satisfied is now complete, and a query cannot see what has not been written. Where this\n"
		"is done, say so at the flush: it looks like a stray write and it is a dependency between\n"
		"steps that reordering will break silently.\n"
		"\n"
		"NOTE: AND WHERE A REFUSAL WILL BE ARGUED ABOUT LATER, MAKE IT A RECORD RATHER THAN A\n"
		"SENTENCE. A heavy check can build its outcome as a structure - sections by KIND, each with\n"
		"its own detail - render it once, and store it against the object that ran the check. Then\n"
		"\"why did this not post in March\" is answerable in April. A message is enough for a person at\n"
		"the screen and gone for everyone after them.\n"
		"* AND THE SET OF DETAIL KINDS THAT REPORT CAN HOLD IS KEPT OPEN BY MAKING THE KIND A NAME:\n"
		"the renderer handles a few built-in kinds - a heading, a sentence, a link, a list of links -\n"
		"and then falls through to \"if a template area of this name exists, render the data through\n"
		"it, once per row if it is a collection\". A new kind of detail is then a new AREA in the\n"
		"template and no change to the renderer or to the collection type. The template is the\n"
		"registry.\n"
		"STOP: THE PRICE IS THAT A MISSPELLED KIND IS NOT AN ERROR, IT IS AN INVISIBLE OMISSION - the\n"
		"renderer finds no area and skips the section without a word. Where the set is open, the check\n"
		"that a name resolves has to be run deliberately, because nothing else will run it.\n"
		"\n"
		"KEY: A DATE IS A DAY AND A MOMENT IS A SECOND - NORMALISE BEFORE COMPARING THEM. A due date,\n"
		"a period, a policy date are given to the day; a movement stands at a moment. Compared\n"
		"directly, documents of the SAME day fall in or out of a selection according to the order\n"
		"they happened to be entered. Decide explicitly - the end of that day, the moment of the\n"
		"document, or a configured choice between them - and apply the SAME rule in the code and\n"
		"inside the query, where the comparison usually happens a second time.\n"
		"\n"
		"A PROBLEM IS A REFUSAL PLUS A MESSAGE, NOT AN EXCEPTION. Posting carries a refusal flag\n"
		"through the whole routine: each check that fails says WHAT is wrong, in which LINE, with\n"
		"the item named, and sets the flag. At the end the document does not post - but the person\n"
		"has every problem at once rather than the first one, fixed, then the second one. An\n"
		"exception thrown from the middle also leaves the write transaction to be unwound by\n"
		"somebody else, which is its own class of trouble.\n"
		"\n"
		"KEY: A CHECK HAS TWO SEVERITIES, AND WHAT CHOOSES BETWEEN THEM IS THE POSTING MODE, NOT\n"
		"THE PERSON. In real time a failed balance control sets the refusal flag and stops the\n"
		"document. In every other mode - a backdated entry, a re-post, a sequence restoration - the\n"
		"same sentence goes to the journal and the run continues. A mass re-post of history is\n"
		"obliged to reach the end: the data is already what it is, and stopping halfway leaves the\n"
		"base in a worse state than a run that complains all the way through.\n"
		"STOP: BUT THE DOWNGRADE IS TO A RECORDED WARNING, NEVER TO SILENCE. A control that returns\n"
		"immediately unless posting is in real time is not a control (`not-mine`): everything\n"
		"entered backdated then drives the balance negative with nothing to read afterwards. Decide\n"
		"both severities when the check is written, and say which mode carries which.\n"
		"\n"
		"NOTE: AND CHECK THE HEADER BEFORE DOING ANY WORK. Organisation, warehouse, date, currency -\n"
		"the handful of values everything downstream depends on. Discovering on line 180 that the\n"
		"warehouse is empty wastes the work and produces a message about the wrong thing.\n"
		"\n"
		"KEY: THE ORDER OF A REAL POSTING, and it is the same in every document worth copying:\n"
		" 1. CLEAR THE OLD MOVEMENTS when re-posting.\n"
		" 2. GATHER, in queries: the header's context, then ONE query per tabular section bringing\n"
		" everything those lines need - accounts, policies, item settings, whatever is reached\n"
		" through a reference. Nothing is fetched inside the loops that follow.\n"
		" 3. CHECK EVERYTHING - the header, each section, the agreement against the currency, the\n"
		" balances, the rights - accumulating refusals and messages rather than stopping at the\n"
		" first.\n"
		" 4. ONLY THEN WRITE, in one block, guarded by \"if nothing refused\". A document that has\n"
		" written half its registers and then found a problem has to unwind them, and the\n"
		" unwinding is where the defects live.\n"
		"\n"
		"* AND THE MOVEMENT TABLES ARE BUILT BEFORE THE CHECKS RUN, NOT AFTER THEM. The balance\n"
		"control has to compare the balance WITH this document's own movements already in it, so it\n"
		"needs the finished tables; the write needs a control that passed. That fixes the order as\n"
		"build - check - write, and it is what makes a half-posted document impossible without\n"
		"leaning on a transaction to undo one.\n"
		"* AND EVERY BUILDER READS THE REFUSAL FLAG AS WELL, returning an empty table when it is\n"
		"already set: after the first refusal the later steps neither compute nor fall over, and the\n"
		"person still gets every problem at once. The flag is written by the checks and read by the\n"
		"builders - which is what makes the whole sequence cheap to abandon at any point.\n"
		"\n"
		"KEY: THE GATHERING QUERY IS NOT WRITTEN - IT IS DECLARED, AND EVERY SUBSYSTEM ADDS TO THE\n"
		"DECLARATION. The document fills in a table of \"name in the result -> where to get it\", where\n"
		"the second half is a PATH - the item's product group, the sales scheme's income account -\n"
		"and the joins are written by the engine. For the header, the declaration also names the\n"
		"SOURCE: a constant, a settings register, an attribute.\n"
		"* WHY IT MATTERS: one field is wanted by three different subsystems, and each of them asks\n"
		"for what it needs by ADDING TO THE SAME DECLARATION - settlements adds its fields, the\n"
		"statutory side adds accounts, tax adds designations. The text is assembled once from the\n"
		"finished declaration. The alternative is three queries reading overlapping data, or one\n"
		"query nobody dares to edit because it serves everybody.\n"
		"KEY: AND THE MOVEMENT MAPPING ITSELF CAN BE A TABLE - ONE POSTING ALGORITHM, A ROW PER\n"
		"DOCUMENT. Address a rule by (document, operation, tabular section, which side of the\n"
		"transfer); let each column of the rule name a field of the movement row and hold either the\n"
		"column to copy, an expression to evaluate, or nothing, with one further column filtering the\n"
		"rows it applies to. Adding a document to the subsystem is then an edit to data, and the\n"
		"engine below never learns a new name.\n"
		"STOP: THE PRICE IS TOTAL AND MUST BE ACCEPTED IN ADVANCE - nothing checked before it runs, no\n"
		"debugger inside a cell, an interpreter invoked per row per expression, and a misspelt column\n"
		"producing an EMPTY FIELD rather than an error. Where the variants differ in a few fields\n"
		"only, declare the differences and assemble the text instead (`query-by-name`); reach for the\n"
		"rule table only when the variety genuinely is one mapping per kind of document.\n"
		"* AND WHERE A PATH IS NOT ENOUGH, THE DECLARATION HOLDS AN EXPRESSION instead: \"if the\n"
		"account on the line is empty, take the one from the header\". Which is also the general\n"
		"convention worth adopting - AN EMPTY VALUE ON A LINE MEANS \"AS IN THE HEADER\", not \"not\n"
		"filled in\".\n"
		"\n"
		"KEY: WHAT IS MANDATORY IS ALSO DECLARED - AND THE DECLARATION CARRIES THE REASON. Rather\n"
		"than a chain of conditions, the document builds a list of required fields where the value\n"
		"beside each name is THE SENTENCE EXPLAINING WHY IT IS REQUIRED, and one shared routine\n"
		"checks them and reports. The person then reads \"this contract settles by order, so the order\n"
		"must be named\" instead of \"field not filled in\" - and requiredness is CONDITIONAL, which is\n"
		"the whole point: it appeared because of something they chose earlier.\n"
		"* EACH SET OF BOOKS ADDS ITS OWN REQUIRED FIELDS to the same list, and only when it is\n"
		"actually being reflected.\n"
		"STOP: BUT THE SECOND KIND OF CHECK DOES NOT FOLD INTO A DECLARATION - \"this COMBINATION is\n"
		"not allowed\": equipment cannot be sold under an agreement settled by orders, faulty goods\n"
		"cannot be consigned. These are written as code and must speak in the words of the trade, not\n"
		"in field names.\n"
		"\n"
		"* AND SOME CHECKS ARE ABOUT THE PERSON, NOT THE DATA: may this user sell at this price,\n"
		"give this discount, post into a closed period, ship beyond what was ordered. They belong\n"
		"with the other checks in step 3 - as RIGHTS, so the answer can differ per role, rather than\n"
		"as a constant that has to be edited when the sales manager is allowed a bigger discount.\n"
		"\n"
		"NOTE: WHAT TRAVELS BETWEEN THE PARTS: one structure carrying the posting's context - the\n"
		"document, its header values, the policy read for that date, the tables being filled, the\n"
		"registers being written. Passing eleven arguments through six routines is how the seventh\n"
		"ends up with a stale copy of one of them.\n"
		"\n"
		"NOTE: ONE DOCUMENT WRITES INTO MANY REGISTERS, and that is normal rather than a smell. A single\n"
		"sale moves stock, consumes lots, changes what the counterparty owes, records the sale for\n"
		"analysis, notes the tax event, writes the double entry, and leaves an index for later\n"
		"returns. Each of those answers a DIFFERENT question, and folding them into one register to\n"
		"be tidy produces something that answers none of them well.\n"
		"* What keeps it manageable is that the document does not know how: it hands its prepared\n"
		"tables to the mechanism that owns each register - stock, settlements, tax, lots - and each\n"
		"writes its own. A document containing the write-off rule, the settlement rule and the tax\n"
		"rule inline is the same code copied into the next document a month later.\n"
		"\n"
		"STOP: AND FILLING A DIMENSION \"JUST IN CASE\" IS A DEFECT, not caution. A dimension is filled\n"
		"only when accounting is actually KEPT by it: the series only where lots are tracked by\n"
		"series, the warehouse only where lots are tracked per warehouse, the order only for work\n"
		"done to order. Otherwise it is left EMPTY - and empty is a legitimate, meaningful value:\n"
		"the balance held without a series.\n"
		"\n"
		"Why it matters more than it looks: a dimension filled where it should be empty SPLITS the\n"
		"balance. The receipt lands under one key and the write-off looks under another, so the\n"
		"lots are \"not there\" while the register plainly shows them - and the report totals\n"
		"correctly, because the sum is right and only the breakdown is wrong. It is the single most\n"
		"common cause of \"there is stock but it will not write off\".\n"
		"STOP: AND THE MIRROR CASE IS QUIETER STILL - A DIMENSION LEFT EMPTY WHERE EVERY READER FILTERS\n"
		"BY IT. Rows written with an empty status, an empty kind or an empty section land in a bucket\n"
		"nothing queries, because each reader passes a value for it. They are neither lost nor\n"
		"visible, and the balance is wrong only where nobody looks - until a return or a report tries\n"
		"to match them.\n"
		"* WHICH MAKES A STATUS ASSIGNED BY A SECOND COPY OF THE CONDITION THAT ADMITTED THE ROW A\n"
		"DEFECT WAITING TO HAPPEN: one test decides which rows exist, another a few lines below\n"
		"decides what they are called, and the day they stop agreeing the rows arrive with that column\n"
		"empty. Make it one test, or take the value from the row.\n"
		"STOP: AND A REGISTER NAMED BY A STRING AT RUN TIME MAKES \"NOT APPLICABLE\" AND \"MISSPELT\" THE\n"
		"SAME EVENT. Where each generator asks a shared helper for the record set by name, a document\n"
		"that does not write that register gets a quiet refusal and returns - and so does a typo. Two\n"
		"rules keep it usable: the quiet path is only for a document that DECLARES it does not write\n"
		"there, and every other unhandled case SHOUTS, naming the value it could not handle and the\n"
		"routine that could not.\n"
		"* A SILENT DEFAULT IN A MOVEMENT BUILDER IS THE WORST FAILURE THIS AREA HAS: the document\n"
		"posts cleanly with no entry, and it is found weeks later, at the close, by somebody else. The\n"
		"same name plus a suffix is also how the second set of books is addressed, so one generator\n"
		"serves both worlds - paid for in the compiler seeing none of it (`parallel-accounting`).\n"
		"\n"
		"* WHICH MEANS THE SET OF DIMENSIONS TO FILL IS DECIDED BY THE POLICY AND THE OPERATION\n"
		"KIND, read for the document's own date - not written as a fixed list in each posting\n"
		"routine. The same document posts different keys in a base that keeps lots per warehouse and\n"
		"in one that does not, and both are correct.") },

	{ wxT("deferred-posting"),
	  ibMcpText("When posting is too slow: doing the urgent part now and the heavy part in a batch."),
	  ibMcpText("SPLITTING A POSTING IN TWO WHEN IT HAS BECOME TOO SLOW.\n"
		"\n"
		"The words are always about time: \"posting takes forty seconds\", \"the close hangs all\n"
		"evening\", \"the warehouse cannot work while accounting posts\". What is actually happening is\n"
		"that ONE document is writing both the movements somebody needs THIS SECOND - stock, reserves,\n"
		"debts - and the movements nobody will read until the month ends - the ledger, the tax\n"
		"registers, the costing detail.\n"
		"\n"
		"KEY: TWO STAGES OF ONE POSTING, NOT TWO POSTINGS. A property carried on the object says\n"
		"which stage this run is - the operational one, the catching-up one, or everything at once -\n"
		"and that property SWITCHES THE FLAGS SAYING WHICH SETS OF BOOKS ARE REFLECTED. The posting\n"
		"code is not branched and not duplicated: it already asks those flags for every movement it\n"
		"writes (`parallel-accounting`), so the split costs nothing but the flag.\n"
		"* WHICH IS THE WHOLE TRICK, AND IT ONLY WORKS IF THE FLAGS EXISTED FIRST. A posting written\n"
		"as one undivided lump cannot be split this way later without being rewritten.\n"
		"\n"
		"KEY: IT IS SWITCHED ON PER COMPANY AND FROM A DATE, held in a small register. Below that\n"
		"date, everything posts as before - so turning it on does not invalidate history, and turning\n"
		"it off is not a migration.\n"
		"\n"
		"KEY: THE LIST OF PARTICIPATING DOCUMENTS IS NOT MAINTAINED BY HAND. \"This document takes\n"
		"part\" is answered by asking its own METADATA whether it writes to the register that records\n"
		"pending work. The document marks itself as needing the second stage by MOVING IN THAT\n"
		"REGISTER, and the mark disappears when the second stage writes. A list kept beside the\n"
		"mechanism would be one more thing to forget when a document is added (`shapes`: a hand-kept\n"
		"list of participants is a defect).\n"
		"\n"
		"KEY: THE BOUNDARY IS \"THE DATE OF THE FIRST DOCUMENT NOT YET CAUGHT UP\", per company. Before\n"
		"it the statutory reports are honest; after it they are not. This is the same question as the\n"
		"boundary in `sequences`, asked about a different mechanism, and it must be SHOWN - a report\n"
		"that is quietly incomplete is worse than one that refuses.\n"
		"* AND THE RIGHT TO REFLECT A DOCUMENT IN THE STATUTORY BOOKS ASKS WHETHER IT IS FULLY POSTED.\n"
		"The two mechanisms are connected on purpose.\n"
		"\n"
		"NOTE: THE CATCHING-UP INTERVAL IS EITHER FIXED OR SLIDING - \"from the 1st to the 15th\", or\n"
		"\"lag N periods behind today\" - and that is a setting, not a constant. Sliding is what people\n"
		"actually want, and it is the one that cannot be expressed by two dates.\n"
		"\n"
		"NOTE: THE SECOND STAGE NEEDS ITS OWN WINDOW, ITS OWN JOURNAL AND ITS OWN JOB. What is queued,\n"
		"what failed and why, how far it has got - a person has to be able to look. See\n"
		"`scheduled-documents` for the shape of the job that drives it.") },

	{ wxT("entered-from"),
	  ibMcpText("Making one document out of another: what carries over, what must not, and what wins."),
	  ibMcpText("ENTERING ONE DOCUMENT FROM ANOTHER.\n"
		"\n"
		"\"Make an invoice out of this order so nobody retypes it.\" One routine serves every pair of\n"
		"documents, and its rule is a single line: IF BOTH SIDES HAVE AN ATTRIBUTE OF THIS NAME, COPY\n"
		"IT. No table of correspondences, no per-pair description - what carries over is the\n"
		"INTERSECTION OF NAMES, checked against the metadata of both documents.\n"
		"* WHICH MEANS THE NAMING DISCIPLINE IS THE MECHANISM (`naming`). The same concept must wear\n"
		"the same name everywhere, or it stops travelling. That is the real reason to care about\n"
		"names, more than readability.\n"
		"\n"
		"KEY: WHERE THE NAMES DIVERGED, NAME IS NOT ENOUGH AND THE TYPE DECIDES. A receiver may take\n"
		"its value from an ordered list of possible sources, and the choice among them is made BY THE\n"
		"TYPE OF THE VALUE - a general \"where the money is\" attribute becomes a till on one document\n"
		"and a bank account on another, read by asking what the value IS. This is exactly the seam\n"
		"where \"copy by name\" ends and a classification begins; recognising it early is cheaper than\n"
		"another pairwise rule.\n"
		"\n"
		"STOP: A FACT IS INHERITED; A DERIVATIVE OF A FACT IS RECOMPUTED. The list of what must NOT\n"
		"be copied is short and the same everywhere:\n"
		" THE EXCHANGE RATE - taken for the date of the NEW document, never carried from the old one.\n"
		" THE CURRENCY, when the document names a till or an account - it comes FROM THEM. \"The till\n"
		" is a euro till, so the document is in euro\" outranks inheritance.\n"
		" THE ACCOUNTING FLAGS - which books this document is reflected in come from the PERSON'S own\n"
		" defaults, and the statutory one only if that company keeps statutory books at all.\n"
		" THE DEAL, cleared explicitly: there is no sensible default for it.\n"
		" THE NUMBER, cleared whenever the company arrived along with it (`numbering`).\n"
		"Anything that depends on \"now\" or on \"who is typing\" is computed on the spot.\n"
		"\n"
		"KEY: TWO FILLINGS RUN, AND THE SECOND MUST NOT OVERWRITE THE FIRST. Filling from the source\n"
		"happens first, and then the form fills whatever is still empty with defaults. The way they\n"
		"are kept apart is not call order but an explicit LIST OF WHAT IS ALREADY DECIDED: the first\n"
		"pass records the names it filled, and the second removes those names before applying its\n"
		"defaults. This is the general answer to \"two roads to one state\" - not sequencing, but a\n"
		"record of what has been settled.\n"
		"* AND THE LIST IS DELIBERATELY SHORT - only the contested fields go in it. Marking\n"
		"everything makes the defaults dead code; marking nothing loses the source's values.\n"
		"\n"
		"KEY: CHANGING AN OWNER CLEARS A DEPENDENT VALUE ONLY WHEN IT HAS BECOME INADMISSIBLE. When\n"
		"the counterparty changes, do not blank the contract - ASK whether the contract already\n"
		"chosen is usable with the new counterparty and company, and keep it if it is. The contact\n"
		"changes only if it belonged to somebody else; the price type only if it belonged to the old\n"
		"party; and where clearing is unavoidable, SAY SO rather than doing it silently.\n"
		"* AND \"IS IT STILL ADMISSIBLE\" IS A NAMED FUNCTION, not a condition written at each place\n"
		"that changes an owner. There are half a dozen such places and they must all agree.") },

	{ wxT("traceability"),
	  ibMcpText("Tracking an individual thing: serial numbers, certificates, shelf life, issued items."),
	  ibMcpText("FOLLOWING ONE PARTICULAR THING, NOT A QUANTITY OF THEM.\n"
		"\n"
		"`stock-control` and `lot-accounting` answer \"how much is there\". This answers \"where is\n"
		"THIS one\" - and it is a different question with a different price, so the first thing to do\n"
		"is find out which one is being asked.\n"
		"\n"
		"KEY: THE QUESTION THAT DECIDES IT. \"If two of these are on the shelf, does anyone ever need\n"
		"to know WHICH of the two went out?\" A yes means individual identity; a no means a series or\n"
		"a lot is enough, and a lot is enormously cheaper (`lot-accounting`: the second design).\n"
		"Warranty, recall, an official register of equipment, anything with an owner - yes. Nuts,\n"
		"paint, flour - no, whatever the customer says at the start.\n"
		"\n"
		"KEY: A SERIAL NUMBER IS NOT A DIMENSION - IT IS A SECOND TABULAR SECTION. The identities are\n"
		"listed in a subordinate table of the document, tied to the goods line by an integer row key\n"
		"(`pricing`: rows are tied by a row key, never by the row number). NO REGISTER GAINS A\n"
		"DIMENSION. That is the whole design, and it is the right one: identity is enormously more\n"
		"numerous than quantity, and a balance keyed by identity is a balance with one row per\n"
		"object for ever.\n"
		"* THE PRICE, and it is paid in full: the link is ordinal rather than referential, so orphan\n"
		"rows have to be swept when lines are deleted, and every reader writes the join itself.\n"
		"* AND THE QUANTITY IS DERIVED FROM THE IDENTITIES, not typed - picking five serials makes\n"
		"the line five. Which also means the same identity can be entered twice in one document\n"
		"unless something checks, and nothing checks across documents at all: there is no place\n"
		"where a serial number has a LOCATION.\n"
		"STOP: AND ANYTHING THAT SPLITS A LINE MUST RE-KEY THE IDENTITIES UNDER IT - this is the half\n"
		"nobody plans for. Filling by available stock, splitting by lot, splitting by warehouse: each\n"
		"turns one line into two, and the subordinate rows still point at the original key. The rule\n"
		"has to be chosen and stated, because there is no right answer - the workable one is \"the tail\n"
		"moves\": allocate a new key, move the LAST n identity rows onto it, leave the rest.\n"
		"* AND THE ROUTINE MUST REFUSE TO RUN TWICE over the same line rather than guess. Called again\n"
		"on a line that already has a key, it cannot tell a legitimate second split from its own\n"
		"earlier work.\n"
		"* THE COST IS REAL AND WORTH SAYING TO THE CUSTOMER: which physical unit lands in which line\n"
		"is decided by the order somebody scanned them, not by anything about the goods.\n"
		"STOP: AND \"AS MANY IDENTITIES AS UNITS\" MUST BE A REFUSAL, NOT A MESSAGE. Where the check\n"
		"counts the identities against the quantity and only PRINTS the mismatch, five machines ship\n"
		"with three serial numbers and the document posts. Found exactly so in a working system: the\n"
		"check is correct, careful, normalises the quantity to the stock unit - and is wired to\n"
		"nothing (`posting`: a refusal is a flag plus a message).\n"
		"* AND CHANGING THE ITEM ON A LINE INVALIDATES ITS IDENTITIES BY CONSTRUCTION, since a serial\n"
		"belongs to one item. Do not silently unlink them - the person typed those in. Say what is\n"
		"about to be lost and let them stop (`entered-from`: clear a dependent value only when it has\n"
		"become inadmissible, and say so).\n"
		"\n"
		"* SO STATE THE LIMIT PLAINLY: this shape records WHICH ones went out on a document. It does\n"
		"not answer \"where is serial 4471 now\". That question needs a register keyed by identity,\n"
		"and its cost is the one above.\n"
		"\n"
		"KEY: WHERE A THING IS HELD BY A PERSON, POSSESSION IS A BALANCE. Items issued to somebody -\n"
		"workwear, tools, a laptop - are a register whose DIMENSION is the person, receipted by the\n"
		"issue and consumed by the return or the write-off. Not a status field on the item: a status\n"
		"cannot say how many are outstanding, and cannot be netted.\n"
		"* AND THE IDENTITY OF AN ISSUED THING IS A TUPLE WHOSE WIDTH IS A SETTING - item, variant,\n"
		"size, person, place, purpose, and one or two more switched on by flags or present only in\n"
		"the second set of books. The same physical jacket therefore has different granularity of\n"
		"identity in different books, which is legitimate and must be said out loud, because a\n"
		"write-off matches on that whole tuple: a field carried but NOT matched on is a silent\n"
		"mismatch (found live in the system examined - quality is carried, printed, and not matched).\n"
		"* THE CURE IS STRUCTURAL, NOT VIGILANCE: DECLARE THE KEY ONCE AND DERIVE EVERYTHING FROM IT.\n"
		"One list of key fields generates the ORDER BY of the cursor, the filter passed into the\n"
		"balance, and the comparison that detects \"a new key has begun\". Then a field cannot be\n"
		"carried, printed and reported without also being matched, because there is only one place\n"
		"that says what the key is.\n"
		"* AND IT MAKES THE WIDTH OF THE TUPLE A SETTING FOR FREE - add the transfer document when the\n"
		"customer wants two identical issues told apart, add the tax designation for the second set of\n"
		"books, and the three uses follow. The price is that the field names live as strings, so\n"
		"nothing checks them until the query runs; a mistyped name loses a whole dimension of the\n"
		"match, silently.\n"
		"\n"
		"KEY: A BARCODE RESOLVES TO A TUPLE, NOT TO A THING. Item plus unit plus variant plus lot\n"
		"plus quality - because a barcode labels a PACKAGE, not an object. It is a lookup key, and it\n"
		"must be allowed to be ambiguous: several codes for one item, one code reused across sizes.\n"
		"Treating a barcode as an identity is the mistake that makes returns unprocessable.\n"
		"\n"
		"KEY: SHELF LIFE IS AN ABSOLUTE DATE ON THE LOT, NOT A DURATION ON THE ITEM. \"Six months from\n"
		"production\" is how it is entered; what must be STORED is the date it expires, because the\n"
		"rule changes and the goods already in stock do not. Then \"what expires first\" is an ordering\n"
		"and \"what has expired\" is a comparison - both cheap. And somebody has to READ it: a stored\n"
		"expiry with no reader is the commonest form of a rule that was written down and never asked\n"
		"(`look-first`).\n"
		"\n"
		"STOP: PROVENANCE IS EITHER STORED OR IT DOES NOT EXIST. \"Which supplier did this lot come\n"
		"from\", \"when was it made\" - if the lot does not carry it, the only way back is scanning the\n"
		"documents that touched it, and that answer is not unique: a lot can be topped up from two\n"
		"deliveries. In the system examined this is done by a query taking the FIRST row it finds\n"
		"with no ordering at all, and one such routine falls off the end without returning anything.\n"
		"If provenance is promised, it is a stored attribute of the lot, set once when the lot is\n"
		"born.\n"
		"\n"
		"STOP: AND A LOOKUP SHAPED TO ITS ONLY CONSUMER STOPS BEING REUSABLE. Where \"was the\n"
		"certifying body accredited on that date\" returns a FORMATTED STRING for a printed form -\n"
		"and returns another string, in capitals, when there is no record - the classification is\n"
		"gone: nothing else can ask the question, and no report can count the cases. Return the\n"
		"record, or the verdict; let the print form do the formatting (`shapes`: hand back the kind,\n"
		"not a word for it).\n"
		"\n"
		"NOTE: A CERTIFICATE IS A DOCUMENT THAT MUST ACCOMPANY GOODS, so its absence has to be a\n"
		"REFUSAL at the moment of shipping, with the line and the item named (`posting`) - not a\n"
		"report somebody runs afterwards. And it is dated: a certificate valid at the time of\n"
		"shipping stays valid for that shipment even after it expires.\n"
		"\n"
		"KEY: AND THE TWO HALVES SIT AT DIFFERENT ALTITUDES: THE OBLIGATION IS A PROPERTY OF THE KIND\n"
		"OF THING, THE EVIDENCE IS A PROPERTY OF THE BATCH. Whether this item may travel without a\n"
		"certificate is a regulatory fact about the item and does not vary batch by batch; the\n"
		"certificate itself is issued for a production run, which is what a lot is. So the flags live\n"
		"on the item and the records in a register keyed by the lot, and the check joins them.\n"
		"* WHICH SETTLES A QUESTION PEOPLE ASK BACKWARDS: an individually identified unit CANNOT be\n"
		"certified. Identity and certification are on different granularities and never meet - the\n"
		"strongest true sentence is \"this unit came in a lot that is certified\".\n"
		"* AND THE REQUIREMENT USUALLY COMES IN MORE THAN ONE KIND - an external certificate and an\n"
		"internal one, each with its own flag and its own record - so build the pair, not the boolean.\n"
		"\n"
		"KEY: A VALIDITY WINDOW IS TWO DATES IN WHICH AN EMPTY ONE MEANS UNBOUNDED, AND THAT RULE HAS\n"
		"TO BE WRITTEN DOWN ONCE. Every test is then \"(from is empty or from is on or before the date)\n"
		"and (to is empty or to is on or after the date)\", and every site that omits half of it\n"
		"silently drops the open-ended records - which are usually the important ones.\n"
		"STOP: AND ORDERING BY EXPIRY NEEDS THE EMPTY DATE MAPPED TO A FAR-FUTURE SENTINEL, or the\n"
		"open-ended record sorts FIRST instead of last and the shortest-lived certificate wins. Where\n"
		"several records cover the same moment, say which one is chosen - latest ending, then latest\n"
		"starting - rather than taking the first row the engine returns.\n"
		"* THE COST IS THAT THE SENTINEL IS A LITERAL REPEATED IN EVERY QUERY THAT SORTS. Name it\n"
		"once.") },

	{ wxT("lot-accounting"),
	  ibMcpText("Lots and cost: one shared write-off, and cost resolved over a graph of movements."),
	  ibMcpText("LOT ACCOUNTING.\n"
		"\n"
		"STOP: FIRST DECIDE WHETHER YOU NEED LOTS AT ALL - there is a second design, and it is often\n"
		"the right one. Two ways to answer \"what did this cost\":\n"
		" KEEP THE LOTS. Every receipt is a lot, the write-off chooses which lots a quantity\n"
		" comes out of, and cost follows the individual lot. Necessary when the ANSWER has to\n"
		" name a source: FIFO required by the accounting policy, expiry dates, serial numbers,\n"
		" goods that are somebody else's, a return that must go back at the price it left at.\n"
		" KEEP QUANTITY AND AMOUNT ONLY. The register carries how much and how much it is worth;\n"
		" a write-off takes the AVERAGE - amount divided by quantity - and no lot is ever\n"
		" identified. \"Which delivery was this from\" becomes a question with no answer, and for\n"
		" most trading and manufacturing bases nobody ever asks it.\n"
		"\n"
		"* THE SECOND IS DRAMATICALLY CHEAPER, and not only in code: no lot dimension, no tree of\n"
		"lots to resolve per document, a fraction of the movements, and backdated entry costs a\n"
		"RECALCULATION rather than a re-selection of which lots each later document consumed. The\n"
		"whole apparatus below - the repayment loop, the shortage messages, the ordering - exists\n"
		"only in the first design.\n"
		"NOTE: Its own difficulty is real but smaller: the average is only final once the month's\n"
		"receipts are all in, so a figure shown during the month is provisional and the close\n"
		"restates it. That is the same provisional-figure problem as below, without the graph.\n"
		"\n"
		"NOTE: SO ASK, BEFORE ANYTHING: \"do you need to know which delivery a particular item came\n"
		"from?\" and \"does your policy say FIFO?\". Two questions, and they decide a month of work.\n"
		"Building lots because they sound more accurate, into a base that only ever reports\n"
		"averages, is the most expensive default in this whole corpus.\n"
		"\n"
		"WHAT FOLLOWS IS THE FIRST DESIGN.\n"
		"\n"
		"IT IS ONE MODULE, NOT A HABIT REPEATED IN EVERY DOCUMENT. The write-off - choosing which\n"
		"lots a quantity comes out of, in which order, at what cost - is written ONCE in a common\n"
		"module, and documents reach it from there (directly, or through a subscription so that\n"
		"posting any of them goes through the same code). Every document that implements its own\n"
		"write-off is another place where the rule can differ, and they will differ: the second\n"
		"one is written by copying the first and then quietly diverging.\n"
		"\n"
		"THE WRITE-OFF IS WHERE THE PENNIES APPEAR. Splitting a cost across the lots a quantity is\n"
		"taken from is exactly the distribution problem in `allocation` - read it before writing\n"
		"the arithmetic, and decide there whether the remainder is placed or absorbed.\n"
		"\n"
		"KEY: AND COST IS NOT KNOWN WHEN THE MOVEMENT HAPPENS. This is the part that surprises\n"
		"people: the actual cost of what left the warehouse today may depend on an invoice that\n"
		"arrives next week, on freight allocated afterwards, on a transfer that has not been\n"
		"priced yet. So the adjustment of actual cost is not a per-document calculation at all -\n"
		"it is resolved over the WHOLE CHAIN, afterwards.\n"
		"\n"
		"The shape to think in is a GRAPH. The vertices are the states goods pass through, the\n"
		"edges are the MOVEMENTS between them - receipt, transfer, assembly, return - and cost\n"
		"flows along that graph. A write-off (a sale, an issue) is a TERMINAL vertex: it is where\n"
		"the route ends, the culmination of everything upstream, and it is priced only once the\n"
		"route leading to it is priced.\n"
		"\n"
		"NOTE: THE CONSEQUENCES ARE PRACTICAL, and they decide the design:\n"
		" the ORDER of resolution matters, and it is the order of the graph, not of document\n"
		" numbers or of dates alone;\n"
		" a cycle in it (goods returned back up the chain, mutual transfers) is a real\n"
		" possibility and has to be recognised rather than looped over forever;\n"
		" the figures a document showed at posting time are PROVISIONAL, and something has to\n"
		" say so - to the user, and in the notes of whatever stores them.\n"
		"\n"
		"Building this per-document, at posting, produces numbers that look right on the day and\n"
		"are never right afterwards.\n"
		"\n"
		"KEY: AND A DOCUMENT ENTERED BACKDATED INVALIDATES EVERYTHING AFTER IT. A sale inserted into\n"
		"last month changes which lots every later sale consumed, and those documents are already\n"
		"posted with their own figures. Nothing about them looks wrong.\n"
		"\n"
		"So there has to be a BOUNDARY OF VALIDITY - the point up to which lot calculations are known\n"
		"good. Documents register themselves against it as they post; writing before the boundary\n"
		"moves it back, and everything after it is marked as needing to be re-posted. Then a person\n"
		"or a scheduled job restores it, in order, and the boundary walks forward again.\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM IS A SEQUENCE OBJECT - a declared boundary per key,\n"
		"moved by the posting and restorable on demand. CHECK WHETHER THIS BASE HAS ONE before\n"
		"designing around it, and say the answer: where there is none, build it as an information\n"
		"register holding the boundary per key (organisation, and whatever else the cost is computed\n"
		"within), written by the posting, plus a scheduled job that re-posts what lies beyond it.\n"
		"Saying which of the two you are in matters more than the design - a pattern read as though\n"
		"the mechanism were there sends somebody looking for a checkbox that is not.\n"
		"NOTE: WITHOUT ONE, backdated entry silently corrupts cost - and it is not detectable\n"
		"afterwards, because every document individually is consistent with what it saw when it was\n"
		"posted. This is the mechanism people mean when they say the base \"has to be re-posted in\n"
		"sequence\", and it is worth building before the first backdated document rather than after.\n"
		"\n"
		"KEY: AND THE WRITE-OFF ITSELF IS A REPAYMENT LOOP, which is worth writing down because every\n"
		"implementation rediscovers it:\n"
		" A QUANTITY STILL TO SETTLE starts at what the line asks for and goes down lot by lot,\n"
		" in the order the policy dictates. The loop ends when it reaches zero - or when the lots\n"
		" run out, which is the interesting case.\n"
		" THERE ARE TWO COEFFICIENTS, NOT ONE, AND THEY POINT IN OPPOSITE DIRECTIONS. The first is\n"
		" the share OF THE LOT being consumed, and everything attached to the lot - cost, currency\n"
		" amount, the debt behind a return to a supplier - is carried out of it in that proportion.\n"
		" The second is the share OF THE DOCUMENT LINE that this lot closes, and it distributes the\n"
		" line's own figures across the lots that answer it. One proportion moves money out of the\n"
		" lot; the other spreads the line over lots. Using one where the other belongs is the\n"
		" classic penny defect here, and it only shows on lines answered by more than one lot.\n"
		" WITHIN EACH DIRECTION IT IS ONE COEFFICIENT APPLIED TO EVERY AMOUNT, which is what keeps\n"
		" quantity and money in step; computing each amount separately is how they drift apart.\n"
		" THE LOTS ARE READ ONCE FOR THE WHOLE DOCUMENT, into a structure the lines then draw\n"
		" from - not a query per line. A document with two hundred lines otherwise asks two\n"
		" hundred times for overlapping answers.\n"
		" AND THAT STRUCTURE IS DECREMENTED AS IT GOES. Each line reduces the lots it consumed, in\n"
		" memory, before the next line reads them - otherwise line two is offered a lot that line\n"
		" one has already emptied, and the document writes more than it had.\n"
		" THE DISTRIBUTION IS DECIDED BEFORE THE MOVEMENTS ARE WRITTEN, not while writing them:\n"
		" which lots answer which line is worked out first, and the loop that writes only records\n"
		" the decision. Two jobs in one loop is why this code is usually unreadable.\n"
		" RUNNING OUT IS A MESSAGE, NOT AN EXCEPTION - naming the line, the item and how much\n"
		" could not be settled. \"Not enough lots\" as a bare refusal leaves a person to find which\n"
		" of two hundred lines caused it. And taking a NAMED lot partially is its own message:\n"
		" the person asked for that lot specifically, and got some of it.\n"
		"\n"
		"WHERE IT COMES FROM AND WHERE IT GOES IS A TABLE, NOT A CHAIN OF IFS. Each kind of\n"
		"operation - sale, transfer, write-off to costs, return to supplier, transfer to a\n"
		"commission agent - names the register it takes from and the one it puts into. Kept as data\n"
		"keyed by the operation, a new kind is a row; written as branches inside each document, it\n"
		"is a change in every one of them.\n"
		"\n"
		"KEY: A RETURN HAS TO GO BACK INTO THE LOT IT CAME OUT OF, and nothing in the return document\n"
		"says which one that was. A retail sale names an item and a quantity; the lot it consumed is\n"
		"buried in the movements. Returning it at today's cost quietly changes the margin of a sale\n"
		"that already happened.\n"
		"* THE ANSWER IS A HELPER REGISTER WRITTEN AS THINGS ARE WRITTEN OFF - item, characteristic,\n"
		"series, warehouse, quantity, operation kind, and the DOCUMENT that did it. A return then\n"
		"looks backwards through it for the most recent sale of the same thing, from the same\n"
		"warehouse, of at least this quantity, and takes its lots and its cost.\n"
		"NOTE: It is an index, not a truth: it duplicates what the movements already imply, and it\n"
		"exists because the movements cannot be asked that question cheaply. Write it in the same\n"
		"posting that writes the movements - a helper filled by a separate pass is a helper that\n"
		"will one day disagree with what it indexes.\n"
		"\n"
		"NOTE: AND THE POLICY IS NOT A CONSTANT. Valuation method, whether lots are kept per warehouse,\n"
		"whether empty series may be written off - these are per ORGANISATION and true AS OF A DATE\n"
		"(`shapes`: an information register with periodicity). Read them for the moment being\n"
		"posted, not for today: re-posting last year's document must use last year's policy.\n"
		"* AND THE POLICY HOLDS FOR A WHOLE MONTH, so it is read AS OF THE END OF THE MONTH the\n"
		"document falls in - not as of the document's own second. Otherwise two documents of the\n"
		"same month, either side of the day somebody changed the setting, post under different\n"
		"rules and their figures cannot be reconciled with each other.\n"
		"* It is also asked for on every line of every document, so it is worth CACHING for the\n"
		"call: the same organisation and month answer the same thing, and the reading is a query.\n"
		"* A related habit: what a thing IS can often be read from the account it sits on - goods\n"
		"held on commission against goods owned outright. One fact, kept once, rather than a flag\n"
		"beside it that can disagree.") },

	{ wxT("sequences"),
	  ibMcpText("The boundary of what is still true, once a document can be entered backdated."),
	  ibMcpText("A BACKDATED DOCUMENT INVALIDATES EVERYTHING AFTER IT - THE BOUNDARY SAYS HOW MUCH.\n"
		"\n"
		"`lot-accounting` says a boundary of validity is needed and that this platform has no\n"
		"ready-made object for it. This is what one is made of, counted off a system that has nine\n"
		"of them.\n"
		"\n"
		"KEY: THE BOUNDARY IS A FUNCTION OF DIMENSIONS, NOT A POINT. It is kept per combination of\n"
		"whatever the sequence is keyed by - lots by organisation, materials by department, staff\n"
		"orders by (person, organisation). A document entered late does not invalidate \"everything\n"
		"after it\", it invalidates everything after it IN ITS OWN SLICE: an order concerning one\n"
		"employee does not spoil the others.\n"
		"* AND THE DIMENSION MAY COME FROM A TABULAR SECTION - one staff order naming thirty people\n"
		"registers thirty times and moves thirty boundaries. THE GRANULARITY OF INVALIDATION IS THE\n"
		"CHOICE OF DIMENSIONS, and it is the whole design decision: too coarse and every document\n"
		"stops the world, too fine and the registration table outgrows the data.\n"
		"\n"
		"KEY: FORWARD ONLY IF NOTHING IS LEFT BEHIND; BACKWARD UNCONDITIONALLY. Two operations, and\n"
		"they are not symmetric.\n"
		" FORWARD is allowed only when there is no document of this sequence between the current\n"
		" boundary and the one being posted - one \"first 1\" query that must come back empty. Post a\n"
		" document while an earlier one is still unposted and the boundary simply stays where it was.\n"
		" BACKWARD happens the moment a document is posted before the boundary: the boundary is put\n"
		" on it. No condition, no question.\n"
		"STOP: AND IF THE DOCUMENT MOVED FORWARD IN TIME, THE BOUNDARY GOES TO WHERE IT LEFT, not to\n"
		"where it landed. What was spoiled is the place it was taken OUT of. The same holds when its\n"
		"organisation changes: the old slice is the damaged one. Getting this backwards is silent -\n"
		"the figures stay wrong and nothing reports it.\n"
		"\n"
		"RESTORING IS A WALK, NOT AN ALGORITHM. Select the recorders strictly after the boundary's\n"
		"(period, recorder) pair, order by that same pair, take a batch, re-post it, move the\n"
		"boundary behind you. THE REGISTRATION TABLE IS THE PLAN OF WORK AND THE BOUNDARY IS THE\n"
		"CURSOR IN IT - which is why restoring can be done for a range of dates and a list of\n"
		"organisations rather than all at once, and why it survives being interrupted.\n"
		"\n"
		"KEY: A BOOLEAN DIMENSION SEPARATES WHAT IS STILL TO DO FROM WHAT IS DONE, INSIDE ONE TABLE.\n"
		"Give the sequence a dimension meaning CALCULATED IN ORDER: every check and every boundary\n"
		"read carries it set to false, and a document flips its own row to true once it has been\n"
		"calculated properly. The plan of work and the finished work then live in the same\n"
		"registration table and are told apart by one bit - no second table, no deleting rows to mark\n"
		"progress, and what remains to be done is a query rather than the difference between two\n"
		"sets.\n"
		"* AND CANCELLING A POSTING DELETES THE ROW OUTRIGHT: a document that is not posted is not in\n"
		"the sequence at all, so it neither holds the boundary back nor asks to be recalculated\n"
		"later.\n"
		"NOTE: THE MOMENT IS A PAIR, NOT A DATE - (period, recorder). Ordering by date alone puts\n"
		"documents of the same second in an arbitrary order, and a re-post in the wrong order inside\n"
		"one second produces different numbers each run.\n"
		"\n"
		"KEY: TWO CLASSES, AND CHOOSING BETWEEN THEM IS CHOOSING A COMPUTATION MODEL.\n"
		" THE ENGINE MOVES THE BOUNDARY at every posting - right when the calculation behind it is\n"
		" cheap (staff records, items in use). The sequence runs in the background and nobody sees it.\n"
		" THE CODE MOVES IT, and only in the online mode or from the restore tool - right when the\n"
		" calculation is heavy (lot costing, settlements). The boundary is then the INTERFACE BETWEEN\n"
		" \"compute now\" and \"compute in a batch\", and switching modes changes nothing except who\n"
		" moves the cursor.\n"
		"\n"
		"STOP: THE MONTH-END DOCUMENTS MUST BE EXCLUDED FROM THE CHECK, or they block themselves. A\n"
		"cost calculation, a revaluation, a production report stand in the LAST SECOND of the period\n"
		"by design; ask \"is there anything after this document\" without excluding them and the\n"
		"regulated close reports its own output as a violation.\n"
		"\n"
		"NOTE: ONE SEQUENCE PER SET OF BOOKS. Lots managerial, lots statutory and lots for materials\n"
		"are separate sequences with separate boundaries - the managerial figures can be current\n"
		"while the statutory ones are three months stale, and that is a legitimate state to report,\n"
		"not a defect to reconcile.\n"
		"\n"
		"NOTE: AND A BOUNDARY IS NEVER TRANSFERRED BETWEEN BASES. It is a local derivative of the\n"
		"state of one base's calculations. What travels is the documents; the receiving base re-posts\n"
		"them and derives its own boundary (`data-exchange`).\n"
		"\n"
		"KEY: BEFORE BUILDING ONE, ASK WHETHER THE CALCULATION NEEDS ORDER AT ALL. A boundary exists\n"
		"because cost is WALKED in document order. Where cost is instead SOLVED - every combination\n"
		"of keys a node, the whole month one system of equations settled by iteration - order stops\n"
		"meaning anything and sequences disappear entirely. Measured in a system carrying both\n"
		"models: five sequences serve the walked one, and the solved one has none.\n"
		"* AND THE DECIDING CASE IS MUTUAL CONSUMPTION: two departments serving each other inside one\n"
		"month have NO answer in document order, whichever order is chosen. A walk can only break the\n"
		"cycle by a rule, and then the figure is stable but arbitrary. If that case is real for this\n"
		"customer, the sequence machinery is not what is missing.\n"
		"* WHAT THE SOLVED SIDE COSTS: it is a MONTHLY, batch answer with no meaningful \"as of\n"
		"today\", and it needs its tolerance, its iteration cap and its acceptable deviation to be\n"
		"settings a person can see rather than constants.") },

	{ wxT("orders"),
	  ibMcpText("An order as a live obligation: both directions, closing it, changing it, where its state lives."),
	  ibMcpText("AN ORDER IS AN OBLIGATION THAT STAYS OPEN UNTIL SOMETHING CLOSES IT.\n"
		"\n"
		"KEY: AND THERE ARE TWO OF THEM, WHICH ARE ONE MECHANISM MIRRORED. An order FROM a customer\n"
		"and an order TO a supplier are not two subsystems to be built twice. Everything in this\n"
		"entry - state as a balance, closing by mirror movement, amendment by a separate document,\n"
		"manual allocation before automatic - is identical in both directions. Learn one and you have\n"
		"the other, and the differences are a short, closed list:\n"
		" WHOSE OBLIGATION IT IS: theirs to pay and ours to deliver, or ours to pay and theirs to\n"
		" deliver. This flips which side of `settlements` it feeds and which account an advance\n"
		" sits on - an advance given and an advance received are the same arithmetic at two\n"
		" addresses.\n"
		" WHAT IT DOES TO STOCK: a customer order RESERVES what we already hold; a supplier order\n"
		" INCREASES what is expected. Two registers, opposite in sign and in meaning - \"held back\n"
		" from the free balance\" against \"not here yet but promised\" (`stock-control`).\n"
		" WHICH PRICE LIST IT READS: our selling prices, or the prices agreed with that supplier.\n"
		" Same mechanism, different owner of the price type (`pricing`).\n"
		" WHAT LIMITS IT: a credit limit and prepayment terms on the way out, a budget or an\n"
		" approval on the way in (`cash-flow`, `orders` approval above).\n"
		"* AND THE TWO ARE JOINED BY PLACEMENT - the record saying which source will cover which\n"
		"demand: this line of the customer's order out of stock, that line out of a supplier order\n"
		"not yet arrived. Placement is the bridge between the mirrors and it is a register of its\n"
		"own, not a computation (`planning`).\n"
		"* SO WHEN SOMEBODY DESCRIBES ONE DIRECTION, DERIVE THE OTHER AND ASK ABOUT THE FOUR\n"
		"DIFFERENCES, rather than waiting to be told the second half. It is the same move as\n"
		"`unfamiliar-domain`, one floor down: the shape is known, only the direction is new.\n"
		"* AND EXPRESS THE MIRROR BY DIRECTION, NOT BY DUPLICATION. Two copies of a mechanism that\n"
		"are meant to stay each other's reflection diverge at the first amendment (`settlements`:\n"
		"the side is a truth table, and the field is addressed by a suffix).\n"
		"\n"
		"KEY: ITS STATE IS NOT A FIELD - IT IS WHAT IS LEFT IN THE REGISTERS. \"Open\", \"partly\n"
		"shipped\", \"closed\" are readings of balances: what was ordered less what was delivered, what\n"
		"is reserved against it, what is placed with a supplier for it. A status attribute beside\n"
		"those balances is a second truth that will disagree with them within a month - usually as\n"
		"\"the order says closed and the reservation is still holding stock\".\n"
		"\n"
		"KEY: SO CLOSING AN ORDER IS A MIRROR MOVEMENT IN EVERY REGISTER WHERE IT IS STILL ALIVE, not\n"
		"a flag. The closing document reads the remaining balances - the order itself, the placement\n"
		"against supply, the reservation, the settlement - and writes them back with the opposite\n"
		"sign. Afterwards nothing is left, and \"closed\" is simply true.\n"
		"* WHAT IT BUYS: undoing the closure is unposting it, and there is no state to repair.\n"
		"* WHAT IT COSTS: the closing must know the COMPLETE list of registers the order takes part\n"
		"in. Miss one and the order is half closed - visible only in a report, months later. When a\n"
		"register is added to the order's life, this document is the second place to change, and\n"
		"nothing will remind you.\n"
		"KEY: AND ONLY GOOD OUTPUT DISCHARGES AN ORDER. Filter what was produced BEFORE the order\n"
		"balance is reduced: rows of any quality but \"new\", rows naming no order, and rows naming an\n"
		"order of another kind close nothing - what was scrapped is still owed. Decide services\n"
		"deliberately, since quality has no meaning there and the filter must not touch them.\n"
		"* THE MIRROR RULE IS IN `planning` - consumption beyond the requirement is reported and\n"
		"posted, output short of it stays outstanding. An order discharged by scrap looks right on the\n"
		"day and produces a shortage nobody can account for a month later.\n"
		"\n"
		"NOTE: THE REASON FOR CLOSING BELONGS TO WHOEVER CLOSED IT FIRST. Keep it in its own small\n"
		"register keyed by the order, and when a second closing meets an existing reason, LEAVE IT\n"
		"and say so. The second closing is usually technical - clearing a remainder - and would\n"
		"overwrite the real reason with \"routine\". The cost is that a wrongly entered reason can only\n"
		"be corrected by unposting the first document, which is the right trade for a figure that\n"
		"feeds a report on why deals are lost.\n"
		"\n"
		"KEY: AN ORDER IS NOT EDITED - IT IS AMENDED BY ANOTHER DOCUMENT. \"The customer changed their\n"
		"mind\" produces an amendment, and the CURRENT terms are the latest of (the order, its\n"
		"amendments), posted, as of a date. Editing the original instead destroys the answer to \"what\n"
		"did we actually agree, and when did it change\", which is the question asked in every dispute.\n"
		"* AND THE READER MUST BE TOLD WHICH KIND OF DOCUMENT IT GOT BACK, not only its reference:\n"
		"the terms of an amendment and of an original are used differently.\n"
		"* ORDER BY THE MOMENT, NOT BY THE DATE. Two amendments on one day, ordered by date alone,\n"
		"come back in an arbitrary order - and the answer to \"what was agreed\" flips between runs.\n"
		"\n"
		"KEY: A PERSON'S MANUAL ALLOCATION IS ALREADY SPENT BEFORE THE AUTOMATIC ONE RUNS. Where\n"
		"lines carry their own placement or reservation typed in by hand, SUBTRACT those quantities\n"
		"from the free pool FIRST, and only then let the automatic distribution work on the\n"
		"remainder. The other order double-books: the machine gives away what the person had already\n"
		"claimed. The same sequencing applies to offsetting advances - hand-entered rows first, the\n"
		"leftover afterwards. Manual intent is a completed decision, not a preference.\n"
		"\n"
		"KEY: WHETHER THE ORDER COLUMN EXISTS AT ALL IS A THREE-VALUED ANSWER, AND IT IS COMPUTED:\n"
		"absent / present / present and mandatory. It is derived from the mode the base is configured\n"
		"in, the kind of operation, and how settlement is kept under this contract - and where\n"
		"settlement is by invoice, the column disappears entirely because the deal lives in the\n"
		"header.\n"
		"* ONE FUNCTION MUST ANSWER IT FOR BOTH THE FORM AND THE POSTING. The form asks it for\n"
		"visibility, the posting asks it for \"is this required\" - two implementations mean a document\n"
		"that hides a field and then refuses to post without it.\n"
		"* AND SINCE THE ANSWER DEPENDS ON THE CONTRACT, CHANGING THE CONTRACT MUST RE-ASK IT AND\n"
		"CLEAR WHAT IS NO LONGER ADMISSIBLE (`entered-from`).\n"
		"\n"
		"NOTE: APPROVAL IS THREE SEPARATE DECISIONS, AND THEY ARE OFTEN CONFLATED.\n"
		" WHAT STATE IS THIS ONE IN - a register keyed by the document: level, stage, person, state.\n"
		" A single attribute cannot hold four things.\n"
		" IS APPROVAL IN FORCE AT ALL - a periodic register per company, read AS OF THE DOCUMENT'S\n"
		" DATE, so switching the control on does not retrospectively invalidate last year's papers.\n"
		" MAY THIS PERSON EDIT IT NOW - decided by comparing the document's stage with the routes\n"
		" this person sits on, BY HIERARCHY: someone senior may amend what is still circulating\n"
		" below them.\n"
		"* AND THE CHECK THAT PAYMENT IS ALLOWED HANGS ON THE WRITE EVENT, not inside each paying\n"
		"document (`cross-cutting-hooks`).\n"
		"\n"
		"NOTE: FILLING A DOCUMENT FROM AN ORDER READS THE ORDER'S REMAINING BALANCE, NOT ITS LINES.\n"
		"Then the second delivery against the same order offers only what is left, with no counter\n"
		"and no \"partly done\" status anywhere. And when the reading comes back empty, DISTINGUISH THE\n"
		"TWO CASES in the message - the order is fully covered, or the order was never posted. They\n"
		"look identical and mean opposite things (`entered-from`).") },

	{ wxT("settlements"),
	  ibMcpText("Settlements with counterparties: contracts, and which currency the balance is in."),
	  ibMcpText("MUTUAL SETTLEMENTS.\n"
		"\n"
		"THE TWO LEVELS, and it is worth knowing which one is being asked for.\n"
		" By COUNTERPARTY alone - one running balance per partner. The primitive level: it\n"
		" works, and it cannot answer \"which of the two agreements is this against\".\n"
		" By CONTRACT, which is what people usually mean. A Contracts catalogue whose OWNER is\n"
		" the counterparty - subordinate to it, so a contract cannot exist without one and the\n"
		" choice lists are narrowed by construction. The contract carries its period of\n"
		" validity and its CURRENCY.\n"
		"\n"
		"THE CONTRACT'S CURRENCY DECIDES THE BEHAVIOUR, which is why it belongs to the contract\n"
		"and not to the document. Settlements are then kept in a register whose dimensions include\n"
		"the counterparty, the contract, and the SETTLEMENT CURRENCY - the contract's, the one the\n"
		"debt is actually owed in.\n"
		"\n"
		"AND THE AMOUNT IS USUALLY MORE THAN ONE NUMBER. The same debt is looked at in the\n"
		"settlement currency (what is owed), and in whatever currency the books are kept in -\n"
		"management, regulated, both. Where those are genuinely separate kinds of accounting they\n"
		"are separate resources on the register, converted at the document's own frozen rate (see\n"
		"`currency`).\n"
		"\n"
		"* AND WHEN THE KINDS ARE NOT YET SEPARATED, carry them all from the start anyway. Adding\n"
		"a second amount later means revisiting every posting, every report and every balance ever\n"
		"computed - while an unused resource costs a column. This is one of the few places where\n"
		"building for a distinction nobody has asked for yet is the cheaper mistake.\n"
		"\n"
		"NOTE: THE CURRENCY IS NOT DERIVABLE LATER. A balance in a register with no currency dimension\n"
		"cannot be told apart afterwards - the numbers are already added together. If there is any\n"
		"chance of a second currency, the dimension goes in now.\n"
		"\n"
		"KEY: OFFSETTING AN ADVANCE IS THE MECHANISM AT THE HEART OF ALL THIS, and it has one shape:\n"
		" 1. EVERY PAYMENT IS SPLIT IN TWO - what it CLOSES of an existing debt, and what is left\n"
		" over, which becomes an ADVANCE. Never one or the other by assumption: a payment of a\n"
		" hundred against a debt of sixty is sixty settled and forty prepaid, and both halves\n"
		" have to be written.\n"
		" 2. DEBTS ARE CLOSED OLDEST FIRST unless somebody says otherwise - FIFO over the\n"
		" outstanding documents. \"Otherwise\" is a person picking the documents by hand, and that\n"
		" screen is worth having: it is how disputes get settled.\n"
		" 3. AN ADVANCE IS KEPT APART FROM A DEBT - money owed TO you and money held FOR you are\n"
		" opposite things, and netting them into one balance hides both.\n"
		" * HOW they are kept apart differs by contour, and this is worth knowing before\n"
		" designing either. IN THE LEDGER an advance sits on a DIFFERENT ACCOUNT, so the offset\n"
		" is a transfer between two accounts and that is what an accountant will look for. IN THE\n"
		" OPERATIONAL REGISTERS there is no second account - the advance is an ordinary row whose\n"
		" settlement-document key is THE PAYMENT ITSELF, standing in for the debt it has not yet\n"
		" been matched to. \"Not yet allocated\" is expressed by that key, not by a status field.\n"
		"\n"
		"STOP: AND THE KEY THE DEBT IS SEARCHED BY IS A SETTING OF THE AGREEMENT, not a constant of the\n"
		"system: settled as a whole, per order, per invoice, or per individual settlement document.\n"
		"Same code, four levels of detail, and the level is read from the agreement. Hard-coding the\n"
		"finest one looks safest and is not - it demands that every payment name an order, which\n"
		"nobody does when the agreement is settled as a whole.\n"
		"\n"
		"NOTE: A RETURN IS NOT A NEGATIVE SALE HERE EITHER. It moves the debt the other way and has its\n"
		"own operation kind; writing it as a minus makes turnover reports understate both sides.\n"
		"* AND WHICH SIDE A DOCUMENT IS ON IS NOT ITS KIND - IT IS A TRUTH TABLE: outgoing and not a\n"
		"return, or incoming and a return, means the purchasing side; the mirror means the selling\n"
		"side. That single expression picks the register, the operation kind and the admissible sorts\n"
		"of contract. Deriving it from the document type instead is how a return ends up counted as a\n"
		"purchase.\n"
		"* AND THE MIRROR SYMMETRY IS BEST EXPRESSED BY ADDRESSING THE FIELD, NOT BY A SECOND BRANCH:\n"
		"take a suffix from the direction and build the field name from it, so one piece of code\n"
		"writes both sides. Two branches that must stay each other's mirror image drift apart at the\n"
		"first amendment.\n"
		"\n"
		"NOTE: AND IN A FOREIGN CURRENCY THE OFFSET ITSELF CREATES AN EXCHANGE DIFFERENCE: the advance\n"
		"came in at one rate, the debt arose at another, and closing one against the other realises\n"
		"the gap. It is computed at the moment of offset, distributed over the lines being closed,\n"
		"and it is the reason a settlement in currency is not the same routine with a rate applied\n"
		"at the end.\n"
		"\n"
		"KEY: AND THE EXCHANGE DIFFERENCE IS A DIFFERENCE OF TWO PROPORTIONS, NOT A MULTIPLICATION BY\n"
		"A RATE. Work out the covered share IN THE FOREIGN CURRENCY first - the lesser of the debt\n"
		"and the payment. Then take THAT SHARE of the debt's own local amount, and the SAME SHARE of\n"
		"the payment's local amount. The gap between the two is the difference.\n"
		"* WHY IT MUST BE A SHARE OF THE REMAINING AMOUNT rather than the foreign figure times a\n"
		"rate: the last settlement then takes the whole remaining local tail and the pennies close\n"
		"exactly. Multiplying by a rate again leaves a residue that belongs to nothing, and somebody\n"
		"writes it off by hand every month.\n"
		"* BOTH REMAINDERS - FOREIGN AND LOCAL - LIVE IN ONE ROW AND FALL TOGETHER. Keeping them in\n"
		"two places is how they stop agreeing.\n"
		"\n"
		"STOP: A THIRD CURRENCY IS NOT REPRESENTABLE, AND THE HONEST ANSWER IS A REFUSAL. An entry\n"
		"carries exactly two money slots - the amount in the currency of account and the foreign\n"
		"amount - so a document in euro against a dollar contract has nowhere to put the third\n"
		"figure. A working system REFUSES to post such a document in the statutory books (while the\n"
		"operational side still lives). Inventing a conversion is worse than refusing: it produces\n"
		"figures nobody can reconcile to either currency.\n"
		"* THE NEIGHBOURING LIMIT COMES FROM THE SAME PLACE: in currency settlements kept per order,\n"
		"a document naming SEVERAL orders is refused - the exchange difference has to be attributed\n"
		"to one deal.\n"
		"\n"
		"KEY: OFFSETTING ONLY EXISTS BECAUSE THE ADDRESSES DIFFER. Where the advance sits on the same\n"
		"account as the debt, or no advance account is set, the offset is zero and no entry is made -\n"
		"correctly, because on one account the balance nets itself. So \"has the advance been offset\"\n"
		"is a meaningful question exactly in those configurations where the two addresses are kept\n"
		"apart, and it is meaningless in the others. Ask which one you are in before promising the\n"
		"report.\n"
		"\n"
		"KEY: EVERY LINE OF AN OFFSET HAS TWO CEILINGS AND THE LESSER WINS - how much is still owed\n"
		"on THAT settlement document, and how much of THIS payment is still unallocated to THAT\n"
		"deal. The second must be counted per deal: otherwise a payment covering two orders lets the\n"
		"first order eat the second one's allowance.\n"
		"* AND WHAT IS LEFT OVER BECOMES ITS OWN SETTLEMENT DOCUMENT - a row whose key is the payment\n"
		"ITSELF. That is all an advance is at the operational level: not a state, not a separate\n"
		"register, but a row standing in its own name until something matches it. A negative leftover\n"
		"means more prepayment was named than the document holds, and that is a refusal.\n"
		"\n"
		"STOP: A DOCUMENT CANNOT RE-READ BALANCES IT IS ITSELF PART OF. Refilling the offset of a\n"
		"POSTED document doubles it, because the balances it reads already contain its own movements.\n"
		"The rule is general and worth stating once: TO RECOMPUTE FROM BALANCES, FIRST REMOVE\n"
		"YOURSELF FROM THEM - unpost, or subtract your own movements explicitly. It applies to stock\n"
		"selection lists and free-balance checks just as much.\n"
		"\n"
		"KEY: THE KEY THAT DECIDES WHETHER TWO ROWS ARE THE SAME ROW IS BUILT FROM THE AGREEMENT'S\n"
		"SETTINGS - the contract always, the deal only if settlement is kept per deal, the settlement\n"
		"document only if it is kept per document. And THE SAME SET OF FIELDS must be used in all\n"
		"three places it appears: finding a row in the table, collapsing the table, and filtering the\n"
		"register. Let them diverge in one place and the collapse merges what the register keeps\n"
		"apart - the total stays right and the breakdown is wrong, which is the hardest kind to see.\n"
		"\n"
		"STOP: A COMPOSITE DIMENSION HAS AS MANY EMPTY VALUES AS IT HAS TYPES, AND THE REGISTER NEEDS\n"
		"ONE. The empty reference of each possible type is a DIFFERENT value, so a debt written with\n"
		"one emptiness is not found by a payment looking for another. Normalise before comparing:\n"
		"take the list of possible types FROM THE DIMENSION'S OWN METADATA, and map every one of\n"
		"those empties to a single value in the query. Without it, balances silently fail to meet -\n"
		"the symptom is \"the debt did not close, though both figures are right there\".\n"
		"\n"
		"NOTE: THREE DIFFERENT CREDIT CONTROLS ARE ASKED FOR IN THE SAME BREATH AND NEED THREE\n"
		"DIFFERENT READINGS. A limit on the amount owed reads the BALANCE. A required percentage of\n"
		"prepayment reads the TURNOVERS, both sides separately - a balance has already netted them\n"
		"and the percentage cannot be recovered from it. And \"owing for more than N days\" is the\n"
		"MINIMUM DATE among unpaid settlement documents, which is answerable only where settlement is\n"
		"kept per document. Ageing a debt is not a property of the debt; it is that minimum, and\n"
		"without the document level the question has no answer at all.\n"
		"* AND THE CONTROLS ARE SWITCHED OFF FOR INCOMING PAYMENTS AND RETURNS. A rule that refuses\n"
		"the payment which would clear the debt is worse than no rule.\n"
		"\n"
		"KEY: A REAL FORK WITH A PRICE - OFFSET THE ADVANCE WHEN POSTING, OR AT THE CLOSE. It is a\n"
		"dated setting per company, and it switches two implementations of ONE operation.\n"
		" WHEN POSTING: the document reads the advance balance, splits its amount into \"offsets an\n"
		" advance\" and \"creates a debt\", and writes the offset then and there. The books are right\n"
		" all month. It costs a read of the account state per document, and any backdated entry\n"
		" invalidates the boundary and drags a re-post behind it (`sequences`).\n"
		" AT THE CLOSE: the document only records the fact and leaves; a scheduled operation does\n"
		" the offsetting. Entry is cheap and fast. It costs the month: until the close, reports show\n"
		" the debt and the advance GROSS, unoffset, and somebody will call that a bug.\n"
		"STOP: AND THE CHEAP OPTION IS FORBIDDEN IN FOREIGN CURRENCY. The exchange difference is born\n"
		"AT THE MOMENT OF OFFSET, so deferring the offset computes it at a different rate. This is\n"
		"the shape of an honest fork: not \"which is better\" but \"here is the border where one of them\n"
		"stops being allowed\".\n"
		"\n"
		"NOTE: ONE FIELD CAN NEED DIFFERENT FILL RULES PER CONSUMER. The same deal reference is\n"
		"written always for one register (or the prepayment percentage cannot be checked), only under\n"
		"a certain settlement mode for another, and never for a third. If such a function becomes\n"
		"necessary, take it as a signal: THE DIMENSION IS SERVING SEVERAL DIFFERENT QUESTIONS, and\n"
		"the honest fix may be to separate them rather than to keep the rules.\n"
		"\n"
		"NOTE: A DUE DATE DERIVED FROM THE CONTRACT STOPS BEING DERIVED THE MOMENT A PERSON EDITS IT.\n"
		"When the document date or the contract changes, ASK before recomputing it - the figure may\n"
		"have been agreed with the customer by telephone, and overwriting it silently breaks a\n"
		"promise the system knows nothing about. General form: a computed field that a person is\n"
		"allowed to override must ask, not decide.") },

	{ wxT("currency"),
	  ibMcpText("Currencies, rates with multiplicity, and why a document keeps its own copy."),
	  ibMcpText("KEEPING ACCOUNTS IN MORE THAN ONE CURRENCY.\n"
		"\n"
		"THE SHAPE. A catalogue of Currencies, and beside it the rates: an InformationRegister with\n"
		"`Periodicity` = Day, the currency as its dimension, and TWO resources - the rate and the\n"
		"MULTIPLICITY. (Periodicity is what makes this an information register rather than an\n"
		"accumulation one: a rate is a value that was true for a stretch of time, which is the\n"
		"definition in `shapes`.)\n"
		"\n"
		"MULTIPLICITY IS NOT OPTIONAL. Some currencies are quoted per 10, per 100, per 1000 units,\n"
		"and a rate on its own is then simply wrong by two orders of magnitude - not visibly, just\n"
		"wrong. The pair is what converts: amount * rate / multiplicity. Store both from the start,\n"
		"even where every rate is currently quoted per one; adding it later means revisiting every\n"
		"line of arithmetic that was written without it.\n"
		"\n"
		"* THE DOCUMENT KEEPS ITS OWN COPY. Give documents their own Rate and Multiplicity\n"
		"attributes, filled from the register at the moment the document is made, and do the\n"
		"document's arithmetic from THOSE - not from the register.\n"
		"\n"
		"The reason is that a document must not change behind the person who signed it. Read the\n"
		"rate live and re-opening last quarter's invoice re-prices it at today's rate: the printed\n"
		"paper and the screen disagree, and nothing is broken anywhere to point at. With the rate\n"
		"copied in, the document is a record of what was agreed - and the copy can be EDITED,\n"
		"which is what people mean by a management rate: this deal was done at this rate, whatever\n"
		"the bank said that morning.\n"
		"\n"
		"This is the legitimate exception in `showing-a-value` in its purest form: not a duplicate\n"
		"of a current fact, but a fact of its own with its own date. Say so in the object's notes,\n"
		"so the next reader does not \"fix\" it into a dot-walk.\n"
		"\n"
		"KEY: THE RATE AND THE MULTIPLICITY TRAVEL AS A PAIR, ALWAYS. Every place that copies one\n"
		"copies the other, every conversion uses both, and a function that returns only the rate will\n"
		"eventually be used on a currency quoted per hundred. Two fields, one fact.\n"
		"\n"
		"NOTE: A CURRENCY WITH NO RATE AT ALL IS THE CASE THAT BREAKS ARITHMETIC, and the cheap\n"
		"answer is an ANCHOR ROW far in the past - rate one, multiplicity one - so that a reading \"as\n"
		"of a date\" always finds something. It is a workaround, and it should be a deliberate one:\n"
		"the alternative is every caller guarding against a zero divisor, and the failure of the\n"
		"guard is a division by zero deep inside a posting.\n"
		"\n"
		"NOTE: A DATE WITH NO TIME MEANS MIDNIGHT, AND MIDNIGHT IS BEFORE EVERYTHING WRITTEN TODAY.\n"
		"Where a rate or a price is read \"as of today\" for a NEW document, take the current moment\n"
		"rather than the start of the day, or today's own entry is invisible to it. The same trap\n"
		"catches every \"as of a date\" reading made for something being created now.\n"
		"\n"
		"NOTE: AND THE EXCHANGE DIFFERENCE ITSELF IS COMPUTED IN `settlements`, NOT HERE - it is born\n"
		"when a debt meets a payment, not when a rate changes. A revaluation of open balances at a\n"
		"period end is a separate, scheduled act.") },

	{ wxT("fixed-assets"),
	  ibMcpText("Long-lived property: what is a register, how depreciation is shaped, recomputing the past."),
	  ibMcpText("PROPERTY THAT IS USED FOR YEARS AND WRITTEN OFF A MONTH AT A TIME.\n"
		"\n"
		"The item itself is a catalogue entry and holds almost nothing - a name, a class, an\n"
		"inventory number. EVERYTHING THAT CAN CHANGE IS A PERIODIC REGISTER, one per family of\n"
		"facts: the initial value, the useful life, the method, the account it sits on, the\n"
		"department it works in, the way its charge is distributed. `shapes` gives the rule; this is\n"
		"the case where it is most obviously right, because the whole subject is \"recompute an old\n"
		"month and get the old figure\".\n"
		"NOTE: AND THE COUNT THAT FOLLOWS FROM IT SURPRISES PEOPLE, SO BUDGET FOR IT: ONE REGISTER PER\n"
		"FAMILY OF FACTS MEANS ONE DOCUMENT PER FAMILY TOO. Somebody has to WRITE each of those\n"
		"registers with a date, an author and a reason, and that is a document apiece - change the\n"
		"method, change the schedule, change the way the charge is reflected, change the tax purpose,\n"
		"change the location. Measured in a working system: some thirty documents around one class of\n"
		"asset, against the half dozen anybody lists when asked.\n"
		"* WHICH IS THE HONEST PRICE OF RECOMPUTING THE PAST, and it is worth naming early rather than\n"
		"discovering at the demonstration. The alternative - one \"edit the asset\" document writing\n"
		"whatever its lines happen to hold - loses the one thing this design exists for: knowing WHICH\n"
		"parameter changed, and when.\n"
		"\n"
		"KEY: EVEN \"IS IT BEING DEPRECIATED AT ALL\" IS A DATED REGISTER, NOT A FLAG. Mothballing an\n"
		"object does not delete its parameters and does not change its method - it WRITES \"do not\n"
		"charge\" with a date, and bringing it back writes the opposite. Because of that, the history\n"
		"of mothballing needs no separate entity: it is already in the register, and a recomputation\n"
		"of last March reproduces last March's behaviour.\n"
		"\n"
		"KEY: THE MOMENT OF THE READING IS PART OF THE RULE. An ordinary object reads its value, life\n"
		"and method AS AT THE START of the month - so in the month it is taken on, it is not charged\n"
		"at all. Low-value items written off at once read the SAME fields AS AT THE END - otherwise\n"
		"they would never be written off, being acquired in that very month. The two readings are\n"
		"chosen by an expression on the method, which means every register is joined TWICE. If\n"
		"somebody asks why one asset started charging in the month of purchase and another did not,\n"
		"this is the answer, and it is a business rule rather than an implementation detail.\n"
		"KEY: A SUB-POPULATION READ AT A DIFFERENT MOMENT IS AN EXPRESSION, NEVER A SECOND COPY OF THE\n"
		"QUERY. The joining twice above is the cheap form. The expensive one appears the moment\n"
		"somebody cannot say \"this group reads at the end of the month\" as a condition and writes a\n"
		"whole second branch of the union instead - in the system examined, thirty-five columns\n"
		"duplicated for the objects taken on in the current month alone, with the balances replaced\n"
		"by literal zeros.\n"
		"* WHAT IT COSTS, and it is paid on every later edit: a new field must be added to BOTH\n"
		"branches in the SAME ORDER, and the copy fires only for a handful of rows a month, so it is\n"
		"the branch nobody tests and the first to drift. Where a branch is genuinely needed, say in\n"
		"one line beside it what differs from the main one - it is always two or three facts, not\n"
		"thirty-five columns.\n"
		"\n"
		"KEY: ONE SKELETON UNDER ALL THE METHODS - EACH ONE ONLY PRODUCES A YEARLY FIGURE. Straight\n"
		"line, sum-of-years, reducing balance, accelerated: they differ ONLY in the formula for the\n"
		"annual amount, and everything after that is shared - divide by twelve, or apply the month's\n"
		"coefficient. Two of them switch to straight line for the final partial year. The one genuine\n"
		"exception is the production method, which has no annual figure at all and goes straight from\n"
		"output to charge.\n"
		"* SO A METHOD IS A FUNCTION OF THREE INPUTS - value, life, residual - and adding one should\n"
		"be adding a function. Where it is written as a long chain of conditions with the shared tail\n"
		"copied into each branch, the copies drift; in the system examined they already had.\n"
		"\n"
		"KEY: SEASONALITY IS NOT A METHOD - IT IS THE MONTH'S SHARE OF THE ANNUAL SUM. \"The harvester\n"
		"works four months a year\" is a coefficient per month applied to the annual figure of ANY\n"
		"method. The denominator is the SUM of the coefficients, not a hundred, so they can be\n"
		"written in whatever units the person thinks in.\n"
		"\n"
		"KEY: THE LAST MONTH OF LIFE IS ONE CLAMP, NOT A BRANCH. After every method: take the lesser\n"
		"of the computed amount and \"what is left down to the residual value\", and never below zero.\n"
		"That single expression removes a whole family of rules - do not depreciate below residual,\n"
		"top up in the final month, never go negative - which would otherwise be repeated inside\n"
		"every method and would disagree between them.\n"
		"\n"
		"STOP: THE SECOND SET OF BOOKS IS A SECOND COMPUTATION, NOT A CONVERSION OF THE FIRST. A\n"
		"different life and a different method give a genuinely different number; there is nothing to\n"
		"convert. In the system examined each method's formula exists SIX times over (two books by\n"
		"three families of asset) and the copies have already diverged - one of them clamps against\n"
		"the wrong base. This is the concrete price named in `parallel-accounting`, caught in the act.\n"
		"\n"
		"KEY: A RULE CAN BE DATED MORE STRONGLY THAN A PARAMETER, and then the answer is a REFUSAL,\n"
		"not a migration. When a method was forbidden by law over a window of years, the calculation\n"
		"does not quietly convert anybody's data - it stops and asks for a new value to be recorded,\n"
		"by document, for that period. And the list of values a field will ACCEPT depends on the\n"
		"document's date. Obsolete values are moved into a group that reads as \"no longer offered\"\n"
		"rather than deleted, because old documents still point at them.\n"
		"\n"
		"NOTE: THE LIFE OF THE OBJECT IS A LEDGER OF EVENTS, NOT A FIELD SAYING WHERE IT IS NOW.\n"
		"Taking on, modernisation, moving, mothballing, disposal - each is a document that writes,\n"
		"and \"what state is it in\" is read back from that ledger as of a date. A MOVE IS A REMOVAL\n"
		"WITH THE OLD DETAILS PLUS AN ARRIVAL WITH THE NEW ONES - never an edit of the old row, or\n"
		"the previous months stop reproducing.\n"
		"STOP: AND DO NOT SKIP A MOVEMENT BECAUSE ITS AMOUNT IS ZERO. A transfer that changes only\n"
		"where a thing is, or who holds it, moves no money at all - the entry's cargo is the QUANTITY,\n"
		"and dropping it as empty loses the movement and leaves the quantity standing where it no\n"
		"longer is. The general form: an entry is written when any resource on it is meaningful, not\n"
		"when the amount is. The habit of guarding writes with \"if the amount is filled\" is right for\n"
		"a money-only register and quietly wrong for every register that also counts things.\n"
		"KEY: AND EACH CHECK OVER THAT LEDGER HAS ITS OWN TIME WINDOW - they are not one query with\n"
		"one date. \"Has this already been taken onto the books\" is asked over ALL time, because a\n"
		"thing can never be taken on twice; \"has it been disposed of\" and \"is it in service\" are\n"
		"asked only up to THIS document's date, because a disposal recorded for next quarter is not in\n"
		"the way of an entry made today.\n"
		"* THE TEST: for every state, ask whether a record AFTER my date contradicts me. Where it\n"
		"does, no date filter; where it does not, filter. Using one window for all of them refuses\n"
		"correct documents in one direction and admits duplicates in the other, and both failures look\n"
		"like the same defect.\n"
		"\n"
		"NOTE: AND \"HAS THIS MONTH ALREADY BEEN CHARGED\" IS ANSWERED BY THE REGISTER'S OWN TURNOVER\n"
		"for that month, not by a flag. Cheap, self-repairing, and it survives a partial run.\n"
		"STOP: BUT A GUARD THAT ACQUIRES AN EXCEPTION HAS STOPPED BEING A GUARD. In the system examined\n"
		"the \"already charged this month\" test carries a second term - and no revaluation turnover -\n"
		"so the whole protection switches OFF for exactly the objects that were revalued, and two\n"
		"charges in a row go through in silence. The exception was added for a real case: a\n"
		"revaluation legitimately needs the month recomputed.\n"
		"* THE FIX IS NOT A SECOND CONDITION BUT A NARROWER QUESTION: ask \"has THIS run already\n"
		"written for this object\" rather than \"has anything been written\", so a recomputation clears\n"
		"its own movements and the guard survives. A guard with a hole in it is worse than none,\n"
		"because it is trusted.\n"
		"\n"
		"STOP: A DOCUMENT ASKING \"DOES THIS ALREADY EXIST\" MUST EXCLUDE ITSELF, TWICE OVER. Read the\n"
		"state as of the MOMENT of this document rather than as of its date - otherwise entries of\n"
		"the same day are invisible - AND exclude this document's own movements from the reading.\n"
		"Miss the second half and the classic symptom appears: posting works the first time and the\n"
		"document refuses itself on re-posting. Both halves are needed together, and this applies to\n"
		"any document that both reads and writes the same state.\n"
		"\n"
		"KEY: THE CHEAPEST WAY TO KEEP N BOOKS IN STEP IS ONE PROPORTION OVER A NAMED BAG OF\n"
		"AMOUNTS. Put every parallel figure of a balance into one structure - cost, tax cost,\n"
		"permanent difference, temporary difference - compute the share being written off ONCE, and\n"
		"multiply every member of the bag by it, decrementing as you go. No parallel amount then has\n"
		"any logic of its own, and they cannot drift apart. Paid for with names becoming strings and\n"
		"\"is there such a field\" moving to run time - a good trade here, because the alternative is\n"
		"four write-off routines that must agree.\n"
		"\n"
		"KEY: WHETHER TWO BOOKS ARE INDEPENDENT AT ALL CAN BE A FUNCTION OF THE DATE. A change in law\n"
		"can make the second book a PROJECTION of the first from a given year - the tax figure simply\n"
		"becomes the accounting one under stated conditions. So the mechanism must support both\n"
		"regimes WITHOUT restructuring the storage: independent in one interval, derived in another.\n"
		"Anyone designing \"two books\" as a permanent architectural fact will be rebuilding it.\n"
		"\n"
		"NOTE: AND WATCH HOW MANY WAYS ONE SYSTEM ENDS UP STORING \"THE SECOND SET OF NUMBERS\". In the\n"
		"one examined there are four at once: separate periodic registers per book; separate\n"
		"RESOURCES inside one register; separate ATTRIBUTES on one ledger entry; and difference\n"
		"resources beside them. Each is defensible where it stands, and the code spends real effort\n"
		"moving amounts between the four. Choosing ONE and stating it is worth more than choosing the\n"
		"best one.\n"
		"\n"
		"NOTE: SPREADING THE CHARGE OVER SEVERAL DESTINATIONS IS THE ORDINARY DISTRIBUTION\n"
		"(`allocation`) over coefficients held in a named \"way of reflecting expenses\" - and where a\n"
		"line of it leaves the department empty, the department comes from the object's LOCATION as\n"
		"of that month. A default that is itself time-dependent.\n"
		"* AND CALL THE DISTRIBUTION THE SAME WAY FOR EVERY BOOK. In the system examined the two\n"
		"books are distributed with different rounding arguments and can differ by a cent - the kind\n"
		"of divergence that is found a year later by an auditor.\n"
		"\n"
		"STOP: A TAX RATE WRITTEN INTO A FUNCTION DESTROYS RECOMPUTATION OF THE PAST. Everything else\n"
		"around it can be right - the two formulas for \"tax included\" and \"tax on top\", the\n"
		"exemptions - and re-posting last year's document still produces today's rate. The rate is\n"
		"the ONE thing in a tax that the law changes; it belongs in a dated register, like every\n"
		"other rate.\n"
		"\n"
		"KEY: \"DOES THIS BECOME PART OF THE ASSET\" IS A PROPERTY OF THE COST'S DESTINATION, NOT OF\n"
		"THE ITEM - and it is decided ONCE, when the cost arrives, not later. Goods and packaging\n"
		"never capitalise; equipment and construction always do; the only genuinely open case is\n"
		"SERVICES, and there the answer comes from the cost account the service is booked to. Asking\n"
		"the item what it is would give the wrong answer for the same delivery charge on two\n"
		"different purchases.\n"
		"\n"
		"KEY: A DIFFERENCE BORN OF A CHANGE IN THE LAW CAN BE GIVEN ITS OWN NAMED DESTINATION AND SENT\n"
		"DOWN THE ORDINARY PIPELINE - instead of a branch in the code. The \"way of reflecting\" the\n"
		"charge is a catalogue (`fixed-assets` above), so the difference arising from a rule that\n"
		"changed on a date becomes a PREDEFINED entry of that catalogue, named for the date it came\n"
		"from, and is then distributed, posted and reported by the same machinery as everything else.\n"
		"* WHAT IT BUYS: the exceptional amount is visible in every report that groups by\n"
		"destination, and no reader of the distribution code needs to know the law changed.\n"
		"* WHAT IT COSTS, and it is real: such an entry usually breaks one of the pipeline's own\n"
		"invariants - here, the check that a destination names a department - so the exemption has to\n"
		"be made explicitly and stated. A synthetic member of a normal set is a good move only while\n"
		"the exemptions it needs are written down beside it.\n"
		"\n"
		"KEY: A COMPANION AMOUNT IS EXTINGUISHED BY THE SAME PROPORTION AS THE THING IT FOLLOWS.\n"
		"A revaluation surplus sits in its own register, and each month the share of it that is\n"
		"released equals the month's depreciation over the remaining value - the same fraction, not a\n"
		"second schedule. It travels as an extra column beside the charge, with its own account, and\n"
		"it changes neither the method nor the amounts of the depreciation itself.\n"
		"* THE GENERAL FORM, and it is worth recognising elsewhere: WHERE ONE FIGURE MUST FOLLOW\n"
		"ANOTHER, DERIVE IT AS A SHARE OF THE DRIVER RATHER THAN GIVING IT A SCHEDULE OF ITS OWN.\n"
		"Two schedules for one asset drift apart - the surplus outlives the object, or dies before\n"
		"it - and nothing reports the divergence (`parallel-accounting`: one proportion over a named\n"
		"bag of amounts is the same idea).\n"
		"\n"
		"NOTE: A TRANSITIONAL RULE LEFT OVER FROM AN OLD LAW IS USUALLY A STOCK TO BE USED UP, not a\n"
		"condition to be evaluated - an allowance carried in the document's context and drawn down by\n"
		"each entry in turn. Two things follow and both must be stated: the RESULT DEPENDS ON THE\n"
		"ORDER of the lines, and the function that draws it down MUTATES what it was given while\n"
		"looking pure. Where a transitional provision is implemented this way, say so beside it.\n"
		"\n"
		"KEY: WHEN AN OBJECT IS SPREAD ACROSS A DOZEN REGISTERS, A REFUSAL MUST NAME THE REGISTER TO\n"
		"FILL IN. \"No information found\" is unactionable. Name the registers that came back empty,\n"
		"the line of the document, and offer the likely cause - \"perhaps it has not been taken onto\n"
		"the books yet\". And the list of names depends on the regime: do not print registers this\n"
		"company does not keep. This is the general form of a useful refusal in any system where one\n"
		"subject lives in many places.") },

	{ wxT("parallel-accounting"),
	  ibMcpText("A second set of books - IFRS, budgeting - and the forks worth knowing before choosing."),
	  ibMcpText("KEEPING A SECOND SET OF BOOKS.\n"
		"\n"
		"Sooner or later someone asks for accounting alongside the accounting they already have -\n"
		"IFRS beside the statutory books, management figures beside both, a budget. There are\n"
		"several ways to carry it and they are not equally good; the choice is worth making\n"
		"deliberately, because it is the one that cannot be changed once there is a year of data.\n"
		"\n"
		" AN ACCUMULATION REGISTER WITH A CATALOGUE STANDING IN FOR ACCOUNTS. It works, and it\n"
		" is the crudest of them: you have re-implemented a chart of accounts as ordinary data,\n"
		" with no correspondence, no double entry, and nothing checking that the two sides\n"
		" agree. Everything the accounting register does for free becomes code somebody\n"
		" maintains. Reach for it only when what is wanted is genuinely not accounting.\n"
		" A CHART OF ACCOUNTS AND AN ACCOUNTING REGISTER OF ITS OWN. The straightforward\n"
		" answer: a second set of books IS a second chart and a second register, and they cost\n"
		" nothing to have side by side. If the words being used are an accountant's, this is\n"
		" where to start.\n"
		" OPERATIONAL REGISTERS THAT FEED IT. Keep the working detail - lots, stock, movement -\n"
		" on accumulation registers where it is cheap to read, and TRANSLATE from them into the\n"
		" accounting register as postings. The operational side answers \"what is where\" fast;\n"
		" the accounting side stays the record that balances. This is the usual shape of a\n"
		" grown-up configuration, and it is worth designing towards even when starting small.\n"
		" NOTE: The translation is then a mechanism with a moment and a direction: decide WHEN it\n"
		" runs and what happens when the source is edited afterwards, and write that in the\n"
		" notes - it is the part that rots quietly.\n"
		"\n"
		"BUDGETING IS THE SAME QUESTION WITH A DIFFERENT ANSWER. A budget is not usually\n"
		"correspondence at all - nothing is debited against anything. It is turnovers: amounts\n"
		"planned per period, per item, per SCENARIO, with the scenario as a dimension of its own\n"
		"so that plan, fact and a revision can sit in one register and be compared. Turnovers give\n"
		"the movement and balances give the standing figure, which together is what people mean by\n"
		"reading a budget - so an AccumulationRegister carries it without a chart of accounts\n"
		"anywhere in sight.\n"
		"* BUT IT CAN BE DONE THE OTHER WAY DELIBERATELY, AND IT HAS BEEN. A working system carries\n"
		"budgeting as a FOURTH SET OF BOOKS - its own chart of items in the shape of a chart of\n"
		"accounts, its own kinds of analysis, its own double-entry register - alongside the\n"
		"statutory, tax and international ones. What that buys is the entire apparatus of ledger\n"
		"reporting for free (`ledger-reports`): the turnover of a budget item and the turnover of an\n"
		"account are read by the same mechanism and drill down the same way. What it costs is that\n"
		"every budget figure must balance against something, which is a real constraint on people\n"
		"who think in plans rather than in entries. Ask before choosing - the answer differs by\n"
		"whether the finance people already live in a ledger.\n"
		"\n"
		"KEY: A SET OF BOOKS IS THREE METAOBJECTS, NOT ONE - a chart of accounts, the kinds of\n"
		"analysis that hang off it, and the register itself, named alike so that reading code can\n"
		"pick the family. Counted in a real system: FOUR such triples. Adding a book is adding a\n"
		"triple, and every reader that resolves the family by NAME has to learn the new one - which\n"
		"is the honest cost of that convenience: the compiler cannot see the family, so nothing\n"
		"tells you which readers you missed.\n"
		"STOP: AND THE CONVENIENCE ONLY HOLDS WHILE THE FAMILIES ARE THE SAME SHAPE - which they stop\n"
		"being almost at once. One book's register carries the legal entity as a dimension and the\n"
		"other's does not; one book's lot register has ten dimensions and six resources against nine\n"
		"and two, because it also holds the tax value and the input tax. Then resolving the family by\n"
		"name drags the CONDITION and the JOIN into the same string, the reader becomes a text\n"
		"generator, and a book that has no such family at all is answered with an empty value rather\n"
		"than a refusal.\n"
		"* SO STATE THE RULE WITH ITS LIMIT: name the families alike, and the day two of them differ\n"
		"in DIMENSIONS, give the odd one its own reader rather than another argument to the text\n"
		"builder.\n"
		"\n"
		"KEY: THE PERSON ENTERS ONE FACT AND A TEMPLATE MAKES THE DOUBLE ENTRY. This is what makes a\n"
		"budget affordable as a ledger. A planning operation records ONE line - scenario, period,\n"
		"item, amount - and the ITEM carries a table of entry templates (debit, credit, a coefficient\n"
		"for the amount, one for the quantity) which explodes it into balanced entries. The price of\n"
		"double entry is then paid ONCE, by whoever set up the item, and never by the person\n"
		"planning. Anyone who objects that planners do not think in debits is right, and this is the\n"
		"answer to them.\n"
		"\n"
		"KEY: THE BALANCING DIMENSION NEED NOT BE THE COMPANY. In a plan ledger it is the SCENARIO -\n"
		"the version of the plan - so optimistic and pessimistic balance separately and can be\n"
		"compared without filtering. And there may be TWO balancing amounts at once (the scenario's\n"
		"currency and the management currency), which costs a real refusal: a line will not post\n"
		"unless every currency involved has a rate that day.\n"
		"\n"
		"KEY: ELIMINATIONS ARE ENTRIES WITH THE COMPANY LEFT EMPTY. No second register, no flag, no\n"
		"separate chart: individual reporting filters by company and never sees them, group reporting\n"
		"does not filter and sums them in. An empty value used as a LEVEL OF AGGREGATION\n"
		"(`combining`: an empty value is a meaning). Worth reaching for whenever a figure belongs to\n"
		"the whole rather than to any part.\n"
		"\n"
		"KEY: THE MAPPING BETWEEN TWO CHARTS IS A DATED, PRIORITISED RULE TABLE, not code. Keyed by\n"
		"the source account IN HIERARCHY, the side of the entry, and the analytics - where a blank in\n"
		"the RULE means \"any\" and a blank in the TARGET means \"carry the source value across, matched\n"
		"by declared type\". Ordered by priority, first match wins.\n"
		"* AND THE NEGATIVE RULE IS NOT THE MIRROR OF THE POSITIVE ONE: exclusions are keyed by the\n"
		"whole CORRESPONDENCE - this account against that one - rather than by a single account,\n"
		"because what must not be transferred is usually a pair.\n"
		"* AND A RULE MAY NEED TO TEST AN ATTRIBUTE OF AN ANALYTIC (\"this account maps one way for\n"
		"goods and another for services\"), which is where a data-driven rule table meets its limit:\n"
		"the test has to name a path and read it dynamically, and it must SURVIVE the attribute not\n"
		"existing on that kind of analytic - skip the rule and say which one, rather than raising.\n"
		"Enumerating the distinction in rows instead means a row per item group for ever.\n"
		"\n"
		"STOP: TRANSLATION TAKES THE RATE OF THE ENTRY'S OWN DATE, so the sum of translated entries\n"
		"is NOT the translation of the sum. Both figures are defensible and they differ; decide which\n"
		"one the reports show and say so, because somebody will add them up by hand and find the gap.\n"
		"\n"
		"STOP: AND A CONSOLIDATION RUN SHOULD BE A DOCUMENT, NOT A WIZARD. Where it is a wizard, a\n"
		"second run writes its eliminations again without removing the first run's, and cleaning up\n"
		"is left to a person. Anything that GENERATES records must own them, so that re-running\n"
		"replaces rather than accumulates (`posting`: writing a set replaces what that recorder had).\n"
		"\n"
		"* THE QUESTION THAT DECIDES: does this have to BALANCE - two sides that must agree, an\n"
		"account that something comes from and one it goes to? Yes, it is a chart of accounts and\n"
		"an accounting register, and imitating it elsewhere throws away the only property that\n"
		"makes it worth having. No, it is accumulation, and reaching for accounts adds ceremony to\n"
		"something that never needed it.\n"
		"\n"
		"---\n"
		"\n"
		"AND ONE LEVEL UP: WHICH STRATEGY THE WHOLE CONFIGURATION FOLLOWS. This is decided once,\n"
		"early, and everything else leans on it.\n"
		"\n"
		" PARALLEL. Management and statutory accounting are kept side by side, and documents\n"
		" carry the flags that say which of them this one is reflected in. Honest when the two\n"
		" genuinely diverge - different valuation, different periods, things recognised in one\n"
		" and not the other - and a real cost everywhere: every document, every report and\n"
		" every user has to know which set they are looking at.\n"
		" FUSED. No flags at all: one truth, recorded once. Far simpler, and correct whenever\n"
		" the two would only ever say the same thing. Do not build the parallel machinery on\n"
		" the chance that they might diverge one day - that chance is paid for daily.\n"
		" TRANSLATED. Operational documents are what people actually work with; the accounting\n"
		" postings are produced FROM them, typically by a scheduled job at month end. The\n"
		" accountant receives a summary and works with that. Good when accounting is a\n"
		" reporting obligation rather than the daily instrument.\n"
		" ACCOUNTING-LED. The accounting register is the primary record: the finance people\n"
		" live in it, the balance is closed there, and everything else is derived. Right when\n"
		" the business IS run in accounting terms.\n"
		"\n"
		"KEY: AND YOU CANNOT READ THIS OFF THE REQUEST - ASK. Two questions settle it: \"will you\n"
		"keep management accounting?\" and \"will you keep statutory accounting?\". People answer\n"
		"them immediately, because they know their own work; guessing produces either machinery\n"
		"nobody wanted or a rebuild once the second kind of accounting turns up. It is one of the\n"
		"few questions worth asking before writing anything at all.\n"
		"\n"
		"KEY: AND THE STRUCTURAL CHOICE IS: ONE REGISTER WITH A \"WHICH BOOKS\" DIMENSION, OR TWO\n"
		"REGISTERS SIDE BY SIDE. Configurations that carry both kinds of accounting for years end up\n"
		"at TWO - stock lots, costs, work in progress, scrap, output, each existing twice, one for\n"
		"management and one for the statutory books. The reasons are worth knowing before choosing:\n"
		" THE DIMENSIONS DIFFER. The statutory side needs the account, the tax designation, the\n"
		" organisation as a legal entity; the management side needs none of them and wants\n"
		" dimensions of its own. Forced into one register, every row carries the other side's\n"
		" empty columns.\n"
		" THE VOLUMES DIFFER, and so does what may be recalculated. Re-posting a quarter of\n"
		" management figures must not touch what has been filed.\n"
		" THE RIGHTS DIFFER. Two registers can be granted separately; one register with a\n"
		" dimension cannot, short of row-level rules.\n"
		"NOTE: THE PRICE IS DUPLICATION - two sets of movements, two write-off routines to keep in step.\n"
		"Pay it with a SHARED ALGORITHM and separate queries (`production`): the traversal is\n"
		"written once, the reading of each side is its own. A single register with a dimension is\n"
		"the right answer only while the two sides genuinely hold the same facts - which stops being\n"
		"true the day the accountant asks for one more account.\n"
		"\n"
		"KEY: AND THERE IS A THIRD SHAPE, WORTH REACHING FOR BEFORE THE OTHER TWO: ONE OPERATIONAL\n"
		"REGISTER, AND ENTRIES DERIVED FROM IT LATER. Documents write their movements once - stock,\n"
		"costs, whatever the operation actually is - and know nothing about accounts. Then a\n"
		"scheduled job walks what was written since it last ran and produces the double entry: at\n"
		"the end of the day, at the end of the month, whenever the accountant needs it.\n"
		"\n"
		"WHAT IT BUYS is the thing the other two shapes pay for: one road for writing, one mechanism\n"
		"to get right, no second set of movements to keep in step - and the accounting rules live in\n"
		"ONE place instead of inside forty documents. Changing how something is reflected in the\n"
		"books becomes an edit to the derivation, not a re-posting campaign.\n"
		"\n"
		"NOTE: WHAT IT COSTS, said plainly: the books LAG. A balance asked for mid-day answers as of the\n"
		"last derivation, and \"why is yesterday's sale not in the ledger\" becomes a question with a\n"
		"legitimate answer that still has to be explained. The derivation needs a boundary of its\n"
		"own - what has already been reflected - and re-posting a document has to invalidate the\n"
		"entries derived from it (`lot-accounting` has the same boundary for cost, and it is the\n"
		"same idea).\n"
		"\n"
		"NOTE: WHICH TO CHOOSE: if the accountant lives IN the ledger all day and posts corrections\n"
		"there, derive nothing - the ledger is primary and the operational side follows it. If the\n"
		"business runs on operational figures and accounting is a monthly obligation, deriving is\n"
		"the cheapest correct design there is, and it is the one people reach for last because the\n"
		"documents look incomplete without their entries.\n"
		"NOTE: AND THE OTHER ROAD IS TAKEN MORE OFTEN THAN THIS SOUNDS, SO SAY WHAT MAKES IT\n"
		"SURVIVABLE. Measured in a full system: a third of all documents post their own entries - some\n"
		"two hundred document-to-ledger links, four ledgers, and no derivation layer anywhere. That is\n"
		"workable for one reason only: WHICH ACCOUNT APPLIES IS DATA, held in settings registers per\n"
		"item, per asset, per way of reflecting a cost, and never as branches inside the documents.\n"
		"* SO THE FORK IS NOT \"documents or derivation\" ALONE. It is: if the account rules are data,\n"
		"writing entries from the document is affordable and stays affordable; if they are branches,\n"
		"the count of documents is the count of places a rule change has to be made, and only\n"
		"derivation saves you.\n"
		"\n"
		"STOP: THE SECOND SET IS NOT A CONVERSION OF THE FIRST. Depreciation is the standing example:\n"
		"the same asset has one life for the books and another for tax, so the month's charge is\n"
		"TWO DIFFERENT NUMBERS computed twice, not one number copied across. The same is true of\n"
		"valuation, of what may be expensed and of when revenue is recognised. Build the parallel\n"
		"figure as a figure in its own right - carried in its own resource, side by side with the\n"
		"first - and a routine that computes \"the amount\" and multiplies it by something to get the\n"
		"other one is a shortcut that will be unpicked.\n"
		"\n"
		"NOTE: AND THE RULES ARE DATED. Tax law changes on a day, and documents before and after that\n"
		"day are computed differently - forever, because re-posting an old period must reproduce\n"
		"what was filed. So the branch is on the DOCUMENT'S date against the law's date, never on\n"
		"today's, and the dates themselves belong in data rather than in the code that reads them.\n"
		"\n"
		"* ONE MORE THING THAT ONLY SHOWS UP IN PRACTICE: an operation in one set of books can drag\n"
		"a companion entry with it in the other. Charging depreciation on an asset that was revalued\n"
		"also moves the revaluation surplus, in proportion to the depreciation, into retained\n"
		"earnings - an entry nobody asks for and everybody's auditor expects. When a mechanism is\n"
		"built for one set of books, ask what it obliges in the other.\n"
		"\n"
		"KEY: WHERE THE SECOND BOOK IS DERIVED, THE MAPPING BETWEEN CHARTS IS A RULE TABLE WITH FOUR\n"
		"PROPERTIES, AND ALL FOUR ARE ASKED FOR. It is TIME-VERSIONED, because the correspondence\n"
		"changes when either chart does and last year must still derive; it is PRIORITISED, because a\n"
		"specific rule must beat a general one and \"more specific\" cannot be inferred; it is\n"
		"SIDE-AWARE, because the account an amount lands on depends on which side of the entry it is;\n"
		"and a rule may test an ATTRIBUTE of the analytic rather than only its account.\n"
		"* AN EMPTY TARGET ANALYTIC MEANS \"CARRY THE SOURCE ACROSS\", matched by type - which is what\n"
		"keeps the table short, since most analytics pass through unchanged. Say it once, in the\n"
		"table's own notes, or every reader invents a different meaning for the blank.\n"
		"* AND THE POSITIVE RULE IS ONE-SIDED WHILE THE NEGATIVE ONE IS TWO-SIDED: \"map this account\n"
		"to that\" needs only the source, but \"do NOT map this\" has to name both sides or it excludes\n"
		"far more than intended. The asymmetry is real and belongs written down beside the table.\n"
		"* A CHAIN THROUGH AN INTERMEDIATE CLASS OF ACCOUNTS IS COLLAPSED AT THE RUN, NOT BY MORE\n"
		"RULES. Following the chain when it is used keeps the table one hop deep and human-sized;\n"
		"pre-expanding it multiplies the rows and makes every later edit ambiguous.\n"
		"STOP: AND A RULE TEST WRITTEN AS A STRING - the attribute's name, the expected value - is the\n"
		"standing weakness of this design: nothing checks it, and a renamed attribute turns a rule\n"
		"off silently. Keep the vocabulary of testable attributes closed and listed.\n"
		"\n"
		"KEY: THE DERIVATION RUN IS A DOCUMENT THAT OWNS A PERIOD, AND TWO OF THEM MAY NOT OVERLAP.\n"
		"That single rule is what makes the derived book explicable: every entry in it belongs to\n"
		"exactly one run, re-running a period replaces that run's output, and \"where did this come\n"
		"from\" is answerable by opening one document (`closing-a-period`).\n"
		"* AND THE REAL PRODUCT OF THE RUN IS WHAT IT REFUSED TO TRANSFER. An entry no rule matched is\n"
		"not an error to swallow - it is the list the accountant works through, so print it with the\n"
		"account, the analytic and the amount, and count it. A derivation that reports only what it\n"
		"did is a derivation nobody can trust.\n"
		"NOTE: AND THE DERIVED BOOK CLOSES ITS OWN YEAR AND REVALUES ITS OWN CURRENCY ITEMS, against\n"
		"ITS OWN definition of what is foreign - which is not the first book's. Where a manual entry\n"
		"is allowed straight into the derived book, it desynchronises that book's subledgers from its\n"
		"own ledger silently; either forbid it or reconcile for it deliberately.\n"
		"\n"
		"NOTE: CONSOLIDATION IS THIS MECHANISM ONE FLOOR UP, AND TWO OF ITS FACTS ARE WORTH CARRYING.\n"
		"An ELIMINATION is an ordinary entry with the organisation dimension left EMPTY - it belongs\n"
		"to the group and to no member - which is why that dimension must permit a blank by design.\n"
		"And whether a counterparty IS a group member is a time-versioned map, not a flag on the\n"
		"counterparty: companies join and leave, and last year must still consolidate as it did.\n"
		"* WHAT IT CANNOT DERIVE IS WORTH SAYING TO THE CUSTOMER EARLY: profit sitting unrealised\n"
		"inside assets one member bought from another is not visible in either member's ledger, so it\n"
		"is entered, not computed. And a run that is a wizard rather than a document is NOT\n"
		"idempotent - running it twice doubles what it wrote - which is the same argument as the\n"
		"period-owning document above, lost.") },

	{ wxT("org-structure"),
	  ibMcpText("The company as it sees itself and as its papers see it - two trees, not one."),
	  ibMcpText("THE COMPANY HAS TWO STRUCTURES, AND THEY ARE NOT THE SAME TREE.\n"
		"\n"
		"Somebody says \"the sales department\" and means one thing. Their documents say it three\n"
		"times, once per legal entity. In a working configuration this appears as PAIRS of\n"
		"catalogues - departments and departments-of-a-legal-entity, positions and\n"
		"positions-of-a-legal-entity, a PERSON and their EMPLOYMENT - joined by a register of\n"
		"correspondence.\n"
		"\n"
		"KEY: AND THE DOUBLING STOPS THERE - WHICH IS THE HALF PEOPLE GET WRONG. Counted in a full\n"
		"system, the catalogues that exist twice are the organisational and personnel ones:\n"
		"departments, positions, grounds for leaving, the ways pay is reflected. Everything commercial\n"
		"is SINGLE and shared - items, variants, warehouses, parties, agreements, currencies, units,\n"
		"price types - however many legal entities there are.\n"
		"* THE TEST IS WHAT THE TWO SIDES ARE ENTITLED TO DISAGREE ABOUT: who reports to whom, what a\n"
		"post is called, why somebody left. Nobody is entitled to a second opinion about what a\n"
		"product IS.\n"
		"* SO A DESIGN THAT DOUBLES THE ITEM LIST HAS MISREAD WHICH SEAM IT IS ON, and it pays for it\n"
		"every day in matching, in duplicates and in reports that cannot be added up.\n"
		"\n"
		"KEY: WHY THEY ARE KEPT APART. One tree answers management questions - who reports to whom,\n"
		"whose result is this, which unit is profitable. The other answers legal ones - whose\n"
		"employee is this on paper, which entity owns this unit. They change for DIFFERENT REASONS\n"
		"and at different moments: a reorganisation of legal entities must not break the management\n"
		"reporting, and a management reshuffle must not touch anybody's employment record.\n"
		"* THE SAME SPLIT AT THE PERSON: a human being and their employment are different things. One\n"
		"person may be several employees - two jobs, two entities, a transfer mid-year - and every\n"
		"payroll and staffing question depends on knowing which of the two is being asked about.\n"
		"\n"
		"KEY: THE TEST FOR WHETHER YOU NEED BOTH is not the size of the company but this question:\n"
		"CAN THE SAME REAL UNIT BELONG TO MORE THAN ONE LEGAL ENTITY, OR CHANGE WHICH ONE IT BELONGS\n"
		"TO, WITHOUT THE WORK IT DOES CHANGING? If yes, one tree will be wrong in one of the two\n"
		"directions for ever. If no - a single company, one entity - the second tree is pure cost and\n"
		"should not be built.\n"
		"\n"
		"NOTE: WHAT IT COSTS, plainly. The correspondence between the trees has to be maintained by\n"
		"somebody, and half the reports acquire a question they did not have: IN WHICH OF THE TWO\n"
		"BREAKDOWNS do you want to see this. That question is not noise - it is the honest form of a\n"
		"choice that exists whether or not the system admits it.\n"
		"\n"
		"NOTE: AND THE WAREHOUSE HAS THE SAME DUALITY, less visibly: where goods PHYSICALLY are, and\n"
		"whose they are ON PAPER, are separate questions kept in separate registers. See\n"
		"`stock-control`. It is the same distinction one floor down.") },

	{ wxT("constants"),
	  ibMcpText("One value for the whole application, the same for everyone - and when it is not."),
	  ibMcpText("WHAT A CONSTANT IS FOR.\n"
		"\n"
		"A Constant holds ONE value for the entire application: the same for every user, every\n"
		"company, every day. The configuration's own version; a global switch that changes how the\n"
		"whole program behaves; the organisation the base is kept for. If you can point at the one\n"
		"value and say \"this is simply what it is here\", it is a constant.\n"
		"\n"
		"THREE QUESTIONS SEND IT SOMEWHERE ELSE, and each of them is asked by someone eventually:\n"
		" \"What was it before?\" - a constant has no history. Writing it overwrites what was\n"
		" there and the previous value is gone, with nothing recording when it changed. If the\n"
		" old value will ever be needed - a rate, a limit, a responsible person - this is an\n"
		" InformationRegister with `Periodicity` (see `shapes`), not a constant.\n"
		" \"Whose?\" - if the answer differs per company, per warehouse, per user, it is not one\n"
		" value. It is a register keyed by whatever it differs by. A constant that grows a\n"
		" second meaning (\"the main warehouse - well, for the main company\") has already\n"
		" stopped being one.\n"
		" \"Which one?\" - if it names a particular item rather than holding a setting, look at\n"
		" `predefined` first: a predefined item is reachable by name from code without a\n"
		" constant standing in front of it, and it cannot be left empty by accident.\n"
		"\n"
		"NOTE: AND A CONSTANT CAN BE EMPTY. Nothing forces it to be filled before something reads it,\n"
		"so code that assumes a value will one day run on a fresh base where nobody set it. Decide\n"
		"what the empty case means - a sensible default, or a refusal that says which constant is\n"
		"missing - rather than letting it read as zero or as an empty reference deep inside a\n"
		"calculation.\n"
		"\n"
		"KEY: THE PROPORTION, WHEN THE THREE QUESTIONS ARE ASKED HONESTLY. A full manufacturing system\n"
		"was counted at 123 constants against 347 information registers: the settings that have a\n"
		"company or a date behind them outnumber the plain ones nearly three to one. In particular\n"
		"THE ACCOUNTING POLICY IS NOT CONSTANTS - it is a periodic register per company, and there is\n"
		"one of them per set of books. \"From this year we value stock differently\" and \"the second\n"
		"company does it another way\" are both ordinary, and both are fatal to a constant.\n"
		"\n"
		"NOTE: WHAT LEGITIMATELY STAYS A CONSTANT: the currency accounting is kept in, and SWITCHES\n"
		"THAT TURN WHOLE MECHANISMS ON AND OFF - whether variants of items are used at all, whether\n"
		"series are tracked, whether record-level access is in force, whether a derived register is\n"
		"maintained (`derived-registers`).\n"
		"* AND A SWITCH THAT WHOLE PARTS OF THE INTERFACE HANG OFF DESERVES TO BE DECLARED AS ONE\n"
		"rather than read as an ordinary flag - so that hiding what it governs is done by the engine\n"
		"instead of by each form remembering to ask. In the system counted there are eleven such\n"
		"declared switches against a hundred and twenty-three plain constants: the weight is\n"
		"justified rarely, and recognising which eleven is the whole skill.\n"
		"* AND SUCH A SWITCH DRIVES THREE DIFFERENT THINGS AT ONCE, which is why it must be asked\n"
		"rather than guessed at each site: whether a dimension is filled when posting, whether a\n"
		"column is shown on a form, and whether a branch of a calculation runs at all. A mechanism\n"
		"half switched on - the column hidden but the dimension still filled - is worse than either\n"
		"state.\n"
		"KEY: AND SUCH A SWITCH USUALLY COMES IN A PAIR AT TWO ALTITUDES: \"is the company in this\n"
		"business at all\" is one value for the base, \"is THIS thing treated that way\" is a flag on\n"
		"the thing. Tracking identities, keeping variants, certifying goods are all shaped like that,\n"
		"and both must be asked - the first decides whether the commands and columns exist, the second\n"
		"whether a given line is checked. Collapsing them into one gives either a setting nobody can\n"
		"switch off or a check that fires on everything.\n"
		"KEY: AND A MECHANISM THAT HAS NO SUBJECT WITHOUT ANOTHER ONE BORROWS ITS SWITCH RATHER THAN\n"
		"INVENTING A SECOND. Certificates are stated per lot: without lots there is nothing to\n"
		"certify, so the reader asks the LOTS switch. That is right, and it costs one thing which must\n"
		"be paid: when the dependent mechanism does nothing, it has to SAY WHY and name the setting to\n"
		"turn on. Otherwise the report is \"I enabled it and nothing happened\", which is the same\n"
		"sentence as a defect.\n"
		"KEY: AND THE ACCOUNTING POLICY IS ITS OWN REGISTER, A STEP OF EVERY AREA RATHER THAN A THING\n"
		"TO ADD AT THE END. It is what lets one document post differently for two companies without a\n"
		"branch anywhere in it: the document reads the policy for its own date and asks the ANSWER,\n"
		"never the circumstances (`posting`). There is usually more than one - counted in a full\n"
		"system, five: one per set of books, plus one for personnel - and their DIMENSION LISTS are\n"
		"the exact statement of what this business may disagree with itself about.\n"
		"* AND A POLICY REGISTER WITH NO DIMENSIONS AT ALL IS LEGITIMATE, which is the case people\n"
		"mistake for a constant: one policy for the whole business, but dated, so last year's figures\n"
		"still recompute under last year's rules. Periodicity alone is reason enough not to be a\n"
		"constant.\n"
		"\n"
		"KEY: ONE SUCH SWITCH DESERVES NAMING BECAUSE IT CHANGES THE SHAPE OF EVERY DOCUMENT:\n"
		"WHETHER THE WAREHOUSE (or the order) LIVES IN THE HEADER OR IN THE LINES. \"One warehouse per\n"
		"document\" and \"several warehouses in one delivery note\" are not a preference - they move a\n"
		"field between two places, and every routine that reads it must ASK first rather than assume.\n"
		"Some calculations change meaning entirely between the two.\n"
		"* AND THE SETTING IS NOT A YES-OR-NO: it is usually per DIRECTION - lines for incoming\n"
		"documents, header for outgoing, or both. A boolean here is the shape that has to be widened\n"
		"within a year.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. One switch that HIDES ITS OWN CONSEQUENCES - every\n"
		"command, column and attribute that depends on it going away together, declared once rather\n"
		"than tested at each site. That is the whole of the requirement, and it is worth stating\n"
		"because it is cheap to want and expensive to imitate.\n"
		"* WHERE NOTHING PROVIDES IT, the switch is a constant (or a settings register when it is\n"
		"dated or per company) and what it hides is hidden by the code that reads it - which makes\n"
		"the rule above load-bearing rather than tidy: a mechanism half switched on is then a thing\n"
		"you can actually build, so the reading side has to be walked deliberately\n"
		"(`where-behaviour-lives`).") },

	{ wxT("numbering"),
	  ibMcpText("Numbers and codes: prefixes as series, who may edit them, and what a blank number means."),
	  ibMcpText("NUMBERING DOCUMENTS AND CODING ITEMS.\n"
		"\n"
		"KEY: A PREFIX IS NOT DECORATION ON A NUMBER - IT IS A SEPARATE SERIES. The number is not\n"
		"assembled as a string. The engine is asked for the next number IN THE SERIES the prefix\n"
		"names, and it continues that series. Everything follows from this: separate numbering per\n"
		"company means different prefixes, continuous numbering means one, and there is nothing else\n"
		"to configure.\n"
		"* \"NO PREFIX\" IS ALSO A SERIES, not the absence of one. Where a document has no company, or\n"
		"the company's prefix is empty, a constant stands in. Otherwise the first document without a\n"
		"company would silently join whichever series was last used.\n"
		"STOP: AND THE PREFIX EATS DIGITS. The number is a fixed width, so every character of prefix\n"
		"is one fewer digit of counter, and all companies must be given prefixes of the SAME LENGTH -\n"
		"reading a prefix back out of a number is done by position.\n"
		"\n"
		"PREFIXES STACK IN A FIXED ORDER: base, then company, then - in the cases that need it -\n"
		"department instead of company. The base prefix goes leftmost because it must separate two\n"
		"bases even when they hold the same companies; it is added only when there is more than one\n"
		"base to separate. The ORDER IS PART OF THE CONTRACT, since the reverse reading counts from\n"
		"the left.\n"
		"\n"
		"KEY: A CODE THE CUSTOMER DICTATES IS A LAYOUT PLUS A SCOPE, AND BOTH ARE DATA. \"Plant code,\n"
		"year, day of the year, then five digits\" is an ordered list of GROUPS, each naming a source -\n"
		"a literal, a part of a date, a separator, a counter, or an identifier of a related object -\n"
		"with the width it is padded or trimmed to. Written as data, a new format is a row; written as\n"
		"code, it is a release.\n"
		"KEY: AND \"RESTART PER PLANT\" IS NOT A SECOND COUNTER - IT IS WHICH DIMENSIONS ARE PINNED.\n"
		"Keep counters in a register dimensioned by everything the customer might ever count within,\n"
		"and let the kind of counter say which of those dimensions carry a value and which carry an\n"
		"EMPTY reference. The empty one is the wildcard (`combining`: an empty value is a meaning), so\n"
		"one reader serves every scope.\n"
		"STOP: TWO THINGS MUST BE SAID BESIDE SUCH A COUNTER. Issuing the next value is a READ AND A\n"
		"WRITE and needs a lock, or two sessions hand out the same number; and a counter with an end\n"
		"value WRAPS - if nothing refuses at the ceiling, the same identity is issued a second time in\n"
		"silence.\n"
		"* AND THE IDENTITY IS THEN A FUNCTION OF MUTABLE DATA: change an item's code and newly issued\n"
		"codes change shape, while nothing ties an issued one back to the rule that made it.\n"
		"\n"
		"KEY: CHANGE THE COMPANY AND THE NUMBER IS CLEARED, NOT REWRITTEN. When the company changes,\n"
		"or its prefix is empty, or the number's current prefix no longer matches, the number is\n"
		"emptied - and empty means \"assign on writing\", so the engine issues the next number in the\n"
		"correct series. The system never renumbers; it returns the object to \"has no number yet\".\n"
		"That is the only safe move, because the right number is whatever the target series is up to,\n"
		"and nobody knows it until the write.\n"
		"* AND IT FIRES WHEN THE COMPANY ARRIVES INDIRECTLY TOO - picked up from a chosen contract\n"
		"rather than typed. Attach it to the VALUE CHANGING, not to the field being edited.\n"
		"\n"
		"NOTE: THE NUMBER FIELD IS READ-ONLY BY DEFAULT, and editing it is opened by a command that\n"
		"ASKS FIRST and says what will happen - that numbering may be broken. Not a hidden setting\n"
		"and not a free field: a deliberate act with its consequence stated. The refusal to let\n"
		"people type numbers is worth defending, because a hand-typed number belongs to no series and\n"
		"the engine will hand it out again later.\n"
		"\n"
		"NOTE: WHETHER NUMBERS MAY BE TYPED AT ALL IS A POLICY HELD AS DATA, PER KIND OF OBJECT. A\n"
		"small register keyed by (kind of object, its name) answers available or not: available\n"
		"REMOVES the command and leaves the field plainly editable, not available keeps the field\n"
		"read-only and the change behind its question. The two things people mean by \"let me set the\n"
		"number\" - a kind whose numbers come from outside and are never ours to issue, and one\n"
		"document that has to be corrected today - are then answered by different mechanisms, and\n"
		"neither of them is a per-person setting.\n"
		"* AND THE GRANT INSIDE AN OPEN FORM IS ONE-SHOT: it is a mark on that form and is stored\n"
		"nowhere, so the next opening is read-only again. The policy, by contrast, is read on EVERY\n"
		"opening of every form, which is what makes it worth caching and worth keeping to one row\n"
		"per kind.\n"
		"\n"
		"NOTE: AN EMPTY NUMBER ON A NEW OBJECT IS EXPLAINED, NOT LEFT BLANK. The field shows why it\n"
		"is empty - the number is assigned when the object is saved - because a blank required-looking\n"
		"field reads as a defect to everyone who has not been told.") },

	{ wxT("object-history"),
	  ibMcpText("Keeping who changed what: snapshots, when to write one, and reading a difference."),
	  ibMcpText("KEEPING A HISTORY OF CHANGES.\n"
		"\n"
		"KEY: STORE SNAPSHOTS, NOT DIFFERENCES. Each version is the WHOLE object serialised and\n"
		"compressed into one row keyed by (object, version number). A snapshot restores and compares\n"
		"against ANY other version with no chain to walk, and it survives the object gaining or\n"
		"losing attributes - a chain of deltas needs every link and breaks the day the schema moves.\n"
		"* THE PRICE IS PAID IN VOLUME and must be said out loud: a document of two hundred lines\n"
		"edited ten times is ten full copies of two hundred lines. Compression is the only lever, and\n"
		"the decision below is what actually keeps it bounded.\n"
		"\n"
		"KEY: WHAT GETS A HISTORY IS DECIDED PER KIND OF OBJECT, AS DATA. A small register keyed by\n"
		"the type name holds one of three answers - never, on posting, always - and where nothing is\n"
		"stored the default is computed from the metadata itself: reference data gets no history,\n"
		"a document that can be posted gets one at posting, a document that cannot gets one always.\n"
		"* \"ON POSTING\" ALSO MEANS THE DRAFT IS NOT KEPT: while an object has no versions and is not\n"
		"yet posted, nothing is written. Otherwise every intermediate save of a document being typed\n"
		"becomes a version, and the history of the one thing people actually ask about - what changed\n"
		"after it was posted - is buried.\n"
		"KEY: AND \"DO NOT WRITE A VERSION IF NOTHING ACTUALLY CHANGED\" IS ANSWERED WITHOUT ANY\n"
		"PER-FIELD CODE. Create two blank objects of the kind, copy into them only the properties in\n"
		"scope, load the line tables that pass the same filter, serialise both and compare the two\n"
		"strings. There is no comparison code to keep in step with the schema, and the answer stays\n"
		"right for an attribute added next year. The price is two serialisations per write and an\n"
		"answer that says THAT they differ, never WHICH field - which is enough, since the difference\n"
		"is computed when it is shown.\n"
		"STOP: AND DO NOT EXPRESS THE PROPERTY FILTER AS A SUBSTRING TEST OVER A COMMA-SEPARATED LIST.\n"
		"Excluding a table called \"Goods\" then also excludes \"GoodsReturned\", and excluding \"Sum\"\n"
		"excludes \"SumTotal\" - silently, and only for the customers who have the second table.\n"
		"\n"
		"KEY: THE DIFFERENCE IS COMPUTED WHEN IT IS SHOWN, NOT WHEN IT IS WRITTEN. Writing must be\n"
		"cheap and must know nothing about comparison; comparing is rare and may be expensive. The\n"
		"reader unpacks two or more snapshots and lays them out as a table - one row per attribute,\n"
		"one column per version, each cell marked changed, added or removed.\n"
		"STOP: AND TABULAR SECTIONS ARE NOT COMPARED ROW BY ROW NUMBER. Inserting one line in the\n"
		"middle would then report every line below it as changed. They are compared by finding\n"
		"matching BLOCKS, and by carrying a row identity that survives reordering. Any history over\n"
		"an object with lines has to answer this or its output is noise.\n"
		"\n"
		"NOTE: A SNAPSHOT KEEPS IDENTITY, NOT APPEARANCE - a reference is stored as what it points\n"
		"to, and the name shown comes from the live base at reading time. Two consequences to state\n"
		"before anyone meets them: an item deleted since will show as a broken reference (so check\n"
		"existence when rendering, do not fail), and an item RENAMED since will show its NEW name in\n"
		"an old version. That is the honest trade - the alternative, storing the presentation, doubles\n"
		"the size and starts lying about what the value was.\n"
		"\n"
		"NOTE: REWORKING HISTORY ALREADY WRITTEN IS A SCHEDULED JOB WITH A MARK IN THE ROW ITSELF -\n"
		"\"this one is done\" stored beside the data, not a separate list of work. Then the operation\n"
		"is interruptible and resumable by construction, and it does not have to finish inside an\n"
		"update. The same shape fits any heavy migration of stored data.\n"
		"\n"
		"NOTE: THE VERSION NUMBER IS THE ONE WEAK POINT. Counting \"the highest so far, plus one\" on\n"
		"every write buys a readable \"version 3\" and costs a query per write plus a race when two\n"
		"people save the same object. The alternative - key by the moment, number only when showing -\n"
		"is cheaper and less pretty. Know which you chose and why.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. Only one thing, and it is usually already there: a\n"
		"value that can PACK ITSELF into a tree and back. Given that, a stored version is one\n"
		"serialisation and a comparison is a walk over two trees; without it, every attribute has to\n"
		"be copied and compared by hand and the code goes stale on the next schema change.\n"
		"* SO SAY THE SPLIT WHEN THIS IS ASKED FOR, because the estimate people expect is the wrong\n"
		"way round: the STORAGE is an afternoon, and the DIFFERENCE SHOWN SIDE BY SIDE - two versions\n"
		"aligned, added, removed and changed rows coloured - is the week.") },

	{ wxT("allocation"),
	  ibMcpText("Spreading an amount over lines so the parts still add up to the whole."),
	  ibMcpText("DISTRIBUTING AN AMOUNT ACROSS LINES - AND THE LEFTOVER PENNIES.\n"
		"\n"
		"THE SIGNAL, in the words people actually use: \"spread this amount over those lines\",\n"
		"\"split one sum across another\", \"I do not want any pennies left over\". A discount, a\n"
		"freight charge, a total to be divided by weight - the amount is known, the lines are\n"
		"known, and the parts must add back to exactly the amount.\n"
		"\n"
		"Rounding each line on its own does not do that: round twelve lines to two decimals and\n"
		"the sum lands a few pennies off, every time, in a document that has to balance. This is\n"
		"not an edge case to be discovered later - it happens on almost every real document, and\n"
		"it is the single most common thing to get quietly wrong.\n"
		"\n"
		"METHOD 1 - BY WEIGHT, WITH THE REMAINDER PLACED. Compute each line's weight from its\n"
		"base, take the share, round it, and add up what you actually handed out; the difference\n"
		"between that and the total goes onto ONE chosen line.\n"
		" weight_i = base_i / SUM(base)\n"
		" part_i = round(total * weight_i)\n"
		" residue = total - SUM(part_i) -> onto the last line (or the largest)\n"
		"This is the common one and it is honest as long as the residue is placed DELIBERATELY.\n"
		"Which line receives it is a decision - the last is simplest, the largest hides it best -\n"
		"and it belongs written in the object's notes, because the next reader will find a line\n"
		"that is a penny off its own weight and wonder whether it is a bug.\n"
		"\n"
		"KEY: WHICHEVER METHOD, RECOMPUTE FROM WHAT IS LEFT AT EACH STEP - the remaining amount over\n"
		"the remaining total of the weights - rather than taking each share of the original. The\n"
		"residue then cannot appear at all, instead of appearing at the end and having to be placed.\n"
		"* AND WALK THE LINES FROM THE LARGEST WEIGHT DOWN, so what is left over lands on the\n"
		"SMALLEST share: a penny on a large line is invisible, a penny on a small one is a percentage\n"
		"somebody will query.\n"
		"* THE ACCUMULATOR OF FRACTIONS CAN BE KEYED BY ANYTHING, and that is what makes one loop\n"
		"serve several independent distributions at once - a bank per tax rate, per currency, per\n"
		"group (`pricing`). Pass the key in; do not write a second loop.\n"
		"\n"
		"METHOD 2 - CUMULATIVE, WITH NOTHING LEFT OVER. Round the RUNNING TOTAL rather than each\n"
		"share, and take each line as the difference between two rounded running totals:\n"
		" C_i = round(total * SUM(base_1..base_i) / SUM(base)), C_0 = 0\n"
		" part_i = C_i - C_(i-1)\n"
		"The parts then add to C_n, which IS the total, by construction - there is no residue to\n"
		"place, because the error never accumulates: each line silently absorbs the previous\n"
		"line's rounding, and no line is ever more than one unit from its ideal share. This is the\n"
		"one to use when the requirement is \"it must come out even\" rather than \"each line must\n"
		"match its own weight exactly\".\n"
		"\n"
		"NOTE: ZERO AND NEGATIVE BASES BREAK BOTH if not thought about: a line with base 0 must get 0\n"
		"and must not be the one carrying the residue, and SUM(base) = 0 has no answer at all -\n"
		"refuse rather than divide. Decide what a line of zero means before writing the loop.\n"
		"\n"
		"* ASK WHICH FAILURE IS ACCEPTABLE, because one of them must be. Either a line differs\n"
		"slightly from its own weight (method 1's chosen line, method 2's absorption) or the\n"
		"parts do not sum to the whole. There is no third outcome; the arithmetic does not allow\n"
		"it. What people mean by \"I do not want any pennies left\" is almost always method 2.\n"
		"\n"
		"KEY: SPREADING OVER TIME IS THE SAME PROBLEM, and it has one form that gets it right - the\n"
		"monthly write-off of something paid for a period (insurance, a licence, deferred expenses):\n"
		"\n"
		" share = round(REMAINING_AMOUNT / days_from_this_month's_start_to_the_END_of_the_term\n"
		" * days_of_the_term_falling_INSIDE_this_month, 2)\n"
		"\n"
		"STOP: THE DIVISOR IS THE DAYS THAT REMAIN, NOT THE DAYS OF THE WHOLE TERM, and it is computed\n"
		"from the REMAINING amount rather than the original. That is the entire trick: rounding\n"
		"never accumulates, because every month re-divides what is actually left over what is\n"
		"actually left. Dividing the original sum by the total days leaves a residue that has to be\n"
		"chased in the final month - and somebody always forgets to chase it.\n"
		"\n"
		"And the last month is an explicit case, not an accident: when the days remaining in the\n"
		"term equal the days falling inside this month, write off the WHOLE remainder without\n"
		"dividing at all. That is what closes the account to exactly zero.\n"
		"\n"
		"NOTE: PARTIAL MONTHS AT BOTH ENDS are the ordinary case - a term starting on the 17th, ending\n"
		"on the 8th - so the month's slice is bounded on both sides: start of the slice is the LATER\n"
		"of the month's start and the term's start, end of it the EARLIER of the month's end and the\n"
		"term's end, and days are counted inclusively at both ends. The by-months variant (equal\n"
		"twelfths) is a different request and a different answer; ask which one is meant, because\n"
		"the two differ by real money in the first and last months.\n"
		"\n"
		"NOTE: SPREADING A COST OVER SEVERAL SUBJECTS MULTIPLIES THE ROW, and the mechanics are worth\n"
		"stating: shares come from a dated register (subject, share), the amount is divided by the\n"
		"ordinary proportion, the first portion OVERWRITES the original line and the rest are added\n"
		"as copies. Where no shares are defined, write the whole amount WITHOUT the subject and warn -\n"
		"do not refuse: a missing allocation rule must not stop a document from posting.\n"
		"* AND SOME COSTS MUST NOT BE SPREAD THAT WAY AT ALL - production costs belong to output, and\n"
		"forcing a project onto them double-counts. Which kinds are excluded is a rule of the COST's\n"
		"nature, decided centrally, not per document.\n"
		"\n"
		"KEY: WHERE THIS MEETS TAX, which is where it is met most often. Computing VAT on each line\n"
		"and adding the results up gives a DIFFERENT number from computing it once on the\n"
		"document's total - each line rounded a fraction of a penny, and twelve of them add up to\n"
		"something visible. Neither is wrong arithmetic; they answer different questions, and one\n"
		"of them has to be declared authoritative:\n"
		" per-line tax is authoritative when each line has to stand on its own - different\n"
		" rates, a line reprinted or reported separately;\n"
		" document-level tax is authoritative when the printed total is what must match, and\n"
		" then the lines are ALLOCATED from it by the methods above rather than summed into it.\n"
		"Decide which, say so in the notes, and never let one road compute it both ways - that is\n"
		"the reconciliation that never converges. See `printing` for the two VAT schemes\n"
		"themselves, which is a separate choice on top of this one.") },

	{ wxT("printing"),
	  ibMcpText("Where a print command belongs, and what a commercial blank is made of."),
	  ibMcpText("BUILDING A PRINTED FORM.\n"
		"\n"
		"WHERE THE COMMAND LIVES - the choice made first and regretted later.\n"
		" A command ON THE FORM that prints inline is the crudest of them. It works, and it\n"
		" means the printout exists only where that form is open: not from a list, not from a\n"
		" job, not from another form. Putting the call behind a procedure changes nothing -\n"
		" it is the same option written more tidily.\n"
		" A command ON THE OBJECT is the one to reach for. It is invoked in its own right, is\n"
		" handed what it needs, and produces the document; the form becomes one caller among\n"
		" several rather than the only door.\n"
		" Or put the printing in the OBJECT or MANAGER module and let the command delegate to\n"
		" it. Older in style, and entirely sound: what matters is that the printout is reachable\n"
		" without a form being open, not which of these two carries it.\n"
		"The test is a question: if this had to be printed for two hundred documents overnight,\n"
		"with nobody at a screen, would it still work? If not, it is on the form.\n"
		"\n"
		"WHAT A COMMERCIAL BLANK IS MADE OF. Nearly all of them are four things, in this order:\n"
		"a HEADER, a TITLE line, the repeating DETAIL row, and a FOOTER. See `form-to-areas` for\n"
		"how to cut them; what follows is what each usually holds.\n"
		"\n"
		"The HEADER identifies the two parties - supplier and buyer: full legal name, legal\n"
		"address, tax and registration numbers, the contract number and date. These read as\n"
		"sentences one after another, so they are usually TEMPLATES rather than bare parameters -\n"
		"`[FullName], [LegalAddress]` sits inside a line of text and stays readable. Where there\n"
		"are genuinely only one or two, filling them as parameters is fine; the template earns its\n"
		"place when the line is prose.\n"
		"\n"
		"The DETAIL row is the goods - product, quantity, price, amount - drawn once per line, and\n"
		"it is the area that repeats. It may be collapsed or expanded differently from one form to\n"
		"another; that is a question about which lines are output, not about a second area.\n"
		"\n"
		"The FOOTER carries the totals, and they sit UNDER THE COLUMNS they total: quantity under\n"
		"quantity, amount under amount. VAT is shown the same way, in its own row beside them.\n"
		"\n"
		"VAT IS WHERE THE VARIATION LIVES, and people will ask about it every time. Two shapes,\n"
		"and they are not the same arithmetic:\n"
		" VAT INCLUDED - the line's amount already contains the tax, and the tax is EXTRACTED\n"
		" from it.\n"
		" VAT ON TOP - the line's amount is the base, and the tax is ADDED to it.\n"
		"Ask which one before writing either: the two produce different totals from the same\n"
		"numbers, and a form built for one silently mis-states the other.\n"
		"\n"
		"NOTE: AND THE RATE IS NOT A CONSTANT IN THE CODE. It is set by legislation and it changes -\n"
		"which makes it the textbook case for an InformationRegister with `Periodicity` (see\n"
		"`shapes`): a value that was true for a stretch of time. A rate written into a formula\n"
		"re-prints last year's documents at this year's rate, and nothing anywhere says so.\n"
		"\n"
		"HOW THE MODULE PLAYS THE BLANK. Read off two real printing modules - a cash receipt\n"
		"order and a delivery note with a goods table.\n"
		"\n"
		"KEY: A ROW IS NOT ONE AREA. IT IS A ROW BAND CROSSED WITH A LIST OF COLUMN BLOCKS, and\n"
		"the SAME list is replayed for every row band of the table. Header row, detail row and\n"
		"each total row all name the same blocks in the same order - number, code, goods, packing,\n"
		"quantity-and-price, discount, amount. The first block of a row is PUT, which starts a new\n"
		"line; every following one is JOINED to its right. That is the whole mechanics of a table,\n"
		"and it is why `form-to-areas` insists a blank is cut in two directions: a blank cut only\n"
		"downwards cannot be played this way at all.\n"
		"\n"
		"KEY: AN OPTIONAL COLUMN BLOCK IS DECIDED ONCE, BEFORE THE TABLE, AND ITS WIDTH IS GIVEN\n"
		"AWAY - never left as a hole. With the code column off, its width is ADDED to the goods\n"
		"column; the same when the discount pair is off, the same when the packing pair is off.\n"
		"The name column is the accordion that absorbs whatever the row does not show, so the\n"
		"blank keeps its total width whichever blocks appear. Simply omitting a block prints a\n"
		"table narrower than the frame around it.\n"
		"* THE THREE SOURCES OF optional-ness are worth telling apart, because only one is a\n"
		"preference: A SETTING (which extra column - article, code, or neither), THE DATA (the\n"
		"packing block is dropped when the packing total is zero: nothing to show), and THE\n"
		"DOCUMENT'S OWN FLAGS (discounts present, tax accounted). The data one is the one that\n"
		"gets forgotten - a column of zeroes is a column that should not have been printed.\n"
		"\n"
		"KEY: THE QUERY'S FIELD ALIASES ARE THE TEMPLATE'S PARAMETER NAMES. An area is filled in\n"
		"BULK from a query row by matching names, and only then are individual parameters\n"
		"overwritten - those needing formatting, an amount in words, a date in a particular\n"
		"locale, a value fetched from elsewhere. This is why one field is sometimes selected under\n"
		"several aliases in a single query: three parameters of the blank wanted the organisation,\n"
		"so the query hands it over three times under three names. WRITE THE BLANK FIRST AND NAME\n"
		"THE QUERY'S FIELDS AFTER IT; the reverse order leaves a module of one-by-one assignments.\n"
		"\n"
		"NOTE: COLUMN CAPTIONS ARE PARAMETERS, NOT TEXT, far more often than looks necessary.\n"
		"`Price` becomes `Price with tax` or `Price without tax` according to the document, and\n"
		"`Amount` likewise. A caption that can vary at all is a parameter - which is why the count\n"
		"of literal text cells in a real blank is so small.\n"
		"\n"
		"NOTE: EACH TOTAL ROW IS A ROW BAND OF ITS OWN, NAMED AFTER WHAT IT TOTALS, and it carries\n"
		"TWO things in two different blocks - the LABEL in a block to the left, the NUMBER in the\n"
		"money block, so the figure lands under its own column. A delivery note commonly has three:\n"
		"the goods total, the tax total, and a grand total that appears only when tax is added on\n"
		"top rather than included.\n"
		"\n"
		"NOTE: IN A BATCH, THE TEMPLATE IS TAKEN FRESH FOR EACH DOCUMENT, because playing a blank\n"
		"EDITS it - the width donations above are written into the template, not into the output.\n"
		"Two acts on an area are easy to confuse: ADDRESSING the template's own area changes its\n"
		"geometry for everything that follows, while TAKING an area yields a copy to fill and\n"
		"output. Only the first is destructive, and it is the one used for widths.\n"
		"\n"
		"NOTE: A BLANK HAS EDITIONS AND THE DOCUMENT'S OWN DATE PICKS ONE. A cash order module\n"
		"chooses among three templates by comparing the document's date with the two dates on\n"
		"which the form changed by law. This is not a speciality of regulated reporting (see\n"
		"`regulated-forms`) - it happens in ordinary commercial blanks, and it is why a template\n"
		"is looked up BY NAME at print time instead of being bound once.\n"
		"\n"
		"NOTE: THE LANGUAGE IS SET ON THE TEMPLATE, ONCE, BEFORE ANYTHING IS FILLED. The template\n"
		"carries a language code, and setting it switches every translated caption inside it. What\n"
		"the module must supply separately is only the strings it builds itself - which is why\n"
		"those appear in the code with each language written out. A blank printed for a foreign\n"
		"counterparty is one assignment, not a second template.\n"
		"\n"
		"NOTE: A GAP BETWEEN TWO TABLES IS A NAMED BAND WHOSE ONLY JOB IS TO BE EMPTY, and a\n"
		"second table on the same blank gets its own family of column-block names rather than\n"
		"reusing the first's. Signatures are CHOSEN from among several bands - by proxy, against\n"
		"another document, plain - not assembled line by line.\n"
		"\n"
		"NOTE: THE REFUSALS COME FIRST, BEFORE ANY QUERY RUNS. An unsaved document cannot be\n"
		"printed at all; an unposted one is a permission question (see `batch-printing`); a\n"
		"modified one is asked about. All three are settled before the sheet is built, because\n"
		"building it and refusing afterwards throws away the expensive part.\n"
		"\n"
		"NOTE: THE PAGE SETUP IS REMEMBERED UNDER A NAME THE SHEET CARRIES, made of the document\n"
		"and the blank. Two blanks of one document then keep their own margins and orientation,\n"
		"which is what a person expects after adjusting one of them once.") },

	{ wxT("batch-printing"),
	  ibMcpText("Printing fifty documents at once: sets, copies, going straight to the printer."),
	  ibMcpText("PRINTING MANY DOCUMENTS IN ONE GO.\n"
		"\n"
		"`printing` is about ONE blank. This is what changes when a person selects fifty rows in a\n"
		"list and presses print - and it changes more than it looks.\n"
		"\n"
		"KEY: THE ORDER IS BY DOCUMENT, NOT BY BLANK. \"Fifty delivery notes, each with its own\n"
		"invoice behind it\" is the normal request, and it is the opposite of how the sheets are\n"
		"produced - each blank is generated for all fifty at once. The way out costs almost nothing:\n"
		"WHILE GENERATING, EACH DOCUMENT'S ROWS ARE GIVEN A NAMED AREA, and the pairs (document,\n"
		"area) are handed back with the sheet. Printing then loops OVER DOCUMENTS on the outside and\n"
		"over blanks inside, printing one named area at a time.\n"
		"* AND THE SAME NAMED AREAS SERVE A SECOND PURPOSE FOR FREE: \"go to this document\" jumps to\n"
		"the right place in every open sheet at once. One mechanism, two features - which is the sign\n"
		"the mechanism was chosen well.\n"
		"* WHETHER THE MODE IS AVAILABLE IS DECLARED BY THE PRINTING ROUTINE ITSELF, not assumed:\n"
		"a blank that cannot be cut per document says so, and the caller does not try.\n"
		"\n"
		"NOTE: THE NUMBER OF COPIES IS PER BLANK, AND IT IS REMEMBERED. Two copies of the note, one\n"
		"of the invoice - stored against a key made of the printing routine and the list of blanks,\n"
		"and written back only if the person actually changed it. A call whose copy count is dictated\n"
		"by code must be able to say so and suppress both the reading and the writing.\n"
		"\n"
		"NOTE: \"STRAIGHT TO THE PRINTER\" IS A PERSONAL SETTING, NOT A SECOND COMMAND. The same\n"
		"routine either sends the sheet to the printer or opens it, decided by the person's own\n"
		"default. Adding a parallel \"print without preview\" command would double every print command\n"
		"in the system.\n"
		"* AND THE RIGHT TO OUTPUT AT ALL IS A SEPARATE PERMISSION, refused with words rather than\n"
		"silently - a person whose print does nothing will file a bug about the printer.\n"
		"\n"
		"KEY: PRINTING AN UNPOSTED DOCUMENT PRINTS SOMETHING THAT MAY NOT BE TRUE, so the print\n"
		"command itself checks. Collect the unposted ones, ASK ONCE FOR THE WHOLE BATCH rather than\n"
		"once per document, post them, and RE-READ THE SOURCE FORM afterwards - it is now stale, and\n"
		"printing was quite possibly invoked from a list rather than from the form. Whatever still\n"
		"failed to post is dropped from the batch with its own message, and the person is asked\n"
		"whether to continue with the rest.\n"
		"* THERE IS A LEGITIMATE RIGHT TO PRINT A DRAFT - but it is a right, not the default.\n"
		"\n"
		"NOTE: THE LIST OF BLANKS IS BUILT WHEN THE MENU OPENS, from what the OBJECT declares plus\n"
		"whatever has been attached from outside (`extensions`). One button when there is a single\n"
		"blank, a submenu when there are several.\n"
		"STOP: AND DO NOT REMEMBER THE DEFAULT BLANK BY ITS CAPTION. Storing which blank is the\n"
		"default as the TEXT of its menu entry means it is lost by a rename, a removal or a change of\n"
		"interface language - and the failure is silent, because the code then quietly takes the\n"
		"first entry in the list. Store the identity. This one is in the code examined, and it is a\n"
		"defect, not a pattern.\n"
		"\n"
		"NOTE: A BLANK EDITED BY THE CUSTOMER OVERRIDES THE SUPPLIED ONE, and it is looked up in a\n"
		"register by (object, blank name) BEFORE the metadata is consulted. That is why such an edit\n"
		"survives an upgrade: it lives in the DATA, not in the configuration. Found in neither place -\n"
		"raise, do not print an empty sheet.\n"
		"\n"
		"NOTE: SIGNATURES ARE READ AS AT THE DOCUMENT'S DATE, so reprinting last year's note prints\n"
		"last year's director - which is the correct behaviour and surprises people. The position and\n"
		"the person's name come from TWO separate periodic registers, because they change\n"
		"independently.\n"
		"\n"
		"KEY: THE ORDER OF THE BLOCKS IS NOT A DESIGN DECISION - IT IS WHAT MAKES IT RECOGNISABLE.\n"
		"Asked for \"a printed form for this document\" with nothing further, put these in this\n"
		"order, and a person who has seen a hundred of them says yes at a glance:\n"
		" 1. THE DESIGNATION, and for a set form its official code beside the title - M-11, KO-1,\n"
		" TORG-12. A blank whose code somebody can quote is a blank they trust.\n"
		" 2. THE ORGANISATION - name and registration codes, conventionally boxed at a corner\n"
		" rather than in the running text.\n"
		" 3. THE IDENTITY - number and date. One line, one phrase, and the standing case for a\n"
		" TEMPLATE cell rather than three: `No. [Number] of [Date]`.\n"
		" 4. THE PARTIES AND THE OCCASION - from whom, to whom, which warehouse, which contract.\n"
		" 5. THE TABLE - its heading, then the detail band, with a LINE NUMBER as the first\n"
		" column. Somebody will refer to \"line four\" over the telephone.\n"
		" 6. THE TOTALS - and they must total exactly what is above them, which is why an\n"
		" optional column block has to be optional in the footer too.\n"
		" 7. THE AMOUNT IN WORDS, on a money document. Not decoration: it is the line the paper\n"
		" is checked against, and it is a parameter like any other.\n"
		" 8. THE SIGNATURES - position, name, and room to sign. A ruled blank under each, which\n"
		" is what makes an unfilled form usable at all.\n"
		"\n"
		"STOP: AND THE PARTIES ARE A BLOCK OF REQUISITES, NOT A LINE. This is where a first attempt is\n"
		"thinnest and where a person notices immediately. A real note identifies each side by what a\n"
		"bank and a tax office need: the name, the account and the bank it is at, the address, the\n"
		"registration codes - four or five parameters per party, stacked, with the label to the left\n"
		"and the block to the right. `From [Warehouse] to [Counterparty]` on one line is a summary,\n"
		"not an identification, and no accountant will accept it as the document.\n"
		"\n"
		"STOP: A TOTAL DOES NOT LIVE IN A CELL OF ITS OWN - IT STANDS UNDER ITS COLUMN. The label\n"
		"(`Total:`, `of which VAT:`) is right-aligned across the columns to the LEFT of the money,\n"
		"and each figure sits directly beneath the column it totals. That is what makes it readable\n"
		"as a total rather than as another row, and it is also why an optional column block has to\n"
		"be optional in the footer: drop the discount column and its total must go with it, or the\n"
		"footer adds up a column that is not on the page. Expect a STACK here, not one line - a\n"
		"sum, the tax within it, the amount to pay.\n"
		"\n"
		"KEY: THE PARAMETER NAMES HAVE A GRAMMAR, AND IT IS WORTH COPYING. Read off the blanks of a\n"
		"working configuration, every name is built the same way and none of them is a bare noun:\n"
		" WHAT, THEN WHOSE. `OrganisationName`, `OrganisationTaxCode`, `OrganisationBank`,\n"
		" `OrganisationBankAccountNumber` - the thing first, the owner after, so everything about\n"
		" one party sorts together and a reader knows whose figure they are looking at.\n"
		" OR WHAT, THEN WHICH FACET. `UnitOfMeasureCode` beside `UnitOfMeasureName` - one subject,\n"
		" two of its faces, told apart in the name rather than by position.\n"
		" A SIGNATURE IS NAMED BY THE ACT, NOT BY ITS PLACE. `Released`, `Received`, `IssuedBy`,\n"
		" `AuthorisedRelease`, `ReceivedFrom` - never `Signature1` and `Signature2`. The name says\n"
		" what the person DID, which is the only thing that distinguishes two ruled lines.\n"
		" A DIGIT MEANS A REPEATED SLOT AND NOTHING ELSE. A tax invoice that holds ten\n"
		" counterparty codes writes `CounterpartyTaxCode_1` … `_10`, with the underscore, because\n"
		" the form genuinely has ten places. A digit reached for to tell two unlike things apart is\n"
		" the mistake this convention exists to make visible.\n"
		" A RENDERED REFERENCE SAYS SO. `SupplierPresentation` is the printable form of a\n"
		" reference; the reference itself is a different thing and is not what goes on paper.\n"
		"\n"
		"NOTE: AND TWO OF THEM ARE COARSER THAN THEY LOOK. A party's whole requisite block is often\n"
		"ONE parameter carrying several lines - `SupplierRequisites` - rather than five, because the\n"
		"module composes it from the counterparty once and the blank has nothing to decide. And the\n"
		"CAPTIONS are sometimes parameters too (`HeadingText`, `BuyerLabel`, `SupplierLabel`), which\n"
		"is how one template serves an invoice and an order: the words change, the layout does not.\n"
		"\n"
		"KEY: AND A TOTAL IS NAMED AFTER THE COLUMN IT SUMS, never `Total`. A blank has as many\n"
		"totals as it has money columns - an invoice foots the amount before discount, the discount\n"
		"and the amount with tax, three of them in a row - and `Total` can only be one of the three.\n"
		"The next one becomes `Total2`, and from that moment nothing in the name says which column\n"
		"it belongs under: the module fills them by name, and the two most similar things in the\n"
		"form are told apart only by a digit.\n"
		"Name it for its column - `QuantityTotal`, `AmountTotal`, `VatTotal` - and three things\n"
		"follow at once. The name says what it is AND what it is of. A reader checking the footer\n"
		"against the table can pair them without counting across. And when an optional column block\n"
		"is left out, its total is the one obviously going with it, instead of a number in the\n"
		"footer that nobody can now attribute.\n"
		"\n"
		"STOP: SIGNATURES ARE A ROW OF PARTIES, NOT A LINE AT THE BOTTOM. Two or three blocks side\n"
		"by side - who released it, who received it, sometimes on whose authority - each with its\n"
		"own caption, its own rule to sign on and its own small print underneath. Where a field\n"
		"carries a condition it is MARKED, with an asterisk against it and the sentence it refers\n"
		"to set small at the foot of the page. A single `Issued by ______` is the shape of a\n"
		"receipt, not of a document two organisations both keep a copy of.\n"
		"\n"
		"NOTE: WHAT DIFFERS BETWEEN KINDS IS WHICH OF THESE SWELLS, NOT THE ORDER. A goods note is\n"
		"mostly its table. A tax invoice is mostly its parties block and its codes, and its totals\n"
		"carry a rate per line. A reconciliation act has TWO tables facing each other and its\n"
		"footer is a balance rather than a sum. A fixed-asset record is mostly a header of\n"
		"attributes with a short table and a commission's several signatures. Recognise which one\n"
		"is being asked for and the proportions follow; the skeleton does not move.") },

	{ wxT("query-craft"),
	  ibMcpText("How accounting queries are actually written - the constructs and why those and not others."),
	  ibMcpText("THE HABITS OF A WORKING QUERY, counted in a real configuration rather than guessed.\n"
		"\n"
		"KEY: LEFT JOIN IS THE DEFAULT, AND BY A LONG WAY - seven of them for every inner one. The\n"
		"reason is not taste: in accounting the LINE must survive even when what it is joined to is\n"
		"absent. An item with no price, a document with no agreement, a lot with no cost yet - an\n"
		"inner join silently DROPS those rows, the totals come out lower, and nothing anywhere says\n"
		"a row was lost. Use inner only when the absence genuinely means the row should not be\n"
		"there, and say to yourself which case you are in.\n"
		"\n"
		"STOP: AND EVERY LEFT JOIN OBLIGES A NULL GUARD. A missing row gives NULL, and NULL poisons\n"
		"arithmetic - added to a number it yields NULL, and the sum of a column with one NULL in it\n"
		"is NULL, not the sum of the rest. So numeric fields coming from the joined side are wrapped\n"
		"the moment they are selected. In the configuration measured, null-guards appear about as\n"
		"often as left joins do, which is the correct ratio: one per join, not one per bug found.\n"
		"\n"
		"* CASE EXPRESSIONS OUTNUMBER EVERYTHING - more than one per query on average. They do two\n"
		"jobs: CLASSIFY (what kind of movement is this, which column does this amount belong in) and\n"
		"PROTECT (a divisor that might be zero, a rate that might be absent). Both belong in the\n"
		"query rather than in the loop that reads it - the database decides once per row, the loop\n"
		"decides once per row per reader.\n"
		"KEY: AND THE THIRD JOB OF A CASE IS TO PIVOT - one row per subject with a column per kind,\n"
		"written as an aggregate over a CASE and joined back with a LEFT join so that a subject with\n"
		"NO rows at all still appears. That absence is usually the case being looked for; an inner\n"
		"join hides exactly the failures the check exists to find.\n"
		"STOP: BUT A PIVOT OVER A GROUPED SET TAKES EACH COLUMN INDEPENDENTLY, so the six columns\n"
		"describing \"the external certificate\" can come from SIX DIFFERENT RECORDS - a number from\n"
		"one, a start date from another - and the row reads as one coherent object. Where more than\n"
		"one record can match a key, either reduce to one record first and pivot the winner, or add a\n"
		"count of the matches and refuse to present the row as a single answer.\n"
		"\n"
		"FILTER BEFORE GROUPING, NOT AFTER. Conditions on the source rows go in the WHERE; the\n"
		"configuration measured uses HAVING exactly zero times in a megabyte of queries. Filtering\n"
		"after aggregation means aggregating what will be thrown away, and it reads as if the filter\n"
		"were about the totals when it is about the rows.\n"
		"\n"
		"UNION ALL, NOT UNION - forty-seven to seven. Combining movements from several sources does\n"
		"not want duplicate elimination: it costs a sort over everything, and worse, it MERGES rows\n"
		"that were legitimately identical - two receipts of the same item, same quantity, same day\n"
		"are two facts, and plain UNION quietly makes them one.\n"
		"KEY: AND COMPARING TWO SETS IS A UNION WITH DISJOINT COLUMNS AND A TOTAL, NOT AN OUTER JOIN.\n"
		"Put both sides into one selection where each fills only its own quantity columns and writes\n"
		"zeros into the other side's, group by the coordinates they share, and the comparison becomes\n"
		"a subtraction on one row. An outer join over eight coordinates, several of them references\n"
		"that may be empty, is slower and wrong at the edges: a coordinate present on one side only\n"
		"either vanishes or duplicates.\n"
		"* ASK FOR TOTALS BY THOSE COORDINATES and walk the result as a hierarchy, so the group row\n"
		"carries \"what the document says\" beside \"what the register says\". An attribute existing on\n"
		"ONE side only is absent from the group row - scan the detail rows for the first that has it\n"
		"and stop once each has been found, rather than adding it to the grouping key.\n"
		"\n"
		"STOP: A CONDITION OF A JOIN IS NOT A CONDITION OF THE QUERY, and moving one into the WHERE is\n"
		"the mistake that looks like tidying. `LEFT JOIN Prices ON ... AND Prices.Kind = &Kind` keeps\n"
		"every row of the left side and joins only the matching price. Move that last test into the\n"
		"WHERE and rows whose price did not match now have NULL there, the test rejects them, and\n"
		"the left join has silently become an inner one - fewer rows, smaller totals, nothing\n"
		"reported. Conditions ABOUT THE JOIN stay in the join; conditions about which rows the query\n"
		"is interested in go in the WHERE.\n"
		"\n"
		"* REACHING THROUGH A DOT IN A QUERY IS A JOIN THE ENGINE WRITES FOR YOU. `Line.Item.Unit`\n"
		"is convenient and honest in a small selection; in a WHERE, or three dots deep, or over a\n"
		"large table, it becomes joins nobody chose and nobody sees in the text. Where it matters,\n"
		"write the join yourself - then the kind of join is a decision (`LEFT` keeps the row when\n"
		"the reference is empty, which the implicit one may not) and the reader can see what the\n"
		"query actually touches.\n"
		"NOTE: The related habit: a dotted path in a CONDITION is the expensive one. Selecting it for\n"
		"display is usually fine; filtering by it makes the engine join before it can filter.\n"
		"\n"
		"* PARAMETERS ARE ALSO WHAT MAKES A QUERY REUSABLE TO THE DATABASE. The same text with a\n"
		"parameter is one prepared plan reused for every value; the same text with the value glued\n"
		"in is a NEW query each time, planned from scratch and filling the cache with single-use\n"
		"entries. That is on top of the type-safety and injection reasons in `query-by-name`.\n"
		"\n"
		"* AND SEVERAL RELATED SELECTIONS TRAVEL AS ONE BATCH - the steps of a calculation sent in a\n"
		"single call rather than one round trip apiece. Same reasoning as the loop rule above, one\n"
		"level up: the cost is in the trips, not in the reading.\n"
		"\n"
		"NOTE: AND A QUERY ONLY READS. It cannot write, and anything that changes data is a separate\n"
		"act afterwards - which is why the shape of a posting is \"read everything, decide, then\n"
		"write\" (`posting`) rather than a query that does the work.\n"
		"\n"
		"KEY: NAME THE TABLES BY THE ROLE THEY PLAY IN THIS QUERY, not by what they are. A register\n"
		"joined to itself is the clearest case: the two copies are `Accruals` and `Endings`, not\n"
		"`T1` and `T2` - one is the record, the other is what comes after it, and the condition\n"
		"between them then reads as a sentence. The same everywhere else: `Balances`, `Movement`,\n"
		"`Salaries`, `TimeNorms`, `FullDistributionBase`. A query with `Doc`, `Doc1`, `Doc2` in it\n"
		"cannot be reviewed - every reader has to reconstruct which is which before they can look\n"
		"for the mistake.\n"
		"* And name a temporary table after its CONTENT for the same reason, since it becomes a\n"
		"source in the next step: `LotsAvailable`, `EmployeesAndAssignments`. The name is what the\n"
		"step after it reads.\n"
		"* AND A LONG TEXT IS MADE READABLE BY CONVENTION, SINCE NOTHING ELSE WILL DO IT. The longest\n"
		"text in the system measured is 438 lines and is legible because it is FIVE statements, each\n"
		"separator followed by a full-width banner comment inside the text itself, with blank lines\n"
		"between groups of fields and each step's name saying what that step produced rather than what\n"
		"it is. Nothing strips a line of slashes, so the apparatus survives every edit. It costs\n"
		"nothing and it is the difference between a text that gets reviewed and one that gets\n"
		"replaced.\n"
		"KEY: NAME A PARAMETER AFTER THE BUSINESS THING IT HOLDS, NOT AFTER ITS ROLE IN THE QUERY.\n"
		"Counted in a working system: 2905 bindings over 926 distinct names, and the commonest are the\n"
		"company, the reference, the period ends, the warehouse, the item. The same name then means\n"
		"the same thing in every query in the system, so a reader moving between modules re-learns\n"
		"nothing.\n"
		"* AND IT PAYS A SECOND TIME WHERE A CLAUSE IS GENERATED: walk the filter, and for each item\n"
		"in use append a condition naming the field while binding under that same identifier. Text and\n"
		"binding are derived from one word in one loop, so they cannot drift apart. The exceptions are\n"
		"named for their VALUE - an empty-of-this-type parameter - because they stand where a field\n"
		"would have been rather than holding one.\n"
		"\n"
		"KEY: ASK THE REGISTER, NOT THE MOVEMENTS. Virtual tables - balances, turnovers, both at once,\n"
		"the latest values as of a date - are used constantly, and the combined balance-and-turnover\n"
		"table more than the separate ones: opening, movement and closing in ONE pass, already\n"
		"aggregated by the engine, instead of two queries whose results have to agree. Summing the\n"
		"movement table by hand to get a balance is slower, longer, and wrong the day the register\n"
		"keeps totals.\n"
		"* For anything periodic - prices, rates, policies, states - the latest-as-of-a-date table is\n"
		"the whole answer.\n"
		"\n"
		"STOP: AND THE PARAMETERS GO INSIDE THE TABLE'S OWN BRACKETS, NEVER INTO THE WHERE. This is the\n"
		"single most expensive habit to get wrong, and both versions look correct:\n"
		"\n"
		" RIGHT: FROM AccumulationRegister.Stock.Balance(&AsOf, Warehouse = &Warehouse) AS B\n"
		" WRONG: FROM AccumulationRegister.Stock.Balance() AS B WHERE B.Warehouse = &Warehouse\n"
		"\n"
		"A virtual table is not a table - it is a CALCULATION the engine performs, and its\n"
		"parameters are the terms of that calculation. Put the date and the condition inside, and\n"
		"the engine folds the register up to that moment for that warehouse alone. Put them in the\n"
		"WHERE, and it computes balances for EVERY warehouse over the whole history, and then throws\n"
		"away all but one. On a small base both answer the same; on a real one the second is the\n"
		"reason a report takes four minutes.\n"
		"KEY: AND THE FILTER INSIDE THOSE BRACKETS SHOULD CARRY THE DOCUMENT'S OWN VALUES. Unload the\n"
		"column, drop the duplicates, and build \"= one value\" when one remains or \"IN (a set)\"\n"
		"otherwise. That is what decides whether the balance is computed over three rows or over the\n"
		"whole register - and it is the difference between a posting that is instant on a one-line\n"
		"document and one that is not.\n"
		"* THE SCALAR CASE IS WORTH THE EXTRA BRANCH: a single value gives the database a far better\n"
		"plan than a one-element set.\n"
		"\n"
		"NOTE: AND SOMETIMES IT IS NOT EVEN THE SAME ANSWER. A period is a parameter of the calculation,\n"
		"not a column of the result: a balance table has no period to compare in a WHERE at all, and\n"
		"a turnover table's period means something different from the boundary that produced it.\n"
		"Filtering afterwards on what looks like the same field can silently give figures nobody\n"
		"ordered.\n"
		"\n"
		"WHICH VIRTUAL TABLE TO ASK FOR is the question before that one:\n"
		" BALANCE - \"what is left\", as of a moment. One row per key.\n"
		" TURNOVER - \"how much moved\", over a period, optionally broken by month or day.\n"
		" BALANCE AND TURNOVER - opening, movement, closing in ONE read. Ask for this whenever a\n"
		" report shows all three: two separate queries over the same register cost twice and can\n"
		" disagree at the boundary.\n"
		" LATEST AS OF A DATE - for a periodic information register: the value in force.\n"
		" THE MOVEMENT TABLE ITSELF - only when the individual records are the subject: an audit\n"
		" of who wrote what, a card of one account. Never for computing a balance.\n"
		"NOTE: AND IN PRACTICE THE VOCABULARY IS TWO WORDS. Counted over 866 virtual-table calls in a\n"
		"working system: 432 are the latest-as-of-a-date of a periodic register and 376 are balances;\n"
		"turnovers and the combined table together are under sixty, and the empty bracket appears\n"
		"twice in the whole system. So the two habits worth drilling are these two tables and the\n"
		"condition INSIDE the brackets - 321 of the 376 balance calls and 285 of the 432 slice calls\n"
		"carry it there. Everything else here is refinement on top of those two.\n"
		"\n"
		"NOTE: AND A TEMPORARY TABLE IS THE OTHER THING ENTIRELY, though both are \"tables that do not\n"
		"exist\". A virtual table is the ENGINE'S answer about a register; a temporary table is YOUR\n"
		"intermediate result, built by a step of your own query and indexed by you. Use the virtual\n"
		"one to ask, the temporary one to keep - and pass the set you already hold into the\n"
		"temporary one rather than into a loop (see `query-by-name`).\n"
		"\n"
		"TEMPORARY TABLES ARE THE UNIT OF A BIG QUERY (see `query-by-name`), indexed on their join\n"
		"fields and DROPPED when the calculation no longer needs them - a long posting holds several\n"
		"at once, and they cost memory on the server for as long as the manager lives.\n"
		"* AND THIS IS ADVICE THAT IS ROUTINELY NOT FOLLOWED, WHICH IS ITSELF THE LESSON: measured\n"
		"across a working configuration, roughly four in five temporary tables carry no index at all\n"
		"and are never dropped explicitly - they are left to the manager's lifetime. It works until a\n"
		"posting grows, and then nothing points at the cause. If you take one habit from this entry,\n"
		"take indexing the join field.\n"
		"KEY: AND WHERE THE ANSWER IS CIRCULAR - transfers between warehouses making cost depend on\n"
		"itself - ITERATE IN THE DATABASE, NOT IN MEMORY. One query primes the working table; then\n"
		"each pass writes the next approximation into a SECOND table, measures the deviation, drops\n"
		"the old table, copies the new one back under the canonical name and drops the scratch. Two\n"
		"names alternating, both indexed on their join fields, both recreated every pass.\n"
		"* THE LOOP COUNT IS THE NUMBER OF ITERATIONS, NEVER THE NUMBER OF ROWS - every query in it\n"
		"reads the whole set - which is exactly the distinction the rule about queries in loops is\n"
		"reaching for. End on convergence or on an iteration cap, AND REPORT BOTH NUMBERS: a cap with\n"
		"no report is a wrong answer that looks like a right one.\n"
		"* A TEMPORARY TABLE IS ALSO AN UNDECLARED CONTRACT. In the same configuration one table name\n"
		"is written with four different column sets in two modules, with nothing anywhere saying what\n"
		"it should contain. Where several routines fill one table, its columns are an interface -\n"
		"write them down beside it (`production`: the fixed column list is the interface of a whole\n"
		"posting module).\n"
		"* AND A BATCH IS USUALLY RUN FOR ITS TABLES, NOT FOR ITS RESULTS - about fifteen batches for\n"
		"every one whose results are read back. That is the normal shape: the batch prepares, one\n"
		"final selection answers.\n"
		"\n"
		"KEY: HOW LONG WAS THAT VALUE IN FORCE - the standing trick, and the one worth memorising. A\n"
		"periodic register stores WHEN a value started and never when it ended: the rate of the 3rd\n"
		"holds until the next rate appears. To get the interval - and from it the number of days -\n"
		"JOIN THE REGISTER TO ITSELF:\n"
		" the left copy is the record itself, and its period is the start;\n"
		" the right copy is joined on the SAME KEY - every dimension, the currency, the employee,\n"
		" the item - with the one extra condition that its period is LATER;\n"
		" take the MINIMUM of those later periods, and that is the end of the interval: the\n"
		" moment the next value took over.\n"
		"\n"
		"STOP: AND IT MUST BE A LEFT JOIN. The newest record has no successor, so an inner join drops\n"
		"exactly the row that matters most - the value in force TODAY. Its end comes back empty,\n"
		"which is the correct answer and reads as \"still current\"; substitute the end of the period\n"
		"being reported when a number is needed.\n"
		"NOTE: AND THE KEY MUST BE COMPLETE. Join on fewer dimensions than the register has and the next\n"
		"record of ANOTHER currency ends this one's interval - the query still runs, the durations\n"
		"are simply wrong, and they are wrong only where the data is dense enough to overlap.\n"
		"\n"
		"Days in force is then the difference between the two dates, and \"which value applied on\n"
		"date X\" is the interval containing it. Where the platform offers window functions the same\n"
		"answer is one line - the next period over a partition - and the self-join is what to write\n"
		"when it does not.\n"
		"* THE SAME SHAPE ANSWERS MORE THAN RATES: how long an employee held a position, how long a\n"
		"price stood, how long an asset was in one department, when a status ended. Any register\n"
		"that records starts and expects the reader to infer ends.\n"
		"* AND WHERE THAT ANSWER IS NEEDED ON EVERY LINE OF EVERY MONTHLY RUN, IT GETS STORED. A\n"
		"working system keeps BOTH: the periodic register answering \"what is it now\", and a second\n"
		"register of INTERVALS - from, to, what - answering \"how long\". The same fact twice, on\n"
		"purpose (`derived-registers`); the price is that the intervals must be rebuilt whenever\n"
		"something is entered backdated.\n"
		"\n"
		"KEY: A SCALE IS READ AS ONE GENERATION, NEVER ROW BY ROW. Discount thresholds, price bands,\n"
		"tax brackets - a SET of rows that only means anything together. Reading them with an\n"
		"ordinary \"latest per key\" quietly assembles a chimera: the first threshold as it was in\n"
		"March, the second as amended in July. Take the latest PERIOD for the scale as a whole, then\n"
		"all rows of that period. The defect is invisible until someone edits one row of a scale.\n"
		"\n"
		"THREE SMALLER ONES THAT COME UP CONSTANTLY:\n"
		" TOTALS IN THE QUERY when the result is going to be walked as a hierarchy - the engine\n"
		" produces the group rows, so the reading code never accumulates by hand and never\n"
		" disagrees with the report.\n"
		" IN HIERARCHY for a filter by a folder: \"everything under this product group\" is one\n"
		" condition, not a recursive walk.\n"
		" CAST a composite field before reaching through it - a field that may hold several types\n"
		" has no attributes until it is narrowed to one, and the message when it is not narrowed\n"
		" names the field rather than the reason.\n"
		" AND CAST EVERY REFERENCE COLUMN OF AN IN-MEMORY TABLE ON ITS WAY INTO A QUERY. A table\n"
		" built in code has untyped columns, and a join between an untyped column and a real table\n"
		" does not fail - IT MATCHES NOTHING, and the calculation comes out empty with no message\n"
		" anywhere. The price is that the caller must know and restate the type of every column it\n"
		" is smuggling in, which is why this road is taken rarely and why a temporary table filled\n"
		" by an earlier step is usually the better one.\n"
		"\n"
		"NOTE: AND THE ONE THAT SAVES THE MOST TIME: run the query alone, on real data, before it is\n"
		"embedded in anything (`query_check` resolves the names; a debugger stop shows the rows).\n"
		"Most \"the posting is wrong\" turns out to be \"the query returned rows nobody looked at\".") },

	{ wxT("query-by-name"),
	  ibMcpText("Assembling a query text so one routine serves many kinds - and where that stops."),
	  ibMcpText("ONE QUERY INSTEAD OF TEN NEARLY IDENTICAL ONES.\n"
		"\n"
		"\"Find the document of kind X that was created from this one\" is the same query for every\n"
		"kind - only the TABLE NAME differs. Written out per kind it is ten copies to keep in step,\n"
		"and the eleventh kind arrives without one. Written once, with the kind's name assembled\n"
		"into the text, it is a routine that works for a kind added tomorrow:\n"
		"\n"
		" query.SetParameter(\"Base\", reference);\n"
		" query.Text = \"SELECT ALLOWED Ref FROM Document.\" + kind + \" WHERE Base = &Base\";\n"
		"\n"
		"KEY: AND WHERE THE BRANCHES ARE FIXED AND ONLY THEIR PARTICIPATION VARIES, SWITCH THEM WITH\n"
		"BOUND PARAMETERS INSTEAD OF ASSEMBLING TEXT. A settings reader whose three storeys of\n"
		"visibility - this person, their group, everybody - are three branches of one union writes\n"
		"each branch with its own switch in the WHERE and binds a flag per branch. ONE prepared text\n"
		"serves all eight combinations, the compiler and the checker see it whole, and there is\n"
		"nothing to misassemble.\n"
		"* THE COST IS THAT EVERY BRANCH IS PLANNED EVERY TIME, even the switched-off ones. That is\n"
		"the right trade for a few small branches and the wrong one for branches over large tables -\n"
		"which is the question to ask before choosing between this and assembly.\n"
		"\n"
		"STOP: AND HERE IS THE LINE, WHICH IS NOT A STYLE PREFERENCE. What may be glued into the text\n"
		"is STRUCTURE - a table name, a field name - and it comes from the METADATA. What must never\n"
		"be glued in is a VALUE: a reference, a date, anything a person typed. Values go through\n"
		"parameters, always, and not only because of injection - a parameter carries its TYPE, so a\n"
		"reference stays a reference and a date does not become a string that happens to look like\n"
		"one.\n"
		"* AND THE LINE HOLDS IN PRACTICE, WHICH IS WORTH KNOWING BECAUSE IT MAKES THE RULE\n"
		"CHECKABLE: measured over three hundred thousand lines of a working configuration, not one\n"
		"string value is glued into a query text, and the six numeric ones that are sit exactly where\n"
		"the grammar forbids a parameter - a row limit, a date built from three literals. If an audit\n"
		"finds more than a handful, they are not exceptions, they are a habit.\n"
		"STOP: A PARAMETER MAKES A VALUE SAFE; IT DOES NOT MAKE A PATTERN SAFE. Text a person typed\n"
		"and bound into a pattern match is still read as a pattern: a per-cent sign matches\n"
		"everything, an underscore matches any character, so searching for \"100%\" returns the whole\n"
		"catalogue and searching for a code with an underscore returns its neighbours.\n"
		"* THE FIX IS ONE SHARED ROUTINE - double the escape character, then escape the pattern\n"
		"metacharacters - AND THE CLAUSE THAT DECLARES THE ESCAPE CHARACTER IN THE QUERY. Both, or\n"
		"neither works. Measured in a working system, the routine existed, was correct, and was\n"
		"reached for by four callers out of thirty-three, because nothing about writing a pattern\n"
		"match prompts the question.\n"
		"\n"
		"NOTE: A NAME ASSEMBLED IS A NAME UNCHECKED. The compiler cannot see inside a string, so a\n"
		"misspelled kind fails when the routine runs - and only for that kind. Two habits pay for\n"
		"themselves: take the name FROM the metadata rather than from a caller's spelling, and put\n"
		"the finished text through the query checker before it is stored (`query_check` reads it the\n"
		"way the engine will, resolving every name against this configuration).\n"
		"KEY: ASSEMBLING A QUERY TEXT IS THE MAJORITY CASE, NOT A TRICK KEPT FOR ONE ROUTINE. Counted\n"
		"over a working configuration: of about a thousand multi-line query texts, 458 are written\n"
		"whole and 551 carry at least one hole. So the question is never whether to assemble, it is\n"
		"WHICH HOLE, and there are three with different contracts: CONCATENATION carries names, a\n"
		"NAMED SLOT carries a name that must always be filled, a COMMENTED-OUT LINE carries a whole\n"
		"branch that may stay off. Mixing them at random is what makes generated text unreadable;\n"
		"choosing by contract is what makes it reviewable. The discipline is deciding, per hole, what\n"
		"happens when nobody fills it.\n"
		"KEY: A HOLE THAT MAY STAY AND A HOLE THAT MUST BE FILLED MUST NOT LOOK ALIKE. A commented-out\n"
		"branch left alone is a MISSING FEATURE; a named slot left alone is a CRASH, because the\n"
		"delimiters reach the parser. Spell them differently and a reader knows which risk they are\n"
		"looking at.\n"
		"* SO EVERY SLOT IS FILLED ON BOTH SIDES OF THE DECIDING BRANCH - the real column name where\n"
		"the dimension is kept, the empty value of its type where it is not - and never with nothing.\n"
		"A slot may also be a FRAGMENT of a name, not a whole one: parallel registers whose names\n"
		"differ by one word are addressed by one text with the word as a slot. Nothing in the platform\n"
		"can validate a name assembled that way, so the vocabulary of fragments must be closed and\n"
		"live in one place.\n"
		"STOP: NOTHING CHECKS THAT EVERY BRANCH FILLS EVERY SLOT. In the system measured, one branch\n"
		"of five did not, and the text was correct only as long as nobody ran that combination. That\n"
		"is the standing price of switching by text - a substitution table has no completeness a\n"
		"compiler can hold - so write the table's rows and its columns down beside it and check them\n"
		"by eye when either grows.\n"
		"STOP: AND DO NOT GIVE A GLUED HOLE THE SIGIL OF A BOUND PARAMETER. A text in which the table\n"
		"name and the value being matched are both written as parameters, where the first is replaced\n"
		"by string substitution and the second is bound, shows a reader two holes of equal weight, and\n"
		"only the code below says which is which. The whole point of the line between structure and\n"
		"value is that it is visible in the text; a shared sigil erases it. Mark the substituted hole\n"
		"so it cannot be mistaken for a binding - any spelling a parameter cannot have - and the audit\n"
		"that counts glued values stays possible.\n"
		"KEY: AN OPTIONAL FIELD CARRIES THE COMMA THAT FOLLOWS IT, AND THE LAST FIELD OF A SELECT LIST\n"
		"IS NEVER OPTIONAL. Optional fields are inserted BEFORE a mandatory one, each ending in its\n"
		"own comma, so removing any subset of them still leaves a valid list. Counted in a working\n"
		"system: 155 glued fragments end with a comma and 5 begin with one.\n"
		"STOP: LEADING COMMAS INVERT THE RULE AND MAKE THE FIRST FIELD LOAD-BEARING - the text is\n"
		"correct in every case except the one customer who has none of the optional fields, which is\n"
		"exactly the case nobody tests. The same rule holds for a clause keyword: the WHERE belongs to\n"
		"the clause that generates it, prepended only if at least one condition survived, or the text\n"
		"ends in a bare WHERE.\n"
		"KEY: A BUILDER THAT DOES NOT YET KNOW WHAT IT WILL EMIT BINDS EVERYTHING AND REFERENCES WHAT\n"
		"IT EMITS. A search box over a field of unknown type asks the metadata for the field's\n"
		"declared type and emits either a pattern match or an equality; both candidate parameters are\n"
		"bound first - the numeric one inside a guard, left undefined when the typed text is not a\n"
		"number - so whichever text is built is complete. Binding a parameter the text does not\n"
		"mention is free; referencing one that was not bound is a failure at run time.\n"
		"* AND THE ALIAS THE GENERATED CONDITION HANGS ON IS AN ARGUMENT, not a guess, because the\n"
		"caller knows whether its query has a subquery layer between the filter and the table.\n"
		"\n"
		"AND SAY ALLOWED. A query in code that ignores access rights either shows a person rows they\n"
		"may not see or fails outright when a narrower role runs it; ALLOWED drops what the reader\n"
		"may not have instead.\n"
		"STOP: BUT IT ONLY DROPS ROWS OF THE TABLE BEING READ - IT DOES NOT PROTECT A FIELD REACHED\n"
		"THROUGH A DOT. Where a forbidden object is reached through a reference, the join yields\n"
		"nothing and the row comes back with empty columns rather than being excluded, so a total\n"
		"quietly loses it. Guard those explicitly (\"and the referenced thing is not missing\") on\n"
		"every dotted field that crosses a restriction (`row-level-access`).\n"
		"NOTE: MEASURED, SAYING IT IS NOT THE HABIT - 215 of 2639 selections do, 8 per cent, against\n"
		"148 places that switch the checks off altogether. The distribution is defensible: the readers\n"
		"that feed a person's own screen say it, and the posting, costing and exchange machinery runs\n"
		"privileged because a total must not depend on who is asking (`row-level-access`).\n"
		"STOP: BUT NOTHING MARKS WHICH SIDE OF THAT LINE A ROUTINE IS ON, so a screen-facing reader\n"
		"that drifts into privileged mode is invisible and no test catches it. Say it in the name or\n"
		"the note of every reader: whose eyes this answer is for. It costs a word and it is the only\n"
		"record there is.\n"
		"KEY: AND EXISTENCE IS NOT A RIGHTS QUESTION - the routine that answers \"does this reference\n"
		"physically exist\" runs privileged. A thing the reader may not see still EXISTS, and a check\n"
		"that answers \"no\" for it makes every caller's cleanup wrong: references get treated as\n"
		"broken, rows get deleted, links get rebuilt. Ask with the checks off, deliberately, and say\n"
		"in the routine's note that this is why. And take the table name from the value's own type\n"
		"through the metadata, in one call - a cascade of \"is it one of these fourteen kinds\" derives\n"
		"what one lookup already knows and disagrees with the other three cascades in the same layer\n"
		"about what it covers (`shapes`).\n"
		"\n"
		"NOTE: AND WHERE A REPORT FAILS FOR ONE PERSON AND NOT ANOTHER, KEEP EVERY QUERY IT RAN so\n"
		"they can be REPLAYED in order under a fresh set of temporary tables. That is what separates\n"
		"\"you lack the rights\" from \"this is a defect\" - and without it the two are indistinguishable\n"
		"from the outside, which is why such reports get reported as bugs for years.\n"
		"NOTE: THE SHAPE THAT MAKES THAT CHEAP IS A QUERY AS PLAIN DATA - one record whose key \"text\"\n"
		"holds the text and whose every other key is a bound parameter with its value. Recording is\n"
		"then seven lines and replaying is two: assign the text, bind the rest. It also fixes a naming\n"
		"rule by construction - no parameter may be called by the name the text is filed under. The\n"
		"same record is storable and sendable, which is what lets a failure be reproduced somewhere\n"
		"other than where it happened.\n"
		"\n"
		"KEY: AN OPTIONAL DIMENSION IS NOT REMOVED FROM THE QUERY - IT IS REPLACED BY AN EMPTY VALUE.\n"
		"Where a setting decides whether stock is kept by series, by variant, by warehouse, the text\n"
		"keeps the column and substitutes the empty reference of that type wherever the dimension is\n"
		"switched off. The column count, the joins and the shape of the result are then INVARIANT\n"
		"under the setting, and no caller has to branch on it. Deleting the column instead means\n"
		"every reader downstream learns about the setting too (`posting`: an empty dimension is a\n"
		"legitimate value, not a missing one).\n"
		"\n"
		"NOTE: WHEN NOT TO. If the branches differ in more than a name - different joins, different\n"
		"conditions, different fields - one assembled text becomes a query nobody can read and the\n"
		"compiler cannot help with. Then they really are several queries, and saying so is cheaper\n"
		"than a string built out of ifs.\n"
		"KEY: WHERE BRANCHES DIFFER BY WHOLE LINES RATHER THAN BY A NAME, WRITE EVERY LINE AND COMMENT\n"
		"OUT THE ONES THIS RUN DOES NOT WANT. Each line of a branch carries the comment marker as its\n"
		"FIRST token, so the text parses in every combination and no combination can leave a dangling\n"
		"comma or an unclosed bracket; switching the branch on is one replace-all that deletes the\n"
		"marker. A branch cannot be half taken, and markers COMPOSE - a general marker stripped first,\n"
		"then the specialised one, which is how one text serves a family of ledgers. Measured in a\n"
		"working system, 3480 query lines are switched on exactly this way.\n"
		"* AND IT WORKS INSIDE A VIRTUAL TABLE'S BRACKETS TOO, so an optional pre-aggregation filter\n"
		"needs no second text.\n"
		"STOP: THE SWITCHING BELONGS IN ONE ROUTINE - a kind in, a finished text out - not at the call\n"
		"sites. In the system measured, one 40-line function served 157 of them, so the marker\n"
		"vocabulary had one definition. Spread across callers, it becomes a vocabulary nobody can\n"
		"enumerate.\n"
		"KEY: WHERE ONE TEXT REALLY MUST SERVE EVERY CASE, LET THE CALLER ASK FOR A NAMED SHAPE, NOT\n"
		"DESCRIBE ONE. A stock-availability check serving every document that moves goods - with or\n"
		"without variants, serial numbers, a quality dimension, a unit coefficient, a warehouse on the\n"
		"line rather than in the header - is one text and one routine that fills it. What keeps that\n"
		"usable is that the condition for the virtual table comes from a small family of builders\n"
		"keyed by NAME: \"full\", \"without quality\", \"reserve\", \"into a temporary table\".\n"
		"* So a caller says which shape it wants and the vocabulary of shapes is enumerable in one\n"
		"place. A caller that describes the shape instead - a structure of flags each site fills\n"
		"differently - moves the combinations back out to the callers, and nobody can then say which\n"
		"combinations are used.\n"
		"\n"
		"KEY: A BIG QUERY IS BUILT IN STEPS, NOT WRITTEN IN ONE BREATH. Any real calculation - the\n"
		"month's payroll, a cost distribution, a stock report with reserves - reads five or six\n"
		"different things and combines them. Written as one text it becomes a page of joins nobody\n"
		"can change safely; written as TEMPORARY TABLES it becomes a sequence:\n"
		" one step per subject, each a small query with a name that says what it selected -\n"
		" the salaries, the time norms, the balances, the reserves;\n"
		" later steps join the earlier ones instead of the raw tables;\n"
		" the final step selects the answer.\n"
		"\n"
		"KEY: THE OTHER AXIS OF \"ONE QUERY INSTEAD OF TEN\" IS GENERATED COLUMNS. Where the count of\n"
		"things comes from the configuration - six indicators in one customer's scheme, eleven in\n"
		"another's - the answer is not a query per indicator but ONE text whose select list and joins\n"
		"are grown in a loop: one more selected column beside one more LEFT JOIN, N times, executed\n"
		"once. The count comes from metadata, so a scheme with a twelfth indicator needs no code, and\n"
		"the alias and the column carry the same counter, which is what keeps a forty-join text\n"
		"readable.\n"
		"\n"
		"* AND THE MANAGER OF THOSE TABLES IS PASSED AROUND, which is the part worth copying: one\n"
		"routine prepares a temporary table, another consumes it, and neither has to know how the\n"
		"other got its data. It is how a calculation is split across procedures without passing\n"
		"tables of values through memory.\n"
		"\n"
		"NOTE: Each step is also separately CHECKABLE - run it alone and look at what it returned, which\n"
		"is the only practical way to debug a calculation that reads six sources. And name the\n"
		"steps after the subject, never after the order: `Salaries`, not `Query2`.\n"
		"\n"
		"STOP: AND THIS IS HOW LARGE VOLUMES ARE HANDLED AT ALL - THE SET GOES INTO THE QUERY, not the\n"
		"query into a loop. The list you have in memory - the document's lines, the employees being\n"
		"paid, the items being written off - is passed AS A PARAMETER, selected into a temporary\n"
		"table, and everything downstream joins against it. One query answers for two thousand rows.\n"
		"KEY: PASSING THE SET AS ONE PARAMETER AND MATCHING WITH AN IN-LIST IS THE ORDINARY ROAD - six\n"
		"times commoner than selecting the set into a temporary table. Take the temporary table when\n"
		"the set is a STEP rather than an ARGUMENT: when several statements of the same batch read it,\n"
		"or when it is large enough to want an index of its own.\n"
		"STOP: AND KNOW THAT THE LIST HAS A CEILING NOBODY HAS WRITTEN DOWN. Measured over three\n"
		"hundred thousand lines, not one place splits a long set into pages before binding it, so the\n"
		"practical limit is wherever the database's own parameter limit falls, and no code knows where\n"
		"that is. A posting that works on two hundred lines and fails on five thousand fails there.\n"
		"Decide the page size once, in the routine that binds the set, or move that set to a temporary\n"
		"table on purpose.\n"
		"KEY: AN IN-LIST CARRIES A SET OF SINGLE VALUES; A SET OF PAIRS HAS NO SUCH FORM. Write the\n"
		"pairs into the text as a union of one-row selections and bind each side, then join the real\n"
		"table against that. The VALUES are still bound - only the parameter NAMES are generated, a\n"
		"fixed stem plus a counter.\n"
		"STOP: AND THAT IS THE WHOLE COST OF A GENERATED NAME - the same concatenation must be written\n"
		"twice, once in the text and once where it is bound, with no shared constant between them.\n"
		"Two independent expressions that must agree character for character is why only a handful of\n"
		"places in a large system do it; the alternative, selecting the pairs into a temporary table,\n"
		"trades the naming risk for one join. Choose the join unless the set is tiny and the text is\n"
		"already assembled.\n"
		"\n"
		"The shape of that first step is always the same: select the columns of the value table into\n"
		"a temporary table, and INDEX IT BY the fields the later joins use. The indexing is not\n"
		"optional - a temporary table without one is scanned once per row of whatever it is joined\n"
		"to, and that is precisely where a calculation that was fine on ten rows dies on ten\n"
		"thousand.\n"
		"\n"
		"STOP: A QUERY OVER ROWS INSIDE A LOOP OVER ROWS IS HOW A SYSTEM IS BROUGHT DOWN, and\n"
		"that is not a figure of speech. It is correct, it is readable, it passes review, and it is\n"
		"one round trip per iteration - so a thousand-line document is a thousand queries, and thirty\n"
		"people posting such documents at once is thirty thousand. The server does not slow down\n"
		"gracefully: it holds connections, locks pile up behind them, and everybody stops.\n"
		"* BUT STATE THE RULE ACCURATELY, BECAUSE THE BLUNT VERSION IS FALSE AND GETS IGNORED.\n"
		"Measured over a whole configuration: about one query execution in eleven is inside some\n"
		"loop, and those loops are legitimate - they iterate over METADATA (each register, each\n"
		"kind, each set of books), not over the rows of a document. The rule that actually holds is\n"
		"narrower and checkable: NO QUERY TEXT IS ASSEMBLED INSIDE A LOOP, and no loop runs over the\n"
		"LINES OF DATA with a reading inside it. Binding a parameter and re-running a prepared text\n"
		"is ordinary and appears everywhere.\n"
		"* SO THE QUESTION TO ASK OF A LOOP IS NOT \"is there a query in it\" BUT \"WHAT IS IT WALKING\":\n"
		"a dozen registers, or ten thousand lines.\n"
		"\n"
		"* THE FIX IS ALWAYS THE SAME THREE STEPS, and it is worth writing out because it is\n"
		"mechanical:\n"
		" 1. BEFORE the loop, collect the keys you are about to ask about - the items, the\n"
		" employees, the documents - into an array or a value table.\n"
		" 2. RUN ONE QUERY over that set: pass it as a parameter and either match with `IN\n"
		" (&Keys)` or select it into an indexed temporary table and join. One trip, everything\n"
		" needed for every iteration.\n"
		" 3. INSIDE the loop, work only with what came back. Walk the selection, or build a map\n"
		" from the result once and look up by key - and touch the database not at all.\n"
		"\n"
		"NOTE: THE TELL THAT IT IS HAPPENING: a query object, or a reference reached through a dot, on\n"
		"a line that is indented inside a loop. Both are reads. If either is there, the loop is\n"
		"inside out and the three steps above are the answer - not caching, not a faster query, not\n"
		"a bigger server.\n"
		"\n"
		"STOP: AND THE TELL IS NOT ENOUGH, BECAUSE THE QUERY HIDES BEHIND A CALL. `GetPrice(item)` on\n"
		"a line inside a loop looks like arithmetic; the query is one level down, in a routine\n"
		"somebody else wrote, and the reviewer who was watching for the word 'query' sees nothing.\n"
		"This is not hypothetical - it is a known way to walk a defect straight through an\n"
		"interview and a code review alike (Max, 2026-09-02, having done exactly that to see who\n"
		"would notice).\n"
		"\n"
		"* SO THE RULE IS ABOUT THE FUNCTION, NOT ABOUT THE LOOP: anything called from inside a\n"
		"loop must be MUTE - it may compute, it may not read. Three habits keep that true:\n"
		" A ROUTINE THAT READS THE DATABASE TAKES A SET AND RETURNS A MAP. `GetPrices(items)` can\n"
		" only be called once; `GetPrice(item)` invites the loop and always gets it. Shape the\n"
		" signature so the wrong use is awkward. And where one name must serve both, NORMALISE AT\n"
		" THE DOOR AND LET THE ANSWER FOLLOW THE QUESTION: test what was passed, wrap a single\n"
		" value into a one-element set, remember which it was, and return a single value to the\n"
		" caller who asked for one and a map to the caller who asked for many. Three lines, and it\n"
		" saves either two exported names per operation or a one-element set built by hand at\n"
		" every call site. It decides only the SHAPE of the answer, never the number of trips.\n"
		" SAY SO IN THE NAME OR THE NOTE when a routine goes to the database, so a reader one\n"
		" level up knows without opening it.\n"
		" AND MEASURE RATHER THAN READ: count the queries a posting actually made. Reading code\n"
		" finds the loops you can see; counting finds the ones behind three calls, which are the\n"
		" ones still in production.\n"
		"KEY: AND THERE IS A THIRD ANSWER BESIDE HOISTING THE TEXT AND PASSING THE SET: READ THE WHOLE\n"
		"SMALL TABLE ONCE AND FILTER IN MEMORY. The accounting policy, the switches, the rates - one\n"
		"row per company per period, a few hundred rows in the life of a base - are read with no\n"
		"condition at all, ordered newest first, and the applicable row is picked by the caller.\n"
		"* THE CONDITION THAT MAKES IT SAFE IS THE SIZE, AND IT MUST BE STATED WHERE THE ROUTINE\n"
		"LIVES: a whole-table read that is right at three hundred rows is a defect at three hundred\n"
		"thousand, and nothing warns when the table crosses over. Only slowly-changing, bounded tables\n"
		"qualify (`combining`: whatever is cached for a session must be true for a session).\n"
		"NOTE: And say ALLOWED in these queries too (`query-by-name` above), and be careful with\n"
		"DISTINCT: it is needed after joins that multiply rows, and it also HIDES duplicates that\n"
		"were a mistake. Add it because the join legitimately fans out, not to make a symptom go\n"
		"away.\n"
		"\n"
		"KEY: A ROUTINE THAT READS MANY REFERENCES AT ONCE HAS A PRECONDITION, AND IT MUST BE STATED\n"
		"WHERE IT CANNOT BE MISSED. \"Give me these fields of these five hundred references\" is one\n"
		"query against ONE table - which means every reference in the array must be of the same kind,\n"
		"and the table is decided by the first element. References of another kind then vanish from\n"
		"the answer with no error at all.\n"
		"* THAT IS A DEFENSIBLE TRADE (one plan, one index scan, against text assembled per table),\n"
		"and it is only defensible while the condition is LOUD. A caller who reads a mixed list gets\n"
		"a silently short answer, which is the worst failure this corpus knows.\n"
		"* AND WHERE MIXED KINDS ARE GENUINELY NEEDED, the shape is a union per table assembled from\n"
		"the metadata - the same move as `query-by-name`.\n"
		"STOP: AND A BATCH READ MUST ANSWER FOR EVERY KEY IT WAS ASKED ABOUT, INCLUDING THE ONES THAT\n"
		"NO LONGER EXIST. After the union runs, walk the ORIGINAL input again and insert an empty\n"
		"answer for every key the query did not return. Otherwise the caller must test for a missing\n"
		"key at every use, and one caller in five will forget - and the keys that go missing are\n"
		"exactly the deleted ones, which is what histories, logs and error reports are full of.\n"
		"* The same rule inverted is a useful shape in itself: where the question is \"which of these\n"
		"are not ready\", return the FAILURES rather than a yes-or-no, so the caller has the list it\n"
		"must act on.\n"
		"STOP: A BATCHED VARIANT OF A READER IS A DIFFERENT SECURITY CONTRACT, NOT A FASTER ONE. In\n"
		"the system measured, the single-reference reader took a permitted-only flag and emitted the\n"
		"access keyword; the set reader eighty lines below took no such flag, emitted nothing, and\n"
		"told callers to switch to privileged mode instead. So the caller who batched for speed\n"
		"silently widened what the reader could see, and neither signature said so. WHEN A SET FORM IS\n"
		"ADDED BESIDE A SCALAR ONE, IT INHERITS EVERY FLAG THE SCALAR ONE HAD, or it gets a different\n"
		"name. Optimisation may change the cost, never the answer or who may have it.\n"
		"\n"
		"STOP: AND DO NOT LET THIS PRIMITIVE EXIST THREE TIMES. In the system measured, one shared\n"
		"layer holds three routines that all read attributes of a reference, and they disagree on\n"
		"everything that matters: whether a forbidden row comes back empty or raises, whether a\n"
		"deleted reference is handled, whether permissions are applied at all. Three answers to one\n"
		"question, and the caller cannot tell which they got (`combining`: one mechanism, declared\n"
		"once).\n"
		"\n"
		"KEY: THE OTHER USE IS READING SEVERAL ATTRIBUTES AT ONCE, and it is a performance habit worth\n"
		"having from the first day. Reaching through a reference - `line.Item.Article`, then\n"
		"`line.Item.Unit`, then `line.Item.VatRate` - fetches the object once PER ATTRIBUTE, and\n"
		"inside a loop over document lines that is thousands of reads nobody sees.\n"
		"\n"
		"Ask for them together: one query over the table the reference points at, selecting the\n"
		"fields wanted, filtered by the reference. The table's name comes from the reference's TYPE\n"
		"through the metadata, so the same routine serves catalogues and documents alike - and the\n"
		"field list is assembled from what the caller asked for, which is structure again and not\n"
		"data.\n"
		"NOTE: The rule underneath: inside a loop, reaching through a reference is a database read. One\n"
		"query before the loop beats a hundred lookups inside it, and the difference is invisible\n"
		"until the document has two hundred lines.") },

	{ wxT("cross-cutting-hooks"),
	  ibMcpText("The mechanisms that must apply to every object - and why none of them lives inside one."),
	  ibMcpText("WHAT MUST APPLY TO EVERYTHING, AND THEREFORE TO NOTHING IN PARTICULAR.\n"
		"\n"
		"A working accounting system carries a handful of mechanisms that are nobody's feature and\n"
		"everybody's obligation. Counted off a real configuration, they subscribe to events on whole\n"
		"KINDS of objects, and not one of them is written inside a document or a catalogue:\n"
		"\n"
		" A PROHIBITION DATE, checked before writing (`closing-a-period`).\n"
		" A HISTORY OF CHANGES, on writing any object (`object-history`).\n"
		" A NUMBER PREFIX, when a new number or code is issued (`numbering`).\n"
		" REGISTRATION FOR TRANSFER to other bases, before and on writing (`data-exchange`).\n"
		" REGISTRATION OF ACCESS OBJECTS, so record-level rights can be resolved (`row-level-access`).\n"
		" THE SECOND STAGE OF POSTING, marked at posting time (`deferred-posting`).\n"
		" CACHE INVALIDATION, when a constant or a settings register is written.\n"
		"\n"
		"KEY: THE LIST IS KNOWN IN ADVANCE, AND THAT IS THE USEFUL PART. When a system is being laid\n"
		"out, these are the seven questions to ask before the first document is designed - because\n"
		"each of them is nearly free at the start and each is a rewrite once fifty documents exist.\n"
		"\n"
		"STOP: A RULE THAT APPLIES TO DOCUMENTS MUST ALSO APPLY TO DIRECT WRITES INTO REGISTERS. The\n"
		"prohibition date is the clearest case: it needs FIVE subscriptions - documents, and each of\n"
		"the four kinds of register - because a closed period edited by writing a record set directly\n"
		"is edited just as thoroughly as one edited through a document. Guarding only the door people\n"
		"usually walk through is not guarding.\n"
		"\n"
		"KEY: AND A DECISION SOMETIMES HAS TO BE TAKEN IN ONE EVENT AND ACTED ON IN ANOTHER. \"Is this\n"
		"new?\" can only be asked BEFORE writing; \"what is its identity?\" only exists AFTER. So the\n"
		"answer is computed early and carried on the object to the later event. Any hook that needs\n"
		"both facts has this shape.\n"
		"\n"
		"NOTE: A CACHE OF SETTINGS IS REPAIRED BY A HOOK, NOT BY A LIFETIME. Values read repeatedly -\n"
		"the accounting policy, the switches, the rates - are cached, and the cache is dropped when\n"
		"the constant or the settings register is WRITTEN. Expiring it on a timer instead means every\n"
		"reader is wrong for the length of the timer, and nobody can say when.\n"
		"\n"
		"NOTE: THE PRICE OF THIS ARRANGEMENT IS THAT NOTHING IS VISIBLE AT THE PLACE IT ACTS. Reading\n"
		"a document's module tells you nothing about the seven mechanisms that will run around it.\n"
		"That is the trade, and it is worth taking - but it means the list above has to be written\n"
		"down somewhere a person will find it, which is what this entry is.\n"
		"\n"
		"NOTE: AND WHERE THE HOOKS ARE A REGISTRY RATHER THAN A FIXED LIST, THREE DECISIONS PAY FOR\n"
		"THEMSELVES. The registry is keyed by a STRING event name, so a subsystem can subscribe\n"
		"without the publisher knowing it exists. Each answer carries the subscriber's VERSION, so a\n"
		"publisher can skip a handler too old for the arguments it is about to pass, instead of\n"
		"failing inside it. And the answer comes back frozen, because it comes out of a cache\n"
		"(`combining`).\n"
		"* The cost is the usual one for a registry: nothing at the publishing site says who will\n"
		"run, so the list of subscribers has to be readable on demand - one call that answers \"who\n"
		"handles this event\".\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. A DECLARED SUBSCRIPTION - \"run this routine before\n"
		"every document writes\", stated once, in the metadata, so that the set of objects it covers\n"
		"is a fact rather than a habit. That is the requirement; whether anything provides it is a\n"
		"separate question and it is worth ASKING, because the difference is large.\n"
		"* WITHOUT IT the registry above is built rather than configured - a shared module holding\n"
		"the list, called from each object's own module - and the price is exact and permanent: the\n"
		"hook exists only in the objects that remembered to call it, so \"who is subscribed\" is\n"
		"answered by reading the code, and a new object silently participates in nothing. An event\n"
		"raised when a KIND is registered gets you most of the way and covers the kind, not the\n"
		"object.") },

	{ wxT("look-first"),
	  ibMcpText("Before building a mechanism, find out whether this base already has one."),
	  ibMcpText("A REQUEST FOR A MECHANISM IS NOT EVIDENCE THAT IT IS MISSING.\n"
		"\n"
		"People describe what they NEED, not what their configuration already contains - they are\n"
		"not holding an inventory of it, and often nobody is. So a request to \"add reservation\"\n"
		"regularly arrives at a base that already reserves, somewhere, written by someone else and\n"
		"working. Build the second one and there are now two answers to \"how much is reserved\",\n"
		"nothing reconciling them, and no error anywhere - just two numbers that drift apart.\n"
		"\n"
		"So look first. `metadata_list` shows what exists by kind, `query_sources` shows what can\n"
		"be read, and the notes on the objects are where the previous builder said what theirs was\n"
		"for. It costs one or two calls, and it is the cheapest moment this question will ever be\n"
		"asked - after the second mechanism has data in it, the answer is a migration.\n"
		"\n"
		"Reservation is the standing example, and stock is full of relatives: goods reserved in\n"
		"warehouses, goods in transit, goods accepted for commission. Each pair looks like a\n"
		"duplicate and often is not - which is exactly why it has to be READ rather than guessed.\n"
		"\n"
		"* AND WHAT TO DO WITH THE FINDING: offer it, do not act on it silently. Say to the person\n"
		"that this already exists here and that it may be worth looking at that code before\n"
		"anything is added. They may know, and have a reason - a mechanism that does not fit, one\n"
		"they intend to retire. Deciding that for them is not yours to do; not telling them is\n"
		"how the duplicate gets built.\n"
		"\n"
		"KEY: AND THE MIRROR OF THIS SEARCH IS WORTH MAKING A HABIT - A SETTING THAT EXISTS IS NOT A\n"
		"SETTING THAT WORKS. Find the READER before promising the behaviour: search for the name of\n"
		"the flag, the permission, the field, and count where it is actually consulted.\n"
		"* THE FINDINGS COME IN THREE STRENGTHS AND THEY MUST BE REPORTED DIFFERENTLY. Consulted\n"
		"nowhere but in its own getter: the setting does nothing at all, and a person has ticked it\n"
		"and gone away satisfied. Consulted only in a form: it is a convenience, and any import,\n"
		"routine or transfer goes straight past it. Consulted where the operation is actually\n"
		"performed: it is a guarantee.\n"
		"* THIS IS A REAL AND COMMON DEFECT, NOT A HYPOTHETICAL: in the system examined, three\n"
		"permissions of exactly this kind are declared, stored, shown, edited - and asked by nobody.\n"
		"A rule that is written down but never read does not refuse; IT SILENTLY PERMITS, which is\n"
		"the worst of the three possible failures.") },

	{ wxT("naming"),
	  ibMcpText("Forming a name: say the whole thing, and only what is not already known."),
	  ibMcpText("NAMING WHAT YOU CREATE.\n"
		"\n"
		"Names are English - they travel into scripts, into query text and into the database\n"
		"schema. What the person actually said goes in the SYNONYM, which is where their language\n"
		"belongs and where it can be translated.\n"
		"\n"
		"A NAME IS THE SENTENCE, TRANSLATED. Say what is counted and where or whose it is, in that\n"
		"order, and read the result back: it should be the thing the person said.\n"
		" GoodsInWarehouses - goods, in warehouses\n"
		" GoodsOfCompany - the same goods, seen as the company's\n"
		" GoodsLotsInWarehouses - lots of goods, in warehouses\n"
		" GoodsTransferred - goods, once handed over\n"
		"These are four different registers because they answer four different questions, and the\n"
		"names are what make that visible at a glance. A name that could equally be any of them\n"
		"(`GoodsRegister`, `Stock2`) has thrown that away.\n"
		"\n"
		"CARRY THE OWNER ONLY WHEN THE OWNER IS PART OF THE CONCEPT. A characteristic is always a\n"
		"characteristic OF something, and a series belongs to what it is a series of - so\n"
		"`ProductCharacteristic` and `ProductSeries` say the whole thing and are right.\n"
		"\n"
		"But a concept that attaches to ANYTHING stands on its own: quality is just `Quality`.\n"
		"Quality can qualify a product, a lot, a characteristic, a service - gluing one of them\n"
		"onto the front states something untrue and makes the name wrong the first time it is\n"
		"used elsewhere. The test: does this idea only ever exist as part of that other thing? If\n"
		"yes, name them together. If it merely happens to sit there today, name it alone.\n"
		"\n"
		"AND DO NOT REPEAT WHAT THE PLACE ALREADY SAYS. An attribute on a product is reached as\n"
		"`Product.Name`; calling it `ProductName` says \"product\" twice and reads worse at every\n"
		"use. The context is already carrying it.\n"
		"\n"
		"KEY: EACH METATYPE HAS ITS OWN GRAMMAR, and following it is what makes a configuration read\n"
		"as one system rather than as a pile of objects:\n"
		" A DOCUMENT IS AN EVENT, so it is named as one - an action plus what it acts on:\n"
		" `GoodsReceipt`, `SalesOfGoodsAndServices`, `ReturnOfGoodsFromCustomer`,\n"
		" `WriteOffOfGoods`, `MonthEndClosing`. A document called `Invoice2` or `StockDoc`\n"
		" describes a piece of paper rather than the thing that happened.\n"
		" A CATALOGUE IS A THING, in the plural of what it holds: `Goods`, `Warehouses`,\n"
		" `Counterparties`, `Currencies`. Its items are things, not events.\n"
		" A REGISTER IS WHAT IT KEEPS PLUS THE CUT IT KEEPS IT BY: `GoodsInWarehouses`,\n"
		" `LotsOfGoodsInWarehouses`, `LotsTransferred`, `SettlementsWithCounterparties`,\n"
		" `SettlementsWithAccountablePersons`, `WorkInProgress`, `ScrapInProduction`. Read the\n"
		" name aloud and it should be the question the register answers.\n"
		" AN ENUMERATION IS A KIND, plural: `VatRates`, `OperationKinds`, `RoundingOrders`.\n"
		" A COMMON MODULE IS A SUBJECT, not a place: `StockManagement`,\n"
		" `SettlementsManagement`, `BalanceControl`, `Pricing`. `Utils`, `Common2` and\n"
		" `Helpers` are where code goes to be lost.\n"
		" A ROLE IS A JOB OR ONE PERMISSION (`roles`): `Storekeeper`, `Cashier` beside\n"
		" `EditItems`, `EditCounterparties`, `SeeEveryOrganisation`.\n"
		"\n"
		"* SUFFIXES CARRY THE VARIANT, AND ONLY THE VARIANT. When the same subject exists twice for\n"
		"a structural reason, the second is the first plus one word - `Costs` and\n"
		"`CostsAccounting`, `WorkInProgress` and `WorkInProgressAccounting` - so the pair is\n"
		"obvious at a glance and sorts together. The same for technical variants of a module: the\n"
		"cached one, the overridable one, the client-side one, the privileged one, each the base\n"
		"name plus its word. What a suffix must never carry is a VERSION or a date: `Sales2`,\n"
		"`SalesNew`, `SalesFinal` are a history nobody can read.\n"
		"\n"
		"KEY: AND MARK WHAT IS YOURS WITH A PREFIX, in any configuration that will be updated from\n"
		"somewhere else. Objects added by the implementer carry a short prefix of their own, and\n"
		"then \"what did we add\" is answerable by sorting the tree - which is exactly the question\n"
		"asked at every update, and unanswerable without it. It costs three characters and settles\n"
		"an argument that otherwise happens once a year.\n"
		"\n"
		"KEY: AND WHAT HAS BEEN RETIRED IS RENAMED, NOT DELETED. An object that is no longer written\n"
		"to still holds the data of past periods, and reports over those periods must still read it.\n"
		"So it keeps its rows and gets a prefix that says \"nothing new goes here\" - loud, ugly, and\n"
		"sorted to one end of the tree. A working system was counted at eleven such registers, all\n"
		"still carrying figures somebody may yet ask for.\n"
		"* THE ALTERNATIVE IS THE TRAP: deleting it means either losing the history or migrating it,\n"
		"and the migration has to be right the first time, for data nobody is looking at, on the day\n"
		"of an upgrade. The prefix costs nothing and can be reversed.\n"
		"\n"
		"THE SYNONYM IS THE PERSON'S OWN WORDS, and it is not a translation of the name - it is\n"
		"what they would say out loud. `SettlementsWithAccountablePersons` is a name; the synonym\n"
		"is whatever the accountant calls that screen, in their language, with their spacing and\n"
		"their capitals. Two rules that save trouble later: keep it a NOUN PHRASE, since it appears\n"
		"as a heading, a menu entry and a column title; and do not put the metatype in it - a\n"
		"catalogue's synonym is \"Warehouses\", never \"Warehouses catalogue\", because the place it\n"
		"is shown already says what it is.\n"
		"NOTE: AND EVERY OBJECT A PERSON CAN SEE NEEDS ONE. A missing synonym falls back to the name -\n"
		"English, run together, technical - and that is what a user reads on the screen. It is the\n"
		"cheapest visible defect in a configuration and the most common.") },

	{ wxT("scheduled-documents"),
	  ibMcpText("Documents the system creates by itself on a schedule - and how it avoids duplicates."),
	  ibMcpText("WORK THAT HAPPENS WITHOUT ANYBODY ASKING.\n"
		"\n"
		"\"It should create the documents itself every month.\" Two things are needed and they are\n"
		"not the same object: WHAT to do, which is a settings item a person edits, and WHEN, which\n"
		"is a scheduler entry. The settings item OWNS the schedule entry - saving it with automatic\n"
		"running on ensures the entry exists and mirrors into it the name, the reference back, and a\n"
		"key that stops two runs of the same setting overlapping. Turning the flag off DISABLES the\n"
		"entry rather than deleting it; deleting the settings item deletes the entry (otherwise the\n"
		"item cannot be deleted at all); COPYING the item must CLEAR the link, or the copy drives the\n"
		"original's schedule.\n"
		"\n"
		"KEY: DUPLICATES ARE PREVENTED BY A CURSOR, NOT BY LOOKING FOR WHAT IS ALREADY THERE. The\n"
		"setting stores a PROCESSED-UP-TO date; the next run always covers \"the day after that,\n"
		"through the end date\", and on success the mark moves to the end of what was done. Nothing\n"
		"ever asks \"does such a document already exist\".\n"
		"* WHY: an existence check needs a key that identifies the document, and it lies the moment\n"
		"somebody deletes one by hand - it then makes another. A monotone cursor is unambiguous and\n"
		"survives any editing of the data behind it.\n"
		"* WHAT IT COSTS, and say it before it is met: THE CURSOR IS ONE PER SETTING, so a gap left\n"
		"in the middle is never filled in, and moving the mark back by hand produces duplicates for\n"
		"certain. The settings object is LOCKED for the whole run so two runs cannot both advance it.\n"
		"\n"
		"KEY: THE MARK MOVES IN THE SAME TRANSACTION AS THE CREATION; POSTING IS PUSHED OUTSIDE IT.\n"
		"Start the transaction, write the NEW mark, create the documents, and if nothing was created,\n"
		"roll back so the mark does not move. But posting a month of documents inside that same\n"
		"transaction takes a lock nobody else can live with - so for the heavy kinds the transaction\n"
		"is closed first and posting failures are logged rather than undoing the work. Whether\n"
		"posting is inside is a property of the KIND of routine, not a checkbox for the user.\n"
		"\n"
		"NOTE: MISSING A PERIOD IS CAUGHT UP IN ONE PIECE, NOT ONE DOCUMENT PER MISSED MONTH. If the\n"
		"server stood still for a week, the next run covers the whole gap as a single interval. A\n"
		"deliberate trade: catching up is simple and always terminates, and the detail of which\n"
		"period was which is lost.\n"
		"\n"
		"KEY: \"THE DATA IS READY\" IS TWO DIFFERENT QUESTIONS, AND ONE CANNOT EXPRESS THE OTHER.\n"
		" A CALENDAR HOLD-BACK - do not touch the last N days, because they are still being typed.\n"
		" AN EXPLICIT CLOSING EVENT - refuse to run at all while a shift, a period or a department\n"
		" is not marked closed, read from the register that records it.\n"
		"A form that offers only the first will be asked for the second within a month.\n"
		"* AND A WINDOW OF DAYS SITS ON TOP OF THE SCHEDULE. A schedule answers \"how often\", never\n"
		"\"on which days of the month is this appropriate\" - \"only between the 25th and the 5th\".\n"
		"That is a separate setting, and it needs its own branch for a window that crosses the end of\n"
		"the month, which reads as \"after the 25th OR before the 5th\".\n"
		"\n"
		"KEY: AND WHAT BELONGS ON A SCHEDULE AT ALL IS DECIDED BY THREE TESTS, ALL OF WHICH MUST HOLD:\n"
		"it is LONG, it needs NOBODY PRESENT, and its answer is \"as of a period\" rather than \"right\n"
		"now\". Counted in a full system, the whole night's work is a short list and every item passes\n"
		"all three - catching up deferred postings, recomputing register totals, computing cost,\n"
		"computing prices, producing the documents that recur, raising people's tasks, exchanging data\n"
		"with other bases and clearing what the exchange left behind, fetching mail, rebuilding the\n"
		"full-text index.\n"
		"* THE USE OF THE LIST IS AS A FILTER. Anything a person is waiting for fails the second test\n"
		"and belongs in a long operation with a progress window (`long-operations`); anything that\n"
		"must be true the instant a document is written fails the third and belongs in the posting.\n"
		"* AND WHATEVER IS MOVED THERE IS NOT TRUE UNTIL IT RUNS - which has to be visible somewhere,\n"
		"or the first report read at ten in the morning is quietly stale (`deferred-posting`).\n"
		"\n"
		"NOTE: A SUMMARISING ROUTINE REPLACES RATHER THAN UPDATES: it returns TWO sets - what it\n"
		"created, and what it consumed - and then the consumed documents are marked for deletion and\n"
		"the created ones posted. Which of the two sets is acted on is asked OF THE ROUTINE, because\n"
		"one kind consumes everything and another consumes nothing. Filter both lists again before\n"
		"acting - delete only what is not already marked, post only what is not already posted - so a\n"
		"second run is harmless.\n"
		"\n"
		"STOP: THE LINK FROM A SCHEDULE ENTRY TO ITS SETTING IS ONE-WAY AND CAN GO STALE, so every\n"
		"background routine opens with the same three checks: the setting still exists (it may have\n"
		"been deleted while the entry survived), automatic running is still switched on (the flag may\n"
		"have been cleared), and lock it for the duration. A background job that trusts its own\n"
		"parameters fails at three in the morning with nobody reading.\n"
		"\n"
		"NOTE: AND IT REPORTS INTO THE LOG, NOT ONTO A SCREEN - including the reasons it decided to\n"
		"do nothing. \"Too early\", \"already processed\", \"shift not closed\" are the answers people\n"
		"will ask about, and there is no one at the screen to be told.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. A JOB DECLARED IN THE METADATA - a schedule, a\n"
		"handler, and a way to pass arguments to the ones that need them - so that \"what runs at\n"
		"night\" is readable in one place and survives a restart. Everything else in this entry, the\n"
		"cursor register and the reporting into the log, hangs off that.\n"
		"* WITHOUT IT, the schedule lives in an operating system somewhere and the base cannot answer\n"
		"what it is supposed to be doing - which is the state in which \"it did not run last night\"\n"
		"takes a day to diagnose.") },

	{ wxT("external-data"),
	  ibMcpText("Getting data out of another base or system - the door that already exists."),
	  ibMcpText("DATA FROM SOMEWHERE ELSE.\n"
		"\n"
		"When the task is to pull data out of another base or another application, the platform\n"
		"already has the door: `ComObject`. It is a real value type of the language - create one,\n"
		"call its methods, read its properties - so a scripted exchange with anything that exposes\n"
		"an automation interface is written, not invented.\n"
		"\n"
		"Reach for it before designing a file exchange. A folder of files to be dropped and picked\n"
		"up is a protocol somebody then has to own: a format, a naming scheme, what happens to a\n"
		"half-written file, who deletes what and when. If the far side can simply be ASKED, all of\n"
		"that disappears.\n"
		"* AND WHERE THE FAR SIDE PUBLISHES PER ITEM, FETCH WHAT YOU ALREADY HOLD RATHER THAN WHAT\n"
		"THEY OFFER. Walk the local list of the things actually wanted, compose the address out of\n"
		"each one's own code and a date, and fetch that small file. What is fetched is then decided by\n"
		"the base, adding a currency is adding a row, and nobody downloads a catalogue of nine hundred\n"
		"to use three. The loop must tell two failures apart: \"this one is not there, carry on\" and\n"
		"\"the far side refused us, stop\" - treating the second as the first walks the whole list to\n"
		"produce one message per item.\n"
		"* AND A POLLING IMPORT IS TWO ROUND TRIPS, ONLY THE SECOND OF WHICH IS EXPENSIVE. Fetch the\n"
		"HEADERS - the identities and whatever the duplicate check needs - hand the whole array to ONE\n"
		"query that removes everything already held, and fetch bodies only for the survivors. \"It\n"
		"takes twenty minutes every morning\" is nearly always this shape missing: a body fetched per\n"
		"item, then discarded because the item was already held.\n"
		"\n"
		"STOP: ENCODING IS DECIDED IN ONE PLACE OR IT IS DECIDED FOUR TIMES, DIFFERENTLY. Counted in\n"
		"one product: a hand-written table of encoding names on a mail account, a two-item switch on\n"
		"an exchange form, a code page wired into a fixed-record reader, a text reader that passes no\n"
		"encoding at all - and NOWHERE is an encoding detected. The customer sentence is always the\n"
		"same: it opens in the spreadsheet program and arrives here as question marks.\n"
		"* AND WHERE THE FILE DECLARES ITS OWN ENCODING, READ THE DECLARATION. Found live: the\n"
		"format's header carries an encoding tag, it is parsed and stored - and the file has already\n"
		"been read twice by then, the second time using a code page a person picked by hand from two.\n"
		"Outgoing files were self-consistent; incoming ones were a guess. The rule: one reader per\n"
		"format is fine, ONE encoding decision is not optional, and the order is declaration, then the\n"
		"agreement's setting, then ask - never ask first.\n"
		"KEY: AND DECIDE ONCE WHAT AN UNKNOWN FIELD IN AN INCOMING FILE MEANS, THEN APPLY IT AT EVERY\n"
		"LEVEL. In the system measured, an unrecognised tag in the header printed a complaint and\n"
		"carried on, while an unrecognised tag inside a record ABANDONED THE WHOLE READ - so \"they\n"
		"added one field and now nothing loads\" was a designed behaviour nobody had chosen. Ignoring\n"
		"the unknown is the usual right answer for a format somebody else versions; refusing is right\n"
		"only where a missing meaning could make the rest wrong.\n"
		"* AND KEEPING THE VOCABULARY AS TEXT - the recognised names as a grouped list of strings,\n"
		"turned into a lookup at start-up and also used to build the row - is a good trade: adding a\n"
		"field is editing one list, and the same list defines both what is accepted and where it goes.\n"
		"STOP: AND SANITISE A FILE NAME BY SUBSTITUTION, NEVER BY DELETION. Removing the characters a\n"
		"name may not contain collapses two different incoming names into one on disk, and the\n"
		"collision then arrives at whatever asks \"overwrite?\" looking exactly like a genuine re-save -\n"
		"so one attachment silently replaces another. Replace each forbidden character with a fixed\n"
		"stand-in, and keep the forbidden set as one list read by both the test and the replacement.\n"
		"\n"
		"NOTE: IT IS WINDOWS-ONLY, and that is the honest cost. A configuration that depends on it\n"
		"stops being portable to the platforms the engine itself runs on. Worth deciding\n"
		"deliberately rather than discovering later - and worth writing in the notes of whatever\n"
		"uses it, so the next reader knows the limit is chosen and not accidental.\n"
		"\n"
		"KEY: AND WHATEVER THE CHANNEL IS, THE LOADING SCREEN HAS ONE SHAPE - importing a bank\n"
		"statement is the case everybody meets first, and every other import is the same five steps:\n"
		" 1. THE SOURCE AND ITS CONTEXT, at the top: the file, and the few things the far side does\n"
		" not know - which organisation, which bank account, which account the entries land on.\n"
		" 2. READ, AND SHOW WHAT WAS READ - a table of what is in the file, one row per record,\n"
		" BEFORE anything is written. \"Refresh from file\" re-reads it, because the file gets\n"
		" replaced while the window is open.\n"
		" 3. THE MATCHING IS COLUMNS OF THAT TABLE: counterparty, contract, cash-flow item, the\n"
		" accounts. The import guesses them from what the file carries - an account number, a\n"
		" tax code - and a person corrects what it got wrong, in the row, before loading. An\n"
		" unmatched row is visible as an empty cell rather than as a message.\n"
		" AND DATES FROM OUTSIDE ARE THE QUIETEST WRONG ANSWER AN IMPORT PRODUCES. A reader that\n"
		" strips everything but the digits and interprets the runs positionally - three runs a\n"
		" date, six a date and time, a first run above a thousand meaning the year came first -\n"
		" handles every file it has met and silently transposes day and month on the first one\n"
		" where the day is under thirteen. A two-digit year needs a PIVOT, which is a decision:\n"
		" found in one product, two readers on the same border with two different pivots, so the\n"
		" same file read by two tools lands sixty years apart. One reader, one pivot, written\n"
		" down - and where the format is knowable, make it a setting of the exchange rather than\n"
		" an inference, since the partner's format is a property of the agreement with them.\n"
		" AND \"IS THIS ONE ALREADY IN THE BASE\" IS ANSWERED BY A SET OF STABLE FIELDS, NOT BY THE\n"
		" NUMBER. The query matches on the date to the day, the far side's account, our account\n"
		" and the company; the number is compared while walking the result, because OUR OWN\n"
		" numbers carry a prefix and theirs do not - so ours match on the last few characters and\n"
		" theirs on equality. Two comparisons, both deliberate. The KIND of document is derived,\n"
		" not read: from the operation word in the file plus which side of it our account sits\n"
		" on; and which date field and which number field each kind uses is a small table - write\n"
		" it once and read it from both the search and the write, or the two drift and re-import\n"
		" starts creating second copies. More than one match is a THIRD outcome: say how many,\n"
		" take one, and mark the row.\n"
		" AND AN IMPORT RESOLVES THE PARTY, NOT THE OBLIGATION. What arrives is money with a name\n"
		" on it; which invoice it closes is decided by the document's own posting against the\n"
		" register that holds the debts (`settlements`), not by the loader. So the loader's job\n"
		" ends at: find the counterparty (by their bank account first, by their registration\n"
		" number second), pick the contract, derive the accounts. Picking the contract is \"the\n"
		" main one, or the only one, or none\" - a query returning at most two candidates, ordered\n"
		" so the party's own principal contract sorts first, filtered by kind, company and\n"
		" settlement currency; two candidates and no principal is a question for a person, not a\n"
		" guess. Matching a payment to a particular debt is a DIFFERENT SCREEN, where a person\n"
		" sees the outstanding amount read from the register and says which one this closes. Do\n"
		" not put it in the importer.\n"
		" 4. A TICK, AND DECIDE WHAT IT SELECTS - it is not always the row. Selecting ROWS is right\n"
		" where half a statement is a normal thing to load. Selecting FIELDS is right for a\n"
		" spreadsheet whose every row is wanted but whose columns are not. Whichever it is, say\n"
		" it on the screen, and choose the initial state deliberately: all ticked suits a\n"
		" statement, none ticked suits anything that creates documents.\n"
		" 5. ONE LOADING COMMAND, and a REPORT OF WHAT HAPPENED afterwards: created, skipped,\n"
		" failed and why. Settings - the general ones and the ones specific to this bank or\n"
		" partner - live on their own buttons, away from the daily path.\n"
		"\n"
		"KEY: LET THE SCREEN BE THE STATE. Every cell holds two things - the text that came out of the\n"
		"file and the RESOLVED value beside it. Resolution writes the second; a person picking by hand\n"
		"writes the second and rewrites the text from what they picked; the load reads the second.\n"
		"Then corrections survive a re-check, what you see is exactly what will be written, and the\n"
		"whole half-finished job can be saved and reopened tomorrow without a parallel table of\n"
		"anything.\n"
		"* AND THE COMPLAINT LIVES ON THE CELL IT IS ABOUT - written into that cell as a note, with\n"
		"commands to walk to the previous and next annotated cell. The address of the problem IS the\n"
		"problem's home, which is the same rule as a message carrying an address (`combining`),\n"
		"applied to a sheet. What it costs: the buffer is limited to what one sheet holds, and an old\n"
		"note stays until the check is run again - so re-check, do not repair notes.\n"
		"\n"
		"KEY: AND THE PREVIEW MUST BE THE LOAD WITH THE WRITE LEFT OUT - THE SAME ROUTINE, CALLED\n"
		"TWICE. One per-row routine resolves every field, writes the complaints and returns the\n"
		"values; the check command runs it over every row and counts, the load command runs the\n"
		"identical call and then writes. There is no second implementation, so the preview CANNOT\n"
		"drift from what actually happens.\n"
		"* A preview written separately agrees with the load on the day it is written and diverges at\n"
		"the first fix that goes into only one of them - and the divergence is discovered by a person\n"
		"who trusted the preview. End the check with two numbers: rows examined, and cells that are\n"
		"wrong or ambiguous. \"No problems found\" is a different sentence from a count of zero and both\n"
		"are worth saying.\n"
		"\n"
		"KEY: AND WHERE THE FILE DECLARES ITS OWN CONTROL TOTALS, THE REPORT IS A RECONCILIATION, NOT\n"
		"A LOG. Per account: a header naming it and the period, a line per record, the totals of what\n"
		"was loaded, and finally the opening and closing figures AS THE FILE DECLARED THEM. Records\n"
		"that produced no document are printed in the warning colour and named.\n"
		"STOP: AND IF THE FILE DECLARES A TOTAL, COMPARE IT YOURSELF rather than printing both for a\n"
		"person to check by eye. The system measured printed the two figures side by side and never\n"
		"compared them - so a load that was short by one record looked exactly like a load that was\n"
		"complete. A declared total is the cheapest verification an import will ever get; use it and\n"
		"say \"agrees\" or \"differs by\".\n"
		"\n"
		"KEY: DECIDE THE TRANSACTION BOUNDARY OF A LOAD, AND SAY IT ON THE SCREEN. Three tools on one\n"
		"border in one product chose three different answers - one transaction per written object, one\n"
		"per document with nothing around the loop, and one transaction for the whole confirmation -\n"
		"and none of them says which. The person's question after a failure is always the same: what\n"
		"state am I in?\n"
		"STOP: AND PER-OBJECT MEANS AN ABORT HALFWAY LEAVES THE EARLIER OBJECTS WRITTEN, WITH NO UNDO.\n"
		"If that is the choice, then the run must leave a trail: stamp every object this run created\n"
		"or changed with what created it and when, so \"undo the load\" is a query rather than an\n"
		"archaeology. A comment saying \"came from an exchange\" with no run identity in it is not\n"
		"enough.\n"
		"* AND WHERE A HOOK MUST ACT ON AN OBJECT THAT NOW HAS AN IDENTITY, the write happens twice\n"
		"inside the one transaction - write, run the hook, write again. That is the shape; it is not a\n"
		"stray write.\n"
		"\n"
		"KEY: AND THE MAPPING IS A ROW PER FIELD OF OURS, not a column of theirs. \"Which of my fields\n"
		"is this, and where does it come from\" - our field named, their column a number inside that\n"
		"row. The other way round cannot express a field we need and the file does not have, which is\n"
		"the ordinary case, nor two of our fields fed from one of theirs.\n"
		"* WITH NOTHING SAVED, THE DEFAULT MAPPING CAN BE TAKEN FROM THE DESTINATION'S OWN FORM -\n"
		"the order, width and visibility of ITS columns. Cheap and surprisingly good, and worth\n"
		"knowing for what it costs: a change to a screen silently becomes a change to how files load.\n"
		"KEY: AND EACH ROW OF THAT MAPPING SAYS HOW ITS FIELD IS FILLED, WHICH IS WHAT MAKES THE\n"
		"ROW-PER-FIELD FORM WORTH HAVING. Four modes and no more: TAKE IT FROM A COLUMN and resolve;\n"
		"SET a stored constant for every row and read no column at all; COMPUTE it from an expression;\n"
		"or LEAVE IT ALONE. \"The warehouse is not in their file, it is always the same one\" is then a\n"
		"mapping row, not a code change.\n"
		"* THE EXPRESSION RUNS WITH THE ROW SO FAR IN SCOPE - this cell's own text, every raw cell of\n"
		"the row by column number, and the fields already resolved for this row - so \"their price\n"
		"includes tax and ours does not\" is one line in the mapping.\n"
		"* AND A FIELD CAN CARRY AN OWNER LINK OR A TYPE LINK THAT NAMES ANOTHER MAPPING ROW: \"the\n"
		"contract must be looked up within the customer on the same line\" is then a field name, not\n"
		"code. At resolution time the loader reads that name out of what this row has resolved so far\n"
		"and folds it into the query, or takes the admissible type from it.\n"
		"STOP: WHICH MAKES THE ORDER OF THE MAPPING A DEPENDENCY ORDER, AND NOTHING ENFORCES IT. An\n"
		"expression or a link pointing further down the list silently gets nothing. Say it beside the\n"
		"field list, and keep the order editable.\n"
		"* AND A MAPPING IS A DESCRIPTION, SO IT RUNS BACKWARDS FOR FREE. The same table that says\n"
		"where each of our fields comes from also says where each of them GOES - so one command fills\n"
		"the sheet from an existing object, a person edits it in a spreadsheet, and the ordinary load\n"
		"puts it back. \"Export these lines, fix them, re-import\" is then not a second tool. Name that\n"
		"command for what it does: found live, the inverse fill was triggered by a button called\n"
		"\"refresh\", offered for one destination kind out of three, and consequently used by almost\n"
		"nobody.\n"
		"\n"
		"KEY: RESOLVING A VALUE HAS THREE OUTCOMES, NOT TWO - none, one, several. On several, THE\n"
		"VALUE ALREADY IN THE CELL WINS: the person chose it last time and the recomputation must not\n"
		"overrule them; then a default; then the first. And the cell stays MARKED as ambiguous with\n"
		"the number of candidates, because a silently-picked one of five is the error nobody sees.\n"
		"KEY: BETTER THAN AN EMPTY CELL: MAKE THE COLUMN COMPOSITE AND LEAVE THE FAILURE IN IT AS A\n"
		"SENTENCE. The column holds either the resolved reference or a readable line - \"not found\n"
		"(name, tax number)\" - built from the very fields that failed to match. The person reads what\n"
		"the file said, in place, and picks the right value in the same cell. \"Did it resolve?\" is\n"
		"then a TYPE TEST, one line, wherever it is asked.\n"
		"STOP: AND NEVER ASK THAT QUESTION BY COMPARING THE TEXT. Found live: a later step decided\n"
		"whether a contract had resolved by testing the cell against the words \"not found\" - which is\n"
		"a translated literal, so in another interface language the test fails and a sentence is\n"
		"assigned to a reference field. The type is the answer; the sentence is only for the person.\n"
		"KEY: AND THE OPPOSITE RULE HOLDS FOR A LINK NOBODY WILL LOOK AT: COUNT FIRST, ASSIGN SECOND.\n"
		"Where an arriving thing must be attached to what it answers, try the exact key first - the\n"
		"identifier it quotes - then infer, and USE THE INFERENCE ONLY IF IT YIELDS EXACTLY ONE\n"
		"candidate. Two candidates means no link, not the first one.\n"
		"* THE DIFFERENCE FROM A RESOLVED CELL IS WHO SEES IT. A value in a row a person is about to\n"
		"check may be guessed and marked ambiguous, because they will correct it. A link written by a\n"
		"background process is never inspected, so a wrong one is permanent and invisible - and a\n"
		"missing one is merely missing.\n"
		"\n"
		"KEY: \"LOAD IT AGAIN AND UPDATE WHAT IS THERE\" IS A SECOND TICK PER FIELD: WHICH FIELDS\n"
		"IDENTIFY THE ROW. Their conjunction is assembled into ONE query before the loop and re-bound\n"
		"per row. A hit means update, a miss means create, and a switch saying \"do not create anything\n"
		"new\" turns a miss into a skip.\n"
		"STOP: AND A ROW WHOSE KEY IS PARTLY EMPTY MUST BE REFUSED BY NAME, not matched on what is\n"
		"left. Say which key fields were missing, in the row; matching on a partial key silently\n"
		"updates the wrong object, which is the one failure of an import nobody detects until a month\n"
		"later.\n"
		"* AND WHAT A REFERENCE IS SEARCHED BY DEFAULTS TO THE TYPE'S OWN PRIMARY PRESENTATION - by\n"
		"code where things are known by code, by name where they are known by name. That decision was\n"
		"already made once, in the metadata; inheriting it is why \"why does it look this one up by\n"
		"code and that one by name\" has an answer.\n"
		"\n"
		"KEY: \"WHAT HAPPENS IF I PRESS IT TWICE\" IS A DESIGN QUESTION WITH ONE ANSWER PER DESTINATION,\n"
		"AND ALL THREE ARE IDEMPOTENT BY A DIFFERENT ROUTE. Into a catalogue: matched rows update and\n"
		"unmatched create, so it is idempotent only if the search fields are right. Into the lines of\n"
		"a document: the whole section is EMPTIED first and the owner written once at the end, so it\n"
		"is idempotent by replacement. Into a register: position on the dimensions and read-then-merge\n"
		"or overwrite, so it is idempotent per record.\n"
		"* State which route this load takes, because the failure mode differs: a bad key doubles rows\n"
		"in the first, silently discards a person's added lines in the second, and loses nothing in\n"
		"the third.\n"
		"\n"
		"STOP: \"NOTHING IS WRITTEN BEFORE THE COMMAND\" IS THE RULE, AND THE EXCEPTION IS WHERE IT\n"
		"BREAKS. An import that creates documents while reading leaves a person no way to say no. But\n"
		"the unresolved counterparties usually get their own \"create these\" command - which writes\n"
		"parties, accounts and contracts BEFORE the load is pressed. That is defensible (resolution\n"
		"must happen before the rows can be matched) and it means the promise is not literally true.\n"
		"So state it as it is: reference data may be created early, ON A SEPARATE COMMAND, and\n"
		"nothing that MOVES anything is written before the load.\n"
		"* AND WHERE THE FAR SIDE HOLDS A COPY, \"HAVE WE GOT THIS\" AND \"MAY THEY FORGET IT\" ARE ONE\n"
		"DECISION. The check that recognises something already held has just looked up the date we\n"
		"first saw it, which is exactly what the retention rule needs: keep no copies means delete\n"
		"now; keep copies for N days means delete once that date plus N has passed. Deciding it\n"
		"anywhere else means reading the same row twice and disagreeing about it once - and expressing\n"
		"it inside the batch query as a computed column rather than in code keeps the two roads in\n"
		"step. Note that having two roads at all is the thing to avoid (`query-by-name`).\n"
		"\n"
		"BOTH DIRECTIONS BELONG IN ONE PROCESSOR, on two pages: sending and receiving are the same\n"
		"agreement with the same far side, the same settings and the same file format. Two separate\n"
		"processors mean the settings are entered twice and drift.\n"
		"\n"
		"AND THREE THINGS THE OUTGOING HALF TEACHES:\n"
		" THE STEPS ARE WRITTEN ON THE FORM, in four short lines beside the fields: choose what\n"
		" to send, untick what should not go, check that the ticked ones are ready, send and\n"
		" then take a report. A screen used once a month by somebody who is not a specialist\n"
		" should not need a manual open beside it.\n"
		" A ROW THAT CANNOT GO IS MARKED IN THE ROW - shown in red, with the REASON stated\n"
		" underneath in the words of the far side's requirement: \"counterparty tax number is\n"
		" empty\". Not a dialog after the attempt, and not a count of errors: the line and the\n"
		" field that is missing.\n"
		" AND GIVE EVERY ROW A SEVERITY THAT ONLY EVER RISES. Adding a complaint takes the greater\n"
		" of what is there and what is new, and appends the text on a new line - so the order the\n"
		" checks run in cannot lower a verdict, and no check has to know about the others. But\n"
		" then DECIDE, EXPLICITLY, WHICH LEVEL REFUSES, and say it on the screen: in the system\n"
		" measured only the top of a five-step ladder blocked a row, so an unresolved\n"
		" counterparty was a warning and the payment was written with the field empty. That may\n"
		" be right; it must be chosen. The question to answer for each level is \"would a person\n"
		" rather have this row missing, or wrong?\" - and the same question applies to every\n"
		" coercion: a value that does not fit the destination's type is complained about and then\n"
		" WRITTEN TRUNCATED. A complaint that does not stop the write is a note in a log, not a\n"
		" check.\n"
		" THE FOOTER COUNTS THE TICKED ONES ONLY - four documents, this much money - because\n"
		" that is what is about to leave. A total over everything read would be a number that\n"
		" describes nothing anybody is doing.\n"
		"\n"
		"KEY: SENDING IS TWO PHASES, AND NOTHING IS REPORTED AS SENT UNTIL THE BYTES LANDED. Write\n"
		"every ticked row into a buffer, marking each as \"in this file\"; only after the buffer is\n"
		"successfully written to disk does a second pass promote them all to \"sent\". A failure between\n"
		"the two leaves everything unsent, which is the only state that can be re-run safely.\n"
		"STOP: BUT DO NOT SPELL THE TWO PHASES AS NEGATIVE VALUES OF THE FIELD THAT MEANS SOMETHING\n"
		"ELSE. Found live: one column carried both \"how bad is this row\" upward and \"how far through\n"
		"sending it is\" downward, with no name for either meaning. Two facts, two fields - the storage\n"
		"saved is nothing and the reader can then be written by somebody who was not there.\n"
		"\n"
		"DEBUGGING IT IS AWKWARD BUT NOT BLIND. The far side is not ours and will not stop for us,\n"
		"so do not try to debug THROUGH it: put the breakpoint in the script that drives it, on\n"
		"our side of the call, and step from there - inspecting what came back, one call at a\n"
		"time. Expect to learn the far side's shape by looking at real answers rather than by\n"
		"reading about it.\n"
		"STOP: AND NEVER RECOVER A STATUS FROM THE TEXT OF AN ERROR. Found live: a fetch caught its\n"
		"exception, searched the localised description for \"407\", \"403\" and \"500\", and showed a\n"
		"different page for each - so the diagnosis depended on the interface language, on the\n"
		"platform's wording, and on no other number in the message happening to look like a code. The\n"
		"ladder was also unreachable, because its first test was true for every non-empty description,\n"
		"and every failure had been showing the generic page for years with nobody able to tell.\n"
		"KEY: A DOOR TO THE OUTSIDE HAS ONE CONVENTION, AND IT IS WRITTEN AT THE DOOR. Either it never\n"
		"throws and returns a result that always carries a status plus either the answer or a message,\n"
		"or it throws and says so in its specification. Both are workable; having both in one product\n"
		"is not - and that is what was measured: a download layer that returns a status beside a mail\n"
		"door whose comment ends \"this may raise, and the caller must handle it\".\n"
		"* AND EVERY FAILURE POINT SPLITS ITS AUDIENCES IN THE SAME BREATH: the DETAILED\n"
		"representation to the log under its own event name, the BRIEF sentence to the caller. From\n"
		"one catch, so the two can never describe different failures (`long-operations`: the same rule\n"
		"for a batch).\n"
		"* AND THE DOOR IS WORTH ITS FOUR LINES. A named module with a documented parameter structure\n"
		"is the contract; the implementation behind it is not. That is what lets the implementation be\n"
		"replaced.\n"
		"\n"
		"KEY: A STATEMENT FILE IS AN AUTHORITY OVER A WINDOW, NOT A STREAM OF EVENTS. It declares a\n"
		"period and a set of accounts, and within that window it is the truth: what we hold and the\n"
		"file does not mention was NOT there. Mark such rows for deletion rather than leaving them -\n"
		"and re-importing must UNMARK them, so the whole cycle can be run again without fear. Guard\n"
		"the past with a processed-up-to date so a file covering last year cannot delete this year's\n"
		"work (`scheduled-documents`: the cursor).\n"
		"* THIS IS THE DIFFERENCE BETWEEN AN IMPORT AND A FEED: a feed adds, an authority replaces\n"
		"within its window. Ask which one arrived before designing anything.\n"
		"KEY: AND NOT EVERY TOOL ON THIS BORDER IMPORTS ANYTHING. \"The bank paid four of the six I\n"
		"sent\" is a screen that lists the documents that ALREADY EXIST for a company, an account and a\n"
		"day, shows the opening balance read from the register, and lets a person tick what actually\n"
		"happened. Every tick recomputes the in-total, the out-total and the closing balance in the\n"
		"form, so the reconciliation against a paper statement happens BEFORE anything is written.\n"
		"* THE COMMAND THEN WRITES ONLY THE ROWS WHOSE TICK CHANGED, in one transaction, and the tick\n"
		"is two-way: un-ticking un-does it. A confirmation screen that can only confirm is one a\n"
		"person cannot correct, and they will correct it in the documents instead, one at a time.\n"
		"* Reach for this shape whenever the outside world tells you about things you already hold. It\n"
		"is far cheaper than an importer and it produces no duplicates by construction.\n"
		"\n"
		"KEY: THE END MARKER IS THE COMMIT OF A READ. A file is collected into memory and accepted\n"
		"ONLY when its closing section is reached - a truncated download then yields nothing rather\n"
		"than a plausible half. The same discipline as a posting: gather, then check, then act\n"
		"(`posting`).\n"
		"STOP: WHICH ONLY HOLDS IF EVERY EXIT FROM THE READER PASSES THE COMMIT. Found live: a\n"
		"malformed section in the middle returned early, past the check for the closing marker,\n"
		"leaving a half-filled table on the screen that the load command would happily write. An early\n"
		"return inside a parser is a commit nobody wrote.\n"
		"* AND CHECK THE MARKER THAT IDENTIFIES THE FORMAT AT THE HEAD, NOT AT THE TRAILER, or a file\n"
		"of entirely the wrong kind is parsed to the end before being refused - and the refusal then\n"
		"blames the end of the file for a problem in its first line.\n"
		"NOTE: AND WHAT YOU STORE AFTER PARSING IS A NORMALISATION, NOT A COPY. Several alternative\n"
		"bodies become one by a fixed precedence, markup is round-tripped through somebody else's\n"
		"parser, embedded references are rewritten into a scheme only this system understands - each\n"
		"step defensible, and together they mean the stored thing can no longer answer \"what exactly\n"
		"did they send us\".\n"
		"* SO DECIDE WHETHER THE ORIGINAL IS KEPT, AND KEEP IT IN THE HARD CASE TOO. Found live: the\n"
		"original was stored only when there were no attachments - the easy case - and discarded in\n"
		"exactly the case where somebody would ask; and the form it was stored in was one the\n"
		"file-saving routine refused to write out. If it is kept, check that it can be got back out.\n"
		"\n"
		"STOP: AND \"RE-IMPORT WRITES ONLY INTO EMPTINESS\" NEEDS THE EXCEPTIONS SPELLED OUT. Keeping a\n"
		"person's manual edit through a second import is right. But where the guard exempts whole\n"
		"KINDS of field wholesale - every flag, every date - a person cannot predict which of their\n"
		"corrections will survive, which is worse than either rule applied consistently. Decide it\n"
		"per field and say it on the screen.") },

	{ wxT("data-exchange"),
	  ibMcpText("Several bases that have to agree: what travels, who wins, and in what order."),
	  ibMcpText("DATA THAT HAS TO AGREE ACROSS SEVERAL BASES.\n"
		"\n"
		"KEY: THE ANSWER IS A SPLIT INTO TWO CLASSES, NOT \"SYNCHRONISE EVERYTHING\". Counted off a\n"
		"working configuration: of 202 catalogues, 187 register their changes automatically; of 236\n"
		"documents, 188 do NOT. THE SHARED VOCABULARY TRAVELS WHOLE AND UNCONDITIONALLY; THE FACTS\n"
		"TRAVEL BY WHO THEY BELONG TO.\n"
		"* AND THE TOTALS DO NOT TRAVEL AT ALL - not one accumulation or accounting register is in\n"
		"that exchange. Documents are sent and RE-POSTED on the receiving side, which recomputes its\n"
		"own balances. Sending movements would be sending a conclusion whose premises the other side\n"
		"cannot check.\n"
		"* THE EXCEPTION IS A MIRROR: when the second base must be a copy rather than a partner,\n"
		"everything goes - registers included. Deciding which of the two you are building is the\n"
		"first question, and it decides all the rest.\n"
		"\n"
		"KEY: BETWEEN ALWAYS AND NEVER SITS A THIRD ANSWER - SEND IT ONLY TO WHOEVER ALREADY HAS IT.\n"
		"Why would a branch hold two hundred thousand counterparties when it trades with forty? The\n"
		"mode is set FOR THE PAIR (kind of object, node) - always, on a condition, WHEN NEEDED, by\n"
		"hand, never - and \"when needed\" means the object travels as a tail behind a document that\n"
		"referenced it, decided from a register of what has already gone where.\n"
		"* WHAT IT COSTS: that register must be maintained for as long as the exchange lives, and an\n"
		"object that has never been written cannot be sent by reference at all - there is nothing yet\n"
		"to record. Reference data then arrives in the order the facts need it, which is also the\n"
		"hardest order to explain to whoever opens the branch catalogue and finds it incomplete.\n"
		"\n"
		"HOW A BASE KNOWS SOMETHING MUST BE SENT. Registration is not a flag on the object - it is a\n"
		"ROW PER RECIPIENT in a queue, so \"changed\" and \"delivered to whom\" stay separate facts, and\n"
		"acknowledgement can clear one recipient without touching another.\n"
		"KEY: ASK TWO QUESTIONS IN ORDER - DID IT CHANGE IN SUBSTANCE, AND ONLY THEN WHO NEEDS IT.\n"
		"Each plan declares WHICH attributes and which lines matter to it; before any recipient is\n"
		"computed, the stored version is compared with the new one on those alone. Unchanged in\n"
		"substance: nothing is registered, and a registration placed earlier is REMOVED. The cheap\n"
		"question comes first and throws away most of the traffic - a write that only touched a\n"
		"comment never reaches the queue at all - and the expensive per-node rules run over what is\n"
		"left.\n"
		"STOP: AN EMPTY DECLARATION MEANS ALWAYS CHANGED. Where nobody listed the attributes that\n"
		"matter, the check passes everything silently and the saving is simply not there, which reads\n"
		"in the field as an exchange that grew heavy for no reason. Whoever puts an object into a\n"
		"plan owes it that list.\n"
		"NOTE: AND \"HAVE THE LINES CHANGED\" IS ONE AGGREGATION, NOT A WALK. Add a column holding +1\n"
		"to the lines as they were and -1 to the lines as they are, concatenate the two tables and\n"
		"total them by the columns that matter: everything cancelling to zero means the two versions\n"
		"are the same set. Reordering and duplicated lines come out right for free, there is no\n"
		"row-by-row comparison and no row identity to maintain, and the answer costs one pass. Where\n"
		"the DIFFERENCE has to be shown to a person, that is the other question and it needs matching\n"
		"blocks instead (`object-history`).\n"
		"KEY: REGISTER WHERE IT WAS AND WHERE IT NOW IS. Before writing, compute the recipients from\n"
		"the STORED version (read from the base) and from the NEW one (in memory), and register in\n"
		"BOTH. Otherwise moving a document to another organisation leaves it visible for ever in the\n"
		"branch it left. Paid for with one extra read per write.\n"
		"STOP: AN OBJECT THAT FALLS OUT OF THE FILTER TRAVELS AS A DELETION, NOT AS SILENCE. The\n"
		"filter is checked twice - at registration and again when sending - and on the second check\n"
		"a failing object is sent as \"delete this\". That is the whole of \"restrict what a branch\n"
		"holds\": narrow the filter and the data physically leaves. Beside it sits a second verdict,\n"
		"IGNORE, for a document simply older than the agreed start date. \"NOT YOURS\" AND \"NOT NOW\"\n"
		"MUST BE DIFFERENT ANSWERS.\n"
		"* A RECORD SET IS CUT ROW BY ROW, NOT ACCEPTED OR REFUSED WHOLE: rows whose dimension is not\n"
		"in the node's list are dropped and, if nothing is left, the set is not sent. The unit of\n"
		"filtering for a register is the ROW - which means the receiver gets a PARTIAL set and, when\n"
		"writing it with replacement, must not lose what it holds under other dimensions.\n"
		"\n"
		"STOP: MOST OBJECTS DO NOT CARRY THE FIELD THE FILTER IS BUILT ON, AND THE ANSWER IS CHASED\n"
		"DOWN A CHAIN. A bank account belongs to its owner; where the owner is a counterparty, on\n"
		"through its contracts to the company named there. In the system examined that is some three\n"
		"hundred lines of type-by-type branching, written and maintained by hand - and THAT is the\n"
		"real cost of filtering by ownership, not the filter. Make it a NAMED FUNCTION PER TYPE,\n"
		"asked by the sender, or the chain gets copied into every place that decides recipients.\n"
		"STOP: AND THE DEFAULTS DECIDE MORE THAN THE RULES DO. An empty owner reads as SHARED rather\n"
		"than as nobody's, so a document whose company was left blank goes to every node; predefined\n"
		"items and the groups of a catalogue travel everywhere unconditionally. Both choices are\n"
		"defensible and neither is obvious - state them, because they are how data reaches a base\n"
		"that was never meant to hold it.\n"
		"\n"
		"STOP: NARROWING A NODE'S FILTER TAKES EFFECT BY ITSELF; WIDENING IT NEVER DOES. On saving\n"
		"the node, everything already queued is re-checked and what no longer passes is DE-registered\n"
		"- instantly and completely. But widening registers only the filter VALUES themselves, not\n"
		"the documents and history that now qualify. This asymmetry is the single most common\n"
		"complaint in the field: \"removing works at once, adding never works\". Whoever widens a\n"
		"filter must ALSO run a bulk registration, and that is a step in the instructions, not a bug\n"
		"to be fixed later.\n"
		"\n"
		"WHEN BOTH SIDES CHANGED THE SAME THING. The conflict is not detected by timestamps or\n"
		"version numbers but by ONE QUESTION: do I have an unsent change of this same object queued\n"
		"for this same node? The queue is already the detector.\n"
		"* WHO WINS IS DECIDED BY TOPOLOGY, NOT BY THE ALGORITHM: accept from the senior node, keep\n"
		"mine from a junior one. Never \"the later one wins\".\n"
		"* AND THE LOSING VERSION IS KEPT - both versions go into the history with explicit kinds,\n"
		"accepted and not accepted. A conflict resolved silently is a conflict that will be argued\n"
		"about later with nothing to look at.\n"
		"* A REFINEMENT WORTH COPYING: compare the two representations first, and if the data is\n"
		"actually identical, drop the conflict. Both sides making the same correction is not a\n"
		"disagreement.\n"
		"NOTE: AND A CLOSED PERIOD MAY REFUSE INCOMING DATA. If someone else's object falls before\n"
		"the local prohibition date, it is IGNORED, the fact is logged, and the exchange continues.\n"
		"Refusing to accept is a normal state, not a failure - `closing-a-period` is a right, and it\n"
		"applies to what arrives as much as to what is typed.\n"
		"\n"
		"KEY: TWO COUNTERS MAKE A RECEIPT, AND A BACKUP DETECTOR FALLS OUT FOR FREE. Each node keeps\n"
		"\"messages I sent\" and \"messages I received\", and every message carries both. The receiver\n"
		"rejects anything not newer than what it already took (replay), and uses the other number to\n"
		"clear its own queue. Now: if the correspondent acknowledges message N while my own records\n"
		"say I only ever sent N-5, I am the one who was rolled back - I have received a message from\n"
		"the future. The cure is to raise my counter to theirs and NOT clear registrations, because\n"
		"those changes may never have gone out.\n"
		"\n"
		"HOW THE OTHER SIDE RECOGNISES AN OBJECT - a ladder of four keys, and the identifier is only\n"
		"third: a previously stored correspondence, then THE NAME OF A PREDEFINED ITEM, then the\n"
		"identifier, then a configurable set of search fields. Predefined items are matched by name\n"
		"BEFORE identity precisely because separate bases give them different identifiers and the\n"
		"same name (`predefined`).\n"
		"STOP: AND \"EQUAL BY FIELDS\" IS NOT \"THE SAME\". Falling back to search fields will merge two\n"
		"genuinely different counterparties that share a tax number. Whether to fall back at all is\n"
		"decided PER TYPE, not once for everything.\n"
		"* A REFERENCE TO SOMETHING THAT HAS NOT ARRIVED YET becomes a stub carrying only its\n"
		"identity, held in a stack of unwritten objects. If the real thing arrives later in the same\n"
		"message the stub is discarded; if the message ends first, the stubs are written as they are\n"
		"- which is exactly where \"empty items\" in the receiving base come from. Deferred writing\n"
		"instead of two passes over the file.\n"
		"\n"
		"KEY: A DOCUMENT IS LOADED WITHOUT BEING POSTED, AND POSTED IN A SEPARATE WAVE. The order of\n"
		"objects in a message follows the transfer rules, not chronology, so at load time the\n"
		"balances a posting would need do not exist yet. Loaded documents go into a queue and are\n"
		"posted after the load finishes, ORDERED BY PRIORITY OF THE DOCUMENT TYPE, THEN BY DATE -\n"
		"receipts before issues. A failure increments a counter and leaves the document in the queue\n"
		"rather than aborting the exchange.\n"
		"* AND THE ORDER OF THE EXCHANGE ITSELF CANNOT BE REARRANGED: RECEIVE, THEN SEND, THEN POST.\n"
		"Only by reading their message do I learn which of mine they already have, so sending first\n"
		"means sending what they hold. If the read fails, the send is cancelled rather than done\n"
		"over unparsed data.\n"
		"\n"
		"NOTE: RECORD WHERE AN OBJECT WAS BORN, or it circles. One row per object saying \"created\n"
		"here\" or \"came from that node\" lets a sender skip returning data to whoever sent it. The\n"
		"decision must be taken BEFORE writing (while \"is new\" is still true) and carried in the\n"
		"object's properties to the write itself, where the reference finally exists.\n"
		"\n"
		"NOTE: A BULK BACKFILL BELONGS IN ITS OWN QUEUE. Loading history registers hundreds of\n"
		"thousands of objects and would strangle the daily exchange, so the backlog is a SECOND NODE\n"
		"of the same composition, and each ordinary message carries a QUOTA of rows out of it, with\n"
		"the number carried written into the message header so the far side can see progress. A queue\n"
		"as a node, not as a table.\n"
		"\n"
		"NOTE: THE UNIT OF EXCHANGE IS WHAT THE RECEIVER UNDERSTANDS, NOT WHAT CHANGED. Where the\n"
		"far side knows only \"an item\", a changed price, a changed stock figure, a new barcode all\n"
		"register a change OF THE ITEM. The cost is real - a one-line price edit re-sends a heavy\n"
		"object - and so is the alternative: sending it a concept it has no place for.\n"
		"\n"
		"NOTE: A NUMBER PREFIX FOR IMPORTED DOCUMENTS IS APPLIED ON LOADING, and it EATS DIGITS. The\n"
		"number is a fixed-width string, so a prefix that makes it longer fails the write outright.\n"
		"And documents older than the agreed start date get no prefix at all, so historical data\n"
		"lives by different rules than current data - for ever.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM, AND IT IS THE HEAVIEST REQUIREMENT IN THIS CORPUS.\n"
		"Three parts, and none of them is optional: a DECLARED LIST OF NODES, AUTOMATIC REGISTRATION\n"
		"OF CHANGES against those nodes (so an object edited anywhere is queued for whoever needs it,\n"
		"without the editing code knowing), and a MESSAGE ENVELOPE WITH ACKNOWLEDGEMENT NUMBERS (so\n"
		"both sides agree on what has been received and nothing is sent twice).\n"
		"* BUILT BY HAND THAT IS WEEKS, NOT DAYS - a catalogue of nodes, a registration register\n"
		"written from every object's module, a numbering of messages, and the change-registration\n"
		"half has the same defect as any hook nobody declares: the objects that forgot it are silent.\n"
		"* SO WHEN SOMEBODY ASKS TO SYNCHRONISE TWO BASES, PRICE IT BEFORE AGREEING, and ask which of\n"
		"the two cheaper shapes they actually need: a one-way FEED over an existing border\n"
		"(`external-data`), or ONE base divided by row-level access (`row-level-access`). Both answer\n"
		"most of what is asked for under the word \"exchange\", and neither needs any of the above.") },

	{ wxT("showing-a-value"),
	  ibMcpText("Asked for a column: look for a path to it before adding a field."),
	  ibMcpText("A COLUMN ASKED FOR IS NOT AUTOMATICALLY A FIELD TO ADD.\n"
		"\n"
		"When someone asks to see something in a list - a dynamic list, a report, a printed form -\n"
		"the first question is not \"where do I put this attribute\". It is: can this value already\n"
		"be REACHED from what the list is over?\n"
		"\n"
		"A list of goods receipt lines already holds a reference to the product, and the product\n"
		"holds its group, its unit, its vendor; the line holds a reference to its document, and\n"
		"the document holds the date, the partner, the warehouse. All of that is reachable through\n"
		"the dot - `Product.Parent`, `Ref.Partner` - without storing anything twice.\n"
		"\n"
		"Adding an attribute instead creates a SECOND copy of a fact that already exists, and from\n"
		"that moment something has to keep the two equal. Nothing does. The copy is written once,\n"
		"at creation, and then the product is renamed or moved to another group and the list goes\n"
		"on showing what was true that day - not visibly wrong, which is what makes it expensive.\n"
		"\n"
		"KEY: A COMPARISON SHOWN IN A LIST IS COMPUTED AT DRAWING TIME, AND BOTH SIDES MUST BE ON THE\n"
		"SAME BASE. \"Are we selling below cost\" is a cell filled while the row is rendered, not a\n"
		"stored field - and if the document's amounts exclude tax, the planned cost must have tax\n"
		"ADDED before the two are compared, or every line looks like a loss.\n"
		"* AND \"NOT KNOWN\" IS A THIRD STATE, NOT ZERO: where there is no planned cost, blank the\n"
		"cells rather than showing 0 and a 100% deviation.\n"
		"\n"
		"NOTE: AND THE EXCEPTION THAT IS NOT ONE: sometimes the value MUST be frozen - the price at\n"
		"which this was actually sold, the address the parcel actually went to, the rate applied\n"
		"on the day. That is not a copy of a current fact, it is a fact of its own with its own\n"
		"date, and it belongs stored. The test is a question about the past: if the source later\n"
		"changes, should this line change with it? Yes - walk the dot. No - store it, and say in\n"
		"the object's notes that it is deliberately a snapshot.") },

	{ wxT("form-to-areas"),
	  ibMcpText("Taking a paper form apart: which parts repeat, which are said once."),
	  ibMcpText("READING A PRINTED FORM INTO AREAS.\n"
		"\n"
		"Handed a blank - an invoice, a delivery note, an act - do not lay it out cell by cell.\n"
		"Read it for what REPEATS, because that is the only structural question a spreadsheet\n"
		"template asks.\n"
		"\n"
		"A form is three kinds of thing, and the middle one is the whole design:\n"
		" the HEADER - said once per document: the number, the date, the parties, the contract.\n"
		" Everything here is a parameter of one document.\n"
		" the DETAIL band - said once per LINE, and drawn over and over from a single area. Its\n"
		" columns are the tabular section's columns. If you find yourself making a second area\n"
		" that differs only in which row it sits on, you have not found the band yet.\n"
		" the FOOTER - said once again at the end: totals, the amount in words, the signatures.\n"
		"\n"
		"COLLAPSE WHAT REPEATS INTO ONE PRIMITIVE. The blank is a SPREADSHEET DOCUMENT, and it is\n"
		"marked out into areas - lines and groups of lines. The whole job is recognising which of\n"
		"them are the SAME line drawn again: if rows differ only in their values, they are one\n"
		"area, output once per line, not five areas that happen to look alike.\n"
		"(Keep the two words apart: the spreadsheet document is the PAPER and is cut into areas;\n"
		"a document's tabular section is DATA, and its lines are what the repeating area is drawn\n"
		"for. One area, many lines - they are not the same thing and do not correspond one to one:\n"
		"a single tabular section can feed several areas, and an area can be fed by none.)\n"
		"\n"
		"AND THE REPETITION IS NOT ALWAYS DOWNWARDS. Sometimes it runs to the RIGHT: a column per\n"
		"warehouse, per month, per price type, with the heading repeating across the page. Then the\n"
		"piece that repeats horizontally is its own area too, output to the right rather than below.\n"
		"Recognising this early is what stops a template being rebuilt when a second warehouse\n"
		"appears - a form drawn column by column has the number of warehouses frozen into it.\n"
		"\n"
		"KEY: WHICH MEANS A TEMPLATE IS CUT BOTH WAYS, and the worked example is a price-setting\n"
		"document. Two areas are named down the ROWS - `TableHeader`, `Row` - and two more across\n"
		"the COLUMNS: `Goods` (the number and the product name) and `Price` (price, unit, currency,\n"
		"discount). Printing walks them as a GRID: for each line of the document, put out `Row` x\n"
		"`Goods` once, then `Row` x `Price` again for every price type there is - wholesale, small\n"
		"wholesale, retail, planned cost - and the same crossing on the heading line, where the\n"
		"price type's NAME becomes the heading above its four columns.\n"
		"\n"
		"The result has as many column groups as the data has price types, and the template says\n"
		"nothing about how many. Draw those four groups by hand instead and the document is correct\n"
		"until somebody adds a fifth price type - after which it is quietly wrong, because nothing\n"
		"in the layout knows it is missing one.\n"
		"\n"
		"NOTE: THE WORDS THAT GIVE IT AWAY are \"a column for each...\" and any heading that is itself a\n"
		"VALUE: a price type, a warehouse, a month. A heading that names data is a vertical area\n"
		"waiting to be recognised.\n"
		"\n"
		"KEY: A VERTICAL AREA IS ALSO HOW A BLOCK OF COLUMNS BECOMES OPTIONAL, which is the other half\n"
		"of why a template is cut sideways. VAT is the standing example: some counterparties are\n"
		"charged it and some are not, and the ones who are not must not be handed a form with two\n"
		"empty columns and a nil total. Cut the VAT columns out as their own vertical area, give it\n"
		"a NAME that says what it is, and the module puts it out or does not - one decision, taken\n"
		"where the fact is known. A discount block, a currency block and a storage place behave the\n"
		"same way.\n"
		"\n"
		"KEY: SO AN OPTIONAL COLUMN HAS TWO BUILDS, AND THEY COST DIFFERENT THINGS. Say the goods may\n"
		"or may not carry a CHARACTERISTIC, and the form must show it as its own column when they do:\n"
		" A VERTICAL AREA for that column, joined on when it is wanted. One heading, one detail\n"
		" band, one decision. Add a second optional block - a discount, a storage place - and it\n"
		" is one more area, not one more form.\n"
		" A SECOND PAIR of areas: `TableHeaderCharacteristic` + `RowCharacteristic`, drawn for\n"
		" exactly that case, beside the plain pair. The module picks a pair and prints it.\n"
		"\n"
		"NOTE: THE SECOND IS SIMPLER UNTIL THE VARIANTS MULTIPLY, and then it multiplies with them: two\n"
		"independent options are four pairs, three are eight. A real delivery note in a working\n"
		"configuration ends up with `Row`, `RowDiscount`, `RowPlace`, `RowCode`, `RowCodeDiscount`,\n"
		"`RowCodePlaceDiscount` - every one of them a full copy of the same line, and a column widened\n"
		"in one of them and not the others is a defect nobody sees until that combination prints.\n"
		"\n"
		"AND VERTICAL AREAS NEST, which is what makes them hold a real form. A till receipt cuts its\n"
		"line into `Number`, `CodeColumn`, `Data` (the product), `AmountBeforeDiscount`,\n"
		"`DiscountAmount` and `Amount` - and the middle two sit under one wider area, `Discount`,\n"
		"because they are switched on and off together and carry a heading spanning both. One pair\n"
		"of areas for the whole receipt, and every question the form asks - is there an article\n"
		"code, is there a discount - is one of these joined on or left out.\n"
		"\n"
		"STOP: A VERTICAL CUT GOES THROUGH EVERY HORIZONTAL BAND IT CROSSES - the heading, the detail\n"
		"line AND THE TOTALS. Left out, the receipt above prints without the discount columns and\n"
		"with ONE total instead of three; a template that cut only the heading and the row would\n"
		"print a footer still totalling columns that are not on the page. Whatever is optional is\n"
		"optional all the way down.\n"
		"\n"
		"* SO: PAIRS WHEN THE VARIANTS ARE FEW AND DIFFER IN LAYOUT, not merely in one column - when\n"
		"the whole line is re-proportioned, the pair is honest and the vertical cut would fight the\n"
		"widths. VERTICAL AREAS WHEN THE OPTIONS ARE INDEPENDENT and combine - that is precisely the\n"
		"case a pair per combination cannot survive. The question to ask is not which looks tidier\n"
		"but HOW MANY COMBINATIONS THERE WILL BE.\n"
		"\n"
		"NOTE: AND THAT IS THE CHOICE BEHIND \"two columns in one area or two areas side by side\". Both\n"
		"print the same page:\n"
		" ONE AREA holding both columns is simpler and says they always travel together. Nothing\n"
		" to sequence, nothing to forget.\n"
		" TWO AREAS make each one optional and reorderable - and hand you the ORDER as a\n"
		" responsibility: they come out left to right in the order the module puts them, so the\n"
		" heading line and the detail line must be walked the same way or the columns and their\n"
		" titles come apart. That is a real cost, and it buys a real thing.\n"
		"Split when a block is genuinely optional or genuinely repeated; keep it whole when it is\n"
		"neither. \"It might be optional one day\" is not a reason to pay the ordering cost today.\n"
		"\n"
		"KEY: AND THAT RECOGNITION IS A DOOR, NOT A DETAIL. The moment the columns come from the data,\n"
		"the sheet has stopped being a blank and become a CROSS TABLE - the same shape a report makes\n"
		"when a grouping is put ACROSS instead of down. Two ways to build it, and knowing which one\n"
		"you are in is the whole decision:\n"
		" A PRINTED FORM with a vertical area, output to the right once per value. Right when the\n"
		" paper is fixed by somebody else - a blank with its own layout, borders and captions -\n"
		" and the horizontal axis is the only thing that varies.\n"
		" A COMPOSER OUTPUT with a level declared across the columns, which IS a cross table and\n"
		" needs no template at all: state the row grouping, state the column grouping, state what\n"
		" is summed, and every heading, every column and every total comes out of the data. Right\n"
		" whenever the answer is a table rather than a document - stock by warehouse, sales by\n"
		" month, price by type.\n"
		"\n"
		"The mistake worth naming: drawing a cross table cell by cell into a template because it\n"
		"started life as a blank. If nothing on the page is fixed by regulation or by a counterparty,\n"
		"it is a report with a column grouping, and drawing it is work that the composer would have\n"
		"done from the data.\n"
		"\n"
		"A ROW IS BROKEN DOWN BY PARAMETERS, and that is usually as far as it needs to go. Each\n"
		"cell is one of three things, and choosing between them IS the decomposition:\n"
		" TEXT - a caption that is the same on every printout. It belongs in the template.\n"
		" PARAMETER - the value comes from outside and fills the cell whole. Name it after what\n"
		" it is, not after where it sits.\n"
		" TEMPLATE - text with `[Name]` in square brackets inside it, for when a value has to\n"
		" sit INSIDE a sentence (\"Received [Quantity] pieces of [Product]\") or when spelling it\n"
		" out reads better on the page than three cells in a row would.\n"
		"A cell holding \"Invoice No. 12 of 3 March\" as one string is three parameters that were\n"
		"never separated: it cannot be reused, translated, or filled from anything else.\n"
		"\n"
		"NOTE: THE HEADER TELLS YOU THE DOCUMENT. Look at it first: what a blank asks for at the top is\n"
		"what the document must already hold, and it is common to find the form asking for\n"
		"something the metadata has no attribute for. Better discovered while reading the blank\n"
		"than while filling it.\n"
		"\n"
		"NAME AREAS BY WHAT THEY MEAN, never by where they sit. `Header`, `Title`, `TableHeader`,\n"
		"`Row`, `Total`, `TotalVat`, `AmountInWords`, `PlaceOfIssue`, `Signatures` - a printing\n"
		"module reads as a sentence when they are named this way, and a name like `Rows12to14`\n"
		"is wrong the first time a line is inserted above it. An empty band between blocks is an\n"
		"area too (`Gap`): spacing that the module can choose to put out or leave alone.\n"
		"\n"
		"KEY: A VARIATION OF THE DETAIL ROW IS ANOTHER PAIR OF AREAS, NOT ANOTHER TEMPLATE. Real\n"
		"blanks differ by which COLUMNS they show - with a discount column, with a storage place,\n"
		"with the article code, with several of those at once - and each variation needs its column\n"
		"headings to match. So they come in PAIRS: `TableHeader` + `Row`, `TableHeaderDiscount` +\n"
		"`RowDiscount`, `TableHeaderPlace` + `RowPlace`, `TableHeaderCodeDiscount` +\n"
		"`RowCodeDiscount`. The module then CHOOSES A PAIR and puts the rows out through it -\n"
		"one decision, taken once, instead of a second template kept in step by hand.\n"
		"\n"
		"TWO BLANKS, SO THE DIFFERENCE IS VISIBLE.\n"
		"\n"
		" A DELIVERY NOTE, the simple case: `Header` (number and date, supplier and buyer with\n"
		" their legal details, the contract), `TableHeader`, `Row`, `Total` and `TotalVat` under\n"
		" their own columns, `AmountInWords`, `Signatures`. Seven areas, one repeating band, and\n"
		" the whole form is a straight run down the page.\n"
		"\n"
		" AN ACT OF WORK DONE, the same skeleton with more said once: an `Approval` block at the\n"
		" very top (two columns of signatures - supplier's side and buyer's side - printed before\n"
		" anything else), `Title`, two lines of ACT PROSE naming the parties in a sentence,\n"
		" `ExtraInfo` for named parameters, then the same table and totals, then `PlaceOfIssue`\n"
		" and `Signatures`. What differs is not the mechanism: the act simply says more before\n"
		" the table.\n"
		"\n"
		" AND THE SAME NOTE GROWN UP - the one a working configuration ends with. Five pairs of\n"
		" table header and row (plain, with discount, with place, with code, with code AND\n"
		" discount), a SECOND table for returnable packaging with its own header, row and total,\n"
		" totals in four flavours (`Total`, `TotalDiscount`, `TotalVat`, `TotalWithVat`), and two\n"
		" signature blocks - one plain, one for a signature by power of attorney. Twenty-odd\n"
		" areas, and still ONE template: every one of them is a band that is either put out or\n"
		" not, decided by the module from what the document actually holds.\n"
		"\n"
		"TWO TABLES ARE TWO SUBJECTS, and that is a different thing from two variations. An act for\n"
		"work done with materials used prints a table of SERVICES and a table of MATERIALS: each\n"
		"has its own heading (\"name of product\" against \"name of raw material\"), its own detail\n"
		"row with its own columns, and its own total. They are not a pair to choose between - both\n"
		"are printed, one after the other, because the document holds two tabular sections and the\n"
		"paper says both.\n"
		"\n"
		"AND THEN THE SIGNATURES FOLLOW THE SUBJECTS. The same act carries `SignaturesMaterials`\n"
		"and `SignaturesServices`: who accepted the materials is not who accepted the work, and the\n"
		"blank asks each to sign under their own part. A single `Signatures` area at the foot is the\n"
		"simple case, not the rule - count the things being agreed to, not the pages.\n"
		"\n"
		"* REPETITION HAPPENS OUTSIDE THE TABLE TOO, and it is the case most often missed. A\n"
		"stocktake or a write-off signed by a COMMISSION has a chairman said once and then MEMBERS -\n"
		"name, position, signature - repeated for as many as there are. That is a detail band in\n"
		"every sense, and it belongs to a list of people rather than to a list of goods. Drawing\n"
		"three member lines into the footer freezes the commission at three.\n"
		"\n"
		"* AT THE OTHER END OF THE SCALE, AN AREA IS ONE LINE - and for the same reason as the big\n"
		"ones: because that line can be absent. Printing an e-mail is the plain case - sender,\n"
		"recipients, copies, subject, responsible, the body, the date it was printed - and each is\n"
		"its own area because each is printed only when it has something in it. No copies, no\n"
		"`Copies` line; nobody responsible, no `Responsible` line. The alternative is a form with\n"
		"labelled blanks, which reads as missing data rather than as absent data.\n"
		"\n"
		"NOTE: THAT IS WHY SUCH TEMPLATES END UP WITH `Header1`, `Header2`, `Header3`: the header did\n"
		"not fall into three ideas, it fell into three PIECES with optional lines between them. It\n"
		"is an honest cost of making single lines optional - but name the pieces after what they\n"
		"hold whenever they hold anything nameable, because a number tells the next reader nothing\n"
		"and stops being true the moment a fourth piece appears.\n"
		"\n"
		"An empty band is worth an area of its own here too (`BlankLine`): spacing that is put out\n"
		"deliberately between blocks that were, or were not, printed - the only way to keep the gaps\n"
		"even when the middle of the form is missing.\n"
		"\n"
		"NOTE: AND SOME FORMS HAVE NO REPEATING BAND AT ALL - one area, and that is the correct answer\n"
		"rather than a lazy one. An order of dismissal (form P-4), an order of appointment, a\n"
		"certificate: every line is said exactly once, so the whole sheet is a single area filled\n"
		"with parameters. Splitting it into `Header` / `Body` / `Footer` invents a structure the\n"
		"paper does not have, and the module then puts out three areas in a fixed order for no\n"
		"reason. Ask what repeats FIRST; when the answer is nothing, stop.\n"
		"\n"
		"Such a form is still made of the same three cell kinds, and two details recur on every\n"
		"personnel blank:\n"
		" A TICK BOX IS A BORDERED CELL with a parameter in it - the mark goes in when the\n"
		" condition holds and the cell stays empty when it does not. It is not a picture and not\n"
		" a font trick.\n"
		" SPACE LEFT FOR A HAND is deliberate: `\"__\" ________ 20__` for a date somebody writes\n"
		" in, ruled cells with nothing behind them. A blank that will be completed by hand has to\n"
		" keep those gaps, and an assistant filling every cell it can find destroys the form.\n"
		"\n"
		"AN OFFICIAL BLANK IS A DIFFERENT ANIMAL FROM A COMMERCIAL ONE, and four of its habits have\n"
		"to be built in rather than discovered late (a payroll payment sheet is the textbook case).\n"
		" IT CARRIES ITS OWN IDENTITY AS TEXT: \"Appendix 1 to the Regulation on cash operations,\n"
		" clause 18 of section II\", printed top right. That is the FORM saying which form it is,\n"
		" not data - it belongs in the template and changes only when the law does.\n"
		" EVERY BLANK LINE IS ANNOTATED. Under each rule sits a small italic caption saying what\n"
		" goes on it - \"(name of the enterprise/institution/organisation)\", \"(signature,\n"
		" surname, initials)\". On an official form these are compulsory, and they are text in\n"
		" the template beneath a bordered cell.\n"
		" THE COLUMNS ARE NUMBERED, on their own line under the headings: 1, 2, 3, 4, 5, 6. The\n"
		" regulation refers to columns BY THOSE NUMBERS, so the line is part of the table\n"
		" heading area and not decoration.\n"
		" AND THERE IS A SECOND HEADER FOR THE CONTINUATION SHEET - \"insert sheet to appendix\n"
		" No...\" - printed at the top of every page after the first. Two header areas, chosen by\n"
		" which page is being started, which is the same pair rule as the detail bands.\n"
		"\n"
		"KEY: AND SOMETIMES THE ROWS ARE NUMBERED PARAMETERS, WHICH IS NOT THE MISTAKE IT LOOKS LIKE.\n"
		"An expense claim has a block of ten accounting-entry lines and three \"received from\" lines,\n"
		"and the blank has exactly that many - printed empty when there is nothing to put in them,\n"
		"because the form is defined that way. So the cells are `Account1`...`Account10`,\n"
		"`Amount1`...`Amount10`, filled by index, and NOT a repeating band: a band would print three\n"
		"lines when there are three, and the form would no longer be the form. Fixed count, fixed\n"
		"height, empty rows and all - the one case where numbering in a name is right.\n"
		"NOTE: The moment the count is NOT fixed by the blank, this becomes the worst way to build a\n"
		"table: eleven entries have nowhere to go, and nothing says so.\n"
		"\n"
		"TWO MORE FIXTURES OF SUCH FORMS: a code entered ONE CHARACTER PER CELL (the tax number, the\n"
		"registration code - a row of little boxes, one glyph each, because the regulator wants it\n"
		"legible digit by digit), and a VERTICAL STRIP down the side - a receipt or a counterfoil,\n"
		"text rotated ninety degrees, that gets torn off and kept. Both are layout, and both are\n"
		"invisible in any description of the data.\n"
		"\n"
		"A TOTAL PER PAGE IS NOT A TOTAL PER DOCUMENT. The same sheet carries \"total for this\n"
		"page\" under the rows, and it only means anything if the module knows where the page ended -\n"
		"so the page break is a decision the printing makes, not a property of the data. Design for\n"
		"it early: a footer that assumes one page has to be taken apart to add it.\n"
		"\n"
		"AND A HEADER CAN HOLD A SMALL FIXED TABLE - the corresponding account block (account,\n"
		"sub-account, analytics code, purpose code) is a three-by-three grid inside the header, said\n"
		"once, with no repetition at all. It is a table by its looks and a header by its behaviour;\n"
		"the second is what decides which area it belongs to.\n"
		"\n"
		"THREE THINGS A PRINTED SHEET SHOWS THAT A DESIGN ON PAPER DOES NOT.\n"
		" A RULED LINE WITH ITS CAPTION UNDER IT is one cell and one small italic line: the rule\n"
		" is the cell's bottom border, `(signature)` sits beneath it as TEXT. Not underscores,\n"
		" which the module would have to print around and which never line up.\n"
		" NOT EVERY COLUMN HAS A TOTAL. A stocktake totals the money columns and leaves the\n"
		" quantity column blank, because units of different goods do not add up to anything a\n"
		" person would read. A total belongs where the addition MEANS something.\n"
		" THE COUNT IS ITS OWN LINE. \"5 items, for 955.30\" and then the amount in words is what\n"
		" a foot of a commercial blank actually says - a sentence built from a row count and a\n"
		" sum, and a second one spelling the sum out. Both are parameters of the footer, not\n"
		" another table.\n"
		"\n"
		"NOTE: THE TEST FOR A NEW AREA is not \"does it look different\" but \"is it said a different\n"
		"number of times, or chosen instead of another one\". Said once per document - part of the\n"
		"header. Once per line - a detail band, and there is one per subject. Chosen between - a\n"
		"pair. Anything else is formatting inside an area that already exists.\n"
		"\n"
		"KEY: A CELL IS FILLED IN ONE OF THREE WAYS, AND ALMOST EVERY CELL IS THE SECOND.\n"
		" TEXT - a caption typed once and printed as typed. `Quantity`, `Total`, `Issued by`.\n"
		" PARAMETER - the WHOLE cell is one value the module substitutes by name. This is what a\n"
		" form is made of.\n"
		" TEMPLATE - literal text with named gaps inside it, `No. [Number] of [Date]`. For a\n"
		" PHRASE that must stay a phrase: a sentence broken into three cells to hold two values\n"
		" cannot be centred, cannot wrap and comes apart the moment a value is longer.\n"
		"Counted across seven working blanks - a cash order, a goods issue note, a tax invoice, a\n"
		"payment order, a turnover sheet, an invoice, a document register: PARAMETER 135, TEXT 8,\n"
		"TEMPLATE 3. A printed form is mostly holes, and a layout that is mostly captions has not\n"
		"been made into a form yet.\n"
		"\n"
		"STOP: ASK HOW MANY LANGUAGES THIS CONFIGURATION HAS BEFORE TYPING THE FIRST CAPTION.\n"
		"platform_state answers it in one word, and the answer decides how every caption in the form\n"
		"is written. One language and a plain string is the whole of it. TWO OR MORE and every\n"
		"caption has to carry the every-language form, exactly as a synonym does - because a bare\n"
		"string is stored as itself and printed as itself, and the second language gets the first\n"
		"language's words.\n"
		"AND NOTHING WILL TELL YOU. The form is correct in the language it was typed in, which is the\n"
		"language whoever built it is looking at; the failure appears for somebody else, later, and\n"
		"reads as a translation that was never done rather than as a form that cannot hold one.\n"
		"Retrofitting is per-cell and there may be two hundred of them, so this is a question asked\n"
		"FIRST or paid for twice.\n"
		"* And it is not only the captions. A form's own designation, its column headings, the words\n"
		" `Total` and `of which VAT`, the small print under a signature - all of it is language.\n"
		" What is NOT is the parameter names, which are identifiers and stay as they are.\n"
		"\n"
		"STOP: AND THE TWO KINDS OF TEXT ARE NOT INTERCHANGEABLE. A CAPTION IS TRANSLATED; A PARAMETER\n"
		"NAME IS NOT. The text of a caption or a template cell goes through localisation as the sheet\n"
		"is put out - so it may carry the every-language form, and a form built in one language comes\n"
		"out right in another. A parameter's text is looked up AS WRITTEN, because it is an\n"
		"identifier the printing module knows. Put a translated string where a name belongs and the\n"
		"cell prints empty in every language but the one it was typed in, with nothing anywhere\n"
		"saying why.\n"
		"\n"
		"STOP: AND THE FILL KIND IS A PROPERTY OF THE CELL, NOT AN EFFECT OF PUTTING A NAME IN IT.\n"
		"A cell carrying a parameter name and still marked as text prints EMPTY - the module's\n"
		"substitution has nothing to reach. It looks correct in every listing, because the name is\n"
		"there; it is wrong only on paper.\n"
		"\n"
		"KEY: A FORM BREATHES THROUGH NARROW COLUMNS, NOT THROUGH PADDING. There is no margin\n"
		"inside a cell - so the gutter between two blocks IS a column of its own, and the gap\n"
		"between two bands IS a short row. In the same blanks the widths run 12-15 for a gutter\n"
		"against 70-210 for a column that carries something, and a spacer row is 4-6 against 30-40\n"
		"for a line of text. Text set hard against a rule is the mark of a layout drawn without\n"
		"them; some forms go further and name the gap - `Spacer` is an AREA in a real invoice.\n"
		"\n"
		"KEY: RULES ARE THE EXCEPTION, AND THEY HAVE WEIGHT. Most cells of a real blank carry NO\n"
		"line at all: in those seven, the commonest border width by a wide margin is 0. Where a\n"
		"line is drawn it is chosen - a heavy 2-3 frames a block and says where the table begins,\n"
		"a hairline 1 divides one row from the next. A sheet ruled everywhere at one weight reads\n"
		"as a grey mesh with no structure in it, which is what ruling a whole table `all` gives\n"
		"you. Draw the frame first, then decide which inner divisions earn a line.\n"
		"\n"
		"NOTE: WRAPPING IS FOR THE COLUMNS THAT CARRY LANGUAGE, and it is a third of the cells in a\n"
		"real blank - 332 wrapped against 787 left to place themselves, with clipping used twice in\n"
		"the lot. The split is by CONTENT, not by taste: a product name, an address, a description\n"
		"is longer than its column and has nowhere to go, so it wraps and the row grows. A figure,\n"
		"a date, a code is not wrapped - it would break in the middle of a number.\n"
		"\n"
		"KEY: A PRINTED FORM IS STRUCTURED BY LINES AND WEIGHT, NOT BY FILL. Counted over six\n"
		"hundred formats in working blanks, a background colour appears ELEVEN times - under two\n"
		"per cent - while borders appear on eight hundred edges. The reason is the paper: a form is\n"
		"printed on a monochrome printer and a filled cell becomes a grey block that swallows the\n"
		"text in it. Shade a heading if you must; structure it with a rule.\n"
		"\n"
		"NOTE: AND THE RULES ARE NOT EVENLY SPREAD - the bottom edge is the commonest by a clear\n"
		"margin (140 bottom, 116 top, 103 left, 88 right in the same count). A form is ruled ACROSS\n"
		"more than DOWN, because most of its lines are either something to write ON or the division\n"
		"between one row and the next. Reach for a bottom border first and add the sides when the\n"
		"thing genuinely is a box.\n"
		"\n"
		"KEY: ONE FACE, THREE SIZES, AND EMPHASIS IS BOLD - THERE IS NO SECOND WAY. Counted over the\n"
		"fonts of six working blanks: fifty-three Arial against four of anything else, so a form does\n"
		"not mix faces; sizes cluster at 8, 9 and 10 for the body, one step up around 14 for the\n"
		"designation at the top, and 6 to 7 for the small print under a signature line. TWENTY-FIVE\n"
		"of the fifty-seven fonts are BOLD and NOT ONE IS ITALIC.\n"
		"Bold is what carries the title, the column captions and the totals row - the three things a\n"
		"reader's eye is supposed to land on. Italic reads as a personal note on a document that is\n"
		"meant to be official, which is why it is absent; and underline is not emphasis at all - it\n"
		"appears twice, both times as a LINE TO WRITE ON. Reach for size to say \"this is the top of\n"
		"the page\" and for bold to say \"this is the number that matters\", and stop there.\n"
		"\n"
		"NOTE: A NEGATIVE FIGURE IS MARKED, not left to be read. A working blank sets \"mark\n"
		"negatives\" on the money columns, so a credit or a loss is visible at a glance rather than\n"
		"found by noticing a minus sign among twenty numbers.\n"
		"\n"
		"KEY: THE HOUSE STYLE IS ITS OWN TEMPLATE, SHARED. A configuration keeps common areas\n"
		"centrally - a report heading, the organisation block, the settings description, the\n"
		"signature block - and every standard report joins them in rather than drawing its own.\n"
		"Two consequences: a form that draws its own heading is already out of step with the rest,\n"
		"and changing the house style is one edit rather than sixty.\n"
		"\n"
		"KEY: THE BANDS HAVE SETTLED NAMES, AND USING THEM IS HALF OF BEING RECOGNISED. Counted\n"
		"across working blanks, the vocabulary barely varies: `Header` for what is said once at the\n"
		"top, `TableHeader` for the column captions, `Row` for the detail band, `Total` and its\n"
		"companions (`TotalVAT`, `TotalToPay`) for the sums, `AmountInWords`, `Footer` for the\n"
		"signatures - and `Spacer` where a gap is deliberate. An invoice adds `Buyer` and `Seller`\n"
		"because it names its parties; a goods note adds `Unit` and `Code` as COLUMN bands.\n"
		"Somebody opening the template later reads those names before they read a single cell, and\n"
		"a form whose bands are called `Area1` and `Area2` has to be read cell by cell to be\n"
		"understood at all. Name what the band IS, not where it sits.\n"
		"\n"
		"NOTE: AND THE LOOK IS DECLARED ONCE, NOT PER CELL. A real blank keeps a table of formats and\n"
		"has its cells point at entries in it - so a hundred cells share four appearances, and\n"
		"changing one changes them together. Where the door only sets a cell at a time, the same\n"
		"discipline is worth keeping by hand: decide the two or three looks a form has (caption,\n"
		"figure, total) and apply them, rather than choosing a font and a weight per cell as you go.\n"
		"\n"
		"KEY: HANDED THE BLANK AS A SPREADSHEET FILE, IMPORT IT AND THEN CUT IT. The layout, the\n"
		"widths, the rules and the captions come in as they are; the work is deciding WHICH CELLS\n"
		"BECOME HOLES and where the bands are. Read the paper the way its owner reads it: what is\n"
		"said once about the document, what is written on every line, what is added up at the end,\n"
		"and what is only there sometimes. Those four questions are the header, the detail band,\n"
		"the footer and the optional column block - in that order, before a single cell is\n"
		"touched.") },

	{ wxT("long-operations"),
	  ibMcpText("Work that takes minutes: running it in the background and telling the person about it."),
	  ibMcpText("WORK THAT TAKES LONGER THAN A PERSON WILL SIT STILL FOR.\n"
		"\n"
		"THE SHAPE IS THREE DECISIONS, AND THE FIRST IS TAKEN BEFORE ANYTHING STARTS: WHERE THE\n"
		"ANSWER WILL GO. A place for the result is created first, its address is handed to the\n"
		"background work as a parameter, and the caller gets back the address plus a handle on the\n"
		"job. Deciding this afterwards is what makes background work hard to retrofit.\n"
		"* AND THE RESULT LIVES AS LONG AS THE FORM THAT ASKED. The job outlives the client; the\n"
		"ANSWER does not. Close the window and there is nobody to collect it and nowhere to put it.\n"
		"Say this out loud when designing, because \"I closed it, where is my report\" is the first\n"
		"question asked.\n"
		"\n"
		"KEY: WAIT A COUPLE OF SECONDS IN SILENCE BEFORE SHOWING ANYTHING. Start the job and wait a\n"
		"short fixed time - longer on a slow connection - swallowing the timeout deliberately.\n"
		"Finished inside that window: the person never sees a progress window at all. Not finished:\n"
		"open the indicator and poll with a GROWING INTERVAL - a second, then half again, up to a\n"
		"ceiling. A short operation must not pay in flicker, a long one must not pay in traffic.\n"
		"\n"
		"KEY: \"NOT FINISHED\" IS ONE ANSWER; EVERYTHING ELSE IS SEVERAL. The state is asked of the\n"
		"scheduler, and four outcomes must be told apart, because the remedy differs:\n"
		" THE JOB IS NOT THERE AT ALL - the server restarted and it was lost.\n"
		" IT FAILED, WITH AN ERROR - unwind the chain of causes to the deepest one and show THAT.\n"
		" IT FAILED, WITH NOTHING - all that can be honestly said is where to look.\n"
		" IT WAS CANCELLED by an administrator.\n"
		"* AND CANCELLING IS ATTEMPTED, NOT ASSERTED: the job may have finished in the same instant,\n"
		"so a failure to cancel is not an error.\n"
		"\n"
		"NOTE: A PROGRESS BAR IS A PROPERTY OF THE ENVIRONMENT, NOT OF THE CALL. The same loop that\n"
		"shows an indicator when a person is watching must run silently when called from a background\n"
		"job. And it is worth a threshold - below two or three items an indicator is noise.\n"
		"* THE LOOP THAT DRAWS PROGRESS IS ALSO THE ONLY PLACE INTERRUPTION CAN HAPPEN, so the check\n"
		"for it belongs in the same step. A batch with no progress step cannot be stopped either.\n"
		"\n"
		"KEY: A BATCH OVER MANY OBJECTS RETURNS ITS FAILURES; IT DOES NOT STOP AT THE THIRD ONE. Each\n"
		"item is checked for unfilled fields FIRST - \"not filled in\" is an outcome, not an exception -\n"
		"then attempted inside a guard, and a failure is collected as a pair of {which object, what\n"
		"went wrong} and the loop continues. An empty list at the end means everything worked.\n"
		"* THE FAILURE LIST CARRIES THE OBJECT, not just the text, so the screen can offer \"open the\n"
		"one that failed\" - which is the only thing the person will want to do next.\n"
		"* AND THE SPLIT BETWEEN AUDIENCES IS DECIDED HERE, ONCE: the SHORT sentence goes to the\n"
		"person, the DETAILED representation with the object and its kind goes to the log. Both from\n"
		"the same guard, so they cannot describe different failures (`external-data`: the same\n"
		"convention at the download door).\n"
		"\n"
		"KEY: A QUESTION ASKED INSIDE A BATCH IS FOUR-VALUED, AND THE ANSWER TRAVELS IN THE SAME\n"
		"VARIABLE THAT CARRIED THE QUESTION. Yes, no, yes to all, no to all - passed by reference, so\n"
		"the routine asks only when the variable holds nothing or a single-item answer, writes the\n"
		"person's reply back into it, and the caller hands the SAME variable to the next item. A\n"
		"standing \"all\" answer then short-circuits every later call and the loop itself knows nothing\n"
		"about dialogues.\n"
		"* Two of the four answers stop that item immediately; two fall through. Say which is which at\n"
		"the routine, because the caller cannot see it. \"Stop asking me about every one of forty\n"
		"attachments\" is a complaint about a missing fourth value, never about the question.\n"
		"\n"
		"STOP: AND A VALUE WHOSE ANSWER DEPENDS ON WHERE THE CODE RUNS MUST NOT BE HANDED OUT UNDER\n"
		"ONE NAME. Two live cases, one shape. A \"working date\" that a person sets is a property of\n"
		"their session and never crosses to the server, so the same call returns their date in one\n"
		"place and today's date in the other. And a setting for reaching outside the system lives per\n"
		"person in one deployment and once for the whole server in another, so the same call resolves\n"
		"differently by deployment mode.\n"
		"* THE VISIBLE SYMPTOM IS ALWAYS \"IT WORKS WHEN I DO IT AND NOT FROM THE SCHEDULED JOB\", and\n"
		"it is designed-in rather than broken. Either give the two answers two names, or pass the\n"
		"value in from whoever knows - and say in the note which of the two you did.\n"
		"* The wider habit to watch: a routine whose signature promises it depends only on its\n"
		"arguments, reading the current user, the current date or a session switch from inside.") },

	{ wxT("user-settings"),
	  ibMcpText("Storing what a person set up for themselves: the address, who sees it, surviving a release."),
	  ibMcpText("KEEPING WHAT A PERSON SET UP FOR THEMSELVES.\n"
		"\n"
		"KEY: THE ADDRESS IS A TRIPLE - WHOSE, OF WHAT, UNDER WHAT NAME. An independent register\n"
		"keyed by (person, object name, setting name) holds the value; `shapes` says settings live in\n"
		"such a register, and this is what its key looks like when the setting is NAMED.\n"
		"* THE OBJECT IS A STRING, NOT A REFERENCE, and that is deliberate: the setting outlives the\n"
		"object, and the object knows nothing about its settings.\n"
		"* THE NAME IS PART OF THE KEY, NOT AN ATTRIBUTE - so renaming a setting is reading it under\n"
		"the old key and writing it under the new one, and the writing routine has to be told which\n"
		"key it replaces.\n"
		"\n"
		"KEY: THREE STOREYS OF VISIBILITY, AND THE PRIORITY IS THE ORDER, NOT A STORED NUMBER. The\n"
		"\"whose\" dimension takes a person (private), a group of people (shared with a group), or\n"
		"NOTHING AT ALL (everybody's). Which one applies is answered by combining the three readings\n"
		"in that order and taking the first row. Nowhere is a priority stored - the priority IS the\n"
		"order of the union, and adding a fourth storey is adding a fourth branch.\n"
		"* WORTH SEEING: THE THIRD STOREY WAS BOUGHT WITH AN EMPTY VALUE, NOT A THIRD DIMENSION. In a\n"
		"composite-typed dimension, \"no value\" is a legitimate meaning, and here it means \"anyone's\".\n"
		"\n"
		"NOTE: \"APPLY THIS ONE WHEN THE FORM OPENS\" IS EXCLUSIVE, AND THE EXCLUSIVITY IS KEPT BY THE\n"
		"WRITING ROUTINE, NOT BY THE DATA. Writing one with the flag clears the flag on the others\n"
		"for that person and object. Nothing in the storage enforces it, so any write that bypasses\n"
		"the routine breaks the invariant - which is the cost of putting an invariant in a procedure.\n"
		"\n"
		"KEY: WHAT WAS LAST TYPED INTO A FIELD IS A SETTING TOO, KEYED BY A PATH AND STORED SERIALISED.\n"
		"The address is the object plus the field, as text; the values are kept as text rather than as\n"
		"live references, so a value somebody deleted cannot break the READ of the whole list. Adding\n"
		"is a most-recently-used move - remove every existing copy, insert at the head, truncate to a\n"
		"few - not an append, or the list stops being recent within a week.\n"
		"* AND THE PRESENTATIONS ARE RE-FETCHED THROUGH AN ACCESS-FILTERED QUERY, WHICH IS WHAT KEEPS\n"
		"IT HONEST. Whatever the query does not return is dropped, so a value the person may no longer\n"
		"see falls out of their own history BY CONSTRUCTION, with no permission check written anywhere\n"
		"in that code; deletion and access are then one pass rather than two rules that disagree.\n"
		"Without it, a remembered list is a hole in `row-level-access` that nobody thinks to audit.\n"
		"* AND A READ THAT REPAIRS MUST DECIDE, EXPLICITLY, WHETHER THE REPAIR IS DURABLE. Cleaning the\n"
		"list on every read and never writing it back means paying for the cleaning for ever and\n"
		"keeping the rubbish; and if the repair is not persisted, the flag that tracks it should not\n"
		"exist either.\n"
		"\n"
		"KEY: SURVIVING A NEW RELEASE IS NOT A MECHANISM, IT IS THE FORM OF STORAGE. What is stored\n"
		"is VALUES BY NAME; the STRUCTURE always comes from the live object. Applying walks the\n"
		"object's current fields, looks each up in what was saved, and skips what is not there. A\n"
		"field that disappeared is a `continue`, not an error. There is no version stamp on a setting\n"
		"at all, and none is needed.\n"
		"* AND THE WRITE SIDE OF THE SAME PROBLEM IS A VERSIONED BACK-FILL. When a key is ADDED to a\n"
		"stored structure, register a handler against the version that introduced it: walk every\n"
		"account, load that account's stored value, insert each missing key with its default, and save\n"
		"back ONLY IF something was missing. Idempotent by construction, cheap on a base where it has\n"
		"already run, and declared beside the code that owns the setting rather than in a central list\n"
		"nobody maintains. Reading tolerates absence, writing supplies the default once; doing only\n"
		"the first leaves every reader carrying a default the person can never see or change.\n"
		"KEY: AND A PERSON WHO MAY NOT SAVE THEIR OWN DATA MUST GET THE DEFAULT EXPERIENCE, NOT AN\n"
		"ERROR. Every read and write of a personal setting begins by asking whether this account holds\n"
		"that right: the writer does nothing, the reader returns the caller's default. Otherwise a\n"
		"restricted or service account cannot open a form at all, and the failure arrives as a stack\n"
		"trace on a screen somebody uses to look at figures.\n"
		"* AND THE READER FOLDS IN THE DEFAULT ITSELF - it takes the default as an argument and\n"
		"returns it when the store answers nothing - so no call site needs a test for absence. One\n"
		"place decides what \"unset\" means, which is what keeps two screens from disagreeing about it.\n"
		"* THE SAME THINKING IN THE SMALL: coerce a saved value to the field's CURRENT type rather\n"
		"than trusting it; accept a list only if the type still matches; where a comparison is no\n"
		"longer possible on that field, degrade it to one that is.\n"
		"\n"
		"NOTE: A SETTING THAT CAME WITH THE PRODUCT AND WAS THEN EDITED IS MARKED INSIDE ITS OWN\n"
		"VALUE - one key added to the stored structure saying it was touched. It answers \"put it back\n"
		"as it was\" without a second row. The cost is that the mark is invisible to a query: you\n"
		"cannot filter or sort by it without unpacking every value.\n"
		"\n"
		"STOP: A SMALL SETTING ADDRESSED BY A GLUED STRING AND STORING A LABEL IS A TRAP WORTH\n"
		"NAMING. \"Which printed form is my default\" stored as the TEXT of a button is found again by\n"
		"searching for that text - and silently falls back to the first entry when the form is\n"
		"renamed, removed, or the interface is translated. Storing a name instead of an identity buys\n"
		"portability between bases and pays with a silent reset.") },

	{ wxT("extensions"),
	  ibMcpText("Adding a printed form or a fill button to a live system without editing the configuration."),
	  ibMcpText("SOMEBODY ELSE'S CODE ATTACHED TO OUR OBJECTS.\n"
		"\n"
		"\"We need our own printed form and our own Fill button, but the configuration must not be\n"
		"touched.\" This is the ordinary state of a deployed system, not an exception: the vendor\n"
		"updates the configuration, the customer's additions must survive the update.\n"
		"\n"
		"KEY: THE ATTACHMENT IS A ROW, AND ITS GLUE IS THE NAME OF THE METADATA OBJECT AS A STRING.\n"
		"An item holds the external code itself, and a table beside it says where it applies: the\n"
		"metadata name it belongs to, WHAT KIND of extension it is (printed form / fills a tabular\n"
		"section / attaches to a report), which section, the caption for its button, extra\n"
		"parameters, and how it is launched. A string rather than a reference is what lets the row\n"
		"exist for an object the extension's author never had.\n"
		"\n"
		"* THE FORM BUILDS ITS EXTRA BUTTONS BY QUERYING THAT TABLE WHEN IT OPENS - grouped by\n"
		"section, so each tabular section gets its own submenu. Nothing is compiled in; a new\n"
		"extension appears without a release.\n"
		"\n"
		"KEY: THE CONTRACT WITH FOREIGN CODE IS A SET OF NAMES, AND IT IS CHECKED BEFORE USE. Before\n"
		"handing the extension the object it is to work on, or its parameters, ASK ITS OWN METADATA\n"
		"whether it declares an attribute of that name. An extension written for an older host is\n"
		"then simply given less, instead of failing on assignment.\n"
		"\n"
		"NOTE: AND THE LAUNCH IS TWO VERBS, NOT ONE - print, or initialise and run - because the two\n"
		"kinds of extension are used at different moments. Deciding which verbs exist is the whole\n"
		"of the extension interface; everything else is the row above.\n"
		"\n"
		"NOTE: WHAT THIS BUYS AND WHAT IT COSTS. It buys a system that can be adapted on site by\n"
		"somebody who cannot rebuild it. It costs a boundary that is checked at RUN time and only\n"
		"there: no compiler sees across it, and the failure of a badly-written extension arrives as\n"
		"a failure of the document it was attached to.\n"
		"\n"
		"KEY: WHERE HANDLERS, SCHEDULED STEPS AND UPDATE STEPS ARE CONFIGURED BY NAME, THE NAME GOES\n"
		"THROUGH ONE GATE. The gate splits the name, checks that its first part is a real module or a\n"
		"permitted kind of object in the metadata, checks that the last part is a legal identifier,\n"
		"and only then calls it. Do not re-implement the identifier grammar: hand the candidate to\n"
		"something in the platform that already refuses non-identifiers and take its refusal.\n"
		"STOP: AND THE CHECKER MUST BE THE EXECUTOR'S OWN LIST, NOT A SECOND COPY OF IT. In the system\n"
		"measured there were two gates - one that runs a name, one that only validates it - and the\n"
		"validating one was missing three kinds of object, so a name the executor would happily run\n"
		"was reported as invalid in advance. One list, one place, and the validator calls it.") },

	{ wxT("sections"),
	  ibMcpText("The command interface: how a person reaches anything at all."),
	  ibMcpText("SECTIONS ARE THE APPLICATION AS A PERSON MEETS IT.\n"
		"\n"
		"A catalogue, a document or a report that belongs to no section works perfectly and is\n"
		"INVISIBLE: there is no menu it appears in and no way to open it. Checking objects into\n"
		"sections is the last step of building anything, and the one that gets forgotten because\n"
		"everything the builder does goes through the designer, where the tree shows it regardless.\n"
		"\n"
		"* A SECTION IS A JOB, NOT A KIND OF OBJECT. Purchases, Sales, Stock, Finance, Production,\n"
		"Payroll, Administration - these are what people DO, and each maps to a person or a part of\n"
		"a day. Sections called Catalogues, Documents and Reports are the metadata tree wearing a\n"
		"costume: they answer \"what kind of thing is it\", which nobody wonders, instead of \"where\n"
		"do I do my work\", which is the only question being asked.\n"
		"\n"
		"THE SAME OBJECT BELONGS IN SEVERAL. A goods catalogue is opened from Purchases, from Sales\n"
		"and from Stock, and putting it in one of them and expecting people to remember which is a\n"
		"decision they will pay for daily. Membership is cheap; hunting is not.\n"
		"\n"
		"KEY: AND WHERE SOMEBODY WORKS WITH A MIXTURE OF DOCUMENT KINDS IN TIME ORDER, THAT IS A\n"
		"JOURNAL, AND IT IS NAMED AFTER THE WORK. A cashier wants receipts and payments interleaved by\n"
		"date, not two lists; so do warehouse papers, the papers of one party, and the month-end\n"
		"operations. Counted in a full system there are some thirty-five of them, named for the job -\n"
		"never \"documents of kind X\", which is the list form doing that already.\n"
		"* THE TEST FOR CREATING ONE: does a person need a TIMELINE across kinds? If they only ever\n"
		"open one kind at a time, a journal adds a place to look and nothing else.\n"
		"* AND ONE JOURNAL PER MECHANISM IS WORTH KNOWING ABOUT: the documents still awaiting a second\n"
		"stage of posting, shown as a timeline. A queue nobody can see is a queue nobody trusts\n"
		"(`deferred-posting`).\n"
		"\n"
		"WHAT A SECTION HOLDS, in the order a person needs it: the LISTS they live in (documents\n"
		"first, then the catalogues those documents use), the REPORTS that answer questions about\n"
		"this work, and the SETTINGS that belong to it. What they open twenty times a day goes\n"
		"first; what they open once a quarter goes last or into a submenu.\n"
		"\n"
		"* AND INSIDE A SECTION THE ENTRIES ARE GROUPED UNDER HEADINGS OF THEIR OWN - a Bank and\n"
		"cash section lists \"Bank\" (payment orders, payment approvals, statements, register\n"
		"payments) and then \"Finance\" (the organisation's finances, credit). The heading is not a\n"
		"command and opens nothing: it is a frame around meaning, and it is what turns a column of\n"
		"fifteen links into three things a person can hold in their head.\n"
		"NOTE: The threshold is about seven entries. Below it a flat list reads fine; above it, an\n"
		"ungrouped column is scanned every single time, because there is nothing to remember a\n"
		"position by.\n"
		"\n"
		"THE GROUPS THEMSELVES COME IN A SETTLED ORDER, and a full section reads the same way in\n"
		"every application worth copying - laid out in COLUMNS so the whole section is one screen\n"
		"rather than a scroll:\n"
		" 1. THE DOCUMENTS OF THIS WORK, split by sub-job where there is one - bank papers in one\n"
		" group, cash-desk papers in the next.\n"
		" 2. THE CATALOGUES AND SETTINGS those documents need - currencies, banks, cash limits,\n"
		" payment purpose codes. Opened while setting up and rarely after.\n"
		" 3. SERVICE: exchanges, imports, whatever talks to the outside - loading a statement from\n"
		" the bank, sending to the client-bank. Occasional, deliberate, and never mixed in with\n"
		" the documents.\n"
		" 4. THE REPORTS OF THIS WORK - the cash book, the registers of orders, the ones that only\n"
		" make sense here.\n"
		" 5. THE STANDARD REPORTS, listed last and REPEATED IN EVERY SECTION: trial balance,\n"
		" account card, account analysis, chess sheet. They belong to the whole system rather\n"
		" than to this job, and an accountant reaches for them from wherever they happen to be\n"
		" standing - which is exactly why they are worth repeating instead of hiding in one\n"
		" place (`ledger-reports`).\n"
		"\n"
		"AND THE SECTIONS THEMSELVES ARE ORDERED BY THE WORK, not alphabetically: the flow of the\n"
		"business - buy, sell, keep stock, count the money - reads as a sequence, and a person\n"
		"learns their place by position. A starting page comes first and is not a section of work\n"
		"at all: it is where somebody lands, and it holds what they need before choosing anything.\n"
		"\n"
		"NOTE: GIVE EVERY SECTION A PICTURE. The bar is recognised by shape and colour long before the\n"
		"words are read - which is precisely why sections with no icon feel unfinished even when\n"
		"every name is right.\n"
		"\n"
		"NOTE: HOW MANY: as many as there are jobs, which is usually five to a dozen. Two sections mean\n"
		"the split says nothing; twenty mean the bar has become a menu, and a person scans it\n"
		"instead of knowing it.\n"
		"STOP: AND DO NOT READ THE BUILD ORDER OFF THE SECTION TREE. Measured in a working system:\n"
		"thirty-seven top-level sections, a hundred and eighty-one nodes altogether, four levels at\n"
		"the deepest - and the DEEPEST trees are the infrastructural ones (the standard layer, the\n"
		"shared mechanisms, personnel), while the trade cycles that were built first are three to\n"
		"five nodes and flat. Sections are a NAVIGATION artefact grown late over an object graph that\n"
		"was organised by something else. They tell you how people are meant to move around the\n"
		"system, and nothing about how it was built or what depends on what.\n"
		"\n"
		"* AND NOT EVERY BRANCH OF THE TREE IS A SECTION A PERSON SEES. A full manufacturing system\n"
		"was counted at THIRTY-SEVEN branches, and a good half of them are not jobs at all - the\n"
		"deferred-posting machinery, the shared library, administration, and nested branches inside\n"
		"the working ones. They exist to group the CONFIGURATION for whoever maintains it, and they\n"
		"are kept out of the interface. So the rule of \"five to a dozen\" is about what a person is\n"
		"SHOWN; the tree itself is routinely three times that, and the two must not be confused when\n"
		"counting.\n"
		"\n"
		"KEY: AND IT IS THE SAME OPERATION ALL THE WAY UP - grouping by MEANING, done at every scale\n"
		"of the application:\n"
		" cells that are read together become an AREA on a printed form (`form-to-areas`);\n"
		" fields that are decided together become a GROUP under a heading on a form;\n"
		" groups that belong to one aspect of a thing become a PAGE;\n"
		" pages, lists and reports that serve one job become a SECTION.\n"
		"Each level asks the identical question - what is understood as one thing here? - and the\n"
		"answer is always the reader's, never the storage's. That is why a section named after a\n"
		"metatype feels wrong for the same reason as a form page called \"other attributes\" and an\n"
		"area called \"rows 12 to 14\": all three group by where something is KEPT instead of by what\n"
		"it MEANS.\n"
		"\n"
		"NOTE: WHAT THIS NEEDS FROM A PLATFORM. Two declared things: a SECTION that owns a command\n"
		"bar, so navigation is metadata rather than a hand-built menu; and a JOURNAL - a declared\n"
		"list interleaving several kinds of document in time order, with the columns they share.\n"
		"* WITHOUT THE JOURNAL the cashier's timeline is a report or a list over a union, built for\n"
		"the purpose and maintained by hand as documents are added - so the test for creating one\n"
		"gets stricter, not looser: build it where somebody genuinely works across kinds in date\n"
		"order, never merely to gather related documents in one place.") },

	{ wxT("picking"),
	  ibMcpText("The dialogue that fills a document: what it hands back, what it must subtract, when not to ask."),
	  ibMcpText("THE SCREEN WHERE A DOCUMENT ACTUALLY GETS FILLED IN.\n"
		"\n"
		"A person spends their day in one dialogue: choose the goods, see what is left, type the\n"
		"quantity, repeat. It is the most-used surface in any trading system and the one most often\n"
		"designed last.\n"
		"\n"
		"KEY: IT HANDS BACK A STRUCTURE OF WHAT IT KNOWS, NOT A ROW. The caller reads each key as\n"
		"\"if this is present, use it\", so ABSENCE MEANS NO OPINION and the caller's own default\n"
		"stands. That one rule is what lets a single dialogue serve documents with different columns:\n"
		"it says what it found out, not what the row should be.\n"
		"* AND IT MAY ANSWER SEVERAL THINGS AT ONCE - each price under a key naming which price type\n"
		"it is, so the caller projects the one it needs. Returning \"the price\" forces the dialogue to\n"
		"know which document it serves.\n"
		"\n"
		"KEY: THE FREE BALANCE IT SHOWS MUST ADD BACK WHAT THE DOCUMENT BEING TYPED HAS ALREADY\n"
		"TAKEN. The form hands the query its own LIVE, unsaved rows - as a table typed from the\n"
		"register's own dimension types - and they are added back into what is available. Without it\n"
		"a person cannot increase their own line, because their own line has already eaten the\n"
		"stock. This is `combining`'s \"subtract yourself\" with the sign reversed, and it is the\n"
		"single most common complaint about picking screens.\n"
		"\n"
		"KEY: THE PARAMETER STRUCTURE IS THE CONTEXT AND THE SUBSCRIPTION LIST AT ONCE. The document\n"
		"hands the dialogue its context under agreed words; the opener then walks those words and, for\n"
		"every one that is also an attribute of THIS document, attaches a change handler pointing at\n"
		"one refresh routine. A header field then moves and the open dialogue replaces that key,\n"
		"re-renders its caption and refills its table - instead of showing stock for the warehouse\n"
		"that was current when it opened. Neither side names the other, and no register of dialogues\n"
		"to notify exists to go stale.\n"
		"* AND THE DIALOGUE KEEPS ONE VOCABULARY WHILE EACH DOCUMENT KEEPS ITS OWN NAMES. Where the\n"
		"same word is spelled differently per document - the warehouse, the sending warehouse, the\n"
		"group of warehouses - the translation lives in the opener alone and runs both ways: aliases\n"
		"in when subscribing, back to the single word when refreshing. What it costs: the agreement is\n"
		"by string, so a renamed attribute silently unsubscribes, and the two directions are written\n"
		"twice and must stay in step. Keep the two halves side by side so the pair is visible.\n"
		"\n"
		"KEY: ASK ONLY WHEN THERE IS A REAL QUESTION. Gather the candidates in one reading over every\n"
		"section the caller named: none - return silently, one - return it, several - open a small\n"
		"form already seeded and positioned. The same for a choice of type: read the RESTRICTION\n"
		"first, and where only one kind is admissible, do not show a menu at all.\n"
		"* A DIALOGUE THAT OPENS TO SHOW ONE OPTION TRAINS PEOPLE TO DISMISS DIALOGUES.\n"
		"\n"
		"KEY: WHEN A HEADER VALUE CHANGES, CLASSIFY THE LINES BEFORE ASKING ANYTHING. Three classes:\n"
		"empty · equal to the OLD header value · different. Empty and equal are inheritance and may\n"
		"be updated; different is somebody's intention and must not be touched. Sections with nothing\n"
		"to change are dropped BEFORE the question, so the question is only asked when it is real.\n"
		"STOP: AND THE QUESTION AND THE WRITE MUST USE THE SAME CLASSIFICATION. In the system\n"
		"examined the prompt is composed from one and the write obeys another, so in one of four\n"
		"combinations it overwrites exactly what it promised to keep. Nothing reports it.\n"
		"\n"
		"KEY: COLUMN VISIBILITY IS ASYMMETRIC. Switching a column OFF hides it AND locks it;\n"
		"switching it ON only unlocks it and leaves the showing to the person's own settings\n"
		"(`user-settings`). Hiding must be enforcement, showing must be a preference - the other way\n"
		"round gives a person a field they may edit and cannot see.\n"
		"* AND ONE ANSWER DRIVES EVERYTHING THAT DEPENDS ON IT: whether a value is given per line or\n"
		"in the header decides visibility, the lock, the mandatory marks in EVERY tabular section, the\n"
		"availability of the command that fills it, and the clearing of the header's own mark - so\n"
		"that A REQUIRED VALUE HAS EXACTLY ONE ADDRESS. Two places asking the question separately is\n"
		"how a form hides a field and then refuses to post without it (`orders`).\n"
		"* AND THE SET OF EXTRA COLUMNS IS DERIVED FROM THAT, NOT LISTED ANYWHERE. The columns behind\n"
		"an extra button are exactly those currently invisible and still adjustable - which the\n"
		"asymmetry above already decides - so no third list is written and none can drift. Their shown\n"
		"state is one boolean per document and field, restored from the person's settings and stamped\n"
		"back onto the button, so button and columns cannot disagree.\n"
		"* AND WHERE A LIST CANNOT BE AVOIDED, LIST THE EXCEPTIONS, NOT THE MEMBERS. A routine told\n"
		"which columns may NOT be hidden, setting every other column adjustable, survives a column\n"
		"being added to a document. One that enumerates the columns it governs does not: the new\n"
		"column arrives governed by nobody, and nothing reports it.\n"
		"\n"
		"KEY: A GENERATED COLUMN IS NAMED AFTER AN IDENTITY, AND ITS HUMAN NAME LIVES IN THE HEADER.\n"
		"Where columns are produced per price type, per currency, per set of books, derive the name\n"
		"from the thing's IDENTIFIER rather than from its name: renaming does not disturb the layout,\n"
		"two things called the same cannot collide, and the mapping needs no registry because it is a\n"
		"pure function. The price is that the names are unreadable, so the readable one has to be\n"
		"carried separately - in the column header.\n"
		"* AND ONE SUCH COLUMN IS USUALLY SEVERAL: a price drags its currency, its unit, its rate and\n"
		"multiplicity, and a flag saying whether it is a real price at all. Plan the group, not the\n"
		"column.\n"
		"\n"
		"KEY: THE TICKED LIST IS THE LAYOUT, AND THE GRID IS ITS PROJECTION. One routine reconciles\n"
		"the two: ticked and present - move it to its place and refresh the header; ticked and\n"
		"missing - insert; unticked - delete. Mark the generated columns as outside the person's own\n"
		"column settings, or their machinery will resurrect a column the list says is gone and the\n"
		"two authorities will fight (`user-settings`).\n"
		"\n"
		"NOTE: WHAT IS SHARED BY THE WHOLE GRID GOES IN THE HEADER; WHAT VARIES PER ROW GOES IN THE\n"
		"CELL. The unit of the balance columns is one for everybody, so it is appended to the header\n"
		"and the numbers stay bare. Prices may each be in their own currency and unit, so those are\n"
		"written into the cell text. And when the person asks to see everything in one currency, the\n"
		"currency MOVES OUT of the cells and into the header - the rule is not \"where it looks nice\"\n"
		"but \"is this the same for every row\".\n"
		"\n"
		"NOTE: THE HEAVY WORK BELONGS ON A COPY. Compute prices, discounts and totals over a detached\n"
		"copy of the lines and write the result back column by column (`promotions`): a detached\n"
		"table raises no form events, so the recalculation cannot loop, and it can be indexed and\n"
		"searched, which a document's own lines cannot.\n"
		"\n"
		"KEY: THE OWNER IS THE KEY - WHICH IS WHY THERE IS EXACTLY ONE BASKET PER DOCUMENT. Ask for\n"
		"the picking form with the calling form as BOTH its owner and its uniqueness key: pressing\n"
		"the button twice raises the window that is already open instead of making a second one, the\n"
		"basket accumulated inside survives, and anything else can find that same window later by\n"
		"asking with the same key. No registry of open dialogues is needed, and none can go stale.\n"
		"* AND FOR A PLAIN VALUE, THE OWNER IS ALSO THE ANSWER. Open the choice form with the FIELD as\n"
		"its owner and the standard mechanism assigns the chosen value straight back into that field:\n"
		"no result handler is written, the dialogue knows nothing about its caller, and the whole\n"
		"agreement is one argument. That is the cheap end of the same idea, and it is worth knowing\n"
		"where it stops - it carries ONE value, so the moment a dialogue must answer several things at\n"
		"once (the price, its currency, its unit, what is free) the structure above is what is needed\n"
		"instead.\n"
		"\n"
		"KEY: REBUILD, THEN RE-APPLY - NEVER MERGE IN PLACE. When the list behind a screen is\n"
		"refreshed, build it afresh from the database and then re-apply the person's choices to the\n"
		"new list: the ticks matched BY IDENTITY, the order replayed as a sequence of references.\n"
		"What disappeared is simply absent, what is new arrives unticked in its natural place, and\n"
		"nothing jumps. Merging into the existing list is where \"a new price type appeared and my\n"
		"columns moved\" comes from.\n"
		"\n"
		"KEY: EVERY AGGREGATE ON SCREEN SHOULD NAME THE REGISTER IT CAME FROM, AND BE A DOOR. Clicking\n"
		"\"reserved: 4\" opens the report that explains it - a report object created in code and\n"
		"configured by a structure (which register, the period, the filters, the groupings, the extra\n"
		"fields), opened already built. Not a bespoke form per number: the same mechanism as\n"
		"`report-shapes`, addressed from the grid.\n"
		"* AND THE FILTER DIFFERS BY LEVEL of the tree it was clicked in - at the top row one value\n"
		"is the item, at the child level it is the warehouse and the item has to be taken from the\n"
		"parent. Build the filter from the ROW'S PLACE, not from the column alone.\n"
		"\n"
		"NOTE: AND WHAT THE DIALOGUE SHOWS IS NOT WHAT THE DOCUMENT STORES. A picking screen may show\n"
		"stock, reservations, prices of three kinds and the last purchase - none of which becomes an\n"
		"attribute of the line unless it must be FROZEN (`showing-a-value`). Everything else is read\n"
		"again when it is next needed.") },

	{ wxT("form-layout"),
	  ibMcpText("Laying a document form out: where things go, and why that order."),
	  ibMcpText("ARRANGING A FORM SOMEBODY WORKS IN ALL DAY.\n"
		"\n"
		"A generated form puts every field in one column in declaration order. It opens, it works,\n"
		"and it is unusable for a person entering fifty documents a shift. What follows is the shape\n"
		"a working document form actually has, top to bottom.\n"
		"\n"
		"1. THE DOCUMENT'S OWN COMMANDS along the top - post, post and close, print, and whatever\n"
		" this document does that others do not (fill from another document, go to related\n"
		" records). Not scattered into the body: a person looks for them in one place.\n"
		"\n"
		"2. THE HEADER, AND IT IS COLUMNS, NOT A LIST. Number and date first, and they sit TOGETHER\n"
		" on one line - two fields a person reads as one fact. Then the attributes that identify\n"
		" the document: organisation, responsible, department down the left; the ones that qualify\n"
		" it - the month it belongs to, the kind of payment, which books it is reflected in - down\n"
		" a second column beside them. Captions on the left of their fields, fields aligned with\n"
		" each other, so the eye runs down one edge instead of hunting.\n"
		" * TWO COLUMNS BECAUSE OF WIDTH, NOT SYMMETRY: a reference field is wide and a date is\n"
		" narrow, and putting them in one column wastes half the window. Group by what is read\n"
		" together, then let the widths decide the split.\n"
		"\n"
		"3. THE TABULAR SECTION WITH ITS OWN COMMAND BAR - add, copy, edit, delete, move up and\n"
		" down, sort, and the ones that belong to THIS table: pick items, fill from a source,\n"
		" replace a mark on every selected line. They belong to the table and travel with it,\n"
		" which is exactly why they are not up with the document's commands.\n"
		"\n"
		"4. TOTALS UNDER THE COLUMNS THEY TOTAL, in the table's footer line - the same rule as on\n"
		" paper. A sum in a caption somewhere below the table is a number a person has to match\n"
		" to a column by reading.\n"
		"\n"
		"5. THE SECOND, THIRD AND FOURTH TABLES GO ON PAGES. A payment document carries payment\n"
		" parameters, contributions, payroll-fund contributions and income tax; stacked they would\n"
		" make a form nobody can see the bottom of. As tabs they are one click apart and the main\n"
		" table keeps its height. The FIRST table stays out in the open - it is what the document\n"
		" is about; the rest are what it entails.\n"
		"\n"
		"6. THE COMMENT LAST, one line across the bottom. Every document has one and nobody looks\n"
		" for it first.\n"
		"\n"
		"THREE THINGS A BUSY FORM DOES THAT A PLAIN ONE DOES NOT.\n"
		" A PAGE TAB SAYS HOW MUCH IS BEHIND IT - \"Products (0 items)\", \"Customer materials\n"
		" (3 items)\". Without it a person opens every tab to find out whether it is empty, which\n"
		" is the cost the tabs were meant to save.\n"
		" THE FORM EXPLAINS ITS OWN STATE IN WORDS, at the foot and beside the totals: \"price\n"
		" type is not set - VAT will be computed automatically\", \"not enough information to\n"
		" calculate the debt\". These are not errors and not a dialog - they are the document\n"
		" telling a person why a figure looks the way it does, in the place where they are\n"
		" looking at it.\n"
		" THE DOCUMENT'S TOTALS SIT UNDER THE TABLE ON THE RIGHT - total, VAT included - because\n"
		" they are facts about the DOCUMENT rather than about the table's columns. The column\n"
		" totals stay in the table's own footer; these two are what somebody reads out loud on\n"
		" the phone.\n"
		"\n"
		"KEY: A LIVE FIGURE ON A FORM IS PAID FOR AT EVERY OPEN, SO PAYING FOR IT IS A RIGHT. A caption\n"
		"saying what this customer owes costs a query each time the form opens, and that is what\n"
		"three-seconds-to-open is made of. Make computing it a permission - and then say something in\n"
		"all four cases: not enough entered to compute it, not computed because it is switched off,\n"
		"nothing owed, and who owes how much. An absent number is STATED, never left blank, or the\n"
		"blank is read as nought. A failure to read gets its own wording rather than an empty label.\n"
		"* AND THE WORD IN THE CAPTION IS DERIVED, NOT CONFIGURED - by contract, by order or by invoice,\n"
		"according to how settlement is kept under that agreement (`settlements`) - and the colour\n"
		"follows which side owes. One less setting, and it cannot disagree with the figure beside it.\n"
		"\n"
		"* AND A COMMAND THAT CHANGES HOW THE WHOLE DOCUMENT IS PRICED GETS ITS OWN BUTTON, not a\n"
		"line in a menu: \"Prices and currency...\" opens the decision that every line's price came\n"
		"from. A person changes it once per document and needs it visible; the rest can live under\n"
		"Actions.\n"
		"\n"
		"A CATALOGUE ITEM IS LAID OUT THE OTHER WAY ROUND, and mixing the two is the usual mistake.\n"
		"A document is an EVENT - a header and the lines it consists of. An item is a THING that\n"
		"many subsystems each know something about, so:\n"
		" WHAT MAKES IT THIS THING STAYS ABOVE THE PAGES, always visible: the folder it is in,\n"
		" the name, the code, the article number, its kind, its units, and the switches that\n"
		" change what it IS - kept by characteristics, kept by batches, a form of strict\n"
		" accountability. A person scrolling the tabs must never lose sight of which item they\n"
		" are editing. A picture, when the thing has one, sits beside that block.\n"
		" THE PAGES ARE SUBJECTS, NOT TABLES: defaults, units, properties, categories,\n"
		" components, barcodes, accounts, specifications, storage places, prices. Each is one\n"
		" department's view of the same item, and each is empty for most items - which is exactly\n"
		" why they are pages and not sections of one long form.\n"
		" INSIDE A PAGE, FIELDS ARE GROUPED UNDER A HEADING that names the group in the words of\n"
		" whoever needs it - \"VAT accounting, details for the tax invoice\", \"cost analytics\".\n"
		" Three or four fields under a title read as one decision; the same fields in a flat\n"
		" column read as a questionnaire.\n"
		" A FIELD THAT DEPENDS ON A SWITCH IS GREYED, NOT HIDDEN. The excise article stays\n"
		" visible and disabled until the item is marked excisable. Hiding it makes the form\n"
		" jump and leaves a person wondering where the field went; greying says \"this exists\n"
		" and here is what turns it on\".\n"
		"\n"
		"NOTE: WHAT DECIDES A COLUMN'S PLACE IN A TABLE: what a person reads to know WHICH LINE this is\n"
		" goes left - number, code, the item itself. What they came to type goes next. What is\n"
		" computed or rarely looked at goes right, and can be narrow. A column nobody has ever\n"
		" filled in is a column to take off the form, not to shrink.\n"
		"\n"
		"* AND THE SMALL CASE STAYS SMALL. A catalogue of employees is a list of two columns - name\n"
		"and code - and an item form of two fields plus, where there is one, a tabular section\n"
		"underneath with its own little bar. Nothing above is a requirement: pages, groups and\n"
		"navigation links earn their place when there is something to put in them, and a form that\n"
		"has four fields and four tabs is worse than the generated one it replaced. Build the plain\n"
		"version, then split what actually grew.\n"
		"\n"
		"THREE HABITS THAT APPLY TO EVERY FORM, LARGE OR SMALL:\n"
		" SEARCH IS A PERMANENT PART OF THE BAR, not a command in a menu - a box with a clear\n"
		" button, over the list and over any tabular section long enough to scroll. Finding a\n"
		" line is the most frequent thing anybody does with a table.\n"
		" THE TITLE NAMES THE SUBJECT, not the form: \"Ivanov (Employee)\", \"Invoice 12 of 3\n"
		" March\". A window called \"item form\" tells a person nothing when four of them are open.\n"
		" THE READER SORTS, by clicking the column heading, and the arrow stays there so they can\n"
		" see what they are looking at. An order fixed by the developer is right for one\n"
		" question and wrong for the next.\n"
		"\n"
		"A LIST IS THE THIRD KIND OF FORM, and it is the one people actually live in - a document\n"
		"form is opened to change one thing, a list is open all day.\n"
		" THE FIRST COLUMN IS WHAT PEOPLE SEARCH BY, which is the name and almost never the code.\n"
		" The code, the article number and the unit follow it; anything computed goes right.\n"
		" A HIERARCHY IS SHOWN THREE WAYS AND THE PERSON CHOOSES: folders-with-contents, a flat\n"
		" list ignoring the hierarchy, or a tree. The same data, three readings - somebody\n"
		" hunting for one item wants the flat list, somebody tidying wants the tree, and neither\n"
		" should have to ask for a different form.\n"
		" FOLDERS AND ITEMS ARE CREATED BY DIFFERENT COMMANDS. \"New\" and \"New folder\" are two\n"
		" buttons because they make two different things, and a person who wanted one and got the\n"
		" other has to delete it.\n"
		" DELETION IS TWO STEPS: mark for deletion, and delete what is marked, later, when\n"
		" nothing refers to it any more. The mark is reversible and visible in the list; that is\n"
		" the whole point, because a reference that vanishes takes documents with it.\n"
		" MOVING AROUND THE HIERARCHY IS ITS OWN SET OF COMMANDS - move to folder, go into the\n"
		" folder, go up a level. Dragging works and is not enough on its own: a thousand-item\n"
		" catalogue is reorganised by picking a target, not by scrolling with the mouse held\n"
		" down.\n"
		" AND \"I WANT THESE IN MY ORDER, NOT ALPHABETICALLY\" IS AN INTEGER ATTRIBUTE WHOSE SCOPE\n"
		" IS THE SIBLING SET. A new row takes the highest value among its siblings plus one - the\n"
		" siblings being those with the same parent, the same owner, or both, whichever the object\n"
		" actually has. Moving up or down finds the nearest neighbour in that direction and SWAPS\n"
		" the two values, so one keystroke is two writes and never a renumbering pass; and the\n"
		" number is recomputed when the parent or the owner changes, because the object has moved\n"
		" into a different scope. The cost, worth saying out loud: the values drift apart as rows\n"
		" are deleted and nothing ever tidies them. That is fine - they are an order, not a\n"
		" position - but any code that reads them as \"the third one\" is wrong from the first\n"
		" deletion.\n"
		"\n"
		"KEY: A FILTER SET BY WHOEVER OPENED THE LIST IS SHOWN AND LOCKED, UNLESS THE CALLER SAYS IT\n"
		"MAY BE RELAXED. Opening a list already narrowed is right; leaving the narrowing editable\n"
		"makes it a suggestion, and hiding it altogether makes the list look simply wrong. So set the\n"
		"value, mark it in use, and disable the setting - then let the caller pass the names of the\n"
		"fields that ARE relaxable, so each one is a hard context or a hint by the caller's decision\n"
		"rather than by the list's.\n"
		"* AND A FILTER WHOSE VALUE CAN NEVER VARY TAKES ITS COLUMN WITH IT. Where the base keeps one\n"
		"company, impose that filter, disable it and REMOVE the column: a column with one value\n"
		"carries no information and costs width on every row.\n"
		"* AND A FILTER ALREADY IMPOSED BY THE ROUTE IN WINS OVER ONE IMPOSED BY POLICY. A list reached\n"
		"from a navigation that has narrowed it must not be narrowed again, or the two rules meet and\n"
		"the person is shown nothing at all, with no way to tell which of them did it.\n"
		"\n"
		"KEY: AND A FORM HAS DATA OF ITS OWN, which is the part most often missed. The object being\n"
		"edited is ONE of the form's attributes, not the form itself: beside it live the things the\n"
		"screen needs and the object does not - a flag saying whether something is already sent, a\n"
		"caption assembled for display, the documents this one was created from, whether the current\n"
		"person may edit at all. Controls bind to PATHS through that data, so adding a screen-only\n"
		"value is adding an attribute to the form rather than a field to the object. The test: would\n"
		"this still mean anything with the form closed? If not, it belongs to the form.\n"
		"\n"
		"HOW A COMMAND BAR IS ORDERED, once there are more than four commands:\n"
		" ONE PRIMARY COMMAND, said in words and visually louder than the rest - the thing a\n"
		" person came to do, usually \"post and close\". Everything else can be an icon.\n"
		" THE COMMON FEW AS ICONS beside it - save, print, the two or three used every day.\n"
		" THE REST IN SUBMENUS GROUPED BY PURPOSE: create-from-this, fill-from, print, exchange.\n"
		" A menu named after what its items DO stays right as items are added; a menu named\n"
		" \"other\" is where commands go to be lost.\n"
		" AND A LAST OVERFLOW for the rare ones. A person who cannot find a command looks in one\n"
		" place before asking.\n"
		"\n"
		"NAVIGATION IS NOT THE SAME AS PAGES, and a form usually needs both. Along the top sit LINKS\n"
		"TO RELATED DATA - the files attached to this item, its prices, its history - each opening a\n"
		"list of its own that belongs to this object but is not part of it. Pages inside the form\n"
		"hold what the object ITSELF carries. Putting attached files on a page loads them with the\n"
		"form; putting the units of measure behind a link hides part of the thing being edited.\n"
		"\n"
		"FOUR SMALL CHOICES THAT DECIDE HOW A FORM FEELS TO TYPE IN.\n"
		" A REQUIRED FIELD IS MARKED BEFORE IT IS SAVED - the empty one carries a border of its\n"
		" own from the moment the form opens, so a person fills it on the way in rather than\n"
		" being sent back to it.\n"
		" TWO OR THREE EXCLUSIVE CHOICES ARE RADIO BUTTONS, not a dropdown: \"goods / service\"\n"
		" shown open costs one click and no memory. A list earns its place from about five.\n"
		" AN EMPTY AREA SAYS WHAT GOES IN IT - \"drop a picture here (5 MB maximum)\" - and says\n"
		" the LIMIT before the attempt rather than after it. An empty rectangle is a question a\n"
		" person answers by trying.\n"
		" A FIELD WITH A NATURAL WAY TO ENTER IT GETS THAT WAY ATTACHED: a calendar on a date, a\n"
		" calculator on a weight, a picker on a reference, and a clear button on anything\n"
		" optional. Typing is the fallback, not the only road.\n"
		"\n"
		"THE FORM SAYS WHAT IS WRONG WHERE IT IS WRONG. A required field left empty is marked in the\n"
		"field itself, not announced when the document is saved. And a problem that has a FIX carries\n"
		"the fix beside it: \"no parent company chosen for this counterparty - choose one\", with the\n"
		"words that do it being a link. A message that only describes leaves the person to find the\n"
		"field; a message that acts is the difference between a warning and a dead end.\n"
		"STOP: THE BUTTON DOES NOTHING IS TWO DIFFERENT DEFECTS, AND BOTH ARE AVOIDABLE. A gate and a\n"
		"lookup must not share a return value. A helper that answers with nothing for\n"
		"you-may-not-see-this, for no-such-form and for it-failed-to-open leaves the caller no\n"
		"response but silence - and the refusal, which the person is entitled to hear, is\n"
		"indistinguishable from an absence. Hand back the kind of answer, not one empty value for\n"
		"three of them (`shapes`).\n"
		"* AND WHERE A COMMAND CAN NEVER WORK WITHIN THIS FORM'S LIFETIME, REMOVE IT RATHER THAN\n"
		"DISABLE IT - no card terminal is connected, record-level restrictions are switched off, this\n"
		"person may not administer users - and take its separator with it. Disabling is for what may\n"
		"become available while the person is looking. It is the greying rule seen from the other\n"
		"side: a control they can wait for is greyed, a control that will never light up is a question\n"
		"they will ask somebody about.\n"
		"\n"
		"NOTE: AND THE FORM IS NOT WHERE BEHAVIOUR LIVES. Filling a line, checking a balance, refusing a\n"
		"posting - those belong to the object and its module, and a form that carries them works\n"
		"only while it is open. See `printing` for the same argument about print commands.\n"
		"\n"
		"KEY: THE STATE AN ACTION NEEDS IS NEGOTIATED BEFORE THE ACTION STARTS, IN ONE PLACE. Filling\n"
		"from a list needs the document written; refilling an offset needs it unposted\n"
		"(`settlements`); replacing the lines needs them empty. Put those in front as GATES that ask\n"
		"the person, perform the write or the unposting themselves, and return a yes-or-no the caller\n"
		"must obey - each with a question the caller may supply and a generated fallback when it does\n"
		"not.\n"
		"* WHAT THE OTHER ORDER COSTS: an action that starts and then discovers the state is wrong has\n"
		"already cleared the lines or written half of them, and the person's answer arrives too late\n"
		"to matter. That is the whole of it heard from outside as: I clicked fill and lost my lines.\n"
		"* AND THE WRITE ITSELF IS A PARAMETER where the action continues inside somebody else's\n"
		"choice handler - the document must not be written until the person has failed to cancel. A\n"
		"failed write returns false rather than raising, because the caller still has to decide what\n"
		"to abandon.\n"
		"\n"
		"STOP: WHATEVER IS HIDDEN MUST ALSO BE CLEARED - OTHERWISE IT IS STILL POSTED. Hiding a field\n"
		"changes what a person can see, and nothing else: the posting code reads the ATTRIBUTE, not\n"
		"the form. So every place that hides on a condition must blank on the same condition - the\n"
		"slots past the active count, the currency of an invisible amount, the indicator of a kind\n"
		"that no longer applies. INVISIBILITY IS NOT A STATE A VALUE MAY HIDE IN, and \"I switched the\n"
		"kind and it still charged the old amount\" is what it looks like from outside.\n"
		"STOP: AND WRITING A VALUE EQUAL TO THE ONE ALREADY THERE IS NOT FREE. Something is watching\n"
		"the write - the form's modification flag, which decides whether a person is asked to save on\n"
		"closing. A form that casts, defaults or propagates values while it is merely opening will ask\n"
		"to save a document nobody touched, and a person asked that twice a day answers it without\n"
		"reading.\n"
		"* SO GUARD THE ASSIGNMENT WITH A COMPARISON wherever a routine may be writing what is already\n"
		"in place: opening, coercing a value to its slot's type, inheriting a header value into the\n"
		"lines, setting a mark. The rule is wider than forms and worth stating that way - an\n"
		"idempotent write costs nothing only where nothing observes writes.\n"
		"\n"
		"KEY: A PAGE IS THE UNIT OF THE RIGHTS DECISION, AND IT APPEARS ONLY IF EVERYTHING BEHIND IT\n"
		"IS VISIBLE. Give the form a map from page to the objects edited on it, fold the view right\n"
		"across the whole array with AND, and the same for the edit right. A tab that would otherwise\n"
		"show half its content is not shown at all - the strict reading is the right one here.\n"
		"* AND \"VIEWABLE BUT NOT EDITABLE\" IS APPLIED PER KIND OF CONTROL, because one intent has\n"
		"different property names on different classes: fields and tables become read-only,\n"
		"checkboxes and switches become disabled. One walk, a branch per kind, and nothing is left\n"
		"editable because its class was forgotten.\n"
		"\n"
		"KEY: REQUIRED-NESS CAN BE A RIGHT RATHER THAN A PROPERTY. The set of mandatory fields is\n"
		"built and then EDITED before use: where this person may sell at zero price, the money fields\n"
		"are removed from the set. Everything downstream iterates the set it was given and knows\n"
		"nothing about permissions - which is what keeps the two mechanisms from growing into each\n"
		"other (`roles`: a permission is asked inside the check it switches off).\n"
		"STOP: BUT IF THAT SAME SET ALSO DRIVES A ROUTINE THAT DELETES FAILING ROWS, SAY WHICH IS\n"
		"WHICH. Silently dropping incomplete rows is right for a machine-generated table - a fill\n"
		"from a list, where an incomplete row is noise - and wrong for one a person typed. In the\n"
		"system examined both live behind one signature that does not say which, one call apart.\n"
		"\n"
		"KEY: A FAMILY OF SLOTS TAKES ITS COUNT, ITS TYPES AND ITS LABELS FROM THE CHOSEN VALUE.\n"
		"Where an account, a kind or a scheme declares its own analytics, the form holds a fixed few\n"
		"slots and the choice decides how many are active, what each is called, and what each may\n"
		"hold. Three rules worth taking whole: the NUMBER of visible fields is a property of the\n"
		"selected value; whether a slot needs a type-choice step is COMPUTED from how many types it\n"
		"admits, never configured; and a value that survives into a slot of another type is CONVERTED\n"
		"rather than discarded or left to fail later. Slots past the active count are cleared, not\n"
		"merely hidden - see the rule above.\n"
		"\n"
		"KEY: A LINE OF A DOCUMENT IS AN EQUATION, AND SOMETHING HAS TO GIVE. Quantity, price,\n"
		"discount and amount cannot all be independent: edit the amount, and either the price moves\n"
		"or the discount does. WHICH ONE YIELDS IS A SETTING - and in a working system it is a\n"
		"setting OF THE PERSON, not of the document: a wholesaler holds the price and moves the\n"
		"discount, a shop does the reverse. Deciding it silently, or differently in different\n"
		"documents, is the commonest cause of \"it changed my price\".\n"
		"* AND THE RECALCULATION MUST BE REACHABLE FROM CODE, NOT ONLY FROM TYPING. Where the chain\n"
		"hangs on the form's own \"the user edited this field\" event, every routine that fills lines\n"
		"programmatically has to imitate a keystroke to make the totals right - and one that forgets\n"
		"leaves a document whose lines do not add up. Attach the chain to the VALUE CHANGING, and let\n"
		"the form be one caller among several. This is the interface-shaped defect that presents as\n"
		"\"works when I type it, wrong when it fills itself\".\n"
		"KEY: THE SERVER ANSWERS WITH VALUES; THE CALLER APPLIES THEM. Give every this-field-changed\n"
		"handler one shape - it takes a structure of what is known and returns a structure of what to\n"
		"fill - and let the caller write the returned values onto the row or the document in one step.\n"
		"The handler touches no object, so the same one serves a row, a whole document, a test and\n"
		"another handler: counterparty-changed is literally find the contract, then behave as if the\n"
		"contract had changed, merging what comes back. Handlers compose instead of being copied.\n"
		"* AND THE INCOMING BAG IS ALSO AN OUT CHANNEL where the caller will shortly need working data\n"
		"- the chosen unit's coefficients, the rate and its multiplicity - which spares a second round\n"
		"trip for a value already in hand. What it costs: one call is one round trip, and the contract\n"
		"is untyped, so write the keys each handler reads and returns down beside it. Nothing else\n"
		"declares them.\n"
		"KEY: A DIALOGUE THAT RESTATES A WHOLE DOCUMENT RETURNS A DIFFERENCE, NOT A RESULT. \"Prices\n"
		"and currency\" changes four independent axes - currency, rate, tax mode, price type - and\n"
		"each drives its own recalculation. Hand back BOTH values per axis, current and new: only\n"
		"then can an idle OK be told from a real change, and only then is a conversion possible at\n"
		"all (it needs both rates). Deciding from \"OK was pressed\" recalculates everything every time.\n"
		"\n"
		"* AND FILLING A FIELD MAY OVERWRITE WHAT A PERSON JUST TYPED. Refilling prices that also\n"
		"resets quantity is not a service; whatever a routine touches beyond its own subject has to\n"
		"be deliberate and stated.") },

	{ wxT("ledger-reports"),
	  ibMcpText("What an accountant expects over a ledger, and why it is one family and not ten reports."),
	  ibMcpText("THE STANDARD REPORTS OVER AN ACCOUNTING REGISTER.\n"
		"\n"
		"An accountant does not ask for \"a report\". They ask for one of a dozen shapes they have\n"
		"used for thirty years, by name, and they expect all of them to exist. The list is short and\n"
		"worth knowing before designing anything:\n"
		" TRIAL BALANCE - every account, with opening balance, turnover and closing balance.\n"
		" The one that is opened first, every morning.\n"
		" TRIAL BALANCE FOR ONE ACCOUNT - the same, broken down by that account's analytics.\n"
		" ACCOUNT TURNOVER, ACCOUNT ANALYSIS, ACCOUNT CARD - the movements of one account: as\n"
		" totals per period, as correspondence with other accounts, and as the list of entries\n"
		" themselves with a running balance.\n"
		" ANALYTICS ANALYSIS, ANALYTICS CARD, TURNOVER BETWEEN ANALYTICS - the same three\n"
		" questions asked of a dimension instead of an account.\n"
		" CHESS SHEET - every account against every account, one cell per correspondence.\n"
		" GENERAL LEDGER, ENTRY REPORT, SUMMARY ENTRIES - the statutory readings of the same\n"
		" data.\n"
		"\n"
		"KEY: THE COLUMNS ARE THE SHAPE, and they are the same everywhere: three PAIRS - opening\n"
		"balance, period turnover, closing balance - each split into debit and credit, under a\n"
		"spanning heading. Six columns, three headings, and an accountant reads them without looking\n"
		"at the titles. Getting this layout right matters more than any amount of styling.\n"
		"\n"
		"THE ROWS ARE THE CHART OF ACCOUNTS, folded: 13 with 131, 132, 133 under it, each level\n"
		"totalling its children. Below the account come its ANALYTICS, level by level, and which\n"
		"ones are shown is the reader's choice rather than the author's.\n"
		"\n"
		"KEY: AND THE THING THAT MAKES THE FAMILY A FAMILY: A CELL LEADS TO ANOTHER REPORT. Standing\n"
		"on the turnover of account 20, a person asks for the trial balance of 20, its card, its\n"
		"analysis, its turnover by month or by day - and lands there with the account, the period\n"
		"and the analytics ALREADY SET. The drill-down is not a detail window: it is the next report\n"
		"of the same family, opened with the context carried over. Design them together or the\n"
		"chain breaks at the first hop.\n"
		"\n"
		"* TWO INDEPENDENT AXES, AND THE ANALYSIS REPORT IS WHERE THAT SHOWS. \"Account analysis\"\n"
		"groups by the account AND by the accounts it corresponded with - two grouping settings side\n"
		"by side, each with its own list of levels, because the question is \"where did this money\n"
		"come from and go to\". A single ladder cannot express it: the correspondent account is not\n"
		"a level under the account, it is the other end of the same entry.\n"
		"\n"
		"AND THE SECOND AXIS CAN BE PUT ACROSS instead of down: the turnover report shows the\n"
		"correspondent accounts AS COLUMNS - opening balance, debit turnover, then a column per\n"
		"account it corresponded with, then credit turnover and the closing balance. That is a cross\n"
		"table (`form-to-areas`, `report-shapes`) with the ledger's own vocabulary, and the columns\n"
		"fold like the rows do, because there can be dozens of them.\n"
		"\n"
		"THREE MORE CONTROLS THAT ARE PARTICULAR TO THIS FAMILY:\n"
		" WHICH FIGURES, SEPARATELY FOR DEBIT AND CREDIT - opening balance, closing balance,\n"
		" turnover, each with its own pair of tick boxes. Six switches, not three: an accountant\n"
		" chasing one side of an account does not want the other.\n"
		" PERIODICITY OF THE TURNOVER - by month, by day, for the period as a whole. It adds a\n"
		" TIME LEVEL to the rows, which is why it is a setting and not a second report.\n"
		" AND THE CHART BUTTON beside the settings: the same composition drawn instead of\n"
		" tabulated. Free once the figures are grouped, and it is what gets shown to a director.\n"
		"\n"
		"NOTE: AND THE ROWS ARE NOT ALL GROUPINGS. Inside each level sit three FIXED rows - opening\n"
		"balance, turnover, closing balance - which are not values of any field: they are the\n"
		"skeleton of accounting, printed for every account whether there is data or not. A report\n"
		"built purely out of groupings cannot produce them, and their absence is the first thing an\n"
		"accountant notices.\n"
		"\n"
		"WHAT THE READER IS GIVEN CONTROL OF, on a panel beside the result rather than in a dialog:\n"
		" WHICH FIGURES - accounting data, tax data, the difference between them, the currency\n"
		" amount - as tick boxes, because they are columns switched on and off.\n"
		" WHICH GROUPINGS - by sub-account, by which analytics, in what order.\n"
		" EXPANDED BALANCE, per account: whether debit and credit are shown separately rather\n"
		" than netted. This is an accounting question with no analogue elsewhere, and leaving it\n"
		" out makes the report wrong for exactly the accounts that need it.\n"
		" SELECTION - the ordinary filter, last.\n"
		"\n"
		"NOTE: AND A NEGATIVE FIGURE IN RED IS NOT DECORATION. On a balance report it means the account\n"
		"is standing the wrong way round, which is a fact somebody has to act on - the report's job\n"
		"is to make it impossible to miss.\n"
		"\n"
		"KEY: THE FIGURES THE FAMILY CAN SHOW ARE ONE STRUCTURE, AND EACH ONE CARRIES TWO SEPARATE\n"
		"FLAGS: IS IT AVAILABLE, AND IS IT SWITCHED ON. Accounting amounts, tax amounts, the\n"
		"difference between them, the currency amount, the quantity, the expanded balance - six\n"
		"entries of the same shape. \"Available\" is a property of THIS DATA (a quantity column means\n"
		"nothing on an account that keeps no quantity), \"switched on\" is the reader's choice.\n"
		"Collapsing the two into one flag produces either columns that cannot be turned on or columns\n"
		"of zeroes.\n"
		"* AND THE SET TRAVELS INTO THE REPORT A CELL DRILLS INTO, adjusted on the way: a quantity is\n"
		"carried only if the target account keeps one, and clicking the DIFFERENCE turns on both\n"
		"sides that make it. The receiving report opens showing the same thing the reader was looking\n"
		"at, which is the whole point of the family.") },

	{ wxT("report-shapes"),
	  ibMcpText("The four shapes a report takes on screen, and what each one is made of."),
	  ibMcpText("WHAT A REPORT LOOKS LIKE WHEN IT IS RUN.\n"
		"\n"
		"Four shapes cover nearly everything anybody asks for, and they are not four mechanisms -\n"
		"they are the same composition with different levels declared.\n"
		"\n"
		"1. A LIST WITH TOTALS. One grouping, the figures beside it, a total at the foot. \"Sales by\n"
		" customer.\" The plain case, and often the right one.\n"
		"\n"
		"2. A LADDER OF GROUPINGS - the workhorse. Department, then counterparty, then the document,\n"
		" then the goods on it, each level indented under the one above and each carrying its own\n"
		" totals across every column. A person opens the level they are asking about and leaves\n"
		" the rest folded, so the same report answers \"how did the department do\" and \"which line\n"
		" of which delivery note\" without being two reports.\n"
		" * A LEVEL MAY CARRY DETAILS OF ITS OWN: the document level shows its number and date in\n"
		" columns of their own, beside the money. Those are FIELDS OF THAT LEVEL, not resources -\n"
		" they are not summed, they identify the row. Mixing the two produces a report that adds\n"
		" up document numbers.\n"
		"\n"
		"3. A CROSS TABLE - a grouping put ACROSS the columns instead of down: years or months or\n"
		" warehouses along the top, the ladder down the side, one resource in the cells and a\n"
		" total column at the right end. Asked for in the words \"by month\", \"per warehouse\",\n"
		" \"compared with last year\". See `form-to-areas` for the same shape when it is printed\n"
		" onto a fixed blank instead.\n"
		"\n"
		"4. A DETAIL LISTING - no grouping at all, one line per record, used for checking rather\n"
		" than for reading: which orders mention this article, which lines carry this comment.\n"
		" Its whole design is the SELECTION, not the structure.\n"
		"\n"
		"5. A STATUTORY RETURN, and it is not built the way the four above are - it is FILLED IN. A\n"
		" balance sheet or a profit-and-loss return is a blank fixed by law: the rows are given,\n"
		" in a given order, each with the LINE CODE the law refers to it by (010, 015, 035...), and\n"
		" two columns - this period and the previous one. Nothing about its shape is a design\n"
		" decision, and a composer is the wrong tool for it because there is nothing to group.\n"
		" What it needs instead:\n"
		" A RULE PER CELL saying where its figure comes from - a turnover, a balance, a sum of\n"
		" accounts - so \"Fill\" computes the whole sheet from the books.\n"
		" CELLS A PERSON MAY OVERWRITE, and those edits SURVIVE the next \"Fill\": an accountant\n"
		" corrects what the automatic rule cannot know, and losing that on a refill is the\n"
		" defect people remember. Computed cells and hand-entered ones are visibly different -\n"
		" colour is the usual way.\n"
		" DRILL-DOWN FROM A CELL to what made it. A number on a statutory form that cannot be\n"
		" explained is a number nobody will sign.\n"
		" ARITHMETIC BETWEEN ROWS, stated once: line 035 is 010 less 015 and 020, and the sheet\n"
		" checks itself. The control sum in the header is the same idea for the whole return.\n"
		" AND THE FORM'S OWN IDENTITY AS TEXT - the appendix number, the regulation and the\n"
		" classifier codes of the organisation - exactly as on any official blank\n"
		" (`form-to-areas`).\n"
		" KEY: AND HERE IS HOW IT IS ACTUALLY ASSEMBLED, because the shape hides the mechanism: the\n"
		" blank is a TEMPLATE, and the form carries a SPREADSHEET FIELD that shows it. The\n"
		" spreadsheet document is not only a thing that gets printed - put on a form it is an\n"
		" editable control, so the return a person sees IS the template, opened into the field.\n"
		" Filling it is then not drawing anything: the cells are NAMED, and the code walks the\n"
		" names it knows and puts values into them. The accountant's corrections come back out of\n"
		" the same named cells, which is what makes hand edits survivable, and a cell can carry a\n"
		" detail value pointing at what produced it - that is the drill-down. Build the blank\n"
		" once, name what is fillable, and the whole return is a loop over names.\n"
		"\n"
		" Four more habits, all of them from the blank rather than from the accounting:\n"
		" A CELL MARKED \"x\" IS FORBIDDEN, not empty. The form says this intersection has no\n"
		" meaning - a permanent difference on a row that cannot have one - and the mark is part\n"
		" of the layout. Filling it, even with a zero, is an error on the return.\n"
		" LINE CODES ARE HIERARCHICAL: 01, then 01.1, 01.2, 01.3 \"of which\". The parts have to\n"
		" add up to their parent, and that arithmetic is as much part of the form as the\n"
		" column totals.\n"
		" THE HEADING SPANS: one title over two columns (\"tax differences\" over \"permanent\" and\n"
		" \"temporary\"), numbered 1...7 underneath. The same nesting as a vertical area on a\n"
		" printed blank, and for the same reason.\n"
		" UNIT AND PRECISION ARE PARAMETERS OF THE WHOLE SHEET - in currency units or thousands,\n"
		" to so many decimals - and so is the choice of HOW it is filled: from the books, or\n"
		" from figures a person typed. Both belong on the form's bar, above the blank, because\n"
		" they change every number on it at once.\n"
		"\n"
		"WHAT THE FORM AROUND IT NEEDS, and it is the same for the first four:\n"
		" ONE LOUD COMMAND - \"Generate\" - because until it is pressed the page is empty and\n"
		" nothing else on the screen matters.\n"
		" THE VARIANT PICKER BESIDE IT, by name: this is where the several views of one report\n"
		" become visible to the person, and the reason a variant must be named (`report-variants`).\n"
		" SETTINGS one click away, not on the page: period, selection, which levels to show. The\n"
		" two or three parameters people change EVERY time - a period, a department - are worth\n"
		" lifting out onto the form itself; the rest belong behind the button.\n"
		"\n"
		"KEY: AND A REPORT CAN HAVE A FORM OF ITS OWN, WITH ATTRIBUTES ON IT - which is a different\n"
		"mechanism from a variant, and the two are easy to confuse:\n"
		" A VARIANT is a named SHAPE - which groupings, which resources, which selection - and it\n"
		" is picked by name from a list. Several answers, one query.\n"
		" A FORM ATTRIBUTE is a VALUE the person types or picks before generating: the period,\n"
		" the warehouse, the organisation, a threshold. It is bound to a query parameter, and\n"
		" there is only one of it.\n"
		"The test: does the person CHOOSE A VIEW, or ENTER A VALUE? Views are variants; values are\n"
		"attributes on the form.\n"
		"\n"
		"* WHAT THE OWN FORM BUYS beyond the two or three fields: defaults that are computed (this\n"
		"month, my department), fields that depend on each other (choose a warehouse, and the\n"
		"storage places narrow), a validation before anything is generated, and commands of the\n"
		"report's own - print this in the customer's layout, send it, save the selection as a\n"
		"variant. A generated form gives none of that and is exactly right until one of them is\n"
		"asked for.\n"
		"NOTE: And keep the WORK out of the form (`form-layout`): the form collects values and asks the\n"
		"report to run. A form that computes the figures itself cannot be run by a scheduled job,\n"
		"which is how monthly reports actually get delivered.\n"
		" AND A FILTER BOX OVER THE RESULT for the detail listing, because that shape exists to\n"
		" be searched.\n"
		"\n"
		"NOTE: THE QUESTION THAT PICKS THE SHAPE: what does the person want to compare? Nothing - a\n"
		"list. Parts against a whole - a ladder. One dimension against another - a cross table.\n"
		"Nothing at all, they want to FIND something - a detail listing with a filter.\n"
		"\n"
		"KEY: DRILLING INTO A CELL - THE CONTEXT IS WRITTEN ONCE, NOT PER CELL. The obvious design\n"
		"gives every cell a copy of everything needed to reopen it - period, company, register,\n"
		"filters - and a large sheet then carries the same context ten thousand times. Instead the\n"
		"report writes the SHARED part once, into the sheet itself, and each cell carries only what\n"
		"is peculiar to it - its own coordinates in the groupings. At the click they are stitched\n"
		"together.\n"
		"* AND THE REPORT'S OWN FILTER GOES INTO THE SHARED PART TOO. What was drilled into must open\n"
		"under the same restriction the figure was computed under, or the second report shows more\n"
		"than the first and the two disagree.\n"
		"* WHAT HAPPENS ON THE CLICK DEPENDS ON THE ROLE OF THE FIELD, not on what it looks like: on\n"
		"a FIGURE, open the next report; on an ANALYTIC VALUE, open that object. Same gesture, two\n"
		"meanings, and the reader expects both without being told.\n"
		"* AND THE OPENED REPORT IS AN UNNAMED, THROWAWAY VIEW - never the named variant the person\n"
		"came from. Drilling must not silently rewrite the settings they will use tomorrow.\n"
		"\n"
		"KEY: A CELL CARRIES A LIST OF ROUTES, NOT ONE DESTINATION. \"Where can I go from this figure\"\n"
		"usually has several answers - the card of the account, the turnovers by day, the analysis by\n"
		"counterparty - so the cell holds descriptors, each with a human name and the settings the\n"
		"target should open with. One route: go. Several: offer the menu in those human words. That\n"
		"is what makes the family navigable rather than a set of reports that happen to exist.\n"
		"* AND EVERY REPORT IN THE FAMILY MUST BE ABLE TO ACCEPT SOMEBODY ELSE'S SETTINGS through one\n"
		"entry point. The route names its target as a STRING, which nothing checks - so the entry\n"
		"point is the contract, and it has to be the same shape in all of them.\n"
		"\n"
		"STOP: AND CARRYING THE ANALYTICS ACROSS IS A TRANSLATION BETWEEN SLOTS, NOT A COPY. In the\n"
		"source they are numbered by their position IN THE REPORT; in the target, by their position\n"
		"ON THE ACCOUNT. The same analytic sits in slot two here and slot one there, so the value has\n"
		"to be re-addressed by WHAT IT IS, not by where it stood - plus a side suffix where debit and\n"
		"credit have separate slots. Copy by position and the drill-down opens on the wrong analytic,\n"
		"which reads as a report that disagrees with the one above it.\n"
		"* AND WHERE THE TRANSLATION IS GENUINELY IMPOSSIBLE - a composite field with no counterpart -\n"
		"SAY SO to the person: \"the total below may not match\". A silently different figure is worse\n"
		"than a warned one.\n"
		"\n"
		"NOTE: THE REPORT'S OWN ATTRIBUTES TRAVEL WITH THE DRILL-DOWN TOO - including its tabular\n"
		"sections, since a list of warehouses the person filled in by hand is part of the question\n"
		"they asked. Exclude only what would drag another report along with it.\n"
		"\n"
		"NOTE: THE HEADING OF A REPORT IS THE SETTINGS WRITTEN AS PROSE - what data, filtered how,\n"
		"sorted how - rendered into a human sentence rather than dumped as a structure. Put the whole\n"
		"block in a NAMED AREA of the result, and \"hide the heading\" becomes a visibility flag rather\n"
		"than a rebuild. Only a result built before the area existed needs regenerating.\n"
		"\n"
		"KEY: A REPORT IS A COMPOSITION SCHEMA PLUS A HANDFUL OF NAMED MOMENTS - NOT A DRAWN SHEET.\n"
		"Read off three working ledger reports, each one is the same shape: a composition schema\n"
		"declares the data, and the report's module implements hooks the framework calls, each named\n"
		"for WHEN it fires rather than for what it does.\n"
		" Two are in all of them - `ProduceReport` and `AdjustComposerBeforeOutput`. The first is\n"
		" the entry point; the second is where a report bends the composition it was given, and it\n"
		" is where nearly all the report-specific code lives.\n"
		" The rest are taken as needed: fill the initial settings, before the whole output, before\n"
		" EACH result element, save and apply a setting, initialise.\n"
		"A report that needs none of the middle ones implements none of them, and the framework does\n"
		"not care - so the set is a vocabulary, not a base class to fill in.\n"
		"\n"
		"KEY: THE QUERY CARRIES ITS OWN SETTINGS CONTRACT, IN THE TEXT. In a working ledger report the\n"
		"query is written with BRACED HOLES - a braced parameter where the period goes, a braced\n"
		"SELECT listing the fields a reader may add to the output, a braced WHERE where their filter\n"
		"lands. The text says what is negotiable and the composer fills exactly that; nothing lists\n"
		"the configurable parts a second time, so they cannot drift from the query they belong to.\n"
		"Everything OUTSIDE the braces is the report's own shape and is not up for discussion.\n"
		"\n"
		"KEY: AND THE SEMANTICS ARE DECLARED ON THE FIELDS, NOT COMPUTED IN CODE. The schema says of\n"
		"each field what it IS - this one is a balance, of this balance type, belonging to that\n"
		"account field, in that balance group; this one carries a role; this one is restricted;\n"
		"these two are shown in that appearance under this condition. Having been told, the composer\n"
		"folds debits against credits, opens and closes the period and totals every level by itself.\n"
		"That is why the report's module barely touches data: what it bends is the COMPOSITION, and\n"
		"a report whose module is full of arithmetic has usually failed to declare something.\n"
		"\n"
		"NOTE: THREE SMALLER HABITS FROM THE SAME QUERIES, each of which costs a rewrite when missed.\n"
		"The rights are asked for IN THE QUERY (`SELECT ALLOWED`), not filtered afterwards - a report\n"
		"that reads everything and hides some of it has already read it. A reference's printable form\n"
		"is fetched in the query as a field of its own rather than resolved per row while printing.\n"
		"And where one report needs several shapes of row - a balance line, then a line per analytic\n"
		"dimension - the data set is a UNION whose arms are padded to one column list with NULLs and\n"
		"told apart by a literal discriminator, rather than several data sets stitched later.\n"
		"\n"
		"KEY: AND THE CHROME IS DELEGATED IN ONE LINE, WHICH IS THE WHOLE POINT OF HAVING IT. The\n"
		"heading and the signature block are hooks on the report and their bodies are a single call\n"
		"into the standard-reports module - the report DECLARES that it has them and hands the\n"
		"drawing to shared code, which reads the shared areas template. So sixty reports look alike\n"
		"because none of them draws its own chrome, and changing the house style is one edit.\n"
		"⚠ THE HOOK IS STILL THERE EVEN WHEN IT ONLY DELEGATES, and that is deliberate: a report\n"
		"that wants a different heading overrides the body without the framework learning anything\n"
		"new, and one that wants none simply does not implement it. An arrangement where the\n"
		"framework drew the chrome ITSELF would make both of those a flag.") },

	{ wxT("regulated-forms"),
	  ibMcpText("A statutory blank that is filled in rather than built: rules per cell, and edits that survive."),
	  ibMcpText("A BLANK THAT IS FILLED IN, NOT BUILT.\n"
		"\n"
		"`report-shapes` names this as the fifth shape and says it is assembled differently. This is\n"
		"how. The sheet is fixed by law and cannot be produced by grouping anything: it has numbered\n"
		"lines, forbidden intersections, arithmetic between rows, and an accountant who is entitled\n"
		"to overrule the computed figure.\n"
		"\n"
		"KEY: THE RULE FOR EACH CELL IS DATA THAT SHIPS WITH THE PRODUCT, NOT CODE. A table lists,\n"
		"per cell: the LINE CODE the law refers to it by, the name of the cell on the sheet, HOW it\n"
		"is filled, and where it sits in the structure. From that table a working structure is built\n"
		"per cell. Because the rules are data, a change in the law is a new table rather than a\n"
		"release - which is the whole reason for the arrangement.\n"
		"* AND EACH PAGE OF A MULTI-PAGE SECTION GETS ITS OWN COPY of that structure, cloned from the\n"
		"first. A section that can repeat cannot share one set of cell values.\n"
		"\n"
		"KEY: THE HAND CORRECTION IS STORED BESIDE THE COMPUTED VALUE, AS A DELTA WITH A REASON. Each\n"
		"cell holds three things: what the data says, what the person adjusted it BY, and WHY. Filling\n"
		"again recomputes the first and leaves the other two untouched, so \"refill\" is safe by\n"
		"construction rather than by a flag saying \"do not touch this one\".\n"
		"* AND HOW MUCH A PERSON MAY DO IS PER CELL: computed only; computed plus an adjustment with\n"
		"a comment; or neither. Three modes, declared in the same table as the rule.\n"
		"* THE REASON MATTERS AS MUCH AS THE NUMBER. A statutory figure differing from the data\n"
		"without a recorded reason is the thing an inspection asks about.\n"
		"\n"
		"STOP: DO NOT ENCODE THE CELL'S MODE IN ITS COLOUR. In the system examined, whether a cell is\n"
		"automatic, manual or either is told apart BY COMPARING BACKGROUND COLOURS against literal\n"
		"values, in order to show the right hint. The colour is there for the human eye and that is\n"
		"correct; the mode belongs in the structure, and reading a type back out of the paint is a\n"
		"defect that breaks the day a palette changes.\n"
		"\n"
		"NOTE: PRINTING IT CUTS THE SECTIONS INTO PHYSICAL SHEETS, and the page number is placed\n"
		"DIGIT BY DIGIT into individually named cells - the blank has one box per digit, and the\n"
		"total number of sheets goes in the same shape on the title page. A sheet whose boxes are not\n"
		"found is skipped WITH A MESSAGE rather than printed unnumbered.\n"
		"\n"
		"KEY: SHIPPING A NEW SET OF BLANKS RECONCILES, IT NEVER TRUNCATES. Walk the manifest, create\n"
		"what is missing, refresh the names and periods of what is present, and DELETE NOTHING - a\n"
		"person's own forms and the ones they unticked have to survive an update. Match a group by\n"
		"name and a blank by (group, identifier), and run the whole pass in one transaction so a\n"
		"failure leaves the previous state rather than half the new one.\n"
		"* AND LET THEM DECLINE ROWS. \"I do not file that one\" is ordinary, and a list that grows\n"
		"back at every update is a list nobody curates.\n"
		"\n"
		"KEY: A BLANK SHIPS EVERY EDITION OF ITSELF AT ONCE, AND THE PERIOD PICKS ONE. The blank is not\n"
		"one form that changes - it is a TABLE of editions (the edition, the act that approved it,\n"
		"valid from, valid to), nineteen rows deep in the largest one, with a set of rules shipped per\n"
		"edition. The END of the reporting period selects the edition.\n"
		"* OVERLAPS ARE NORMAL AND THE PERSON ARBITRATES - two editions can both be valid for one\n"
		"period, and the system offers rather than decides. A period matching NO edition cannot be\n"
		"filed at all, and saying so is the correct behaviour.\n"
		"* THIS IS WHY THE RULES ARE DATA. An edition is a new sheet of rules, not a release.\n"
		"\n"
		"STOP: AND CHANGING EDITION IS WHERE THE CORRECTIONS ARE SILENTLY LOST. Per-cell settings are\n"
		"merged three ways - old, new, shipped - and where the shipped default wins over what the\n"
		"person chose, the DELTA COLUMN SURVIVES UNTOUCHED while the fill mode is reset. The\n"
		"correction stops being applied but stays recorded, and the figure moves by exactly the\n"
		"disputed amount with nothing naming the cell. When merging settings, a value the person set\n"
		"beats the shipped default, or the merge must SAY what it overrode.\n"
		"\n"
		"KEY: REQUIREDNESS IS ONE NUMBER, NOT A FLAG: 1 means this cell is required, N greater than 1\n"
		"means \"at least one of group N\". That covers the real rule on statutory forms - fill this,\n"
		"or that, or the third - without a language for conditions. Anything genuinely conditional is\n"
		"written beside the table and stays the exception.\n"
		"* AND THE CHECKS COVER ONLY THE SHEETS THAT WILL ACTUALLY BE SUBMITTED, AND NEVER BLOCK -\n"
		"they ask. A statutory form is often filed knowingly imperfect against a deadline.\n"
		"\n"
		"KEY: A FIGURE CARRIED FORWARD COMES FROM THE FILED RETURN, NOT FROM THE LEDGER. \"The closing\n"
		"balance of the previous period\" is read out of the neighbouring return - matched on exact\n"
		"period boundaries, ordered by the date it was SIGNED - and where the neighbour is missing,\n"
		"REFUSE rather than compute. Recomputing it from the books gives a different number the\n"
		"moment anything was corrected after filing, and the discrepancy surfaces at an inspection\n"
		"rather than at the desk.\n"
		"\n"
		"NOTE: FILING IS A DOCUMENT of its own - it can be batched, it carries its own number, it has\n"
		"a state. And an AMENDING return is a kind of the same document (`shapes`: an operation kind\n"
		"before a new metatype), not a separate blank per amendment - the system examined has both\n"
		"answers half-built at once, the kind-and-number in the shared engine and seven separate\n"
		"amending blanks in use, which is what happens when that decision is not taken.\n"
		"\n"
		"NOTE: EVERY FIGURE MUST LEAD BACK TO WHAT MADE IT (`report-shapes`). A number on a statutory\n"
		"return that cannot be drilled into is a number nobody can defend, and it will be asked about\n"
		"exactly once a year, under pressure.\n"
		"\n"
		"KEY: A BLANK IS A CATALOGUE ENTRY THAT POINTS AT A REPORT, NOT THE REPORT ITSELF. That\n"
		"indirection is what lets blanks be shipped, listed, filtered by period and legal form,\n"
		"switched off by a person, and reconciled against a new delivery - none of which a metaobject\n"
		"can do. And it makes DUPLICATES survivable rather than an error: when the same blank arrives\n"
		"twice, pick one deterministically, mark the rest for deletion, and carry on. A shipment that\n"
		"refuses to install because of a duplicate is a shipment that blocks a filing deadline.\n"
		"* WHICH PERIODS A BLANK MAY BE FILED FOR TRAVELS WITH IT, as data in the delivery - not as a\n"
		"rule in code. It is the kind of fact that differs per blank and changes without warning.\n"
		"* AND AN EXTERNALLY SUPPLIED BLANK IS RECOGNISED BY COMPARING WHAT WAS LOADED WITH WHAT IS\n"
		"REGISTERED, byte for byte, so an unregistered one opens READ-ONLY rather than being refused.\n"
		"Somebody must be able to look at a blank they were sent; nobody should be able to file from\n"
		"one nothing vouches for.\n"
		"\n"
		"NOTE: AND THE WIDELY SHIPPED IMPLEMENTATION DOES IT THE OTHER WAY, WHICH IS WHAT THE POSITION\n"
		"ABOVE COSTS AND SAVES. Opened and counted, one statutory balance sheet carries NINE dated\n"
		"report forms - 2003Q4, 2007Q1, 2008Q1, 2009Q4, 2012Q1, 2013Q1, 2013Q3 and the rest - with\n"
		"SIX matching indicator-list templates beside them, every one a metaobject in the\n"
		"configuration. So each act of parliament is a configuration release, a form from two decades\n"
		"ago still ships today, and a customer who needs last quarter's edition needs an upgrade.\n"
		"That is the arrangement this entry argues against, and it is not a straw man - it is what\n"
		"the reference implementation of this whole subject actually does. Knowing that is worth\n"
		"more than agreeing with either side: it says the cost is real and paid, and that anybody\n"
		"choosing data over metaobjects here is departing from the common practice on purpose.\n"
		"\n"
		"KEY: THE RETURN IS SAVED AS A DICTIONARY OF NAMED CELLS, NEVER AS A SHEET. The names are the\n"
		"prescribed identifiers of the law, so a return filled under one edition opens under a later\n"
		"one, and a cell that moved on the paper costs nothing. That single decision is what makes\n"
		"every other rule in this entry possible.\n"
		"* SO REFILL CAN BE \"CLEAR EVERYTHING AND RECOMPUTE\", WHICH IS THE ONLY SAFE SHAPE - the\n"
		"person's work is not in the sheet, it is in the deltas beside the computed values, and every\n"
		"computed value goes through ONE door that knows the difference. A refill that tries to\n"
		"preserve what it finds in the cells is guessing.\n"
		"* AND THE DIRECTION IS ONE-WAY BY DESIGN: older data may be opened by a newer blank, never\n"
		"the reverse. Say so, refuse the other direction with that sentence, and where the shape\n"
		"genuinely changed, a hand-written map with a numbered conversion step is the honest answer -\n"
		"stamped onto the data, so \"which conversions has this been through\" is readable.\n"
		"* WHEN AN EDITION CHANGES, the person's per-cell settings are merged three ways - what the\n"
		"old edition said, what the new one says, what the person changed - and the rule for the tie\n"
		"must be stated, because it is the case that loses somebody's work.\n"
		"\n"
		"KEY: THE PAPER IS A LAYOUT PROBLEM WITH THREE PARTS, AND EACH ONE IS ASKED ABOUT. A section\n"
		"that runs to several pages is ONE sheet plus a table of pages with one marked ACTIVE, so\n"
		"editing is always editing one page and printing walks them all. Page NUMBERS are written one\n"
		"digit per box, filled from the right, and a sheet that carries no number box consumes no\n"
		"number - which is why the numbering pass and the printing pass are the same pass. And a value\n"
		"is SCATTERED into one-character boxes on the way in and GATHERED back on the way out, by one\n"
		"pair of routines, or the two directions disagree about padding.\n"
		"STOP: AND A DISPLAY CHOICE THAT IS THEN FILED IS NOT A DISPLAY CHOICE. Rounding a statement to\n"
		"thousands \"for readability\" and then submitting that number makes the rounding a fact of the\n"
		"filing: it belongs to the return, is stored with it, and is stated on the printout - never a\n"
		"switch on a toolbar that the person can leave in either position.\n"
		"\n"
		"KEY: FILING IS A DOCUMENT, AND WHAT IT CARRIES IS MORE THAN THE FIGURES. Which pages are\n"
		"actually submitted is a TABLE on the return - decided in part by the filer's legal form, so\n"
		"it is computed and then editable - and the completeness check looks only at those pages. That\n"
		"check NEVER BLOCKS: it produces findings, each carrying the cell's coordinate so that\n"
		"clicking one walks to the cell. Requiredness is one number, not a flag, so \"at least one of\n"
		"this group\" is expressible (above).\n"
		"* AND THE ELECTRONIC FORM IS A FLAT NAME-AND-VALUE TEXT built from the SAME named cells, in\n"
		"which an absent value is absent rather than nought - which must be said, because a person\n"
		"looking at a printed nought and an empty line in the file will report it as a defect.\n"
		"* AND WHERE FILING IS HANDED TO AN OUTSIDE SERVICE, THAT IS A DATE PER LEGAL ENTITY, asked at\n"
		"the door and stored - not a global switch. Half a group filing through an agent and half\n"
		"filing directly is the ordinary case.\n"
		"NOTE: THE DEADLINE IS NOT IN THE BLANK. It is an obligation row per organisation, blank and\n"
		"period - which is what lets a calendar of what is due exist at all, and what lets one company\n"
		"be exempt from something another must file. Putting the deadline in the blank makes every\n"
		"exemption a code change.\n"
		"NOTE: AND A RETURN UNDER EDIT IS LOCKED FOR THE SESSION, with an autosave interval the person\n"
		"sets. Two people in one return is not a merge problem worth solving; losing an afternoon's\n"
		"typing is worth one setting.\n"
		"NOTE: AND WHERE THE SAME BLANK MUST RUN AGAINST TWO DIFFERENT ACCOUNTING SETS, IT IS THE\n"
		"REGISTER NAMES THAT SWITCH AT RUN TIME, not the blank. It works, it is the cheapest thing\n"
		"that could work, and it is paid for exactly as `query-by-name` says: nothing checks the names\n"
		"until the run.") },

	{ wxT("report-common-settings"),
	  ibMcpText("The few fields a reader sets before every run - period, company, which books."),
	  ibMcpText("THE PANEL OF SETTINGS THAT SITS ABOVE THE RESULT.\n"
		"\n"
		"\"The period and the company go at the top, always visible, not buried in the settings.\"\n"
		"Two or three fields are asked for on EVERY run of every report of the family, and they must\n"
		"not be found through a dialogue.\n"
		"\n"
		"KEY: THIS IS A SECOND LAYER OF SETTINGS, LAID OVER THE COMPOSITION BEFORE IT IS BUILT, and\n"
		"it is TWO things, not one:\n"
		" WHAT THE PANEL OFFERS - which fields, where each one sits, whether it appears at all. This\n"
		" belongs to the report.\n"
		" WHAT THE PERSON PUT IN THEM. This belongs to the person.\n"
		"Keeping them apart is what lets the panel be rearranged without losing values, and values be\n"
		"kept without freezing the layout.\n"
		"* AND THE PANEL IS NOT PART OF THE VARIANT. A variant describes STRUCTURE - the groupings,\n"
		"the outputs, the resources (`report-variants`). The panel carries VALUES. Mixing them makes\n"
		"every change of period look like a new variant.\n"
		"\n"
		"STOP: THE COMMON SETTINGS DO NOT LIVE ABOVE THE VARIANTS - EACH VARIANT KEEPS ITS OWN COPY.\n"
		"This is worth stating because the natural guess is the opposite. Switching variant does, in\n"
		"order: save the panel values of the CURRENT variant, WIPE the panel, switch, then read the\n"
		"panel values of the NEW one. They survive the switch not because they are global but because\n"
		"each variant has a copy - and if the new variant has none, they are seeded (below), not\n"
		"inherited from the variant just left. Anyone who assumes global values will write a defect\n"
		"where one report's filter silently follows the reader into another view.\n"
		"\n"
		"KEY: WITH NOTHING SAVED, SEED FROM THE PERSON'S OWN DEFAULTS. The report declares WHICH of\n"
		"its fields correspond to which personal default - my company, my warehouse - and the\n"
		"platform supplies the values from the one place those defaults live. The report says what to\n"
		"fill; it does not own the values. That is why a new employee's reports open sensibly on the\n"
		"first day without anybody configuring each report.\n"
		"\n"
		"KEY: \"WHICH SET OF BOOKS\" IS A SWITCH DESCRIBED AS DATA, NOT DRAWN ON THE FORM. The list of\n"
		"available books produces a description - captions, values, visibility, what happens on\n"
		"change - and the form BUILDS the control from that description. The report then carries one\n"
		"attribute holding the answer, and its query branches on it. Drawing four radio buttons by\n"
		"hand in each of forty reports is the alternative, and the fifth book is then forty edits.\n"
		"\n"
		"NOTE: A PANEL FIELD MAY BE DECLARED REQUIRED, AND THEN THE REPORT REFUSES TO RUN - stating\n"
		"which field, before doing any work. Requiredness is a property of the field's DESCRIPTION,\n"
		"not a check written inside the report (the same move as `posting`: what is mandatory is\n"
		"declared, and one mechanism reports it).\n"
		"\n"
		"KEY: A PANEL FIELD EDITS THE FILTER THAT IS ALREADY THERE - it does not add one. Find the\n"
		"enabled element on that field and change its value, its comparison and whether it applies;\n"
		"adding a second element leaves two filters on one field, and which of them wins is anybody's\n"
		"guess. Some choices SWITCH THE ELEMENT OFF rather than setting it (\"include subordinate\n"
		"units\" - the restriction then belongs to the query, not to the filter), and a dependent\n"
		"field is cleared when its owner changes, exactly as on a form (`entered-from`).\n"
		"\n"
		"NOTE: A PAGE HEADER AND FOOTER ARE ONE SETTING FOR THE WHOLE BASE, with substitutions for\n"
		"the report name and the person printing. Individual reports do not own it; they apply it.") },

	{ wxT("report-variants"),
	  ibMcpText("One report, several named views - and why that beats three reports."),
	  ibMcpText("SEVERAL QUESTIONS, ONE REPORT.\n"
		"\n"
		"People ask for what looks like several reports: \"sales\", \"sales with gross margin\",\n"
		"\"sales by manager\", \"the same thing but only for one warehouse\". Underneath they are one\n"
		"query answered with different groupings, different resources and different filters - and\n"
		"that is exactly what a VARIANT is.\n"
		"\n"
		"A variant is a NAMED SETTING over the composer's query. It carries the outputs, the levels,\n"
		"the resources and the selection; it does not carry a query of its own. The person running\n"
		"the report picks one by name, and the composer runs on the setting inside it.\n"
		"\n"
		"* SO BUILD ONE REPORT AND SEVERAL VARIANTS. Three reports for those three questions means\n"
		"three copies of one query to keep in step: a field added to the source has to be added\n"
		"three times, and the day it is added twice they disagree without anybody being told.\n"
		"\n"
		"THE NAME IS THE WHOLE OF WHAT A VARIANT ADDS, which is why a nameless one is refused when\n"
		"the configuration is saved. `report_variant` names one, and with `add` makes another\n"
		"starting from the settings of the one you point at - which is what a second view usually\n"
		"is: the first with a column added or a grouping taken away.\n"
		"\n"
		"The SYNONYM is what the person actually reads in the picker, so it is written in their\n"
		"language while the name stays the identifier code refers to.\n"
		"\n"
		"NOTE: WHEN IT IS GENUINELY A SECOND REPORT: when the QUERY differs - another table, another\n"
		"join, another period bound. Variants are settings over one query, and forcing two unlike\n"
		"queries into one composer means a query that reads more than either question needed.\n"
		"\n"
		"KEY: A VARIANT IS AN ITEM OF DATA, NOT A PART OF THE REPORT - and that is what makes it\n"
		"shareable. It carries the address of what it configures, the stored settings, a name, a\n"
		"description, whether it opens by default, and A LIST OF WHO MAY USE IT with a flag for who\n"
		"may change it. Rights over a variant are DATA, not roles: \"make me my version and give it to\n"
		"the sales team\" must not require a release.\n"
		"* AND THE PERSON'S OWN SETTINGS ARE A SECOND ROW OF THE SAME KIND, whose \"what it\n"
		"configures\" points AT THE VARIANT. One field, one storage, two roles - the author's variant\n"
		"addresses the report by name, a personal setting addresses the variant by reference. Where\n"
		"no variant is chosen, the address falls back to the report itself.\n"
		"\n"
		"KEY: A SUPPLIED VARIANT LIVES IN THE PRODUCT AND IS STAMPED INTO THE BASE, AND AN UPGRADE\n"
		"OVERWRITES IT ONLY IF NOBODY TOUCHED IT. The stored value carries a mark saying it has been\n"
		"edited; without the mark the upgrade refreshes it, with the mark it is left alone. The mark\n"
		"is stripped when the variant is exported - it describes a state, not the content.\n"
		"* AND SAY WHAT AN OVERWRITE COSTS: it cascades, removing the personal settings hanging on\n"
		"that variant. An upgrade that silently discards what people set up is remembered longer than\n"
		"the feature that came with it.\n"
		"\n"
		"KEY: BUILDING THE REPORT DAMAGES THE SETTINGS, SO TAKE A SNAPSHOT BEFORE AND RESTORE AFTER.\n"
		"Between them, the settings are legitimately polluted with everything needed to EXECUTE:\n"
		"panel values, technical filters, computed period bounds, formatting. \"Settings for running\"\n"
		"and \"settings the person owns\" are two different objects that happen to share a type, and\n"
		"the snapshot is the boundary between them. Without it, a person finds things in their\n"
		"settings they never put there.\n"
		"\n"
		"KEY: WHAT THE COMPOSITION CANNOT EXPRESS COSTS A SECOND PASS THROUGH MEMORY. Top N, a\n"
		"threshold, an ABC classification, hiding zero rows - none is a grouping or a filter. The\n"
		"honest implementation executes the data sets into a table, works on it, adds the columns,\n"
		"extends the schema and composes AGAIN over that table.\n"
		"* AND THE LIMITS MUST BE SAID OUT LOUD: the whole selection goes into memory, and it works\n"
		"for ONE data set only. A feature that silently switches itself off for a report with two\n"
		"data sets is worse than one that refuses.\n"
		"\n"
		"NOTE: KEEP A SHORT HISTORY OF SETTINGS - the last ten, de-duplicated BY THEIR SERIALISED\n"
		"CONTENT, with a human title generated from the settings themselves (\"by account 41\", \"by\n"
		"analytics Items, Warehouses\", plus the period). The identity of a setting is its content;\n"
		"the name is derived, and only for the person.\n"
		"\n"
		"NOTE: CACHE THE RESULT PER VARIANT, NOT PER REPORT - the built sheet together with its\n"
		"drill-down data - so switching variants swaps a sheet instead of recomputing. And notice\n"
		"what else belongs to the VARIANT rather than to the report: the page setup for printing.\n"
		"Different views of one report are printed differently, and people expect that to be\n"
		"remembered.\n"
		"\n"
		"STOP: A TECHNICAL SETTING MARKED BY A MAGIC STRING IN ITS CAPTION IS A DEFECT WAITING FOR A\n"
		"RENAME. Where some filters are structural rather than the reader's - the company, a control\n"
		"flag - they must carry a TYPE that says so, because a drill-down has to unpack them into the\n"
		"receiving report's own fields rather than copy them as filters. Recognising them by\n"
		"comparing caption text works until somebody translates the interface.") },

	{ wxT("same-shape-elsewhere"),
	  ibMcpText("The multiplier: a task in one trade answered by a mechanism already solved in another."),
	  ibMcpText("THE SAME SHAPE, SOLVED SOMEWHERE ELSE ALREADY.\n"
		"\n"
		"`unfamiliar-domain` goes one way - a trade you have never seen turns out to be a shape you\n"
		"know. This entry goes the other way and sideways: a task you already understand is answered\n"
		"by a MECHANISM that was built for a different subject entirely, and everything that was\n"
		"learned there - what it costs, where it goes wrong, what has to be said out loud - comes\n"
		"with it for nothing.\n"
		"* WHY IT IS WORTH A SEPARATE HABIT: the corpus is not a list of answers, it is a set of\n"
		"shapes times the number of subjects they apply to. Every entry added multiplies what every\n"
		"other entry can answer. The failure it prevents is narrow and constant - looking for an\n"
		"entry ABOUT budgets, finding none, and inventing something that stock control solved years\n"
		"ago.\n"
		"\n"
		"KEY: THE MOVE IS THREE QUESTIONS, IN THIS ORDER.\n"
		" 1. WHAT SHAPE IS THIS, in the vocabulary of `combining` - a boundary? a priority? a\n"
		" balance that must not go negative? a run that owns a period?\n"
		" 2. WHERE IS THAT SHAPE ALREADY SOLVED HERE - the index below answers this in one hop.\n"
		" 3. WHAT DID THEY LEARN THERE THAT I HAVE NOT MET YET? This is the part that pays. The\n"
		" entry that solved it has already been argued about by somebody, and its STOP lines are\n"
		" the defects you would otherwise find in production.\n"
		"STOP: AND DO NOT SEARCH BY THE NOUN OF THE TRADE. \"Budget\", \"membership\", \"licence\",\n"
		"\"tariff\" reach nothing, and the absence reads as \"the corpus has no answer\" when the answer\n"
		"is under another word. Search by the QUESTION - what is left, what is owed, what may be\n"
		"exceeded, what must reproduce for an old month.\n"
		"\n"
		"THE INDEX: EACH PRIMITIVE, AND WHERE IT IS ALREADY SOLVED. Recognise the primitive, then\n"
		"read the nearest neighbour rather than the nearest subject.\n"
		" A BOUNDARY - what is still valid, where recomputation must start. `sequences` (the\n"
		" boundary of validity), `closing-a-period` (a prohibition date is a TABLE), `deferred-\n"
		" posting` (the queue's frontier), `scheduled-documents` (the cursor), `external-data`\n"
		" (processed-up-to, so an old file cannot delete this year), `derived-registers` (a switch\n"
		" date is a period boundary), `traceability` (a validity window: empty means unbounded).\n"
		" A PRIORITY EXPRESSED AS ORDER, never as branches. `pricing` (which price applies),\n"
		" `bill-of-materials` (which specification), `settlements` (which debt this closes),\n"
		" `planning` (what covers this requirement), `orders` (one integer serving as the order AND\n"
		" the ceiling), `not-mine` (which contract).\n"
		" SUBTRACT YOURSELF - anything reading a total it also contributes to. `settlements`\n"
		" (refilling an offset), `cash-flow` (free money while holding a reservation), `stock-\n"
		" control` (free stock), `picking` (the line being typed has already eaten the stock),\n"
		" `fixed-assets` (does this already exist - exclude yourself, twice over).\n"
		" A DECLARATION EXECUTED BY ONE MECHANISM, instead of code per case. `posting` (the\n"
		" gathering query is declared), `external-data` (the mapping is a row per field, and it runs\n"
		" backwards for free), `regulated-forms` (a rule per cell), `parallel-accounting` (the\n"
		" account mapping is a rule table), `payroll` (each method declares its data appetite).\n"
		" A DELTA BESIDE A COMPUTED VALUE, so a recomputation cannot eat a person's work.\n"
		" `regulated-forms` (the hand correction), `pricing` (a typed discount is not trimmed, an\n"
		" automatic one is), `payroll` (the gross-up correction).\n"
		" A MATERIALISATION WITH A SWITCH - store what is asked for constantly. `derived-registers`\n"
		" (the four-part switch), `allocation` (a base must be SHOWABLE), `traceability` (the joined\n"
		" key stored as its own attribute), `stock-control` and `not-mine` (availability computed,\n"
		" not stored - the same question answered the other way).\n"
		" CHECKING THE OLD STATE AND THE NEW. `posting` (clear, then write), `closing-a-period` (a\n"
		" moved date needs BOTH sides checked), `object-history` (serialise both and compare),\n"
		" `stock-control` (the balance including this document's own movements).\n"
		" AN EMPTY VALUE THAT MEANS SOMETHING. `posting` (an empty dimension is legitimate, not\n"
		" missing), `numbering` (an empty dimension is the wildcard scope), `parallel-accounting`\n"
		" (an empty target analytic means carry the source across; an elimination is an entry with\n"
		" no organisation), `user-formulas` (an empty subject means the whole company). And its\n"
		" opposite in `not-mine`: never encode the state that costs money as an absence.\n"
		" A REFUSAL THAT IS A FLAG AND A MESSAGE. `posting`, `stock-control`, `lot-accounting`,\n"
		" `orders` (one check, two severities, chosen by the MODE not the person), `external-data`\n"
		" (a severity that only rises), `row-level-access` (a manual check must carry its refusal\n"
		" back or the caller reports success).\n"
		" KINDS THE USER MAY ADD, EACH WITH A VALUE. `shapes` (the chart of characteristic types),\n"
		" `roles` (a permission that carries a limit), `user-formulas` (indicators), `traceability`\n"
		" (kinds of certificate), `user-settings`.\n"
		"\n"
		"KEY: AND SOME WHOLE MECHANISMS ARE THE SAME MECHANISM UNDER DIFFERENT WORDS. This is the\n"
		"list that multiplies fastest - each line is one thing to build, reused in every trade that\n"
		"asks for it under its own name.\n"
		" A VALIDITY WINDOW: a certificate, a price, an exchange rate, an accounting policy, a tax\n"
		" designation, an employment, a licence, a membership. Two dates in which empty means\n"
		" unbounded, a far-future sentinel for ordering, and a stated rule for which record wins\n"
		" when two cover the same moment (`traceability`).\n"
		" A BALANCE THAT MUST NOT GO NEGATIVE: stock, a felling quota, a credit limit, sessions\n"
		" bought against sessions used, holiday days, a returnable-packaging ceiling, budget left in\n"
		" a line. One register, one control, one message naming the key (`stock-control`).\n"
		" A COMMITMENT THAT IS NOT YET A FACT: a reservation, a due-out, a purchase commitment\n"
		" against a budget, a booked seat, an approved but unspent order. Always a register of its\n"
		" own beside the balance, never a status on the document (`stock-control`, `orders`).\n"
		" AND THE PAIR ABOVE COVERS MOST OF WHAT IS CALLED SCHEDULING, which surprises people:\n"
		" the CAPACITY of a work centre in a period is a balance that must not go negative, an\n"
		" operation placed on it is a commitment against that balance, free capacity is the one\n"
		" minus the other, and a BOTTLENECK is simply where that difference reaches zero first -\n"
		" a reading, not a mechanism. Hours instead of goods, a work centre instead of a\n"
		" warehouse, and everything in `stock-control` applies unchanged: the control, the\n"
		" message naming the key, who may exceed it, subtract-yourself while a plan is being\n"
		" typed. What is genuinely NOT in this corpus is the ARITHMETIC around it - offsetting by\n"
		" lead times, sizing a launch batch, forward against backward scheduling - and that is a\n"
		" much smaller thing to bring in from outside than a mechanism would be.\n"
		" A RUN THAT OWNS A PERIOD: a derivation of the second book, a month-end close, a statutory\n"
		" return, an exchange message, a payroll run. Two of them may not overlap, re-running\n"
		" replaces, and \"where did this come from\" is answered by opening one document\n"
		" (`parallel-accounting`, `closing-a-period`).\n"
		" A LIMIT THAT MAY BE EXCEEDED ON PURPOSE: an over-issue on the shop floor, a credit limit,\n"
		" a discount floor, a packaging ceiling, an overdrawn budget line. Record the excess in a\n"
		" column of its own rather than blocking it, and let a permission decide who may\n"
		" (`stock-control`, `roles`).\n"
		" A COUNT THAT ESTABLISHES QUANTITY AND HAS NO OPINION ABOUT VALUE: a stocktake, a count of\n"
		" work in progress, a cash count, an inventory of assets. Price the difference pro rata from\n"
		" the book value, one routine for both directions (`stock-control`).\n"
		" TWO PHASES SO NOTHING IS REPORTED DONE BEFORE IT LANDED: an export buffered then promoted,\n"
		" two-step shipping, deferred posting, a production movement written as expense then\n"
		" receipt. The middle state must be the one that is safe to re-run (`external-data`,\n"
		" `deferred-posting`).\n"
		" A NORM AGAINST AN ACTUAL, WHERE THE DIFFERENCE IS THE SUBJECT: a specification against\n"
		" what was really consumed, a plan against a fact, a scheduled charge against a metered one,\n"
		" a quoted price against a paid one. The variance is where the trade's money is, so it is\n"
		" stored, not derived at the moment somebody asks (`production`, `planning`).\n"
		"\n"
		"WORKED TRANSFER - \"WE NEED BUDGETING\", ANSWERED ALMOST ENTIRELY OUT OF WAREHOUSE AND\n"
		"SETTLEMENT ENTRIES. This is the case that proves the habit, because nothing in the request\n"
		"sounds like stock.\n"
		" \"How much is left on this line\" is a BALANCE, so the budget is a register and not a\n"
		" table of numbers - and the whole of `stock-control` applies to it: the control, the\n"
		" message naming every dimension of the key, who may exceed it.\n"
		" \"This purchase order has been approved but not spent\" is a RESERVATION. Same shape as\n"
		" goods promised and not yet shipped: a commitment register beside the balance, and free\n"
		" budget is on-hand minus committed (`stock-control`, `orders`).\n"
		" \"Which version of the plan is this\" is a SCENARIO - a balance-bearing dimension, exactly\n"
		" as a set of books is (`parallel-accounting`), which is why two scenarios subtract.\n"
		" \"The sales budget is agreed in October, the capital one in December\" is a PROHIBITION\n"
		" DATE per scenario, centre and project - `closing-a-period`, which already says it is a\n"
		" table and not a date.\n"
		" \"Spread the annual figure over the months\" and \"scale last year by twelve per cent\" are\n"
		" ONE primitive - a profile of weights - and the pennies problem is `allocation`.\n"
		" \"Transport is six per cent of purchases\" is a DERIVED LINE, and the rule is a register,\n"
		" not code - the same argument as an account rule being data (`parallel-accounting`).\n"
		" \"Re-plan the rest of the year from where we are\" is the `pricing` defect one floor up:\n"
		" never hand-adjust a figure a recalculation owns. Write a new version, say what you did,\n"
		" leave the original readable - or the variance report shows zero for ever.\n"
		"WHAT WAS GENUINELY NEW, and it is two things: the planner types one-sided lines, so the\n"
		"double entry comes from a template on the article; and a plan entry touching three\n"
		"currencies must be refused unless all three have a rate that day. Everything else was\n"
		"already built for somebody selling boxes (`planning`).\n"
		"\n"
		"WORKED TRANSFER - A SPORTS CLUB, which has no goods, no production and no warehouse, and is\n"
		"still four entries you know.\n"
		" A MEMBERSHIP IS A VALIDITY WINDOW plus a periodic register for its rate - the same shape\n"
		" as a certificate and a price list, so renewal, overlap and \"which one applied in March\"\n"
		" are already answered (`traceability`, `pricing`).\n"
		" TEN SESSIONS BOUGHT AND SIX USED IS A BALANCE, and money paid for sessions not yet taken\n"
		" is an ADVANCE - a liability until it is worked off, which is `settlements` exactly, and\n"
		" the reason the club's own \"revenue\" figure is wrong before it is built.\n"
		" A BOOKING IS A RESERVATION against the capacity of a hall at an hour: a commitment\n"
		" register beside a balance, with `combining`'s subtract-yourself when the screen shows what\n"
		" is free while the person is holding a slot.\n"
		" THE MONTHLY CHARGE IS A SCHEDULED DOCUMENT with a cursor and a window of days\n"
		" (`scheduled-documents`), and a coach paid per session is `payroll` with a formula over an\n"
		" indicator - one row per session read from the same register that answers the balance.\n"
		" EQUIPMENT IS `fixed-assets`, depreciated by USE rather than by month where it is worth\n"
		" it, and individually identified kit is `traceability`.\n"
		"WHAT IS GENUINELY NEW: nothing structural. The work is vocabulary and screens - which is\n"
		"the honest answer to give, and it is worth giving, because the customer expects to be told\n"
		"their trade is special.\n"
		"\n"
		"NOTE: AND THE TRANSFER RUNS BOTH WAYS, WHICH IS THE HALF PEOPLE FORGET. A niche trade\n"
		"teaches the core one: logging's norm-against-actual is the production variance stated more\n"
		"sharply because the yield is only known after cutting; a club's prepaid sessions are the\n"
		"cleanest example there is of why an advance is a liability; a filing service's per-entity\n"
		"handover date is the general shape of \"half the group does it one way\". When a new subject\n"
		"is worked through, ask what it just taught the entries it borrowed from, and write that back\n"
		"- that is what makes the corpus grow by more than one entry at a time.") },

	{ wxT("body-map"),
	  ibMcpText("The body of an ERP: which organs exist, how big each is, what it joins to, and where to look."),
	  ibMcpText("THE BODY OF AN ERP - THE MAP TO NAVIGATE BY.\n"
		"\n"
		"Every other entry describes one organ. This is the anatomy: what a whole system is made of,\n"
		"how heavy each part is, what it touches, and which entry to open. Use it when the request\n"
		"does not say where it belongs, when a system has to be sized, or when reading somebody\n"
		"else's configuration for the first time.\n"
		"\n"
		"THE SPINE - EVERYTHING ELSE HANGS OFF IT.\n"
		" THE VOCABULARY. Items, parties, places, companies, units, and the closed sets. In a full\n"
		" system this is a section of its own with ~100 catalogues and no documents at all. Reached\n"
		" from everywhere; depends on nothing. -> `shapes`, `predefined`, `naming`, `external-data`\n"
		" THINGS MOVING. Balance registers, the documents that write them, the check before writing.\n"
		" Quantity only - value belongs elsewhere. Among the SMALLEST areas (~190 objects) and the\n"
		" most depended-upon. -> `stock-control`, `posting`, `not-mine`, `traceability`\n"
		" OBLIGATIONS. Who owes whom, in which currency, matched by which key. Joins to money on one\n"
		" side and to orders on the other. -> `settlements`, `currency`, `orders`, `cash-flow`\n"
		" WHAT THINGS COST. Lots or average, the write-off, the boundary of what is still true.\n"
		" Reads movements, feeds the ledger, and is where re-posting the past becomes expensive.\n"
		" -> `lot-accounting`, `sequences`, `production`, `allocation`, `derived-registers`\n"
		" THE LEDGER. Charts of accounts and their registers - four sets of books in a real system,\n"
		" and budgeting can be one of them. Assembles results; produces none. ~400 objects.\n"
		" -> `parallel-accounting`, `ledger-reports`, `vat`, `fixed-assets`\n"
		"\n"
		"THE ORGANS THAT SIT BESIDE IT.\n"
		" PRODUCTION (~360). Specifications, explosion, shop-floor movements, the close.\n"
		" -> `bill-of-materials`, `production`, `planning`\n"
		" PEOPLE AND PAY (~620, THE LARGEST AREA IN THE SYSTEM). Comes last, weighs most.\n"
		" -> `payroll`, `user-formulas`, `org-structure`\n"
		" PRICES AND OFFERS. Feeds every selling document; touches nothing else.\n"
		" -> `pricing`, `promotions`\n"
		" REPORTING (382 reports - more than there are documents). -> `report-shapes`,\n"
		" `report-variants`, `report-common-settings`, `ledger-reports`, `regulated-forms`\n"
		" THE SCREENS PEOPLE LIVE IN. -> `form-layout`, `picking`, `sections`, `showing-a-value`,\n"
		" `printing`, `batch-printing`, `form-to-areas`\n"
		" WHAT KEEPS IT HONEST. -> `roles`, `row-level-access`, `closing-a-period`,\n"
		" `object-history`, `numbering`\n"
		" WHAT KEEPS IT RUNNING. -> `cross-cutting-hooks`, `scheduled-documents`, `deferred-posting`,\n"
		" `long-operations`, `user-settings`, `extensions`, `data-exchange`\n"
		"\n"
		"THE TISSUE - NOT AN ORGAN, BUT PRESENT IN ALL OF THEM.\n"
		" HOW ANYTHING IS READ AT ALL. Every organ above answers its questions with queries, and the\n"
		" habits are shared: what may be assembled into a text and what may never be, temporary\n"
		" tables as the unit of a big calculation, virtual tables and their brackets.\n"
		" -> `query-craft`, `query-by-name`\n"
		" WHAT IS SET UP RATHER THAN ENTERED. A constant, a functional option, a settings register,\n"
		" a person's own arrangement - four different homes, and picking the wrong one is the\n"
		" commonest early mistake. -> `constants`, `user-settings`, `derived-registers`\n"
		" HOW ONE DOCUMENT BECOMES ANOTHER, and what must not travel with it. -> `entered-from`,\n"
		" `document-chains`\n"
		" AND THE HABIT THAT SAVES THE MOST WORK: look for it before building it. -> `look-first`\n"
		"\n"
		"THE HEAD - HOW TO THINK ABOUT ALL OF IT. These are not areas of a system; they are how the\n"
		"rest of this corpus is used, and a search by the words of a trade will never reach them.\n"
		" TAKING A REQUEST: which four questions to ask, in what order to search your own stock, how\n"
		" to hand a fork back with its price. -> `intake`\n"
		" THE TEN PRIMITIVES everything here is made of, and how one request is assembled out of\n"
		" six entries at once. -> `combining`\n"
		" A TRADE NOBODY HERE KNOWS is almost always a known shape plus two or three real\n"
		" differences. -> `unfamiliar-domain`\n"
		" THE SAME SHAPE SOLVED SOMEWHERE ELSE - the index from primitive to the entries that\n"
		" already solved it, and two worked transfers across trades. -> `same-shape-elsewhere`\n"
		" \"ADD THIS TO THE SALES DOCUMENT\" when the thing asked for belongs to a shared mechanism\n"
		" or to the month-end. -> `where-behaviour-lives`\n"
		" WHAT IS DECIDED BEFORE THE FIRST OBJECT, and the order of the eight steps after it.\n"
		" -> `building-an-erp`, `where-to-start`, `recipes`, `proportions`\n"
		"\n"
		"KEY: THE JOINTS - WHERE TWO ORGANS MEET IS WHERE THE DEFECTS ARE. Each of these is a seam\n"
		"two areas share and neither owns:\n"
		" MOVEMENT meets COST at the write-off: the quantity is known now, the value is not\n"
		" (`lot-accounting`).\n"
		" ORDER meets STOCK at the reservation: a promise holds back something real (`orders`).\n"
		" DOCUMENT meets LEDGER at posting: one act, many registers, and the flags saying which\n"
		" books are reflected (`posting`, `parallel-accounting`).\n"
		" TODAY meets THE PAST at the boundary and the prohibition date (`sequences`,\n"
		" `closing-a-period`).\n"
		" HERE meets ELSEWHERE at the exchange, where facts travel and totals do not\n"
		" (`data-exchange`).\n"
		" THE PERSON meets THE DATA at rights, and the check often runs privileged\n"
		" (`row-level-access`).\n"
		"\n"
		"KEY: HOW TO READ A SYSTEM YOU HAVE NEVER SEEN, in this order - it takes an hour and answers\n"
		"most questions:\n"
		" 1. COUNT THE METAOBJECTS BY KIND (`proportions`). The shape of the counts tells you what\n"
		" kind of system it is before you read a line: many calculation registers means payroll is\n"
		" real; four charts of accounts means several sets of books; one business process means the\n"
		" workflow is elsewhere.\n"
		" 2. LIST THE BALANCE REGISTERS AND THEIR DIMENSIONS. That is the data model. Which of them\n"
		" carry the company, which carry only quantity, which carry a lot - all the important\n"
		" decisions are visible here.\n"
		" 3. LIST THE EVENT HOOKS (`cross-cutting-hooks`). They name every mechanism that applies\n"
		" to everything, and none of it is visible in any document.\n"
		" 4. OPEN THE LARGEST DOCUMENT'S POSTING and read its section order (`posting`). It is the\n"
		" house style: how queries are gathered, how refusals are collected, how movements are\n"
		" dispatched.\n"
		" 5. LOOK AT THE SEQUENCES AND THE SCHEDULED JOBS. They say what is computed in batches and\n"
		" therefore what is NOT true at any given moment.\n"
		"\n"
		"KEY: AND THE PROPORTIONS TO CARRY IN YOUR HEAD, because they correct the usual intuitions:\n"
		"closed sets outnumber everything · settings outweigh counting two to one · double entry is\n"
		"under one per cent of the registers · there are more reports than documents · the area built\n"
		"first is among the smallest and the area built last is the largest · nearly as much code\n"
		"lives beside the objects as inside them.\n"
		"\n"
		"NOTE: WHAT IS NOT AN ORGAN AT ALL. Sections are NAVIGATION grown late over a graph organised\n"
		"by something else - do not read the build order off them (`sections`). And a workflow engine\n"
		"is not a layer: measured in a full ERP, exactly one process needed one, and it was the\n"
		"month-end close (`production`).") },

	};

	return s_patterns;
}

// ⭐⭐ A PATTERN IS READ IN LAYERS, and the reason is arithmetic. The corpus grew past a hundred
// kilobytes: handing over a whole entry to answer one question spends more than the answer is
// worth, and the parts nobody asked for crowd out what they did.
//
// So the entries are CUT INTO TOPICS - by the headings they already carry, rather than by a second
// structure written beside them. Asking for a pattern gives its summary and the list of what is
// inside; asking for a topic gives that part in full. Nothing is rewritten and nothing can drift,
// because the table of contents IS the text.
//
// ⚠ WHAT COUNTS AS A HEADING is deliberately narrow: a line that opens a paragraph and begins with
// two or more WORDS IN CAPITALS, after any marker. That is how this corpus is written throughout,
// so the split follows the author's own emphasis - and a paragraph that is not marked stays with
// the topic above it, which is the correct reading of an unmarked continuation.
struct ibMcpTopic {
	wxString m_title;
	wxString m_body;
};

bool LooksLikeHeading(const wxString& line)
{
	size_t at = 0;

	// Past the indent and past whatever marker opens the line - a star, a stop sign, a bullet.
	while (at < line.length() && !wxIsalpha(line[at]))
		at++;

	int capitalised = 0;

	while (at < line.length()) {

		size_t start = at;
		while (at < line.length() && wxIsalpha(line[at]))
			at++;

		const size_t length = at - start;
		if (length == 0)
			break;

		// ⚠ A SHORT WORD DOES NOT BREAK THE RUN, it is simply not counted. Half the headings in this
		// corpus open with "A …" or "AND A …", and a rule that stopped at the first one- or
		// two-letter word found no heading at all - every entry came back as one topic called
		// "Overview" (caught by running the split over the corpus before it ever shipped).
		bool shouts = true;
		for (size_t index = start; shouts && index < at; index++)
			shouts = wxIsupper(line[index]) != 0;

		if (!shouts)
			break;

		if (length >= 3)
			capitalised++;

		// ⚠ WHAT SEPARATES THE WORDS OF A HEADING IS NOT ONLY A SPACE. The marks that open them are
		// written as words now - `KEY:`, `STOP:`, `NOTE:` - and a colon stopping the run took every
		// one of those headings out of the table of contents, which is exactly the set that matters
		// most (caught by reading a live answer, 2026-09-02: the contents came back holding the
		// ordinary paragraphs and none of the marked ones). So anything that is not a letter is
		// stepped over between words; the run ends when a word is not in capitals.
		while (at < line.length() && !wxIsalpha(line[at]))
			at++;
	}

	return capitalised >= 2;
}

std::vector<ibMcpTopic> TopicsOf(const wxString& text)
{
	std::vector<ibMcpTopic> topics;

	wxString current;
	wxString title = wxT("Overview");   // whatever stands before the first heading
	bool paragraphStart = true;

	size_t at = 0;

	while (at <= text.length()) {

		const size_t end = text.find(wxT('\n'), at);
		const wxString line = text.Mid(at, (end == wxString::npos ? text.length() : end) - at);

		if (line.IsEmpty()) {
			paragraphStart = true;
		}
		else {
			if (paragraphStart && LooksLikeHeading(line) && !current.IsEmpty()) {
				topics.push_back({ title, current });
				current.Clear();
				title = line;
			}
			else if (paragraphStart && LooksLikeHeading(line)) {
				title = line;
			}
			paragraphStart = false;
		}

		current << line << wxT("\n");

		if (end == wxString::npos)
			break;
		at = end + 1;
	}

	if (!current.IsEmpty())
		topics.push_back({ title, current });

	return topics;
}

// How many lines a topic is - so a table of contents says the SIZE of what it offers and not only
// its name. Without it, "WHAT A FULL CLOSE ACTUALLY CONTAINS" and a two-line aside look alike from
// outside, and the only way to find out is to fetch one and see.
size_t LinesIn(const wxString& body)
{
	size_t lines = 0;

	for (size_t at = 0; at < body.length(); at++)
		if (body[at] == wxT('\n'))
			lines++;

	return lines;
}

// The line a reader would have found themselves - the first one carrying any word of the query,
// so a hit can be judged before it is opened.
wxString MatchingLine(const wxString& body, const wxString& query)
{
	// ⭐ THE LINE IS FOUND BY THE SAME RULE THAT FOUND THE TOPIC (ibMcpWordsFound) - stems, and a
	// regular expression when that is what was written. Anything else and the two disagree: the
	// hit is real, the line quoted under it is not the one that matched, and the caller judges the
	// passage by a sentence that has nothing to do with their question.
	size_t at = 0;

	while (at <= body.length()) {

		const size_t end = body.find(wxT('\n'), at);
		const wxString line = body.Mid(at, (end == wxString::npos ? body.length() : end) - at);

		if (ibMcpWordsFound(line, query) > 0) {
			wxString trimmed = line;
			trimmed.Trim(true).Trim(false);
			return trimmed.length() > 200 ? trimmed.Left(197) + wxT("...") : trimmed;
		}

		if (end == wxString::npos)
			break;
		at = end + 1;
	}

	return wxEmptyString;
}

// The heading as a LABEL - the sentence a reader picks from, not the paragraph it opens.
wxString TopicLabel(const wxString& title)
{
	wxString label = title;
	label.Trim(true).Trim(false);

	// Cut at the first full stop or dash: the heading states its subject and then explains it.
	for (const wxChar* stop : { wxT(". "), wxT(" - "), wxT(", ") }) {
		const int at = label.Find(stop);
		if (at != wxNOT_FOUND && at > 12) {
			label = label.Left(at);
			break;
		}
	}

	if (label.length() > 96)
		label = label.Left(93) + wxT("...");

	return label;
}

const ibMcpPattern* FindPattern(const wxString& name)
{
	for (const ibMcpPattern& pattern : Patterns())
		if (name.IsSameAs(pattern.m_name, false))
			return &pattern;
	return nullptr;
}

} // namespace

// ⭐⭐ THE CORPUS, REACHABLE BY SOMETHING THAT IS NOT A TOOL. `prompts` is a surface of the protocol
// the PERSON sees — a menu in their client — and it is served by the server, not from in here, so
// the entries have to be readable from outside this file.
//
// ⚠ TWO FUNCTIONS AND NO MORE. Not the whole table: what a caller outside needs is the INDEX (to
// build a menu) and ONE ENTRY BY NAME (to answer a choice from it). Handing out the vector would
// let the next surface re-derive summaries, headings and search of its own, which is how the
// corpus would end up with two readers disagreeing about what it says.
std::vector<std::pair<wxString, wxString>> ibMcpPatternIndex()
{
	std::vector<std::pair<wxString, wxString>> index;

	for (const ibMcpPattern& pattern : Patterns())
		index.emplace_back(wxString(pattern.m_name), pattern.m_summary);

	return index;
}

wxString ibMcpPatternText(const wxString& name)
{
	const ibMcpPattern* found = FindPattern(name);
	return found != nullptr ? found->m_text : wxString();
}

//---------------------------------------------------------------------------
// patterns
//---------------------------------------------------------------------------

class ibMcpToolPatternRead : public ibMcpTool {
public:

	wxString GetName() const override { return wxT("pattern_read"); }

	wxString GetActivity(const ibDataNode& params) const override
	{
		const wxString name = ArgName().Text(params);
		return name.IsEmpty()
			? ibMcpText("listing the patterns")
			: wxString::Format(ibMcpText("reading the '%s' pattern"), name);
	}

	wxString GetDescription() const override
	{
		return ibMcpText("A translator from the language of the people who ask - accountants, warehouse "
			"managers, anyone describing their work - into the shapes this platform has. They do "
			"not say \"accumulation register\"; they say \"I want to see it monthly\", \"how much "
			"is left\", \"the account it goes to\", and each of those names a shape exactly. It "
			"also holds how the mechanisms behind them are built: costing, lots, month-end close, "
			"settlements, printed forms, screen layout, roles.\n"
			"READ IT IN LAYERS, as needed, rather than up front: `query` with the words of the "
			"problem answers WHERE it is covered - pattern, topic, matching line; `name` alone "
			"gives a summary and what is inside; `name` with `topic` gives that part in full. No "
			"argument lists everything there is. Recommendations, not rules. Worth consulting "
			"BEFORE creating a metaobject - the choice of shape is the one decision that is "
			"expensive to revisit once there is data in it.\n"
			"THE ENTRIES ARE IN ENGLISH, and the request will often not be: whatever language the "
			"person writes in, search this in the English words the trade uses. A miss is far more "
			"often the wording than a gap. English is where the SHAPES are written down, the same "
			"way the code is - it is not the language of the conversation: answer the person in "
			"theirs, in the words their trade uses there, and let the names of what gets built "
			"follow the project's own rule.\n"
			"AND EIGHT ENTRIES ARE ABOUT USING THE OTHERS - `body-map` (the anatomy of a whole "
			"system: which organs exist, how heavy each is, which entry to open), `intake` (which "
			"questions to ask and in "
			"what order), `combining` (the ten primitives everything here is made of, and how one "
			"request is assembled from several), `same-shape-elsewhere` (the index from a primitive "
			"to the entries that already solved it, and worked transfers across trades), "
			"`document-chains`, `unfamiliar-domain` (a trade nobody here knows is almost always a "
			"known shape plus two or three real differences), `where-behaviour-lives`, "
			"`building-an-erp`. A search by the words of a trade will never reach them, so start "
			"there when what arrived is a whole task rather than a term.\n"
			"IF YOU ARE NEW HERE, THIS IS THE PATH, AND IT IS FOUR STEPS. What shape is this - ask "
			"`combining`, not the noun of the trade. Where is that shape already solved - "
			"`same-shape-elsewhere` answers it in one hop, and the STOP lines of the entry that "
			"solved it are the defects you would otherwise ship. What does the shape NEED FROM A "
			"PLATFORM - entries state that, and they deliberately do NOT say what this engine has, "
			"because that would be wrong the day it changes. Then GO AND CHECK whether it is here - "
			"`metadata_accepts`, `metadata_list`, `syntax_search` answer that, never assume - and say the "
			"answer out loud: it can be built, or it can be built by hand at this price, or it "
			"cannot be built until the engine has X. Naming a missing mechanism as a piece of work "
			"is part of the job, not a complaint; building a weak imitation without saying so is "
			"the one wrong move.");
	}

	// ⭐⭐ THE CORPUS IS THE INDEX. This tool is a door onto a body of text written in the WORDS OF
	// THE PEOPLE WHO ASK — "how much is left", "I want to see it monthly", "the account it goes
	// to" — and those are exactly the words a caller searches with. The description above says
	// what the door is; it does not contain them, so searching it missed every one.
	//
	// Handing the whole corpus over is what keeps this true without a second list to maintain: an
	// entry added tomorrow is findable by its own sentences the moment it is written. Held once,
	// built on first use — the texts are already static, so this is a concatenation and not a copy
	// of anything.
	wxString GetSearchText() const override
	{
		static wxString s_index;

		if (s_index.IsEmpty()) {
			for (const ibMcpPattern& pattern : Patterns())
				s_index << pattern.m_name << wxT("\n")
					<< pattern.m_summary << wxT("\n") << pattern.m_text << wxT("\n");
		}

		return s_index;
	}

	// ⭐⭐ WHERE IN THE CORPUS THE ANSWER IS - written once and asked by both doors: this tool's own
	// `query`, and mcp_search with the same words. Two implementations of "find the passage" would
	// drift within a week, and the caller would learn to distrust whichever one they hit second.
	//
	// Ranked, not filtered: everything that met every word if anything did, and otherwise the best
	// there was, said as "3 of your 5 words" so a partial answer is never mistaken for a complete
	// one. That is the difference between a search that fails politely and one that says "there is
	// nothing about this" - which, about a corpus this size, is never true and always acted on.
	void FindInside(const wxString& query, std::vector<ibDataValue>& places) const override
	{
		if (query.IsEmpty())
			return;

		struct ibPlace { const ibMcpPattern* m_pattern; ibMcpTopic m_topic; size_t m_score; };

		std::vector<ibPlace> scored;
		size_t asked = 0, best = 0;

		for (const ibMcpPattern& pattern : Patterns()) {

			for (const ibMcpTopic& topic : TopicsOf(pattern.m_text)) {

				// The pattern's NAME and SUMMARY count towards the topic's score: a caller asking
				// "lots" should reach every part of the lots entry, not only the paragraphs that
				// happen to repeat the word.
				const wxString haystack = wxString(pattern.m_name) + wxT("\n")
					+ pattern.m_summary + wxT("\n") + topic.m_body;

				const size_t score = ibMcpWordsFound(haystack, query, &asked);
				if (score == 0)
					continue;

				best = std::max(best, score);
				scored.push_back({ &pattern, topic, score });
			}
		}

		const bool partial = best > 0 && best < asked;
		size_t given = 0;

		for (const ibPlace& place : scored) {

			if (place.m_score < best)
				continue;

			// A single common word can stand in half the corpus, and an address list nobody can
			// read is the problem this tool exists to solve, one level up.
			if (++given > 24)
				break;

			std::shared_ptr<ibDataNode> hit = std::make_shared<ibDataNode>();
			hit->SetValue(wxT("pattern"), wxString(place.m_pattern->m_name));
			hit->SetValue(wxT("topic"), TopicLabel(place.m_topic.m_title));

			if (partial)
				hit->SetValue(wxT("matched"), wxString::Format(
					ibMcpText("%i of your %i words"), (int)place.m_score, (int)asked));

			// The line that matched, so a caller can judge the hit without fetching it.
			const wxString line = MatchingLine(place.m_topic.m_body, query);
			if (!line.IsEmpty())
				hit->SetValue(wxT("line"), line);

			places.push_back(ibDataValue::Child(hit));
		}
	}

	const std::vector<ibMcpArgument>& Arguments() const override
	{
		static const std::vector<ibMcpArgument> s_arguments = { ArgQuery(), ArgName(), ArgTopic() };
		return s_arguments;
	}

	bool Call(const ibDataNode& params, ibDataNode& result, wxString& refusal) const override
	{
		const wxString name = ArgName().Text(params);
		const wxString query = ArgQuery().Text(params);

		// ⭐ SEARCH FIRST, IF THERE IS ONE. A caller with words and no name gets addresses back -
		// pattern, topic, and the line that matched - and reads exactly the part that answered.
		if (!query.IsEmpty()) {

			std::vector<ibDataValue> hits;
			FindInside(query, hits);

			if (hits.empty()) {
				refusal = wxString::Format(
					ibMcpText("Not one word of '%s' appears in the patterns. THE CORPUS IS IN ENGLISH - "
					  "if that query is in another language, ask again with the English words the "
					  "trade uses for it. Otherwise say it in other words, or ask with no argument "
					  "to see what the corpus covers - it is a hundred kilobytes of shapes, and a "
					  "miss here is far more often the wording than a gap."), query);
				return false;
			}

			result.AddField(wxT("found"), ibDataValue::Int((s64)hits.size()));
			result.AddField(wxT("hits"), ibDataValue::Array(hits));
			result.SetValue(wxT("note"), hits.size() >= 24
				? ibMcpText("Read one with {name, topic} - quoting the topic line above. This many "
				  "addresses means the words are common ones: add a word to narrow it.")
				: ibMcpText("Read one with {name, topic} - quoting the topic line above."));
			return true;
		}

		// NO NAME — THE LISTING. Summaries only: the point of a listing is to choose from it, and
		// a listing that inlines every text is the `instructions` problem again, one call later.
		if (name.IsEmpty()) {

			std::vector<ibDataValue> out;

			for (const ibMcpPattern& pattern : Patterns()) {
				std::shared_ptr<ibDataNode> entry = std::make_shared<ibDataNode>();
				entry->SetValue(wxT("name"), wxString(pattern.m_name));
				entry->SetValue(wxT("summary"), pattern.m_summary);
				out.push_back(ibDataValue::Child(entry));
			}

			result.AddField(wxT("patterns"), ibDataValue::Array(out));

			// ⭐⭐ A STRANGER SEES THE COUNT AND THE SHAPE BEFORE THE LIST. Sixty-odd name-and-summary
			// pairs read as an undifferentiated heap: nothing in them says that seven are about
			// USING the other sixty, and those seven are exactly the ones a search by the words of
			// a trade can never reach. Naming them here, above the list, is what turns a first
			// contact into a path — and the count is what tells the reader this is a body of work
			// rather than a handful of notes.
			result.AddField(wxT("count"), ibDataValue::Int((s64)out.size()));
			{
				static const wxChar* const s_start[] = {
					wxT("intake"), wxT("combining"), wxT("same-shape-elsewhere"),
					wxT("unfamiliar-domain"), wxT("document-chains"),
					wxT("where-behaviour-lives"), wxT("building-an-erp"), wxT("body-map")
				};

				std::vector<ibDataValue> start;
				for (const wxChar* const nm : s_start)
					start.push_back(ibDataValue::String(wxString(nm)));

				result.AddField(wxT("start_here"), ibDataValue::Array(start));
			}

			result.SetValue(wxT("note"),
				ibMcpText("`count` is how many there are; `start_here` names the few that are about USING "
				  "the rest, and a search by the words of a trade will never land on them - so when "
				  "what arrived is a whole task rather than a term, read those first. Everything "
				  "else is one subject each. These are recommendations, and what each is FOR is "
				  "said inside it, so a case that does not fit can be recognised rather than "
				  "forced. The entries are ENGLISH: search them in English whatever language the "
				  "request came in.\n"
				  "THE PATH, IF THIS IS THE FIRST TIME: what SHAPE is this (`combining`) -> where "
				  "is that shape already solved (`same-shape-elsewhere`) -> what does it NEED FROM "
				  "A PLATFORM (each entry says; none of them says what this engine HAS) -> go and "
				  "check whether it is here and SAY the answer. A missing mechanism named as a "
				  "piece of work is a useful answer; a weak imitation built without saying so is "
				  "not."));

			// ⭐⭐ THE WARNING THAT BELONGS ON THE LISTING RATHER THAN INSIDE ONE ENTRY, because it
			// is about what the reader brings WITH them and therefore applies before any entry is
			// opened. A model arrives fluent in other ERPs and will answer a domain question out
			// of that fluency - describing currency accounting, or costing, or period close, in
			// another system's model - and it reads as competence rather than as an import. It is
			// the same failure as writing another language's syntax, one floor up: it looks right
			// and does not fit. Named because it was observed, repeatedly (Max, 2026-08-31: "you
			// keep telling me about currency accounting out of the SAP world").
			result.SetValue(wxT("beware"),
				ibMcpText("If you know other ERP systems, notice when an answer is coming from one of "
				  "them. Their concepts have familiar names here and different edges, and a "
				  "design imported wholesale looks reasonable until it meets the platform it is "
				  "not built on. What is written here is what THIS platform has and how the "
				  "people who use it describe their work - prefer it to what you already know, "
				  "and when something is genuinely missing say so plainly instead of "
				  "substituting the shape you are used to."));
			return true;
		}

		const ibMcpPattern* found = FindPattern(name);

		// ⚠ NAMED AND NOT FOUND IS A REFUSAL, not an empty answer. A caller who mistyped a name
		// and got `{}` back reads it as "there is no advice about this" and proceeds.
		if (found == nullptr) {
			wxString known;
			for (const ibMcpPattern& pattern : Patterns()) {
				if (!known.IsEmpty())
					known += wxT(", ");
				known += pattern.m_name;
			}
			refusal = wxString::Format(
				ibMcpText("There is no pattern called '%s'. There is: %s."), name, known);
			return false;
		}

		result.SetValue(wxT("name"), wxString(found->m_name));
		result.SetValue(wxT("summary"), found->m_summary);

		const std::vector<ibMcpTopic> topics = TopicsOf(found->m_text);
		const wxString wanted = ArgTopic().Text(params);

		// EVERYTHING, when asked for it - or when the entry is short enough that a table of
		// contents would cost more than the text it describes.
		if (wanted.IsSameAs(wxT("all"), false) || topics.size() < 3
			|| found->m_text.length() < 2500) {
			result.SetValue(wxT("text"), found->m_text);
			return true;
		}

		// ONE PART, named by any words of its heading. Matched loosely on purpose: a caller quotes
		// the listing approximately, and refusing a near miss teaches them to fetch the whole thing
		// instead - which is the behaviour this exists to avoid.
		if (!wanted.IsEmpty()) {

			wxString answered;
			std::vector<ibDataValue> parts;

			for (const ibMcpTopic& topic : topics) {
				if (topic.m_title.Lower().Find(wanted.Lower()) == wxNOT_FOUND
					&& TopicLabel(topic.m_title).Lower().Find(wanted.Lower()) == wxNOT_FOUND)
					continue;

				std::shared_ptr<ibDataNode> entry = std::make_shared<ibDataNode>();
				entry->SetValue(wxT("topic"), TopicLabel(topic.m_title));
				entry->SetValue(wxT("text"), topic.m_body);
				parts.push_back(ibDataValue::Child(entry));
			}

			if (!parts.empty()) {
				result.AddField(wxT("parts"), ibDataValue::Array(parts));
				return true;
			}

			refusal = wxString::Format(
				ibMcpText("'%s' has no topic matching '%s'. Ask it without a topic to see what is in it, "
				  "or with topic 'all'."), name, wanted);
			return false;
		}

		// THE TABLE OF CONTENTS - what this entry holds, so the next call fetches one part rather
		// than a hundred lines to answer one question.
		std::vector<ibDataValue> contents;

		for (const ibMcpTopic& topic : topics) {

			// ⭐ A NAME WITHOUT A SIZE IS HALF A TABLE OF CONTENTS. Two headings read alike from
			// outside while one is four lines and the other is forty, so the only way to find out
			// which is which is to fetch them - which is precisely the cost this listing exists to
			// avoid. The weight makes the next call a decision rather than a probe.
			std::shared_ptr<ibDataNode> entry = std::make_shared<ibDataNode>();
			entry->SetValue(wxT("topic"), TopicLabel(topic.m_title));
			entry->AddField(wxT("lines"), ibDataValue::Int((s64)LinesIn(topic.m_body)));

			contents.push_back(ibDataValue::Child(entry));
		}

		result.AddField(wxT("topics"), ibDataValue::Array(contents));
		result.SetValue(wxT("note"),
			ibMcpText("Read one with `topic`, quoting any words of its line above; `topic: \"all\"` gives "
			  "the whole entry. `lines` is how long each part is."));
		return true;
	}
};

MCP_TOOL_REGISTER(ibMcpToolPatternRead);
